    fn push_registry_session_authority(
        authority: &PreparedAuthority,
    ) -> SnapbackResult<(&str, &str, u64)> {
        authority.validate_admission("push-token registry operation")?;
        if authority.source() != InvocationSource::PushTokenRegistry
            || authority.active_mode() != AuthMode::Sessions
        {
            return Err(SnapbackError::error(
                "SNAPBACK_PUSH_SESSION_REQUIRED",
                "push",
                "push-token registry operations require exact session authority",
            ));
        }
        match authority.resolved() {
            ResolvedAppAuthority::Session {
                user_id,
                session_id,
                generation,
                ..
            } => Ok((user_id, session_id, *generation)),
            _ => Err(SnapbackError::error(
                "SNAPBACK_PUSH_SESSION_REQUIRED",
                "push",
                "push-token registry operations require exact session authority",
            )),
        }
    }

    pub fn register_push_token(
        &mut self,
        authority: &PreparedAuthority,
        request: &crate::push::RegisterPushTokenRequest,
        now_ms: u64,
    ) -> SnapbackResult<crate::push::PushTokenRegistrationResponse> {
        let (principal_id, session_id, session_generation) =
            Self::push_registry_session_authority(authority)?;
        let _effect = authority.effect_guard("push-token registration transaction")?;
        let declaration = self.db.schema().push_seam.clone().ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_PUSH_SEAM_NOT_DECLARED",
                "push",
                "the app schema does not declare definePushSeam",
            )
        })?;
        self.db.push_registry().register(
            &declaration,
            principal_id,
            session_id,
            session_generation,
            &request.installation_id,
            request.token.as_str(),
            now_ms,
        )
    }

    pub fn unregister_push_token(
        &mut self,
        authority: &PreparedAuthority,
        request: &crate::push::UnregisterPushTokenRequest,
        now_ms: u64,
    ) -> SnapbackResult<crate::push::PushTokenUnregisterResponse> {
        let (principal_id, session_id, session_generation) =
            Self::push_registry_session_authority(authority)?;
        let _effect = authority.effect_guard("push-token unregister transaction")?;
        let declaration = self.db.schema().push_seam.clone().ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_PUSH_SEAM_NOT_DECLARED",
                "push",
                "the app schema does not declare definePushSeam",
            )
        })?;
        self.db.push_registry().unregister(
            &declaration,
            principal_id,
            session_id,
            session_generation,
            &request.installation_id,
            now_ms,
        )
    }

    /// Execute one auth-owner-minted database operation. The sealed trait
    /// prevents adapters from substituting an arbitrary closure or obtaining
    /// the engine's raw database handle.
    pub fn execute_auth_plan<P: snapback_auth::auth::database_plan::AuthDatabasePlan>(
        &mut self,
        plan: P,
    ) -> P::Output {
        plan.execute(self.db.auth_database_mut())
    }

    /// Execute one sealed auth maintenance pass and the existing push-idle
    /// retirement in the same target-owner turn.
    pub fn execute_auth_gc_plan<P>(
        &mut self,
        plan: P,
        now_ms: u64,
    ) -> crate::auth::provider::ProviderResult<crate::auth::provider::AuthGcPass>
    where
        P: snapback_auth::auth::database_plan::AuthDatabasePlan<
                Output = crate::auth::provider::ProviderResult<crate::auth::provider::AuthGcPass>,
            >,
    {
        let pass = plan.execute(self.db.auth_database_mut())?;
        if let Some(declaration) = self.db.schema().push_seam.clone() {
            self.db
                .push_registry()
                .retire_idle(&declaration, now_ms)
                .map_err(crate::auth::provider::ProviderError::from)?;
        }
        Ok(pass)
    }

    pub fn memory() -> SnapbackResult<Self> {
        let asset_store_config = AssetStoreConfig::from_env();
        let snapback = Self::from_database(LocalDatabase::memory()?, None, asset_store_config)?;
        snapback.record_process_start_lifecycle();
        Ok(snapback)
    }

    /// Construct an in-memory production instance under an authoritative
    /// target descriptor. The schema owns `app_id`; the descriptor owns the
    /// opaque environment identifier.
    // @ref LLP 0154#d1--telemetry-store-a-sibling-sqlite-database-generation-bound —
    //   local production construction consumes descriptor authority directly.
    pub fn memory_for_target(target: &crate::deploy::TargetDescriptor) -> SnapbackResult<Self> {
        let asset_store_config = AssetStoreConfig::from_env();
        let db = LocalDatabase::memory()?;
        let identity = Self::telemetry_identity_for_target(&db, target)?;
        let snapback = Self::from_database(db, Some(identity), asset_store_config)?;
        snapback.record_process_start_lifecycle();
        Ok(snapback)
    }

    pub fn open(path: impl AsRef<Path>) -> SnapbackResult<Self> {
        let asset_store_config = AssetStoreConfig::from_env();
        Self::open_with_optional_target(path.as_ref(), None, asset_store_config)
    }

    /// Open a file-backed production instance under an authoritative target
    /// descriptor. Compatibility [`Self::open`] intentionally remains
    /// unbound; it never derives identity from the path or target profile.
    // @ref LLP 0154#d1--telemetry-store-a-sibling-sqlite-database-generation-bound —
    //   app and environment identity enter together at the production seam.
    pub fn open_for_target(
        path: impl AsRef<Path>,
        target: &crate::deploy::TargetDescriptor,
    ) -> SnapbackResult<Self> {
        let asset_store_config = AssetStoreConfig::from_env();
        Self::open_with_optional_target(path.as_ref(), Some(target), asset_store_config)
    }

    #[cfg(any(test, feature = "test-support"))]
    pub fn open_with_asset_store_backend_for_test(
        path: impl AsRef<Path>,
        backend: crate::assets_store::AssetStoreBackend,
    ) -> SnapbackResult<Self> {
        Self::open_with_optional_target(path.as_ref(), None, AssetStoreConfig::for_backend(backend))
    }

    fn open_with_optional_target(
        path: &Path,
        target: Option<&crate::deploy::TargetDescriptor>,
        asset_store_config: AssetStoreConfig,
    ) -> SnapbackResult<Self> {
        let config = ConfigStore::open_for_database(path)?;
        let db = LocalDatabase::open(path)?;
        let identity = target
            .map(|target| Self::telemetry_identity_for_target(&db, target))
            .transpose()?;
        let mut snapback = Self::from_database(db, identity.clone(), asset_store_config)?;
        let incarnation = snapback.db.ensure_authorization_stream_incarnation()?;
        snapback.telemetry = match identity {
            Some(identity) => crate::telemetry::Telemetry::open_for_database_with_identity(
                path,
                incarnation.as_str(),
                identity,
                config.telemetry_config().clone(),
            )?,
            None => crate::telemetry::Telemetry::open_for_database(
                path,
                incarnation.as_str(),
                config.telemetry_config().clone(),
            )?,
        };
        snapback.record_process_start_lifecycle();
        snapback.config = config;
        Ok(snapback)
    }

    fn telemetry_identity_for_target(
        db: &LocalDatabase,
        target: &crate::deploy::TargetDescriptor,
    ) -> SnapbackResult<crate::telemetry::TelemetryStoreIdentity> {
        crate::telemetry::TelemetryStoreIdentity::new(
            db.schema().app_id.clone(),
            target.environment_id.clone(),
        )
    }

    pub fn telemetry(&self) -> crate::telemetry::Telemetry {
        self.telemetry.clone()
    }

    /// Atomically claim this graph for the supported AppState composition
    /// seam and bind its already-resolved transport posture. A second claim
    /// fails before it can mutate profile or network state.
    pub fn claim_app_state_graph(
        &mut self,
        profile: ServerProfile,
        auth_deployment: crate::auth::deployment::AuthDeploymentTarget,
    ) -> SnapbackResult<EngineAppStateBindings> {
        if !self.db.claim_app_state_graph() {
            return Err(SnapbackError::error(
                "SNAPBACK_EMBED_APP_STATE_ALREADY_OWNED",
                "embed",
                "one SharedSnapback graph already belongs to an AppState; clone that AppState for additional routers",
            ));
        }
        self.server_profile = profile;
        self.auth_deployment = auth_deployment;
        Ok(EngineAppStateBindings {
            admission: self.admission.clone(),
            telemetry: self.telemetry.clone(),
            derived_instance_identity: self.derived_fork_identity().cloned(),
            connected_clients: ConnectedClientObserver {
                registry: self.connected_clients.clone(),
            },
            network_profiles: NetworkProfileView {
                state: self.network_profiles.clone(),
            },
            operator_authority: EngineOperatorAuthority {
                identity: self.operator_authority_identity.clone(),
            },
        })
    }

    fn network_profile_authority(&self) -> crate::network_profile::NetworkProfileAuthority {
        crate::network_profile::NetworkProfileAuthority::classified(
            self.server_profile,
            self.auth_deployment,
            self.hosted_serving_present,
            self.derived_fork_identity().is_some(),
        )
    }

    pub fn activate_startup_network_profile(
        &mut self,
        profile: crate::network_profile::NetworkConditionProfile,
    ) -> SnapbackResult<Arc<crate::network_profile::ActiveNetworkProfile>> {
        if self.network_profile_startup_activated {
            return Err(SnapbackError::error(
                "SNAPBACK_NETWORK_PROFILE_FORBIDDEN",
                "network-profile",
                "startup network profile activation is one-shot",
            ));
        }
        let active = self.network_profiles.activate(
            profile,
            self.network_profile_authority(),
            crate::network_profile::NetworkProfileSource::Env,
            None,
        )?;
        self.network_profile_startup_activated = true;
        Ok(active)
    }

    pub fn activate_operator_network_profile(
        &mut self,
        operator: &EngineOperatorAuthority,
        authority: &PreparedAuthority,
        profile: crate::network_profile::NetworkConditionProfile,
        source: crate::network_profile::NetworkProfileSource,
        principal: Option<String>,
    ) -> SnapbackResult<Arc<crate::network_profile::ActiveNetworkProfile>> {
        self.validate_operator_authority(operator, authority)?;
        if !matches!(
            source,
            crate::network_profile::NetworkProfileSource::Api
                | crate::network_profile::NetworkProfileSource::Console
                | crate::network_profile::NetworkProfileSource::HostOps
                | crate::network_profile::NetworkProfileSource::Mcp
        ) {
            return Err(SnapbackError::error(
                "SNAPBACK_NETWORK_PROFILE_FORBIDDEN",
                "network-profile",
                "runtime network profile activation requires an operator surface",
            ));
        }
        Ok(self.network_profiles.activate(
            profile,
            self.network_profile_authority(),
            source,
            principal,
        )?)
    }

    #[cfg(test)]
    pub(crate) fn install_network_profile_state(
        &mut self,
        state: crate::network_profile::NetworkProfileState,
    ) {
        self.network_profiles = state;
    }

    #[cfg(any(test, feature = "test-support"))]
    pub fn server_profile_for_test(&self) -> ServerProfile {
        self.server_profile
    }

    fn renew_live_subscription_observation(
        &mut self,
        subscription_id: &str,
        name: &str,
        connection_id: &str,
    ) {
        let telemetry = self.telemetry.clone();
        if let Some(stored) = self.subscriptions.get_mut(subscription_id) {
            stored.observation.finish(200, None, "resumed");
            let caller_details = stored.authority.telemetry_caller_details();
            stored.observation = LiveSubscriptionObservation::new(telemetry.start_classified_span(
                crate::telemetry_contract::OperationClassIdV1::LIVE_RESUBSCRIBE,
                name,
                Some(connection_id),
                caller_details,
            ));
        }
    }

    fn record_process_start_lifecycle(&self) {
        // @ref LLP 0154#d2--the-observation-span-classification-registry-and-phase-1-kinds —
        //   construction admits start only; readiness belongs to the actual
        //   bound-server or direct-service cut and cannot survive a later
        //   startup failure as a lie.
        self.telemetry.point_classified(
            crate::telemetry_contract::OperationClassIdV1::LIFECYCLE,
            "process_start",
            Some(200),
            None,
            None,
            None,
            crate::telemetry::Priority::Reserved,
        );
    }

    pub fn begin_telemetry_generation_transition(&self) {
        self.telemetry.begin_generation_transition();
    }

    pub fn rebind_telemetry_to_current_incarnation(
        &mut self,
        lifecycle_name: &str,
    ) -> SnapbackResult<()> {
        let incarnation = self.db.ensure_authorization_stream_incarnation()?;
        self.finish_telemetry_generation_transition(incarnation.as_str())?;
        self.telemetry.point_classified(
            crate::telemetry_contract::OperationClassIdV1::LIFECYCLE,
            lifecycle_name,
            Some(200),
            None,
            None,
            None,
            crate::telemetry::Priority::Reserved,
        );
        Ok(())
    }

    fn finish_telemetry_generation_transition(&mut self, incarnation: &str) -> SnapbackResult<()> {
        let Some(current) = self.telemetry_store_identity.as_ref() else {
            return self.telemetry.finish_generation_transition(incarnation);
        };
        let successor = crate::telemetry::TelemetryStoreIdentity::new(
            self.db.schema().app_id.clone(),
            current.environment_id().to_owned(),
        )?;
        self.telemetry
            .finish_generation_transition_with_identity(incarnation, successor.clone())?;
        self.telemetry_store_identity = Some(successor);
        Ok(())
    }

    /// Internal provider/lifecycle lane for protected auth transactions.
    /// Callers must acquire the auth-maintenance/address coordination guards
    /// before taking the outer app-instance lock that lends this database.
    /// This lends the non-owner database view, never `ServingDatabase` or its
    /// kernel-private fact-assertion root. The cloneable binding reachable from
    /// this view proves identity only and cannot mint admitted carriers.
    // @ref LLP 0057#catalog-write-and-lifecycle-rules — auth state bypasses app journals, receipts, versions, and live delivery.
    // @ref LLP 0057#concurrency-locks-and-linearization — provider coordination precedes the outer app/database lock.
    pub(crate) fn auth_database_mut(&mut self) -> &mut crate::storage::LocalDatabase {
        self.db.auth_database_mut()
    }

    /// Exact durable reset boundary used by rehearsal-grant instance binding.
    /// The value is the same UUIDv7 authorization-stream incarnation that
    /// reset rotates; it is not an app-addressable identifier.
    ///
    /// @ref LLP 0213#binding-validation — reset must invalidate a grant even
    ///   when the process, app id, and deployment bytes are otherwise equal.
    pub fn auth_rehearsal_instance_id(&self) -> SnapbackResult<String> {
        self.db
            .authorization_stream_incarnation()
            .map(|incarnation| incarnation.as_str().to_owned())
    }

    pub fn bind_auth_coordinator(
        &mut self,
        coordinator: &crate::auth::coordinator::AuthCoordinator,
    ) -> SnapbackResult<()> {
        let durable = self.db.authorization_stream_incarnation()?;
        if coordinator.authorization_stream_incarnation()? != durable.as_str() {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_PROJECTION_UNAVAILABLE",
                "auth",
                "the auth coordinator belongs to a different authorization stream",
            ));
        }
        self.auth_rehearsal_authority_binding = Some(coordinator.rehearsal_authority_binding()?);
        Ok(())
    }

