    /// Revalidate the exact finite service carrier while the caller owns the
    /// app lock. Terminal auth writers use that same outer lock and premark
    /// the process fence before commit, so a successful check linearizes every
    /// subsequent synchronous app effect in this lock hold before termination.
    pub fn validate_prepared_service_authority(
        &self,
        authority: &PreparedAuthority,
    ) -> SnapbackResult<()> {
        if let Some(principal) = authority.asset_callbacks_service() {
            let ResolvedAppAuthority::ServicePrincipal {
                actor_user_id,
                grant_id,
                ..
            } = authority.resolved()
            else {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                    "auth",
                    "asset-callbacks authority lost its service-principal identity",
                ));
            };
            if actor_user_id != &principal.actor_user_id
                || grant_id != &principal.grant_id
                || !self
                    .db
                    .asset_callbacks_service_principal_is_live(principal)?
            {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_GRANT_SCOPE_DENIED",
                    "auth",
                    "the asset-callbacks service-principal grant is no longer current",
                )
                .with_details(json!({ "reason": "terminally_invalid_entry" })));
            }
            return Ok(());
        }
        let ResolvedAppAuthority::ServicePrincipal {
            actor_user_id,
            effective_user_id,
            grant_id,
            token_id,
            credential_id,
            credential_generation,
            token_expires_at_ms,
            ..
        } = authority.resolved()
        else {
            return Ok(());
        };
        let (now_ms, monotonic_now) = authority.service_clock_sample(now_millis(), Instant::now());
        let witness = match authority.resolve_service_authority_act(now_ms, monotonic_now)? {
            Some(ServiceAuthorityActResolution::Current(witness)) => witness,
            Some(ServiceAuthorityActResolution::Terminal(disposition)) => {
                let wire = match disposition {
                    ServiceAuthorityDisposition::Carrier => "carrier",
                    ServiceAuthorityDisposition::DurableDelete => "durableDelete",
                };
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_SCOPED_TOKEN_INVALID",
                    "auth",
                    "scoped agent token authority is no longer current",
                )
                .with_details(json!({ "authorityDisposition": wire })));
            }
            Some(ServiceAuthorityActResolution::Unavailable) => {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                    "auth",
                    "finite service authority termination is unresolved",
                ));
            }
            None => {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                    "auth",
                    "finite service authority has no exact process fence",
                ));
            }
        };
        if witness.actor_user_id() != actor_user_id
            || witness.effective_user_id() != effective_user_id.as_deref()
            || witness.grant_id() != grant_id
            || witness.token_id() != token_id
            || witness.credential_id() != credential_id
            || witness.credential_generation() != *credential_generation
            || witness.expires_at_ms() != *token_expires_at_ms
        {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                "auth",
                "finite service authority disagrees with its exact process fence",
            ));
        }
        // @ref LLP 0055#dated-amendment-llp-0204-integration-registrations-and-watch-anchors-2026-08-08 — re-read reversible integration admission under the app lock so suspension is named rather than collapsed into revocation/carrier churn.
        self.db
            .require_active_integration_if_present(actor_user_id)?;
        if !self.db.retained_service_authority_is_live_readonly(
            crate::storage::auth_agent_credentials::RetainedServiceAuthority {
                actor_user_id,
                credential_id,
                credential_generation: *credential_generation,
                grant_id,
                token_id,
                effective_user_id: effective_user_id.as_deref(),
            },
            now_ms,
        )? {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_SCOPED_TOKEN_INVALID",
                "auth",
                "scoped agent token authority is no longer current",
            )
            .with_details(json!({ "authorityDisposition": "carrier" })));
        }
        Ok(())
    }

    pub(crate) fn persist_and_validate_prepared_service_authority(
        &mut self,
        authority: &PreparedAuthority,
    ) -> SnapbackResult<()> {
        self.persist_service_deadline_if_due(authority)?;
        self.validate_prepared_service_authority(authority)
    }

    pub fn persist_service_deadline_if_due(
        &mut self,
        authority: &PreparedAuthority,
    ) -> SnapbackResult<()> {
        let (now_ms, monotonic_now) = authority.service_clock_sample(now_millis(), Instant::now());
        if let Some(deadline) =
            authority.expired_service_deadline_terminal(now_ms, monotonic_now)?
        {
            // A managed server caller cannot terminalize while it owns Local:
            // the exact async gate must close/drain every affected token before
            // the write, and the independently owned server task must retain the
            // complete token set through lifecycle propagation. Fail this act
            // closed; the registered HTTP middleware or live observer performs
            // that owned terminal transaction after Local is released. Direct
            // embedders have no retained server lifecycle graph and preserve the
            // synchronous persistence seam below.
            //
            // @ref LLP 0059#finite-service-authority-fence — process premark,
            // drain, durable write, and propagation are one owned choreography.
            if crate::exec_guard::local_write_scope_active() {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                    "auth",
                    "finite service authority expiry requires the owned terminal path",
                ));
            }
            self.db.terminalize_expired_service_authority(&deadline)?;
        }
        Ok(())
    }

    /// Host-owned StreamAttemptV1 persistence (LLP 0076): the detached action
    /// host performs these short writes under the instance lock. The durable
    /// row — not the in-process registry — is what the startup reconciler
    /// reads after a crash, so the pre-mark must commit before the upstream
    /// send.
    pub fn stream_attempt_record(
        &self,
        client_key: &str,
    ) -> SnapbackResult<Option<(String, String)>> {
        self.db
            .settlement_read()
            .stream_attempt_by_client_key(client_key)
    }

    pub fn stream_attempt_namespace(&self) -> usize {
        self.stream_attempt_namespace
    }

    /// Resolve every declared capability requirement against the served
    /// instance manifest (LLP 0076 §Target contract): the same
    /// instance-live declaration `/inspect` reports, never a static
    /// committed artifact. Unknown (non-registry) strings are left to the
    /// v1 grammar validation; a registry id the live instance does not
    /// support is a fatal admission error.
    fn validate_required_capabilities_against_instance(
        &self,
        manifest: &FunctionManifest,
    ) -> Vec<Diagnostic> {
        let served = crate::manifest::CapabilityManifest::local_v0_instance(
            self.capability_gaps(),
            crate::runtime::outbound_actions_enabled(),
        );
        // @ref LLP 0058#capability-maturity — an experimental entry is not
        // plain support: the requirement admits only when the artifact
        // acknowledges the experimental contract it binds to.
        let acknowledged = manifest.acknowledged_capability_ids();
        let mut diagnostics = Vec::new();
        let mut check = |owner: &str, capability: &str| {
            let Ok(id) = capability.parse::<crate::manifest::TargetCapabilityId>() else {
                return;
            };
            if !served.supported_capabilities.contains(&id) {
                diagnostics.push(Diagnostic::error(
                    "SNAPBACK_CAPABILITY_UNSUPPORTED",
                    "runtime",
                    format!(
                        "{owner} requires capability {capability}, which the served instance manifest does not support"
                    ),
                ));
            } else if id.maturity() != crate::manifest::CapabilityMaturity::Stable
                && !acknowledged.contains(&id)
            {
                diagnostics.push(Diagnostic::error(
                    "SNAPBACK_CAPABILITY_UNSUPPORTED",
                    "runtime",
                    format!(
                        "{owner} requires capability {capability}, which this target supports only at {} maturity; the artifact must list it in acknowledgedExperimentalCapabilities",
                        id.maturity().as_str()
                    ),
                ));
            }
        };
        for function in &manifest.functions {
            for capability in &function.required_capabilities {
                check(&format!("function {}", function.name), capability);
            }
        }
        for job in &manifest.cron_jobs {
            for capability in &job.required_capabilities {
                check(&format!("cron job {}", job.name), capability);
            }
        }
        diagnostics
    }

    pub fn persist_stream_attempts(
        &mut self,
        rows: &[(String, String, String)],
    ) -> SnapbackResult<()> {
        self.db
            .settlement()
            .upsert_stream_attempts(rows, now_millis())
    }

    pub fn settle_stream_transcript(
        &mut self,
        record: &crate::storage::stream_transcripts::StreamTranscriptRecord,
    ) -> SnapbackResult<()> {
        self.db.settle_stream_transcript(record)
    }

    pub fn stream_transcript(
        &self,
        attempt_token: &str,
    ) -> SnapbackResult<Option<crate::storage::stream_transcripts::StreamTranscriptRecord>> {
        self.db.stream_transcript(attempt_token)
    }

    /// Revalidate the durable and carrier axes before every retained live
    /// computation. Session authority is fenced by the projection; service
    /// authority is checked directly against the protected catalog without
    /// recovering or retaining its bearer.
    // @ref LLP 0055#ending-authority-revocation-expiry-deactivation — retained service authority and immutable scope shapes end as host-trusted terminal deletes.
    fn prepare_live_rerun_authority(
        &mut self,
        retained: &RetainedLiveAuthority,
        admission: AdmissionLease,
    ) -> SnapbackResult<PreparedAuthority> {
        if let ResolvedAppAuthority::ServicePrincipal {
            actor_user_id,
            credential_id,
            credential_generation,
            grant_id,
            token_id,
            effective_user_id,
            ..
        } = retained.resolved()
        {
            // @ref LLP 0055#dated-amendment-llp-0204-integration-registrations-and-watch-anchors-2026-08-08 — a retained live computation observes current suspension as an admission refusal without deleting its durable installation.
            self.db
                .require_active_integration_if_present(actor_user_id)?;
            if !self.db.retained_service_authority_is_live(
                crate::storage::auth_agent_credentials::RetainedServiceAuthority {
                    actor_user_id,
                    credential_id,
                    credential_generation: *credential_generation,
                    grant_id,
                    token_id,
                    effective_user_id: effective_user_id.as_deref(),
                },
                now_millis(),
            )? {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_SCOPED_TOKEN_INVALID",
                    "auth",
                    "the retained service-principal authority is no longer current",
                )
                .into_trusted_permission_denial());
            }
            let scope = retained.matched_grant_scope().ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_AUTH_GRANT_SCOPE_DENIED",
                    "auth",
                    "the retained live owner has no exact function scope",
                )
                .with_details(json!({ "reason": "missing_retained_entry" }))
                .into_trusted_permission_denial()
            })?;
            let current = self.db.current_auth_scope_basis(
                scope.function_id(),
                scope.kind(),
                scope.authority_creating(),
            )?;
            if current != Some(scope.basis()) {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_GRANT_SCOPE_DENIED",
                    "auth",
                    "the retained grant scope is terminally invalid",
                )
                .with_details(json!({ "reason": "terminally_invalid_entry" }))
                .into_trusted_permission_denial());
            }
        }
        let session_claims = self.session_claims_for_authority(
            retained.resolved(),
            retained.profile(),
            now_millis(),
        )?;
        let prepared = retained.prepare_rerun(admission, session_claims)?;
        self.persist_and_validate_prepared_service_authority(&prepared)?;
        Ok(prepared)
    }

    fn live_evaluation_memo_authority_component(
        auth: &AuthInput,
        projection: &HandlerAuthProjection,
        authority_identity: &str,
    ) -> Option<String> {
        // `AuthInput`'s public wire serializer deliberately skips the
        // server-owned authorization projection. Those facts remain runtime
        // inputs, so spell out every field alongside the complete sealed
        // handler projection and the bearer-free prepared-authority identity.
        let AuthInput {
            principal,
            session_id,
            user_id,
            authorization_kind,
            authorization_actor_kind,
            authorization_activity_actor_kind,
            authorization_actor_user_id,
            authorization_grant_id,
            client_mutation_id,
            client_mutation_digest,
            authorization_is_delegated,
        } = auth;
        crate::watches::canonical_json(&json!({
            "authInput": {
                "principal": principal.as_deref(),
                "sessionId": session_id.as_deref(),
                "userId": user_id.as_deref(),
                "authorizationKind": authorization_kind.as_deref(),
                "authorizationActorKind": authorization_actor_kind.as_deref(),
                "authorizationActivityActorKind": authorization_activity_actor_kind.as_deref(),
                "authorizationActorUserId": authorization_actor_user_id.as_deref(),
                "authorizationGrantId": authorization_grant_id.as_deref(),
                "clientMutationId": client_mutation_id.as_deref(),
                "clientMutationDigest": client_mutation_digest.as_deref(),
                "authorizationIsDelegated": authorization_is_delegated,
            },
            "handlerProjection": projection,
            "authorityIdentity": authority_identity,
        }))
        .ok()
    }

    fn live_evaluation_memo_key(
        &mut self,
        subscription: &LiveSubscription,
        authority: &PreparedAuthority,
    ) -> Option<LiveEvaluationMemoKey> {
        if self.pending_live_fanout.evaluation_memo.disabled {
            return None;
        }
        // Exhaustive on purpose: a future HandlerInput field must be assigned
        // to the key, the refusal rule, or a documented result-irrelevant
        // category before this compiles again. `read_set` is mutation OCC
        // metadata and query execution does not consume it; `correlation` is
        // telemetry/receipt metadata and is never exposed to the handler.
        let HandlerInput {
            args,
            auth,
            read_set: _,
            correlation: _,
            ctx_ledger,
        } = &subscription.input;
        if ctx_ledger.is_some() {
            return None;
        }
        let cut_version = self
            .current_live_evaluation
            .as_ref()
            .map(|evaluation| evaluation.cut_version)?;
        let canonical_arguments = crate::watches::canonical_json(args).ok()?;
        let authority_component = Self::live_evaluation_memo_authority_component(
            auth,
            authority.projection(),
            &authority.resolved().invalidation_subject(),
        )?;
        // @ref LLP 0209#6 — within one drain cycle, sharing is the specified
        // one-evaluation-turn/N-delivery mechanism for exact function/plan
        // generation + canonical args + handler-visible prepared authority +
        // the scheduler's atomic evaluation cut. Cross-cycle reuse is refused:
        // without a ctx-answer ledger, host now, fresh IDs, and warm-pool
        // module state are not proven identical across cycles under LLP 0190
        // §4.3's complete-inputs standard. The containing scheduler makes
        // LocalSnapback instance identity implicit.
        let key = LiveEvaluationMemoKey {
            drain_cycle: self.pending_live_fanout.drain_cycle,
            function_generation: self.app_generation,
            function: subscription.function.clone(),
            canonical_arguments,
            authority: authority_component,
            cut_version,
        };
        #[cfg(test)]
        {
            self.pending_live_fanout.evaluation_memo.keys_built = self
                .pending_live_fanout
                .evaluation_memo
                .keys_built
                .saturating_add(1);
        }
        Some(key)
    }

    fn invoke_live_subscription_query(
        &mut self,
        subscription: &LiveSubscription,
        authority: PreparedAuthority,
    ) -> SnapbackResult<QueryInvocation> {
        // Generation admission is a per-subscription gate, not part of the
        // evaluation turn, and therefore still runs on a memo hit.
        self.validate_expected_generation(&authority, subscription.expected_generation.as_ref())?;
        let key = self.live_evaluation_memo_key(subscription, &authority);
        if let Some(key) = key.as_ref()
            && let Some((cached, evictions)) = self
                .pending_live_fanout
                .evaluation_memo
                .get(key, &subscription.id)
        {
            // @ref LLP 0209#6 — a hit skips only the query invocation. The
            // caller continues through the subscription-specific authority
            // gate, obligations, dependency update, serialization, and
            // delivery path with an oracle-exact cloned QueryInvocation.
            self.live_evaluation_stats.memo_hits =
                self.live_evaluation_stats.memo_hits.saturating_add(1);
            self.live_evaluation_stats.memo_evictions = self
                .live_evaluation_stats
                .memo_evictions
                .saturating_add(evictions);
            return Ok(cached);
        }
        if key.is_some() {
            self.live_evaluation_stats.memo_misses =
                self.live_evaluation_stats.memo_misses.saturating_add(1);
        }
        self.live_evaluation_stats.evaluations_executed = self
            .live_evaluation_stats
            .evaluations_executed
            .saturating_add(1);

        let result = if is_reserved_live_function(&subscription.function) {
            self.reserved_live_invocation(&authority, &subscription.function, &subscription.input)
        } else {
            self.invoke_query_with_dependencies_prepared_generation(
                &subscription.function,
                subscription.input.clone(),
                authority,
                subscription.expected_generation.as_ref(),
            )
        }?;

        let turn_is_publishable = self
            .current_live_evaluation
            .as_ref()
            .is_some_and(|evaluation| !evaluation.control.is_abandoned());
        if turn_is_publishable && let Some(key) = key {
            let evictions = self.pending_live_fanout.evaluation_memo.insert(
                key,
                &subscription.id,
                &result,
                &mut self.live_evaluation_stats.memo_oversize_refusals,
            );
            self.live_evaluation_stats.memo_evictions = self
                .live_evaluation_stats
                .memo_evictions
                .saturating_add(evictions);
        }
        Ok(result)
    }

    /// Resolve the claims half of the authority projection from the protected
    /// catalog. Every caller then hands the resolved authority and this value
    /// to the one `HandlerAuthProjection::from_authority` constructor, which
    /// rejects either a session omission or a non-session claim injection.
    ///
    /// @ref LLP 0214#62-projection-rules — a real catalog session projects
    /// claims in its first snapshot; non-session authority cannot acquire them.
    fn session_claims_for_authority(
        &mut self,
        resolved: &ResolvedAppAuthority,
        profile: ServerProfile,
        now_ms: u64,
    ) -> SnapbackResult<Option<crate::auth::identity_core::AuthClaimsProjection>> {
        resolved
            .session_id()
            .map(|session_id| self.db.identity_claims(session_id, now_ms, profile))
            .transpose()
    }

    #[allow(clippy::too_many_arguments)]
    fn prepare_resolved_authority(
        &mut self,
        source: InvocationSource,
        active_mode: AuthMode,
        profile: ServerProfile,
        admission: AdmissionLease,
        wire: &WireAuthorityFields,
        resolved: ResolvedAppAuthority,
        now_ms: u64,
    ) -> SnapbackResult<PreparedAuthority> {
        let session_claims = self.session_claims_for_authority(&resolved, profile, now_ms)?;
        InvocationGate::prepare_admitted_authority(
            source,
            active_mode,
            profile,
            admission,
            wire,
            resolved,
            session_claims,
        )
    }

    #[allow(clippy::too_many_arguments)]
    pub fn prepare_anonymous_authority(
        &mut self,
        source: InvocationSource,
        active_mode: AuthMode,
        profile: ServerProfile,
        admission: AdmissionLease,
        wire: &WireAuthorityFields,
        now_ms: u64,
        publication: Option<crate::auth::session_projection::FencedPublication>,
    ) -> SnapbackResult<PreparedAuthority> {
        let authority = self.prepare_resolved_authority(
            source,
            active_mode,
            profile,
            admission,
            wire,
            ResolvedAppAuthority::Anonymous,
            now_ms,
        )?;
        Ok(match publication {
            Some(publication) => authority.with_fenced_publication(publication),
            None => authority,
        })
    }

    #[allow(clippy::too_many_arguments)]
    pub fn prepare_dev_authority(
        &mut self,
        source: InvocationSource,
        profile: ServerProfile,
        admission: AdmissionLease,
        wire: &WireAuthorityFields,
        resolved: ResolvedAppAuthority,
        now_ms: u64,
    ) -> SnapbackResult<PreparedAuthority> {
        if !self.admission.owns_lease(&admission) {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                "auth",
                "dev authority admission belongs to another engine graph",
            ));
        }
        if source == InvocationSource::OperatorCommand {
            return Err(SnapbackError::error(
                "SNAPBACK_INVOCATION_SOURCE_INVALID",
                "auth",
                "operator authority requires the composition-owned operator carrier",
            ));
        }
        if !matches!(
            resolved,
            ResolvedAppAuthority::Anonymous | ResolvedAppAuthority::DevImpersonation { .. }
        ) {
            return Err(SnapbackError::error(
                "SNAPBACK_INVOCATION_AUTHORITY_INVALID",
                "auth",
                "dev authority preparation accepts only the closed dev authority classes",
            ));
        }
        self.prepare_resolved_authority(
            source,
            AuthMode::Dev,
            profile,
            admission,
            wire,
            resolved,
            now_ms,
        )
    }

    #[allow(clippy::too_many_arguments)]
    pub fn prepare_admin_authority(
        &mut self,
        source: InvocationSource,
        profile: ServerProfile,
        admission: AdmissionLease,
        wire: &WireAuthorityFields,
        now_ms: u64,
        publication: crate::auth::session_projection::FencedPublication,
    ) -> SnapbackResult<PreparedAuthority> {
        if !matches!(
            source,
            InvocationSource::DirectAdminRunner
                | InvocationSource::HostOperationFunctionRun
                | InvocationSource::HostOperationMutationDryRun
                | InvocationSource::ProtectedRecordErasure
                | InvocationSource::OperationCoverageActivation
        ) {
            return Err(SnapbackError::error(
                "SNAPBACK_INVOCATION_SOURCE_INVALID",
                "auth",
                "administrative authority requires an exact registered admin source",
            ));
        }
        self.prepare_resolved_authority(
            source,
            AuthMode::Sessions,
            profile,
            admission,
            wire,
            ResolvedAppAuthority::AdminBypass {
                reason: "administrative application invocation".to_owned(),
            },
            now_ms,
        )
        .map(|authority| authority.with_fenced_publication(publication))
    }

    pub fn prepare_operator_authority(
        &mut self,
        operator: &EngineOperatorAuthority,
        admission: AdmissionLease,
        wire: &WireAuthorityFields,
        now_ms: u64,
        publication: Option<crate::auth::session_projection::FencedPublication>,
    ) -> SnapbackResult<PreparedAuthority> {
        if !Arc::ptr_eq(&operator.identity, &self.operator_authority_identity) {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_REQUIRED",
                "auth",
                "operator authority belongs to a different engine graph",
            ));
        }
        let active_mode = admission.active_mode().ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                "auth",
                "operator authority requires a settled auth-mode admission",
            )
        })?;
        let resolved = match (active_mode, publication.as_ref()) {
            (AuthMode::Dev, None) => ResolvedAppAuthority::Anonymous,
            (AuthMode::Sessions, Some(_)) => ResolvedAppAuthority::AdminBypass {
                reason: "administrative application invocation".to_owned(),
            },
            _ => {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                    "auth",
                    "operator authority publication does not match the active auth mode",
                ));
            }
        };
        let authority = self.prepare_resolved_authority(
            InvocationSource::OperatorCommand,
            active_mode,
            self.server_profile,
            admission,
            wire,
            resolved,
            now_ms,
        )?;
        Ok(match publication {
            Some(publication) => authority.with_fenced_publication(publication),
            None => authority,
        })
    }

