    /// Cloneable process-local admission authority for HTTP composition.
    // Retained as the direct LocalSnapback embedding seam; the production
    // router currently obtains the same controller from its ReadLane.
    #[allow(dead_code)]
    pub(crate) fn admission_controller(&self) -> AdmissionController {
        self.admission.clone()
    }

    /// Compatibility embedding seam: legacy callers may request dev
    /// authority only through this instance's exact-mode controller. A
    /// settled Sessions instance rejects the request before app code runs.
    pub(crate) fn prepare_legacy_dev_authority(
        &self,
        source: InvocationSource,
        profile: ServerProfile,
        input: &HandlerInput,
    ) -> SnapbackResult<PreparedAuthority> {
        InvocationGate::prepare_admitted_dev_input(
            source,
            profile,
            input,
            self.admission.admit_dev()?,
        )
    }

    /// Mint/resolve the per-app bearer-free callback service and prepare its
    /// exact mutation scope under the current sessions admission epoch.
    ///
    /// @ref LLP 0055#dated-amendment-per-app-asset-callbacks-service-principal-2026-08-03
    ///   — callbacks receive a protected-catalog principal plus an immutable
    ///   exact-function grant, never the asset owner's session authority.
    fn prepare_asset_callbacks_authority(
        &mut self,
        handler: &str,
    ) -> SnapbackResult<PreparedAuthority> {
        let function = self.function(handler)?.clone();
        let kind =
            crate::storage::auth_grants::ScopedFunctionKind::from_function_kind(&function.kind)
                .filter(|kind| {
                    matches!(
                        kind,
                        crate::storage::auth_grants::ScopedFunctionKind::Mutation
                    )
                })
                .ok_or_else(|| {
                    SnapbackError::error(
                        "SNAPBACK_ASSET_CALLBACK_INVALID",
                        "assets",
                        "an asset lifecycle callback must remain a declared mutation",
                    )
                })?;
        let basis = self
            .db
            .current_auth_scope_basis(&function.id, &function.kind, function.authority_creating)?
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_AUTH_GRANT_SCOPE_DENIED",
                    "auth",
                    "the callback mutation has no current exact-function scope basis",
                )
                .with_details(json!({ "reason": "missing_scope_basis" }))
            })?;
        let scope = crate::storage::auth_grants::ExactGrantScope {
            function_id: function.id,
            kind,
            basis,
            authority_creating: function.authority_creating,
        };
        let app_id = self.functions.app_id.clone();
        let principal =
            self.db
                .ensure_asset_callbacks_service_principal(&app_id, scope, now_millis())?;
        InvocationGate::prepare_admitted_asset_callbacks(
            ServerProfile::Dev,
            self.admission.admit_for_mode(AuthMode::Sessions)?,
            principal,
        )
    }

    /// Close app-data/cron/live/nested admission and wait for the finite
    /// current epoch before a staged-mode transaction takes the write lane.
    // Retained for embedders that stage directly against LocalSnapback; the
    // shipped router begins transitions through its cloned controller.
    #[allow(dead_code)]
    pub(crate) fn begin_auth_mode_transition(&self) -> SnapbackResult<ModeTransitionGuard> {
        self.admission.begin_transition()
    }

    /// Activate a preflighted sessions successor during cold startup. The
    /// transport adapter retains only diagnostic presentation; transition
    /// admission and the durable same-mode cut remain inside the engine.
    pub fn activate_startup_sessions_successor(
        &mut self,
        carrier: &crate::auth::mode::StartupArtifacts,
        expected: &crate::auth::mode::DeploymentIdentity,
        observed: &crate::auth::mode::DeploymentIdentity,
    ) -> SnapbackResult<crate::auth::mode::AuthModeStateRecord> {
        use crate::auth::admission::ModeCommitFailure;
        use crate::manifest::AuthMode;

        let transition = self.begin_auth_mode_transition()?;
        let repeated = transition.repeat_preflight(|| {
            let snapshot = self.db.auth_mode_snapshot()?;
            if snapshot.state.active != AuthMode::Sessions
                || snapshot.state.active_deployment.as_ref() != Some(expected)
            {
                return Err(crate::auth::mode::mode_corrupt(
                    "settled sessions deployment changed before startup successor activation",
                ));
            }
            self.preflight_auth_artifacts(carrier, AuthMode::Sessions)
        })?;
        if repeated != *observed {
            return Err(crate::auth::mode::mode_corrupt(
                "startup successor identity changed between complete-pair preflight passes",
            ));
        }

        let publication_generation = self.reserve_function_publication_generation()?;
        let schema = carrier.schema.clone();
        let functions = carrier.functions.clone();
        let deployment = observed.clone();
        let ((), state, _) = transition.commit_and_publish_mode_state(|| {
            let committed = crate::generation_activation::GenerationActivation::new(self)
                .activate_same_mode_network_generation(
                    deployment,
                    schema,
                    functions,
                    None,
                    publication_generation,
                    DiagnosticBoundary::Standalone,
                )?;
            let state = committed.commit.state.clone();
            Ok::<_, ModeCommitFailure>(((), state))
        })?;
        Ok(state)
    }

    /// Pre-bind only: align process admission with the final durable record
    /// after startup composition may have staged, consumed, or unstaged it.
    #[cfg(any(test, feature = "test-support"))]
    pub fn synchronize_auth_mode_admission(
        &self,
        state: &crate::auth::mode::AuthModeStateRecord,
    ) -> SnapbackResult<crate::auth::admission::AdmissionSnapshot> {
        self.admission.synchronize_mode_state(state)
    }

    /// Validate one complete cold-start/provisioning pair without changing
    /// schema, functions, cron, config, or auth-mode state. The returned
    /// identity is safe to pin durably only because every artifact-owned and
    /// target-owned predicate has already run against these exact values.
    // @ref LLP 0058#complete-candidate-pair-preflight — hashes are evidence only after the complete pair and target capability registry validate.
    pub fn preflight_auth_artifacts(
        &mut self,
        artifacts: &StartupArtifacts,
        requested_mode: AuthMode,
    ) -> SnapbackResult<DeploymentIdentity> {
        if artifacts.format_version != STARTUP_ARTIFACT_FORMAT_VERSION {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_STARTUP_ARTIFACT_MISMATCH",
                "auth",
                "startup artifact carrier has an unsupported format",
            ));
        }
        artifacts.schema.validate_artifact()?;
        artifacts.functions.validate_artifact()?;
        artifacts
            .functions
            .validate_media_commands_against_schema(&artifacts.schema)?;
        artifacts
            .schema
            .validate_api_against_functions(&artifacts.functions)?;
        if let Some(push_seam) = &artifacts.schema.push_seam {
            crate::push::validate_config_uses(push_seam, &artifacts.functions)?;
        }
        validate_collection_definitions(&artifacts.schema.ephemeral_collections)
            .map_err(ephemeral_manifest_error)?;
        validate_collection_permission_backing(
            &artifacts.schema.ephemeral_collections,
            &artifacts.schema.tables,
            requested_mode == AuthMode::Sessions,
        )
        .map_err(ephemeral_manifest_error)?;

        let deployment = artifacts.deployment_identity(requested_mode)?;
        // @ref LLP 0234#d3--widening-requires-a-remotely-prior-artifact-closed-approval-receipt
        // activation consumes target-owned custody and the exact derived
        // deployment identity before any durable schema/function cut. A
        // request or bundle field cannot supply these inputs.
        let _governance_warnings = crate::visibility_governance::validate_activation_from_target(
            &artifacts.schema,
            &artifacts.functions,
            self.server_profile,
            now_millis(),
            None,
        )?;
        // @ref LLP 0076#target-contract — cold-start capability admission
        // composes the candidate pair with the exact process's live egress
        // fact, just like `/inspect` and ordinary function loading. The
        // conservative committed declaration is not authority for a process
        // that explicitly enabled outbound actions.
        let target = CapabilityManifest::local_v0_instance(
            self.capability_gaps(),
            crate::runtime::outbound_actions_enabled(),
        );
        // @ref LLP 0058#capability-maturity — the artifact pair's
        // experimental acknowledgments (declared on the function manifest,
        // covering the pair) accompany every requirement, including the
        // schema-level ones: schema and functions are one generated unit.
        let acknowledged = artifacts.functions.acknowledged_capability_ids();
        target.require_capabilities(
            artifacts
                .schema
                .required_capabilities
                .iter()
                .map(String::as_str)
                .chain(
                    artifacts.functions.functions.iter().flat_map(|function| {
                        function.required_capabilities.iter().map(String::as_str)
                    }),
                )
                .chain(
                    artifacts
                        .functions
                        .cron_jobs
                        .iter()
                        .flat_map(|job| job.required_capabilities.iter().map(String::as_str)),
                ),
            &acknowledged,
        )?;
        validate_function_schema_references(&artifacts.functions, &artifacts.schema)?;
        let cron_diagnostics = validate_cron_manifest(&artifacts.functions);
        if let Some(diagnostic) = cron_diagnostics.iter().find(|diagnostic| {
            matches!(
                diagnostic.severity,
                DiagnosticSeverity::Error | DiagnosticSeverity::Fatal
            )
        }) {
            return Err(SnapbackError::new(diagnostic.clone()));
        }
        if requested_mode == AuthMode::Sessions {
            // This read-only shape check catches exact-object and dormant
            // namespace collisions before staging can make the app pending.
            self.db.inspect_auth_catalog()?;
        }
        for function in &artifacts.functions.functions {
            if let FunctionRuntime::IbexModule(module) = &function.runtime {
                crate::runtime::prepare_ibex_module(module, &function.kind)?;
            }
        }
        self.remember_preflighted_pair(
            deployment.clone(),
            artifacts.schema.clone(),
            artifacts.functions.clone(),
        );
        Ok(deployment)
    }

    fn remember_preflighted_pair(
        &mut self,
        deployment: DeploymentIdentity,
        schema: SchemaManifest,
        functions: FunctionManifest,
    ) {
        self.preflighted_artifact_pairs
            .retain(|pair| pair.deployment != deployment);
        self.preflighted_artifact_pairs
            .push_back(PreflightedArtifactPair {
                deployment,
                schema,
                prepared_functions: PreparedFunctionGeneration {
                    manifest: functions,
                },
            });
        while self.preflighted_artifact_pairs.len() > 2 {
            self.preflighted_artifact_pairs.pop_front();
        }
    }

    pub(crate) fn install_auth_invalidation(
        &mut self,
        issuer: LiveInvalidationIssuer,
        authorization: crate::storage::AuthorizationVersion,
        version_stream: String,
    ) -> SnapbackResult<()> {
        issuer.install_authorization_expectation(authorization.clone())?;
        issuer.install_version_stream(version_stream.clone())?;
        let obligations = ObligationRegistry::new(ObligationExpectation {
            authorization,
            version_stream: Some(version_stream.clone()),
            issuer_id: Some(issuer.authenticated().issuer_id.clone()),
        })?;
        self.auth_invalidation = Some(LocalInvalidationState {
            issuer: issuer.clone(),
            obligations,
            version_stream,
            next_cause_sequence: 1,
        });
        let ephemeral = self.ephemeral.clone();
        crate::exec_guard::run_or_defer_after_local(move || {
            ephemeral.install_authorization_issuer(issuer);
        });
        self.db.enable_authorization_commit_interlock()?;
        Ok(())
    }

    /// Remove every process-local issuer projection after a durable reset
    /// whose successor cannot be reconstructed exactly. The coordinator stays
    /// globally closed; clearing both query and room leaves no lower-level
    /// embedding path holding a usable issuer for either incarnation.
    fn clear_auth_invalidation_after_failed_reset(&mut self) {
        self.auth_invalidation = None;
        let ephemeral = self.ephemeral.clone();
        crate::exec_guard::run_or_defer_after_local(move || {
            ephemeral.clear_authorization_issuer();
        });
    }

    /// Reserve, authenticate, and install the boot-local invalidation issuer
    /// without exposing the intermediate database reservation. The provider
    /// is the opaque key-custody authority; an optional reset carrier exact-
    /// matches the already-committed successor incarnation.
    pub fn install_authenticated_auth_invalidation(
        &mut self,
        provider: &crate::auth::provider::AuthProvider,
        reset_successor: Option<&str>,
    ) -> SnapbackResult<EngineInvalidationBinding> {
        let attempt = (|| {
            let schema = self.db.schema();
            let app_id = schema.app_id.clone();
            let target_profile_id = schema.target_profile.clone().unwrap_or_else(|| {
                crate::manifest::TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX.to_owned()
            });
            let (authorization, version_stream, boot_sequence) =
                self.db.reserve_invalidation_boot_issuer()?;
            if let Some(reset_successor) = reset_successor
                && authorization.incarnation != reset_successor
            {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_PROJECTION_UNAVAILABLE",
                    "auth",
                    "reset successor issuer reservation observed another authorization incarnation",
                ));
            }
            let issuer_id = crate::auth::invalidation::IssuerId::fresh(
                authorization.incarnation.clone(),
                boot_sequence,
            )?;
            let issuer = provider
                .authenticate_invalidation_boot_issuer(issuer_id, &target_profile_id, &app_id)
                .map_err(crate::auth::provider::ProviderError::into_snapback_error)?;
            self.install_auth_invalidation(issuer.clone(), authorization, version_stream)?;
            Ok(EngineInvalidationBinding { issuer })
        })();
        if attempt.is_err() && reset_successor.is_some() {
            self.clear_auth_invalidation_after_failed_reset();
        }
        attempt
    }

    /// Clear a just-installed reset issuer only when the caller returns the
    /// exact authenticated issuer currently held by this instance.
    pub fn clear_installed_auth_invalidation(
        &mut self,
        binding: &EngineInvalidationBinding,
    ) -> SnapbackResult<()> {
        let matches = self.auth_invalidation.as_ref().is_some_and(|state| {
            state.issuer.authenticated().issuer_id == binding.issuer.authenticated().issuer_id
        });
        if !matches {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_PROJECTION_UNAVAILABLE",
                "auth",
                "auth invalidation issuer does not match the installed reset successor",
            ));
        }
        self.clear_auth_invalidation_after_failed_reset();
        Ok(())
    }

    /// Compatibility orchestration for synchronous embedders that own a
    /// `LocalSnapback` directly instead of entering through the managed server
    /// write lane. The room dependency is installed and quiesced before the
    /// logical Local scope begins; SQLite may only bind that already-prepared
    /// carrier. Committed issuer/notifier/room effects are then drained after
    /// the scope ends, even when the transaction body unwinds.
    ///
    /// Managed callers already own a `LocalSnapbackWriteScope` and must have
    /// installed their exact carrier before taking Local. In that case this
    /// helper deliberately does no fallback work: in-lock action/nested seams
    /// must be routed through their own staged protocol, never hidden behind a
    /// second reservation.
    ///
    /// @ref LLP 0059#locking-and-linearization — direct and managed writes use
    /// the same off-Local reservation and after-Local publication boundary.
    fn try_with_direct_authorization_write<R>(
        &mut self,
        preflight: crate::storage::AuthorizationCommitPreflight,
        work: impl FnOnce(&mut Self) -> R,
    ) -> SnapbackResult<R> {
        if crate::exec_guard::local_write_scope_active() {
            return Ok(work(self));
        }

        let cancellation =
            Arc::new(crate::storage::AuthorizationReservationCancellation::default());
        let reservation = self
            .ephemeral
            .reserve_authorization_commit(preflight, cancellation)?;
        let reservation_scope = reservation.install();

        let mut local_scope = crate::exec_guard::LocalSnapbackWriteScope::enter();
        let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| work(self)));
        let unused = reservation_scope.take_unused();
        let after_local = local_scope.take_after_local_batch();
        drop(local_scope);

        if let Some(unused) = unused {
            unused.cancel();
        }
        crate::exec_guard::run_after_local_batch(after_local);

        match outcome {
            Ok(output) => Ok(output),
            Err(panic) => std::panic::resume_unwind(panic),
        }
    }

    pub fn apply_schema(&mut self, manifest: SchemaManifest) -> SnapbackResult<Vec<Diagnostic>> {
        manifest.validate_artifact()?;
        if manifest
            .visibility_governance
            .as_ref()
            .is_some_and(|governance| governance.required)
        {
            return Err(SnapbackError::error(
                "SNAPBACK_TABLE_VISIBILITY_GOVERNANCE_REMOTE_CUSTODY_UNAVAILABLE",
                "auth",
                "a governed visibility program requires complete-pair activation with a target-owned protected observer verdict",
            ));
        }
        if self.functions_loaded {
            manifest.validate_api_against_functions(&self.functions)?;
        }
        if self.functions_loaded
            && let Some(push_seam) = &manifest.push_seam
        {
            crate::push::validate_config_uses(push_seam, &self.functions)?;
        }
        validate_collection_definitions(&manifest.ephemeral_collections)
            .map_err(ephemeral_manifest_error)?;
        validate_collection_permission_backing(
            &manifest.ephemeral_collections,
            &manifest.tables,
            manifest.effective_auth_mode() == AuthMode::Sessions,
        )
        .map_err(ephemeral_manifest_error)?;
        self.try_with_direct_authorization_write(
            crate::storage::AuthorizationCommitPreflight::AllProtectedRooms,
            move |snapback| {
                let ephemeral_collections = served_ephemeral_collections(
                    &manifest.ephemeral_collections,
                    &snapback.functions,
                );
                let generation = next_app_generation()?;
                let successor_telemetry_identity = snapback
                    .telemetry_store_identity
                    .as_ref()
                    .map(|current| {
                        crate::telemetry::TelemetryStoreIdentity::new(
                            manifest.app_id.clone(),
                            current.environment_id().to_owned(),
                        )
                    })
                    .transpose()?;
                let telemetry_identity_changes = successor_telemetry_identity
                    != snapback.telemetry_store_identity;
                let telemetry_incarnation = telemetry_identity_changes
                    .then(|| snapback.db.ensure_authorization_stream_incarnation())
                    .transpose()?;
                if telemetry_identity_changes {
                    // Fence before the app-schema commit. A successor app id
                    // must never admit rows under its predecessor's meta pair.
                    // @ref LLP 0154#d1--telemetry-store-a-sibling-sqlite-database-generation-bound —
                    //   schema publication rotates identity without relabeling
                    //   predecessor-generation rows.
                    snapback.telemetry.begin_generation_transition();
                }
                let mut diagnostics = match snapback.db.schema_seed().apply_schema(manifest) {
                    Ok(diagnostics) => diagnostics,
                    Err(error) => {
                        if telemetry_identity_changes {
                            snapback.telemetry.cancel_generation_transition();
                        }
                        return Err(error);
                    }
                };
                if let Some(incarnation) = telemetry_incarnation
                    && let Err(error) = snapback
                        .finish_telemetry_generation_transition(incarnation.as_str())
                {
                        // The schema commit is durable. Keep telemetry closed
                        // and surface the independent sibling failure rather
                        // than reporting a rollback that did not happen.
                        diagnostics.push(error.diagnostic);
                }
                let ephemeral = snapback.ephemeral.clone();
                crate::exec_guard::run_or_defer_after_local(move || {
                    ephemeral
                        .replace_collections(ephemeral_collections)
                        .expect("prevalidated ephemeral definitions publish infallibly");
                });
                crate::generation_activation::GenerationActivation::install_process_generation(
                    snapback, generation,
                );
                snapback.refresh_read_manifests();
                // Schema-driven route-param typing depends on the schema
                // (LLP 0092 §0E.6): a served route manifest that no longer
                // validates against the new schema drops fail-closed.
                if let Some(routes) = snapback.routes.clone()
                    && let Err(error) = snapback.validate_routes_manifest(&routes)
                {
                    snapback.routes = None;
                    snapback.routes_manifest_hash = None;
                    diagnostics.push(Diagnostic::warning(
                        "SNAPBACK_ROUTES_MANIFEST_INVALID",
                        "runtime",
                        format!(
                            "served route manifest dropped: it no longer validates against the new schema ({})",
                            error.diagnostic.message
                        ),
                    ));
                }
                snapback.record_attached_diagnostics(diagnostics.clone());
                Ok(diagnostics)
            },
        )?
    }

    pub fn load_functions(&mut self, manifest: FunctionManifest) -> Vec<Diagnostic> {
        self.load_functions_with_intent(
            manifest,
            crate::generation_activation::FunctionGenerationActivationIntent::Automatic,
        )
    }

    /// Reinstall the artifacts named by the durable raw-dev generation
    /// record. Unlike [`Self::load_functions`], this recovery-only entry point
    /// refuses instead of interpreting a non-match as a successor deployment.
    pub fn rehydrate_committed_generation(
        &mut self,
        manifest: FunctionManifest,
    ) -> Vec<Diagnostic> {
        self.load_functions_with_intent(
            manifest,
            crate::generation_activation::FunctionGenerationActivationIntent::RehydrateCommittedGeneration,
        )
    }

    fn load_functions_with_intent(
        &mut self,
        manifest: FunctionManifest,
        intent: crate::generation_activation::FunctionGenerationActivationIntent,
    ) -> Vec<Diagnostic> {
        if let Err(error) = manifest.validate_artifact() {
            let diagnostic = error.diagnostic;
            self.record_attached_diagnostics(vec![diagnostic.clone()]);
            return vec![diagnostic];
        }

        let sequence_declarations = sequence_declarations_from_functions(&manifest);

        let mut preflight = Vec::new();
        if let Err(error) = self.db.schema().validate_api_against_functions(&manifest) {
            preflight.push(error.diagnostic);
        }
        preflight.extend(self.db.schema().api_exposure_diagnostics(&manifest));
        if let Some(push_seam) = &self.db.schema().push_seam
            && let Err(error) = crate::push::validate_config_uses(push_seam, &manifest)
        {
            preflight.push(error.diagnostic);
        }
        let order_field_bounds =
            match validate_function_schema_references(&manifest, self.db.schema()) {
                Ok(()) => {
                    let bounds = order_field_bounds_from_functions(&manifest, self.db.schema())
                        .expect("schema-reference validation reconciled order-field bounds");
                    if let Err(error) = self.db.validate_order_field_bounds(&bounds) {
                        preflight.push(error.diagnostic);
                    }
                    if let Err(error) = self
                        .db
                        .validate_sequence_declaration_preflight(&sequence_declarations, false)
                    {
                        preflight.push(error.diagnostic);
                    }
                    Some(bounds)
                }
                Err(error) => {
                    preflight.push(error.diagnostic);
                    None
                }
            };
        // @ref LLP 0076#target-contract — capability admission resolves
        // against the SAME served instance manifest `/inspect` reports for
        // this exact process, before any handler or nested-mutation code can
        // run. Every local loader path (raw dev, provisioning, embedding)
        // funnels through here, so a stream-requiring artifact cannot be
        // installed on an egress-disabled instance.
        preflight.extend(self.validate_required_capabilities_against_instance(&manifest));
        preflight.extend(validate_cron_manifest(&manifest));
        if preflight
            .iter()
            .any(|diagnostic| diagnostic.severity == DiagnosticSeverity::Error)
        {
            self.record_attached_diagnostics(preflight.clone());
            return preflight;
        }

        let generation = match next_app_generation() {
            Ok(generation) => generation,
            Err(error) => {
                let diagnostic = error.diagnostic;
                self.record_attached_diagnostics(vec![diagnostic.clone()]);
                return vec![diagnostic];
            }
        };

        crate::generation_activation::GenerationActivation::new(self).activate_functions(
            crate::generation_activation::FunctionGenerationActivation {
                manifest,
                generation,
                order_field_bounds: order_field_bounds
                    .expect("error-free preflight prepared order-field bounds"),
                sequence_declarations,
                trusted_active_generation: false,
                publish_ephemeral_collections: false,
                validate_routes_after_install: true,
                inject_publication_warning: false,
                diagnostic_boundary: DiagnosticBoundary::Attached,
                diagnostics: preflight,
                intent,
            },
        )
    }

    /// Legacy raw function publication is a dev-only embedding seam. Every
    /// sessions deployment must enter through complete-pair provisioning and
    /// own the activation transition; pending/quarantined state cannot use a
    /// raw swap as a recovery side door.
    pub fn load_functions_in_settled_dev(
        &mut self,
        manifest: FunctionManifest,
    ) -> SnapbackResult<Vec<Diagnostic>> {
        // A raw loader has no sibling artifact with which to prove a complete
        // deployment pair. It is therefore only the legacy v0-dev seam; a v1
        // function half must go through complete-pair provisioning.
        // @ref LLP 0058#the-two-admissible-tuples — v1-dev is never an
        // admissible tuple, including when activeDeployment is still null.
        if manifest.schema_version != crate::manifest::SNAPBACK_SCHEMA_VERSION {
            return Err(SnapbackError::error(
                "SNAPBACK_CAPABILITY_UNSUPPORTED",
                "auth",
                "raw dev function loading accepts only snapback.v0 artifacts",
            )
            .with_details(serde_json::json!({
                "authMode": "dev",
                "schemaVersion": manifest.schema_version,
                "expectedSchemaVersion": crate::manifest::SNAPBACK_SCHEMA_VERSION,
            })));
        }
        let admission = self.admission.admit_dev()?;
        let state = self.db.auth_mode_snapshot()?.state;
        if state.active != state.desired
            || state.mode_state != crate::auth::mode::AuthModeStatus::Settled
            || state.app_data_availability != crate::auth::mode::AppDataAvailability::Available
        {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_MODE_PENDING",
                "auth",
                "raw functions.load is unavailable while auth mode is not settled and available",
            ));
        }
        if state.active != AuthMode::Dev {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                "auth",
                "sessions functions.load requires complete-pair activation coordination",
            ));
        }
        let _publication = admission.effect_guard("raw dev function publication")?;
        Ok(self.load_functions(manifest))
    }

    /// Publish a function generation and its committed schema's collection
    /// projection after both passed
    /// [`Self::preflight_auth_artifacts`] against the schema now committed by
    /// a startup, staged-mode, or same-mode network transaction. Artifact
    /// validation is complete before this call; managed server work defers the
    /// ephemeral lifecycle projection until Local is released while retaining
    /// the logical writer/admission barrier through completion. Secondary
    /// cron/config persistence failures remain ordinary diagnostics after the
    /// generation is live.
    // @ref LLP 0058#same-mode-provisioning — network same-mode activation keeps admission closed through collection and function publication.
    // @ref LLP 0058#consume-ordering-dev-to-sessions — the prepared generation publishes only after the durable consume cut.
    pub fn publish_preflighted_functions(
        &mut self,
        manifest: FunctionManifest,
        generation: u64,
        diagnostic_boundary: DiagnosticBoundary,
    ) -> Vec<Diagnostic> {
        debug_assert!(manifest.validate_artifact().is_ok());
        debug_assert!(validate_function_schema_references(&manifest, self.db.schema()).is_ok());
        debug_assert!(!validate_cron_manifest(&manifest).iter().any(|diagnostic| {
            matches!(
                diagnostic.severity,
                DiagnosticSeverity::Error | DiagnosticSeverity::Fatal
            )
        }));

        let sequence_declarations = sequence_declarations_from_functions(&manifest);
        let trusted_active_generation = self.db.auth_mode_snapshot().ok().is_some_and(|snapshot| {
            crate::auth::mode::DeploymentIdentity::from_manifests(
                snapshot.state.active,
                self.db.schema(),
                &manifest,
            )
            .ok()
            .as_ref()
                == snapshot.state.active_deployment.as_ref()
        });
        let order_field_bounds = order_field_bounds_from_functions(&manifest, self.db.schema())
            .expect("preflighted generation reconciles order-field bounds");
        if let Err(error) = self.db.validate_order_field_bounds(&order_field_bounds) {
            let diagnostics = vec![error.diagnostic];
            self.record_diagnostics_at_boundary(diagnostics.clone(), diagnostic_boundary);
            return diagnostics;
        }
        if let Err(error) = self.db.validate_sequence_declaration_preflight(
            &sequence_declarations,
            trusted_active_generation,
        ) {
            let diagnostics = vec![error.diagnostic];
            self.record_diagnostics_at_boundary(diagnostics.clone(), diagnostic_boundary);
            return diagnostics;
        }
        crate::generation_activation::GenerationActivation::new(self).activate_functions(
            crate::generation_activation::FunctionGenerationActivation {
                manifest,
                generation,
                order_field_bounds,
                sequence_declarations,
                trusted_active_generation,
                publish_ephemeral_collections: true,
                validate_routes_after_install: false,
                inject_publication_warning: true,
                diagnostic_boundary,
                diagnostics: Vec::new(),
                intent: crate::generation_activation::FunctionGenerationActivationIntent::Automatic,
            },
        )
    }

    /// Reserve the non-reusable process generation before a durable mode cut.
    /// A failed transaction may waste a generation, but no committed cut can
    /// reach the otherwise-infallible publication step and discover wrap.
    pub fn reserve_function_publication_generation(&self) -> SnapbackResult<u64> {
        next_app_generation()
    }

    /// Retain serve-time diagnostics in the same bounded ring as runtime
    /// diagnostics. The caller supplies already-redacted closed facts; this
    /// seam deliberately accepts no path or keyring error carrier.
    pub fn record_startup_diagnostics(&mut self, diagnostics: &[Diagnostic]) {
        self.record_standalone_diagnostics(diagnostics.to_vec());
    }

    pub fn reset(&mut self) -> SnapbackResult<()> {
        self.reset_with_seed(None).map(|_| ())
    }

    /// Atomically reset durable app data and optionally install a seed, then
    /// advance the in-memory lifecycle boundary only after SQLite commits.
    /// A rejected seed therefore preserves both the old database and every
    /// subscription/runtime generation that describes it.
    pub fn reset_with_seed(
        &mut self,
        seed: Option<SeedData>,
    ) -> SnapbackResult<Option<MutationOutput>> {
        if crate::exec_guard::local_write_scope_active() {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_PROJECTION_UNAVAILABLE",
                "auth",
                "direct reset cannot prepare its authorization stream while a managed Local writer is active",
            ));
        }

        // A direct embedder has no server-owned projection coordinator. Build
        // its minimal stream-only coordinator and premark it before entering
        // the direct Local/SQLite scope; finalization likewise happens only
        // after that scope and every committed after-Local effect have ended.
        let projection = self.db.admitted_stream_projection_snapshot()?;
        let coordinator = Arc::new(
            crate::auth::coordinator::AuthCoordinator::from_admitted_snapshot(
                projection,
                now_millis(),
                Instant::now(),
            )?,
        );
        let carrier = coordinator.premark_stream_reset_if_drained()?;
        let predecessor = carrier.predecessor().clone();
        let successor = carrier.successor().clone();

        let attempt = self.try_with_direct_authorization_write(
            crate::storage::AuthorizationCommitPreflight::AllProtectedRooms,
            move |snapback| match snapback.attempt_reset_with_seed_and_authorization_stream(
                seed,
                &predecessor,
                &successor,
            ) {
                crate::storage::auth::AuthTransactionAttempt::Committed(committed) => {
                    crate::storage::auth::AuthTransactionAttempt::Committed(
                        snapback.publish_coordinated_reset(committed),
                    )
                }
                crate::storage::auth::AuthTransactionAttempt::RolledBack(error) => {
                    crate::storage::auth::AuthTransactionAttempt::RolledBack(error)
                }
                crate::storage::auth::AuthTransactionAttempt::CommitUncertain(error) => {
                    crate::storage::auth::AuthTransactionAttempt::CommitUncertain(error)
                }
            },
        );
        let attempt = match attempt {
            Ok(attempt) => attempt,
            Err(error) => crate::storage::auth::AuthTransactionAttempt::RolledBack(error),
        };
        coordinator.finish_stream_reset(carrier, attempt)
    }

    fn keep_telemetry_closed_for_uncertain_reset(&self) {
        // @ref LLP 0154#d1--telemetry-store-a-sibling-sqlite-database-generation-bound —
        // durable predecessor/successor truth is unknown after an uncertain
        // reset COMMIT. Only boot-time incarnation reconciliation may reopen
        // the sibling; neither in-process generation is safe to expose.
        self.telemetry.begin_generation_transition();
    }

    /// Perform the destructive database half of a coordinator-premarked reset.
    /// In-memory generations move only when the durable stream successor is
    /// known to have committed (including exact post-COMMIT reconciliation).
    pub fn attempt_reset_with_seed_and_authorization_stream(
        &mut self,
        seed: Option<SeedData>,
        predecessor: &crate::contract_types::AuthorizationStreamIncarnation,
        successor: &crate::contract_types::AuthorizationStreamIncarnation,
    ) -> crate::storage::auth::AuthTransactionAttempt<CoordinatedResetCommit> {
        use crate::storage::auth::AuthTransactionAttempt;

        let app_generation = match next_app_generation() {
            Ok(generation) => generation,
            Err(error) => return AuthTransactionAttempt::RolledBack(error),
        };
        let secret_read_generation = self.secret_read_reset_generation.load(Ordering::Acquire);
        let next_secret_read_generation =
            match next_secret_read_reset_generation(secret_read_generation) {
                Ok(generation) => generation,
                Err(error) => return AuthTransactionAttempt::RolledBack(error),
            };
        self.telemetry.begin_generation_transition();
        match self
            .db
            .schema_seed()
            .attempt_reset_and_seed_with_authorization_stream(seed, predecessor, successor)
        {
            AuthTransactionAttempt::Committed(seeded) => {
                if let Err(error) = self.finish_telemetry_generation_transition(successor.as_str())
                {
                    // The app reset is already durable. Keep telemetry closed
                    // if its independent sibling cannot rebind; reporting a
                    // rollback here would lie about the app database.
                    self.record_attached_diagnostics(vec![error.diagnostic]);
                } else {
                    self.telemetry.point_classified(
                        crate::telemetry_contract::OperationClassIdV1::LIFECYCLE,
                        "reset_generation_rotation",
                        Some(200),
                        None,
                        None,
                        None,
                        crate::telemetry::Priority::Reserved,
                    );
                }
                AuthTransactionAttempt::Committed(CoordinatedResetCommit {
                    seeded,
                    app_generation,
                    secret_read_generation,
                    next_secret_read_generation,
                })
            }
            AuthTransactionAttempt::RolledBack(error) => {
                self.telemetry.cancel_generation_transition();
                AuthTransactionAttempt::RolledBack(error)
            }
            AuthTransactionAttempt::CommitUncertain(error) => {
                // The auth coordinator marks this process globally rebuild-
                // required because durable predecessor/successor truth is not
                // known. Reassert the D1 fence: cancelling could expose the
                // predecessor after a committed reset, while rebinding could
                // expose a successor that rolled back. Boot-time durable-pair
                // reconciliation is the existing recovery authority.
                self.keep_telemetry_closed_for_uncertain_reset();
                AuthTransactionAttempt::CommitUncertain(error)
            }
        }
    }

    pub fn ensure_versioned_seed(
        &mut self,
        request: crate::seed_identity::InstallSeedRequestV1,
    ) -> SnapbackResult<crate::seed_identity::SeedEnsureResultV1> {
        self.db.schema_seed().ensure_versioned_seed(request)
    }

    pub fn preview_versioned_seed(
        &mut self,
        request: crate::seed_identity::SeedPreviewRequestV1,
    ) -> SnapbackResult<crate::seed_identity::SeedPreviewResultV1> {
        self.db.schema_seed().preview_versioned_seed(request)
    }

    pub fn replay_versioned_seed_operation(
        &mut self,
        operation_id: &str,
        request_digest: &str,
    ) -> SnapbackResult<Option<crate::seed_identity::SeedInstallReceiptV1>> {
        self.db
            .schema_seed()
            .replay_versioned_seed_operation(operation_id, request_digest)
    }

    pub fn attempt_versioned_seed_reset_with_authorization_stream(
        &mut self,
        request: crate::seed_identity::ResetSeedRequestV1,
        predecessor: &crate::contract_types::AuthorizationStreamIncarnation,
        successor: &crate::contract_types::AuthorizationStreamIncarnation,
    ) -> crate::storage::auth::AuthTransactionAttempt<CoordinatedVersionedSeedResetCommit> {
        use crate::storage::auth::AuthTransactionAttempt;

        let app_generation = match next_app_generation() {
            Ok(generation) => generation,
            Err(error) => return AuthTransactionAttempt::RolledBack(error),
        };
        let secret_read_generation = self.secret_read_reset_generation.load(Ordering::Acquire);
        let next_secret_read_generation =
            match next_secret_read_reset_generation(secret_read_generation) {
                Ok(generation) => generation,
                Err(error) => return AuthTransactionAttempt::RolledBack(error),
            };
        self.telemetry.begin_generation_transition();
        match self
            .db
            .schema_seed()
            .attempt_versioned_seed_reset_with_authorization_stream(request, predecessor, successor)
        {
            AuthTransactionAttempt::Committed((seeded, receipt)) => {
                if let Err(error) = self.finish_telemetry_generation_transition(successor.as_str())
                {
                    self.record_attached_diagnostics(vec![error.diagnostic]);
                } else {
                    self.telemetry.point_classified(
                        crate::telemetry_contract::OperationClassIdV1::LIFECYCLE,
                        "reset_generation_rotation",
                        Some(200),
                        None,
                        None,
                        None,
                        crate::telemetry::Priority::Reserved,
                    );
                }
                AuthTransactionAttempt::Committed(CoordinatedVersionedSeedResetCommit {
                    reset: CoordinatedResetCommit {
                        seeded,
                        app_generation,
                        secret_read_generation,
                        next_secret_read_generation,
                    },
                    receipt,
                })
            }
            AuthTransactionAttempt::RolledBack(error) => {
                self.telemetry.cancel_generation_transition();
                AuthTransactionAttempt::RolledBack(error)
            }
            AuthTransactionAttempt::CommitUncertain(error) => {
                // Same fail-closed durable-ambiguity rule as the legacy reset:
                // only boot-time incarnation comparison can reopen telemetry.
                self.keep_telemetry_closed_for_uncertain_reset();
                AuthTransactionAttempt::CommitUncertain(error)
            }
        }
    }

    pub fn publish_coordinated_versioned_seed_reset(
        &mut self,
        committed: CoordinatedVersionedSeedResetCommit,
    ) -> crate::seed_identity::SeedInstallReceiptV1 {
        self.finish_committed_reset(
            committed.reset.app_generation,
            committed.reset.secret_read_generation,
            committed.reset.next_secret_read_generation,
        );
        // Asset tables cleared inside the reset transaction; the store's
        // files are unreferenced by construction now (LLP 0109 §17).
        // Best-effort like other post-commit staging cleanup.
        if let Ok(store) = self.asset_store_obj() {
            let _ = store.wipe_all();
        }
        committed.receipt
    }

    /// Publish reset-owned process state while the coordinator's stream
    /// mutation ticket still blocks predecessor and successor publication.
    /// The server installs a freshly authenticated successor issuer after
    /// this clears the predecessor state, then finalizes the coordinator as
    /// the last step that reopens app authority.
    pub fn publish_coordinated_reset(
        &mut self,
        committed: CoordinatedResetCommit,
    ) -> Option<MutationOutput> {
        self.finish_committed_reset(
            committed.app_generation,
            committed.secret_read_generation,
            committed.next_secret_read_generation,
        );
        // Asset tables cleared inside the reset transaction; wipe the now
        // unreferenced store files (LLP 0109 §17), best-effort.
        if let Ok(store) = self.asset_store_obj() {
            let _ = store.wipe_all();
        }
        committed.seeded
    }

    fn finish_committed_reset(
        &mut self,
        app_generation: u64,
        secret_read_generation: u64,
        next_secret_read_generation: u64,
    ) {
        let exchanged = self.secret_read_reset_generation.compare_exchange(
            secret_read_generation,
            next_secret_read_generation,
            Ordering::AcqRel,
            Ordering::Acquire,
        );
        debug_assert_eq!(exchanged, Ok(secret_read_generation));
        crate::generation_activation::GenerationActivation::install_process_generation(
            self,
            app_generation,
        );
        self.warm_vms.clear();
        self.connected_clients.clear();
        self.terminalize_all_local_live_effects();
        // ENG-23333: capture the live subscriptions being dropped so their
        // clients can be told. Clearing the map alone leaves every connected
        // client's WebSocket open on subscription ids that no longer exist
        // server-side — no future commit (including a post-reset seed) would
        // ever deliver to them, so a tab would render pre-reset data forever,
        // indistinguishable from a healthy idle app.
        let dropped_subscriptions: Vec<LiveSubscription> =
            self.subscriptions.values().cloned().collect();
        for subscription in &dropped_subscriptions {
            subscription.observation.finish(200, None, "reset");
        }
        self.subscriptions.clear();
        let memo_disabled = self.pending_live_fanout.evaluation_memo.disabled;
        self.pending_live_fanout = PendingLiveScheduler::empty_with_memo_disabled(memo_disabled);
        self.live_evaluation_timeout_streaks.clear();
        if let Some(coalescer) = &self.live_coalescer {
            for subscription in &dropped_subscriptions {
                coalescer.retire_subscription(&subscription.id);
            }
        }
        self.refresh_auth_scoped_live_connections();
        // The authenticated issuer names the pre-reset authorization
        // incarnation. Reset terminates those scopes; coordinated server reset
        // installs a freshly reserved successor before reopening authority.
        self.auth_invalidation = None;
        self.permission_epochs.clear();
        self.refresh_read_epochs();
        self.cron.reset_runtime_state(&self.functions);
        self.live_delivery = LiveDeliveryStats::default();
        // Signal the dropped subscriptions AFTER `reset_runtime_state`: the
        // ephemeral reset clears every connection outbox, so anything
        // enqueued earlier would be wiped.
        // @ref LLP 0008#realtime-delivery — resync sentinels: a dropped
        // subscription must get a resync signal, never a silent freeze.
        // Counters were just reset, so the reset's own signals are counted —
        // the same convention as the ephemeral reset's `Restarted` resyncs.
        // Each client gets a `resync_required`
        // (reason "reset") on its still-open connection so it re-snapshots
        // instead of silently freezing, and the global receipts ring gets the
        // same `disposed` markers `disconnect` pushes.
        let mut reset_signals = Vec::with_capacity(dropped_subscriptions.len());
        if !dropped_subscriptions.is_empty() {
            self.live_delivery.total_fanout_attempts += dropped_subscriptions.len() as u64;
            self.live_delivery.last_fanout_subscriptions = dropped_subscriptions.len();
            let now_ms = now_millis();
            for subscription in &dropped_subscriptions {
                self.receipts.push_global(
                    Receipt::Subscription {
                        event: SubscriptionReceiptEvent::Disposed,
                        reason: Some("reset".to_owned()),
                        subscription_id: Some(subscription.id.clone()),
                        superseded_by: None,
                        lane: None,
                        binding_id: None,
                        collection: None,
                        removed: None,
                        scope: subscription.input.args.clone(),
                        snapshot_version: None,
                        correlation: None,
                        received_at_ms: now_ms,
                    }
                    .into_value(),
                );
                let Ok(payload) = serde_json::to_vec(&LiveEnvelope::ResyncRequired {
                    network_profile: None,
                    reason: "reset".to_owned(),
                    subscription_id: Some(subscription.id.clone()),
                    scope: Some(String::new()),
                    epoch: Some(0),
                    clear_retained: true,
                }) else {
                    continue;
                };
                reset_signals.push((
                    subscription.connection_id.clone(),
                    subscription.effect_fence.clone(),
                    payload,
                ));
                self.live_delivery.total_deliveries += 1;
                self.live_delivery.last_deliveries += 1;
            }
        }
        // Runtime reset and its durable dropped-subscription sentinels are one
        // ordered after-Local effect: enqueueing before the reset would lose
        // the sentinels, while running either half beneath Local would take
        // lifecycle/room/notifier locks. Direct-library reset executes this
        // closure synchronously.
        // @ref LLP 0059#reset-restore-and-stream-publication — the stream
        // ticket remains closed until the successor runtime projection ends.
        let ephemeral = self.ephemeral.clone();
        crate::exec_guard::run_or_defer_after_local(move || {
            ephemeral.reset_runtime_state();
            for (connection_id, effect_fence, payload) in reset_signals {
                match effect_fence {
                    Some(effect_fence) => {
                        ephemeral.enqueue_durable_bound(connection_id, payload, effect_fence);
                    }
                    None => {
                        ephemeral.enqueue_durable(connection_id, payload);
                    }
                }
            }
        });
        // Clearing subscriptions can disarm a demand-gated cron job (L5).
        self.refresh_cron_active();
        // The durable reset has already committed. A secondary cron-state
        // persistence failure is diagnostic-only: returning an error here
        // would falsely imply the destructive operation rolled back.
        if let Err(error) = self.persist_cron_state() {
            self.record_attached_diagnostics(vec![error.diagnostic]);
        }
    }

    /// LLP 0184 §B: `debug.live.forceResync`, a non-production debug
    /// perturbation. It makes exactly one live subscription re-snapshot
    /// through the protocol's ordinary `resync_required` recovery path (LLP
    /// 0094/0095) by enqueueing that frame on the subscription's own
    /// connection outbox — it does not drop the subscription, does not
    /// touch any application data, and does not invent a new
    /// per-subscription generation (LLP 0095's subscription-scoped resync
    /// transition requires only `subscription_id`; this reuses that
    /// identity rather than the sessions-artifact `expected_generation`
    /// pinned on [`LiveSubscription`], which is a different, auth-artifact
    /// fact this operation does not read or repurpose).
    ///
    /// Fenced by connection id plus subscription id — the same pair the
    /// gated `/_snapback/api/inspect` twin already exposes as
    /// [`LiveSubscriptionInfo`]. The caller's startup nonce and target
    /// eligibility (local non-production only in v1) are both verified by
    /// the host-ops HTTP handler before this is ever reached; this method
    /// assumes both checks already passed and fences only on the
    /// connection/subscription pair actually being open together.
    ///
    /// Connection-wide targeting (every subscription on a connection) is
    /// explicitly out of v1 scope (LLP 0184 OQ4), not silently reachable
    /// through this method.
    ///
    /// @ref LLP 0184#b-forced-live-resync--add-now — single-subscription
    ///   v1 scope, startup-nonce fencing, closed operator/test reason,
    ///   selectable `clearRetained` disposition, normal `resync_required`
    ///   path, no application-data change.
    pub fn force_live_resync(
        &mut self,
        connection_id: &str,
        subscription_id: &str,
        reason: &str,
        clear_retained: bool,
    ) -> Result<ForceLiveResyncReceipt, SnapbackError> {
        let subscription = self.subscriptions.get(subscription_id).ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_LIVE_FORCE_RESYNC_SUBSCRIPTION_NOT_FOUND",
                "debug",
                "no live subscription with that id is currently open",
            )
            .with_details(json!({ "subscriptionId": subscription_id }))
        })?;
        if subscription.connection_id != connection_id {
            return Err(SnapbackError::error(
                "SNAPBACK_LIVE_FORCE_RESYNC_CONNECTION_MISMATCH",
                "debug",
                "the subscription id is not open on the given connection id",
            )
            .with_details(json!({
                "subscriptionId": subscription_id,
                "requestedConnectionId": connection_id,
                "actualConnectionId": subscription.connection_id,
            })));
        }
        let effect_fence = subscription.effect_fence.clone();
        let function = subscription.function.clone();
        let Ok(payload) = serde_json::to_vec(&LiveEnvelope::ResyncRequired {
            network_profile: None,
            reason: format!("operator_forced: {reason}"),
            subscription_id: Some(subscription_id.to_owned()),
            scope: Some(String::new()),
            epoch: Some(0),
            clear_retained,
        }) else {
            return Err(SnapbackError::error(
                "SNAPBACK_LIVE_FORCE_RESYNC_ENCODE_FAILED",
                "debug",
                "failed to encode the resync_required frame",
            ));
        };
        // Deferred the same way `finish_committed_reset`'s dropped-subscription
        // signals are: the ephemeral outbox lock must never nest inside the
        // Local lock this method already holds.
        // @ref LLP 0059#locking-and-linearization — after-Local projection
        //   never overlaps a successor managed Local operation.
        let ephemeral = self.ephemeral.clone();
        let connection_id_owned = connection_id.to_owned();
        crate::exec_guard::run_or_defer_after_local(move || match effect_fence {
            Some(effect_fence) => {
                ephemeral.enqueue_durable_bound(connection_id_owned, payload, effect_fence);
            }
            None => {
                ephemeral.enqueue_durable(connection_id_owned, payload);
            }
        });
        Ok(ForceLiveResyncReceipt {
            connection_id: connection_id.to_owned(),
            subscription_id: subscription_id.to_owned(),
            function,
            reason: reason.to_owned(),
            clear_retained,
        })
    }

    pub fn app_generation(&self) -> u64 {
        self.app_generation
    }

    fn resolve_complete_provision_pair(
        &self,
        requested_mode: AuthMode,
        schema: Option<SchemaManifest>,
        functions: Option<FunctionManifest>,
        seed: Option<SeedData>,
        state: &AuthModeStateRecord,
    ) -> SnapbackResult<StartupArtifacts> {
        let (schema, functions) = match (schema, functions) {
            (Some(schema), Some(functions)) => {
                return Ok(StartupArtifacts {
                    format_version: STARTUP_ARTIFACT_FORMAT_VERSION,
                    schema,
                    functions,
                    seed,
                });
            }
            pair => pair,
        };

        let sibling_identity = if requested_mode == state.active {
            state.active_deployment.as_ref()
        } else if requested_mode == state.desired {
            state.requested_deployment.as_ref()
        } else {
            None
        };
        let sibling = sibling_identity.and_then(|identity| {
            self.preflighted_artifact_pairs
                .iter()
                .rev()
                .find(|pair| &pair.deployment == identity)
        });
        let Some(sibling) = sibling else {
            return Err(SnapbackError::error(
                "SNAPBACK_CAPABILITY_UNSUPPORTED",
                "auth-mode",
                "a partial provision requires the complete preflighted sibling pair from this process",
            ));
        };

        Ok(StartupArtifacts {
            format_version: STARTUP_ARTIFACT_FORMAT_VERSION,
            schema: schema.unwrap_or_else(|| sibling.schema.clone()),
            functions: functions.unwrap_or_else(|| sibling.prepared_functions.manifest.clone()),
            seed,
        })
    }

    fn require_provision_posture(
        state: &AuthModeStateRecord,
        requested_mode: AuthMode,
    ) -> SnapbackResult<()> {
        use crate::auth::mode::AuthModeStatus;

        match state.mode_state {
            AuthModeStatus::Settled => Ok(()),
            AuthModeStatus::PendingRestart | AuthModeStatus::Quarantined
                if requested_mode == state.desired && requested_mode != state.active =>
            {
                Ok(())
            }
            AuthModeStatus::PendingRestart | AuthModeStatus::Quarantined => {
                Err(SnapbackError::error(
                    "SNAPBACK_AUTH_MODE_PENDING",
                    "auth-mode",
                    "a pending auth-mode transition may only be corrected by re-staging its desired mode",
                ))
            }
        }
    }

    /// First, read-only provisioning pass. It resolves any same-boot sibling,
    /// validates the complete pair and target registry, and returns owned
    /// bytes that can cross the admission barrier. No schema, function,
    /// mode-state, or seed effect occurs here.
    // @ref LLP 0058#stage-ordering — mode staging preflights before closing admission and repeats under the write lane.
    pub fn prepare_auth_provision(
        &mut self,
        requested_mode: EnsureAppMode,
        schema: Option<SchemaManifest>,
        functions: Option<FunctionManifest>,
        seed: Option<SeedData>,
    ) -> SnapbackResult<AuthProvisionPlan<LocalSnapback>> {
        self.prepare_auth_provision_with_routes(requested_mode, schema, functions, seed, None, None)
    }

    /// The `/app-api/current` discovery document (LLP 0062 §5). Sessions
    /// targets only: a dev-posture instance serves no discovery document —
    /// the caller maps None to the typed refusal. The envelope marker is
    /// verify-on-read: a stored record whose inputsHash disagrees with the
    /// active generation reports the typed absent state, never a stale
    /// envelope (the crash window between activation cut and record).
    pub fn app_api_discovery(
        &self,
    ) -> SnapbackResult<Option<crate::api_envelope::AppApiDiscoveryV1>> {
        let snapshot = self.db.auth_mode_snapshot()?;
        if snapshot.state.active != AuthMode::Sessions {
            return Ok(None);
        }
        let Some(deployment) = snapshot.state.active_deployment.clone() else {
            return Ok(None);
        };
        let state = self.db.api_envelope_read().load_api_envelope_state()?;
        let envelope = match state.and_then(|state| state.current) {
            Some(current) if current.inputs_hash == deployment.inputs_hash => {
                crate::api_envelope::AppApiDiscoveryEnvelopeV1::Current {
                    sha256: current.digest,
                }
            }
            _ => crate::api_envelope::AppApiDiscoveryEnvelopeV1::Absent,
        };
        Ok(Some(crate::api_envelope::AppApiDiscoveryV1 {
            artifact_kind: "appApiDiscovery".to_string(),
            format_version: "snapback.app-api-discovery.v1".to_string(),
            app_id: deployment.app_id.clone(),
            tuple: crate::api_envelope::AppApiDiscoveryTupleV1 {
                schema_version: deployment.schema_version.clone(),
                auth_mode: "sessions".to_string(),
                schema_hash: Some(deployment.schema_hash.clone()),
                bundle_hash: Some(deployment.bundle_hash.clone()),
                inputs_hash: Some(deployment.inputs_hash.clone()),
            },
            envelope,
            // Echoes the served capability manifest's `app-cli.target`
            // descriptor (LLP 0062 §4; dated LLP 0058 amendment). This is the
            // advisory pre-flag only — the descriptor itself, with the
            // principal classes and caps the engine actually gates on, rides
            // `/inspect`. A target whose manifest declares no descriptor stays
            // honestly capability-absent here.
            app_cli_target: crate::manifest::CapabilityManifest::local_v0_declared()
                .app_cli_target
                .is_some(),
            app_cli_descriptor: crate::manifest::CapabilityManifest::local_v0_declared()
                .app_cli_target,
            engine_range: None,
        }))
    }

    /// The canonical bytes for a retained envelope digest (LLP 0062 §5's
    /// current-plus-previous retention window).
    pub fn app_api_envelope_bytes(&self, digest: &str) -> SnapbackResult<Option<String>> {
        self.db.api_envelope_read().load_api_envelope_bytes(digest)
    }

    /// Resolve and verify the current envelope under one local-state cut so
    /// generated external catalogs cannot join two active generations.
    pub fn current_app_api_envelope(&self) -> SnapbackResult<(String, String)> {
        let Some(discovery) = self.app_api_discovery()? else {
            return Err(crate::diagnostic::SnapbackError::error(
                "SNAPBACK_APP_API_UNAVAILABLE",
                "app-api",
                "app-api discovery is served by sessions targets only; dev targets use /inspect and local artifacts",
            ));
        };
        let crate::api_envelope::AppApiDiscoveryEnvelopeV1::Current { sha256 } = discovery.envelope
        else {
            return Err(crate::diagnostic::SnapbackError::error(
                "SNAPBACK_APP_API_UNAVAILABLE",
                "app-api",
                "the active generation has no API envelope; refetch /app-api/current after provisioning one",
            ));
        };
        let Some(canonical) = self.app_api_envelope_bytes(&sha256)? else {
            return Err(crate::diagnostic::SnapbackError::error(
                "SNAPBACK_APP_API_STATE_PARSE_FAILED",
                "app-api",
                "the current discovery digest has no retained envelope bytes",
            ));
        };
        let (_, actual_digest) = crate::api_envelope::parse_and_validate(canonical.as_bytes())
            .map_err(|refusal| {
                crate::diagnostic::SnapbackError::error(
                    "SNAPBACK_APP_API_STATE_PARSE_FAILED",
                    "app-api",
                    "the current persisted envelope no longer passes admission",
                )
                .with_details(serde_json::json!({
                    "envelopeCode": refusal.code,
                    "error": refusal.message,
                }))
            })?;
        if actual_digest != sha256 {
            return Err(crate::diagnostic::SnapbackError::error(
                "SNAPBACK_APP_API_STATE_PARSE_FAILED",
                "app-api",
                "the current discovery digest does not identify its persisted envelope bytes",
            ));
        }
        Ok((sha256, canonical))
    }

    pub fn prepare_auth_provision_with_routes(
        &mut self,
        requested_mode: EnsureAppMode,
        schema: Option<SchemaManifest>,
        functions: Option<FunctionManifest>,
        seed: Option<SeedData>,
        routes: Option<crate::bundle::RoutesManifest>,
        api_envelope: Option<crate::api_envelope::ApiEnvelopeMembersV1>,
    ) -> SnapbackResult<AuthProvisionPlan<LocalSnapback>> {
        let requested_mode = requested_mode.auth_mode();
        let snapshot = self.db.auth_mode_snapshot()?;
        Self::require_provision_posture(&snapshot.state, requested_mode)?;
        let artifacts = self.resolve_complete_provision_pair(
            requested_mode,
            schema,
            functions,
            seed,
            &snapshot.state,
        )?;
        let deployment = self.preflight_auth_artifacts(&artifacts, requested_mode)?;
        if let Some(routes) = &routes {
            Self::validate_routes_manifest_against(
                routes,
                &artifacts.functions,
                &artifacts.schema,
            )?;
        }
        AuthProvisionPlan::prepare(
            self,
            requested_mode,
            artifacts,
            deployment,
            routes,
            api_envelope,
        )
    }

    /// State-sensitive second pass and atomic durable cut. A caller staging a
    /// mode change or activating a same-mode Sessions deployment must hold the
    /// transition guard supplied by the admission controller. Same-mode dev
    /// callers remain serialized by the app write lane alone.
    #[cfg(any(test, feature = "test-support"))]
    pub fn commit_auth_provision(
        &mut self,
        prepared: AuthProvisionPlan<LocalSnapback>,
        profile: &str,
    ) -> SnapbackResult<(EnsureAppProvisionOutcome, AuthModeStateRecord)> {
        self.commit_auth_provision_classified(prepared, profile, None)
            .map(|committed| {
                let (outcome, state, _) = committed.into_parts();
                (outcome, state)
            })
            .map_err(ModeCommitFailure::into_error)
    }

    pub fn commit_auth_provision_classified(
        &mut self,
        prepared: AuthProvisionPlan<LocalSnapback>,
        profile: &str,
        activation_admission: Option<&AdmissionLease>,
    ) -> Result<AuthProvisionResult<LocalSnapback>, ModeCommitFailure> {
        if crate::exec_guard::local_write_scope_active() {
            return self.commit_auth_provision_classified_in_scope(
                prepared,
                profile,
                activation_admission,
            );
        }
        match self.try_with_direct_authorization_write(
            crate::storage::AuthorizationCommitPreflight::AllProtectedRooms,
            move |snapback| {
                snapback.commit_auth_provision_classified_in_scope(
                    prepared,
                    profile,
                    activation_admission,
                )
            },
        ) {
            Ok(committed) => committed,
            Err(error) => Err(ModeCommitFailure::RolledBack(error)),
        }
    }

    fn commit_auth_provision_classified_in_scope(
        &mut self,
        prepared: AuthProvisionPlan<LocalSnapback>,
        profile: &str,
        activation_admission: Option<&AdmissionLease>,
    ) -> Result<AuthProvisionResult<LocalSnapback>, ModeCommitFailure> {
        let (requested_mode, artifacts, deployment, routes, api_envelope, result_projection) =
            prepared.into_untrusted_parts();
        let before = self
            .db
            .auth_mode_snapshot()
            .map_err(ModeCommitFailure::RolledBack)?;
        Self::require_provision_posture(&before.state, requested_mode)
            .map_err(ModeCommitFailure::RolledBack)?;
        let observed = self
            .preflight_auth_artifacts(&artifacts, requested_mode)
            .map_err(ModeCommitFailure::RolledBack)?;
        if observed != deployment {
            return Err(ModeCommitFailure::RolledBack(
                crate::auth::mode::mode_corrupt(
                    "prepared provisioning identity changed between preflight passes",
                ),
            ));
        }
        if let Some(routes) = &routes {
            Self::validate_routes_manifest_against(routes, &artifacts.functions, &artifacts.schema)
                .map_err(ModeCommitFailure::RolledBack)?;
        }
        if before.state.active == AuthMode::Sessions
            && requested_mode == before.state.active
            && activation_admission.is_none()
        {
            return Err(ModeCommitFailure::RolledBack(SnapbackError::error(
                "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                "auth-mode",
                "same-mode sessions provisioning requires the closed activation admission",
            )));
        }

        // The activation's identity, captured before the deployment moves
        // into the durable cut: the envelope record binds to it.
        let activation_inputs_hash = deployment.inputs_hash.clone();

        // Server-composed api envelope (LLP 0062 §5, 2026-08-01 ruling):
        // compose and self-verify BEFORE any durable effect, so a failing
        // composition refuses activation with nothing written. The composed
        // bytes persist only after the activation cut succeeds; the
        // discovery read path verifies the record's inputsHash against the
        // active generation, so the crash window between cut and record
        // degrades to the typed absent marker, never a stale envelope.
        let composed_envelope = match api_envelope.as_ref() {
            Some(members) => Some(
                crate::api_envelope::compose_api_envelope(
                    &crate::manifest::public_function_manifest_for_schema(
                        &artifacts.schema,
                        artifacts.functions.clone(),
                    ),
                    members,
                    match requested_mode {
                        AuthMode::Sessions => "sessions",
                        AuthMode::Dev => "dev",
                    },
                )
                .map_err(|refusal| {
                    ModeCommitFailure::RolledBack(
                        SnapbackError::error(
                            "SNAPBACK_APP_API_COMPOSITION_FAILED",
                            "app-api",
                            "the api envelope failed composition self-verification; activation refused",
                        )
                        .with_details(serde_json::json!({ "refusal": refusal.to_string() })),
                    )
                })?,
            ),
            None => None,
        };

        // @ref LLP 0204#d2--surface-1-the-third-party-api — compare only the
        // currently served predecessor with the self-verified candidate and
        // refuse a breaking exposed-contract change before the durable cut.
        // @ref LLP 0225#1-ownership-map — storage supplies retained bytes;
        // pure compatibility policy remains with the API-envelope contract.
        let prior_digest = self
            .db
            .api_envelope_read()
            .load_api_envelope_state()
            .map_err(ModeCommitFailure::RolledBack)?
            .and_then(|state| state.current)
            .filter(|current| {
                before.state.active == AuthMode::Sessions
                    && before
                        .state
                        .active_deployment
                        .as_ref()
                        .is_some_and(|deployment| deployment.inputs_hash == current.inputs_hash)
            })
            .map(|current| current.digest);
        let prior_envelope = match prior_digest {
            Some(digest) => self
                .db
                .api_envelope_read()
                .load_api_envelope_bytes(&digest)
                .map_err(ModeCommitFailure::RolledBack)?
                .and_then(|canonical| {
                    crate::api_envelope::parse_and_validate(canonical.as_bytes())
                        .ok()
                        .and_then(|(envelope, actual)| (actual == digest).then_some(envelope))
                }),
            None => None,
        };
        let next_envelope = composed_envelope
            .as_ref()
            .map(|composed| crate::api_envelope::parse_and_validate(composed.canonical.as_bytes()))
            .transpose()
            .map_err(|refusal| {
                ModeCommitFailure::RolledBack(
                    SnapbackError::error(
                        "SNAPBACK_APP_API_COMPOSITION_FAILED",
                        "app-api",
                        "the api envelope failed composition self-verification; activation refused",
                    )
                    .with_details(serde_json::json!({ "refusal": refusal.to_string() })),
                )
            })?
            .map(|(envelope, _)| envelope);
        let compatibility = crate::api_envelope::ApiEnvelopeV1::classify_compatibility(
            prior_envelope.as_ref(),
            next_envelope.as_ref(),
        );
        if !compatibility.is_compatible() {
            return Err(ModeCommitFailure::RolledBack(
                SnapbackError::error(
                    "SNAPBACK_API_INCOMPATIBLE_CHANGE",
                    "app-api",
                    "the exposed API contract contains a breaking change; activation refused",
                )
                .with_details(serde_json::json!({ "breaking": compatibility.breaking() })),
            ));
        }
        let compatibility_advisories = compatibility.into_advisories();

        let comparison = if requested_mode == before.state.active {
            before.state.active_deployment.as_ref()
        } else {
            before.state.requested_deployment.as_ref()
        };
        let schema_matched =
            comparison.is_some_and(|identity| identity.schema_hash == deployment.schema_hash);
        let functions_matched =
            comparison.is_some_and(|identity| identity.bundle_hash == deployment.bundle_hash);
        let routes = routes.clone();
        let incoming_routes_hash = routes.as_ref().and_then(|manifest| {
            serde_json::to_value(manifest)
                .ok()
                .and_then(|value| crate::rqs_contract::sha256_identity(&value).ok())
        });
        let routes_matched =
            incoming_routes_hash.is_some() && incoming_routes_hash == self.routes_manifest_hash;
        let requested_mode_is_active = requested_mode == before.state.active;

        let (seed_outcome, state, mut diagnostics) = if requested_mode_is_active {
            let publication_generation = self
                .reserve_function_publication_generation()
                .map_err(ModeCommitFailure::RolledBack)?;
            let activation = crate::generation_activation::GenerationActivation::new(self)
                .activate_same_mode_network_generation(
                    deployment,
                    artifacts.schema,
                    artifacts.functions,
                    artifacts.seed,
                    publication_generation,
                    DiagnosticBoundary::Attached,
                )?;
            let crate::generation_activation::SameModeNetworkActivation {
                commit: committed,
                committed_at,
                diagnostics,
            } = activation;
            let NetworkDeploymentCommit {
                seed_outcome,
                activation_changed,
                state,
                authorization,
                projection_publications: _,
            } = committed;
            if let Some(routes) = routes.as_ref()
                && !routes_matched
            {
                // The candidate routes were preflighted against this exact
                // schema/function pair before the durable activation cut.
                // Repeating install after function publication binds the
                // served route generation to the now-active pair.
                self.install_routes_manifest(routes.clone())
                    .map_err(ModeCommitFailure::Uncertain)?;
            }
            if before.state.active == AuthMode::Sessions
                && (activation_changed || seed_outcome == NetworkSeedOutcome::Seeded)
            {
                // @ref LLP 0058#same-mode-provisioning — publish the prepared
                // generation, project this transaction's exact auth event,
                // and invalidate retained authority-independent snapshots
                // while ordinary successor admission is still closed.
                let admission = activation_admission.expect(
                    "settled sessions activation checked transition-owned admission before commit",
                );
                self.begin_live_commit_egress(committed_at);
                let fanout = (|| -> SnapbackResult<()> {
                    self.begin_live_delivery_frame(self.subscriptions.len());
                    if activation_changed {
                        self.invalidate_generation_bound_live_subscriptions_for_activation(
                            admission,
                        )?;
                    }
                    let already_resynced = if let Some(authorization) =
                        authorization.as_ref().filter(|event| event.witness.event)
                    {
                        self.notify_authorization_activation_in_frame(
                            &authorization.witness,
                            authorization.min_commit_version,
                            admission,
                        )?
                    } else {
                        BTreeSet::new()
                    };
                    if seed_outcome == NetworkSeedOutcome::Seeded {
                        let frame_version = self.db.versions_read().current_version()?;
                        self.dispatch_live_data_fanout(
                            &[],
                            &already_resynced,
                            frame_version,
                            admission,
                        )?;
                    }
                    Ok(())
                })();
                self.end_live_commit_egress();
                fanout.map_err(ModeCommitFailure::Uncertain)?;
            }
            (seed_outcome.as_str(), state, diagnostics)
        } else {
            let seeded = artifacts.seed.is_some();
            let committed = self.db.stage_auth_mode_with_functions_classified(
                deployment,
                artifacts.schema,
                &artifacts.functions,
                artifacts.seed,
            );
            let state = match committed {
                DurableModeCommit::Committed(committed) => committed,
                DurableModeCommit::RolledBack(error) => {
                    return Err(ModeCommitFailure::RolledBack(error));
                }
                DurableModeCommit::Uncertain(error) => {
                    return Err(ModeCommitFailure::Uncertain(error));
                }
            };
            (
                if seeded { "seeded" } else { "skipped-absent" },
                state,
                Vec::new(),
            )
        };
        diagnostics.extend(compatibility_advisories);
        // Persist the envelope disposition after the successful cut. Failure
        // here is Uncertain, not silent: the activation is durable and the
        // envelope record is not, which the verify-on-read rule tolerates,
        // but the caller deserves the honest classification.
        self.db
            .api_envelope()
            .record_api_envelope(
                &activation_inputs_hash,
                composed_envelope
                    .as_ref()
                    .map(|composed| (composed.digest.as_str(), composed.canonical.as_str())),
            )
            .map_err(ModeCommitFailure::Uncertain)?;

        let outcome = EnsureAppProvisionOutcome {
            intent: EnsureAppIntent::Provision,
            schema: if schema_matched {
                "matched"
            } else {
                "provisioned"
            }
            .to_owned(),
            functions: if functions_matched {
                "matched"
            } else {
                "provisioned"
            }
            .to_owned(),
            seed: seed_outcome.to_owned(),
            routes: routes.as_ref().map(|_| {
                if !requested_mode_is_active {
                    "skipped-pending-mode"
                } else if routes_matched {
                    "matched"
                } else {
                    "provisioned"
                }
                .to_owned()
            }),
            profile: profile.to_owned(),
            api_envelope: Some(
                if composed_envelope.is_some() {
                    "composed"
                } else {
                    "absent"
                }
                .to_owned(),
            ),
        };
        Ok(result_projection.project_committed(outcome, state, diagnostics))
    }

    /// ENG-22527: the ensure-everything mount-lifecycle operation. Inspects
    /// the loaded schemaHash/bundleHash against the posted generated
    /// manifests; provisions ONLY the missing/mismatched halves (when the
    /// profile allows provisioning — otherwise those halves report 'gated');
    /// seeds server-side only when every seed target table is empty (the
    /// true seed-without-reset path).
    pub fn ensure_app(
        &mut self,
        input: EnsureAppInput,
        provisioning_allowed: bool,
        profile: &str,
    ) -> SnapbackResult<EnsureAppOutcome> {
        // Validate every posted artifact before the first hash comparison or
        // effect. In particular, a matching hash is attestation evidence, not
        // permission to bypass an unsupported artifact version; validating
        // both halves up front also prevents a valid schema from applying
        // before an invalid function artifact is rejected.
        if let Err(error) = input.validate_artifacts() {
            // Preserve load_functions' diagnostic trail while moving the
            // validation itself ahead of every hash comparison and effect.
            // Schema-header failures gain the same rejected-artifact record.
            self.record_attached_diagnostics(vec![error.diagnostic.clone()]);
            return Err(error);
        }

        let schema_outcome = match input.schema {
            None => "skipped-absent",
            Some(manifest) => {
                let loaded = self.db.schema().schema_hash.clone();
                if loaded.as_deref() == manifest.schema_hash.as_deref() && loaded.is_some() {
                    "matched"
                } else if provisioning_allowed {
                    // apply_schema is additive for tables and identity-guarded
                    // for ephemeral collections (replace_collections no-ops on
                    // identical definitions — live rooms survive a matched
                    // ensure by construction; LLP 0025).
                    self.apply_schema(manifest)?;
                    "provisioned"
                } else {
                    "gated"
                }
            }
        };

        let functions_outcome = match input.functions {
            None => "skipped-absent",
            Some(manifest) => {
                let loaded = self.functions.bundle_hash.clone();
                if loaded.as_deref() == manifest.bundle_hash.as_deref() && loaded.is_some() {
                    "matched"
                } else if provisioning_allowed {
                    let diagnostics = self.load_functions(manifest);
                    if let Some(error) = diagnostics.iter().find(|diagnostic| {
                        matches!(
                            diagnostic.severity,
                            DiagnosticSeverity::Error | DiagnosticSeverity::Fatal
                        )
                    }) {
                        return Err(SnapbackError::new(error.clone()));
                    }
                    "provisioned"
                } else {
                    "gated"
                }
            }
        };

        // Routes install after the functions half so validation runs against
        // the manifest this same ensure just applied (LLP 0092 §0C.1).
        let routes_outcome = match input.routes {
            None => None,
            Some(manifest) => {
                let incoming_hash = serde_json::to_value(&manifest)
                    .ok()
                    .and_then(|value| crate::rqs_contract::sha256_identity(&value).ok());
                if incoming_hash.is_some() && incoming_hash == self.routes_manifest_hash {
                    Some("matched")
                } else if provisioning_allowed {
                    self.install_routes_manifest(manifest)?;
                    Some("provisioned")
                } else {
                    Some("gated")
                }
            }
        };

        let seed_outcome = match input.seed {
            None => "skipped-absent",
            // Gate BEFORE the emptiness scan (ENG-22527 FIX 2): when
            // provisioning is disallowed the schema half is also gated, so its
            // tables were never created — scanning them would raise
            // SNAPBACK_UNKNOWN_TABLE and turn the primary fresh-prod mount into
            // a 500 instead of an honest seed:"gated". Report gated and never
            // touch the store.
            Some(_) if !provisioning_allowed => "gated",
            Some(seed) => {
                let mut all_empty = true;
                for table in seed.tables.keys() {
                    let scan = self.db.query_reads_read().scan_table(table, 1, 0)?;
                    if !scan.rows.is_empty() {
                        all_empty = false;
                        break;
                    }
                }
                if !all_empty {
                    // Seed-if-empty, never reset-then-seed (LLP 0034 §5 edit
                    // 2): existing data always wins.
                    "skipped-nonempty"
                } else {
                    self.seed(seed)?;
                    "seeded"
                }
            }
        };

        Ok(EnsureAppOutcome {
            schema: schema_outcome.to_owned(),
            functions: functions_outcome.to_owned(),
            seed: seed_outcome.to_owned(),
            routes: routes_outcome.map(str::to_owned),
            profile: profile.to_owned(),
        })
    }

    /// Compare an identity-only pair against the currently loaded artifacts.
    /// This path is observational by construction: it has no manifest or seed
    /// input and takes `&self`, so Public attestation cannot stage or mutate.
    pub fn attest_app(
        &self,
        requested_mode: EnsureAppMode,
        pair: EnsureAppPairIdentity,
    ) -> SnapbackResult<EnsureAppAttestOutcome> {
        let requested = pair.normalized(requested_mode)?;
        let requested_deployment = DeploymentIdentity {
            schema_version: requested.schema_version.clone(),
            auth_mode: requested_mode.auth_mode(),
            app_id: requested.app_id.clone(),
            schema_hash: requested.schema_hash.clone(),
            bundle_hash: requested.bundle_hash.clone(),
            inputs_hash: requested.inputs_hash.clone(),
        };
        requested_deployment.validate().map_err(|_| {
            ensure_request_invalid(
                "app.ensure attestation identity is not valid for its requested auth mode",
            )
        })?;

        let snapshot = self.db.auth_mode_snapshot()?;
        if snapshot.state.mode_state != crate::auth::mode::AuthModeStatus::Settled
            || snapshot.state.active != requested_mode.auth_mode()
            || snapshot.state.desired != requested_mode.auth_mode()
        {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                "auth",
                "app.ensure attestation requires a settled active mode matching requestedMode",
            ));
        }
        let active_deployment = snapshot.state.active_deployment.ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_AUTH_POLICY_UNAVAILABLE",
                "auth",
                "app.ensure attestation requires a complete coherent active artifact pair",
            )
        })?;
        let active = EnsureAppActiveIdentity {
            schema_version: active_deployment.schema_version,
            app_id: active_deployment.app_id,
            schema_hash: active_deployment.schema_hash,
            bundle_hash: active_deployment.bundle_hash,
            inputs_hash: active_deployment.inputs_hash,
        };
        // @ref LLP 0081#6-compatibility-and-deployment-ordering — the
        //   posture-aware handshake: a client attesting the predecessor
        //   artifacts of a successor-only publication receives the stable
        //   upgrade-required refusal, never a generic mismatch it might
        //   answer by re-provisioning the predecessor over the successor.
        if active != requested
            && let Some(transition) = self.db.latest_schema_transition()?
            && matches!(
                transition.body.compatibility_posture,
                crate::migration::CompatibilityPosture::SuccessorOnly
            )
            && requested.schema_hash == transition.body.predecessor_schema_hash
        {
            return Err(SnapbackError::error(
                "SNAPBACK_MIGRATION_UPGRADE_REQUIRED",
                "runtime",
                "this application published a successor-only migration; upgrade the client \
                 artifacts and resync before replaying offline work",
            ));
        }
        Ok(EnsureAppAttestOutcome {
            intent: EnsureAppIntent::Attest,
            matched: active == requested,
            active,
        })
    }

    pub fn seed(&mut self, seed: SeedData) -> SnapbackResult<MutationOutput> {
        let preflight = self.authorization_commit_preflight_for_seed(&seed)?;
        self.try_with_direct_authorization_write(preflight, move |snapback| {
            let output = snapback.db.schema_seed().seed(seed)?;
            snapback.notify_live_subscriptions(&[]);
            Ok(output)
        })?
    }

    // Cheap identity/artifact facts for host-ops envelopes (LLP 0032 P6):
    // every envelope carries them, so they must not pay inspect()'s price.

    pub fn loaded_app_id(&self) -> String {
        self.db.schema().app_id.clone()
    }

    pub fn loaded_schema_hash(&self) -> Option<String> {
        self.db.schema().schema_hash.clone()
    }

    pub fn loaded_bundle_hash(&self) -> Option<String> {
        self.functions.bundle_hash.clone()
    }

    pub fn loaded_route_manifest_hash(&self) -> Option<String> {
        self.routes_manifest_hash.clone()
    }

    /// The active envelope identity bound to the active deployment's inputs.
    /// This is mode-independent so dev-generated readiness can verify the
    /// exact same persisted ensureApp fact as sessions discovery.
    pub fn loaded_api_envelope_hash(&self) -> SnapbackResult<Option<String>> {
        let snapshot = self.db.auth_mode_snapshot()?;
        let Some(deployment) = snapshot.state.active_deployment else {
            return Ok(None);
        };
        let Some(current) = self
            .db
            .api_envelope_read()
            .load_api_envelope_state()?
            .and_then(|state| state.current)
            .filter(|current| current.inputs_hash == deployment.inputs_hash)
        else {
            return Ok(None);
        };
        let Some(canonical) = self
            .db
            .api_envelope_read()
            .load_api_envelope_bytes(&current.digest)?
        else {
            return Ok(None);
        };
        let (_, observed) =
            crate::api_envelope::parse_and_validate(canonical.as_bytes()).map_err(|refusal| {
                SnapbackError::error(
                    "SNAPBACK_APP_API_STATE_PARSE_FAILED",
                    "app-api",
                    "the active API envelope failed readiness verification",
                )
                .with_details(json!({
                    "envelopeCode": refusal.code,
                    "error": refusal.message,
                }))
            })?;
        Ok((observed == current.digest).then_some(current.digest))
    }

    pub fn active_seed_identity(
        &mut self,
    ) -> SnapbackResult<Option<crate::seed_identity::ActiveSeedIdentityV1>> {
        self.db.schema_seed().active_seed_identity()
    }

    /// Validate one existing-row patch by executing the ordinary buffered
    /// writer in rollback mode. The returned row image therefore reflects
    /// storage normalization, relation stamps, uniqueness checks, and every
    /// other invariant the real commit path applies.
    ///
    /// @ref LLP 0184#a-bounded-direct-row-patch--add-now — preview and apply
    ///   reuse the normal changeset path; no raw SQL or insert/delete branch
    ///   exists here.
    pub fn preview_direct_data_patch(
        &mut self,
        input: &crate::data_patch::DataPatchPreviewInputV1,
    ) -> SnapbackResult<crate::data_patch::ValidatedDataPatchV1> {
        if input.patch.is_empty() {
            return Err(SnapbackError::error(
                "SNAPBACK_DATA_PATCH_VALIDATION_FAILED",
                "data-patch",
                "a direct row patch must contain at least one field",
            ));
        }
        let before = self
            .db
            .query_reads_read()
            .get(&input.table, &input.row_id)
            .map_err(crate::data_patch::map_storage_error)?
            .ok_or_else(crate::data_patch::row_not_found)?;
        let actual_version = before
            .get("_version")
            .and_then(Value::as_u64)
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_DATA_PATCH_VALIDATION_FAILED",
                    "data-patch",
                    "the target row has no valid per-row version",
                )
            })?;
        if actual_version != input.expected_version {
            return Err(crate::data_patch::stale_version(
                input.expected_version,
                actual_version,
            ));
        }
        let dependency = CapturedReadDependency {
            kind: CapturedReadKind::Row,
            table: Some(input.table.clone()),
            id: Some(input.row_id.clone()),
            version: Some(input.expected_version),
            predicate: None,
            rows: Vec::new(),
            field: None,
            value: None,
            order: None,
            limit: None,
            result_count: None,
            boundary: None,
        };
        let commit = self
            .db
            .mutation_writes()
            .dry_run_buffered_writes(
                &input.authority.handler_input(),
                vec![crate::storage::BufferedWrite::Patch {
                    table: input.table.clone(),
                    id: input.row_id.clone(),
                    values: input.patch.clone(),
                }],
                Vec::new(),
                Vec::new(),
                vec![dependency],
                Value::Null,
                CtxAnswerLedger::default(),
                Vec::new(),
            )
            .map_err(crate::data_patch::map_storage_error)?;
        let after = commit
            .changes
            .first()
            .and_then(|change| change.row.clone())
            .unwrap_or_else(|| before.clone());
        let mut fields = input.patch.keys().cloned().collect::<Vec<_>>();
        fields.sort();
        let before_fields = fields
            .iter()
            .filter_map(|field| {
                before
                    .get(field)
                    .cloned()
                    .map(|value| (field.clone(), value))
            })
            .collect::<BTreeMap<_, _>>();
        let after_fields = fields
            .iter()
            .filter_map(|field| {
                after
                    .get(field)
                    .cloned()
                    .map(|value| (field.clone(), value))
            })
            .collect::<BTreeMap<_, _>>();
        let live_functions = self
            .functions
            .functions
            .iter()
            .filter(|function| function.kind == FunctionKind::LiveQuery)
            .filter(|function| {
                self.function_declared_read_tables(&function.name)
                    .iter()
                    .any(|table| table == &input.table)
            })
            .map(|function| function.name.clone())
            .collect::<Vec<_>>();
        Ok(crate::data_patch::ValidatedDataPatchV1 {
            table: input.table.clone(),
            row_id: input.row_id.clone(),
            expected_version: input.expected_version,
            normalized_patch: after_fields.clone(),
            diff: crate::data_patch::DataPatchDiffV1 {
                fields,
                before: before_fields,
                after: after_fields,
            },
            affected_live_query_classes: vec![crate::data_patch::AffectedLiveQueryClassV1 {
                class: "durableTable".to_owned(),
                table: input.table.clone(),
                live_functions,
            }],
        })
    }

    /// Commit a token-owned normalized patch through the same storage writer
    /// as an app mutation, then fan its ChangedRows through the normal live
    /// notifier.
    pub fn apply_direct_data_patch(
        &mut self,
        binding: &crate::data_patch::DataPatchTokenBindingV1,
    ) -> SnapbackResult<crate::storage::MutationCommit> {
        // The host compares process context before consuming the token. Check
        // the mutable app/schema identity again under the same Local lock as
        // the commit so a concurrent artifact load cannot create a gap
        // between that comparison and storage validation.
        //
        // @ref LLP 0184#a-bounded-direct-row-patch--add-now — catalog/schema
        //   identity is part of the exact token binding, including at commit.
        if self.loaded_app_id() != binding.target.app_id
            || self.loaded_schema_hash() != binding.schema_identity
        {
            return Err(crate::data_patch::apply_context_mismatch());
        }
        let dependency = CapturedReadDependency {
            kind: CapturedReadKind::Row,
            table: Some(binding.table.clone()),
            id: Some(binding.row_id.clone()),
            version: Some(binding.expected_version),
            predicate: None,
            rows: Vec::new(),
            field: None,
            value: None,
            order: None,
            limit: None,
            result_count: None,
            boundary: None,
        };
        // @ref LLP 0184#a-bounded-direct-row-patch--add-now — the per-row
        //   dependency is the CAS; a global database-version precondition
        //   would spuriously reject unrelated concurrent writes.
        let commit = self
            .db
            .mutation_writes()
            .commit_buffered_writes(
                &binding.authority.handler_input(),
                vec![crate::storage::BufferedWrite::Patch {
                    table: binding.table.clone(),
                    id: binding.row_id.clone(),
                    values: binding
                        .normalized_patch
                        .clone()
                        .into_iter()
                        .collect::<Map<_, _>>(),
                }],
                vec![dependency],
                Value::Null,
            )
            .map_err(crate::data_patch::map_storage_error)?;
        self.notify_live_subscriptions(&commit.changes);
        Ok(commit)
    }

    #[cfg(test)]
    pub(crate) fn initialize_data_version_stream_for_test(&mut self) -> SnapbackResult<String> {
        self.db.initialize_data_version_stream_for_test()
    }

    /// Create a managed in-app branch from the exact currently served app and
    /// function bundle. IDs, custody paths, and the branch grant are all
    /// server-derived after the AdminWrite host gate; callers choose only a
    /// finite subset of currently loaded functions and a bounded TTL.
    ///
    /// @ref LLP 0162#3-safe-current-head-forks — product creation is current
    ///   head, same app/bundle, server named, and no broader than its creator.
    #[cfg(test)]
    pub(crate) fn create_operator_in_app_branch(
        &mut self,
        allowed_functions: Vec<String>,
        ttl_ms: i64,
        now_ms: i64,
    ) -> SnapbackResult<crate::fork_promotion::ManagedInAppBranchReceiptV1> {
        self.create_operator_in_app_branch_with_policy(
            allowed_functions,
            ttl_ms,
            now_ms,
            crate::fork_promotion::ForkEgressPolicyV1::DenyAll,
        )
    }

    pub(crate) fn create_operator_in_app_branch_with_policy(
        &mut self,
        mut allowed_functions: Vec<String>,
        ttl_ms: i64,
        now_ms: i64,
        egress_policy: crate::fork_promotion::ForkEgressPolicyV1,
    ) -> SnapbackResult<crate::fork_promotion::ManagedInAppBranchReceiptV1> {
        const MIN_TTL_MS: i64 = 1_000;
        const MAX_TTL_MS: i64 = 15 * 60_000;
        if !(MIN_TTL_MS..=MAX_TTL_MS).contains(&ttl_ms) {
            return Err(SnapbackError::error(
                "SNAPBACK_BRANCH_LIMIT_INVALID",
                "storage",
                "managed branch ttlMs must be between 1000 and 900000",
            ));
        }
        allowed_functions.sort();
        allowed_functions.dedup();
        if allowed_functions.is_empty()
            || allowed_functions
                .iter()
                .any(|name| self.function_kind(name).is_none())
        {
            return Err(SnapbackError::error(
                "SNAPBACK_BRANCH_AUTHORITY_DENIED",
                "auth",
                "managed branch allowedFunctions must be a non-empty subset of the served manifest",
            ));
        }
        let audience = self.loaded_app_id();
        let schema_hash = self
            .loaded_schema_hash()
            .filter(|value| !value.trim().is_empty());
        let function_bundle_hash = self
            .loaded_bundle_hash()
            .filter(|value| !value.trim().is_empty());
        if audience.is_empty() || schema_hash.is_none() || function_bundle_hash.is_none() {
            return Err(SnapbackError::error(
                "SNAPBACK_BRANCH_ARTIFACT_IDENTITY_MISSING",
                "storage",
                "managed branch creation requires a loaded app, schema hash, and function bundle hash",
            ));
        }
        let principal_id = format!("host-operator:{audience}");
        let grant_id = format!("branch-grant-v1:{}", uuid::Uuid::now_v7());
        let authority_fingerprint = crate::fork_promotion::derive_branch_authority_fingerprint(
            &principal_id,
            &grant_id,
            &audience,
        )?;
        let expires_at_ms = now_ms.checked_add(ttl_ms).ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_BRANCH_LIMIT_INVALID",
                "storage",
                "managed branch expiry overflowed",
            )
        })?;
        let request = crate::fork_promotion::InAppBranchCreateV1 {
            schema_version: 1,
            branch_id: crate::branches::BranchId(format!("branch-v1:{}", uuid::Uuid::now_v7())),
            child_stream_id: crate::branches::ChildStreamId(format!(
                "branch-stream-v1:{}",
                uuid::Uuid::now_v7()
            )),
            base_stream: self.db.current_data_version_stream()?,
            base_version: self.db.versions_read().current_version()?,
            artifact_binding: crate::fork_promotion::BranchArtifactBindingV1 {
                schema_hash: schema_hash.expect("validated schema hash"),
                function_bundle_hash: function_bundle_hash.expect("validated function bundle hash"),
            },
            grant: crate::fork_promotion::BranchGrantV1 {
                principal_id,
                grant_id,
                audience,
                authority_fingerprint,
                allowed_functions,
                allowed_lanes: vec!["ordinaryMutation".to_owned()],
                expires_at_ms,
            },
            limits: crate::fork_promotion::BranchLimitsV1 {
                max_live_branches_per_principal: 8,
                max_live_branches_per_app: 32,
                max_operations: 256,
                max_retained_bytes: 8 * 1024 * 1024,
                max_diff_rows: 10_000,
                max_digest_work_bytes: 64 * 1024 * 1024,
                ttl_ms,
            },
            coverage: crate::fork_promotion::ForkCoverageV1 {
                covered_lanes: vec!["ordinaryMutation".to_owned()],
                uncovered_lanes: vec!["productionWriterCoverage".to_owned()],
                schema_covered: false,
                system_fields_covered: false,
                assets_covered: false,
                effects_covered: egress_policy
                    == crate::fork_promotion::ForkEgressPolicyV1::CaptureOnly,
            },
            egress_policy,
            created_at_ms: now_ms,
        };
        self.db.branch_ops().create_managed_in_app_branch(&request)
    }

