    pub fn inspect(&mut self) -> SnapbackResult<InspectState> {
        let mut inspect = self.inspect_core()?;
        inspect.ephemeral = self.ephemeral.diagnostics();
        Ok(inspect)
    }

    /// Capture Local/SQLite-owned inspect state only. Managed server callers
    /// release Local before composing [`EphemeralDiagnostics`] on their
    /// blocking owner; direct-library [`Self::inspect`] remains synchronous.
    pub fn inspect_core(&mut self) -> SnapbackResult<InspectState> {
        // @ref LLP 0010#v0-implementation-charter — missing non-v0 capabilities must be reported explicitly.
        let capability_gaps = self.capability_gaps();
        let capability_manifest = self.served_capability_manifest(capability_gaps.clone());
        let active_live_functions = self.active_live_functions();
        let cron = self
            .cron
            .inspect(&self.functions, &active_live_functions, now_millis());

        Ok(InspectState {
            artifact_kind: "runtimeState".to_owned(),
            schema_version: SNAPBACK_SCHEMA_VERSION.to_owned(),
            target_profile_id: TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX.to_owned(),
            target: TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX.to_owned(),
            storage: self.db.info()?,
            runtime: self.runtime.capabilities().clone(),
            schema: self.db.schema().clone(),
            functions: self.functions.clone(),
            capability_manifest,
            route_manifest_hash: self
                .routes_manifest_hash
                .clone()
                .unwrap_or_else(|| "absent".to_owned()),
            subscriptions: self
                .subscriptions
                .values()
                .map(|subscription| LiveSubscriptionInfo {
                    id: subscription.id.clone(),
                    connection_id: subscription.connection_id.clone(),
                    function: subscription.function.clone(),
                })
                .collect(),
            active_connections: self.connections_last_seen.len(),
            reaped_connections: self.reaped_connections,
            live_delivery: self.live_delivery.clone(),
            live_matcher: self.live_matcher_stats.clone(),
            live_evaluation: self.live_evaluation_stats.clone(),
            live_coalesce: self.live_coalesce_stats.clone(),
            live_settlement: self
                .live_settlement_stats
                .lock()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .clone(),
            live_authority: self.live_authority_stats.clone(),
            live_watermarks: self.live_watermark_stats.clone(),
            ephemeral: EphemeralDiagnostics::default(),
            cron,
            maintenance: self.maintenance.clone(),
            telemetry: self.telemetry.diagnostics(),
            push_registry: self.db.push_registry_inspection()?,
            recent_diagnostics: self.recent_diagnostics.iter().cloned().collect(),
            capability_gaps,
        })
    }

    /// Compose the served capability manifest from this exact process's live
    /// facts: the shared instance constructor plus the post-construction
    /// warm-VM lifecycle override. Every reporting seam (`/inspect`, the RQS
    /// generation identity) goes through this one helper so the override
    /// cannot drift between seams
    /// (issues/20260729-centralize-served-capability-manifest-composition.md).
    // @ref LLP 0076#target-contract — the served manifest is instance-live:
    // it reflects whether THIS process enabled outbound egress and so the
    // bounded response-stream profile, not the conservative declaration.
    fn served_capability_manifest(&self, capability_gaps: Vec<String>) -> CapabilityManifest {
        let mut capability_manifest = CapabilityManifest::local_v0_instance(
            capability_gaps,
            crate::runtime::outbound_actions_enabled(),
        );
        // @ref LLP 0009#dk-4-retired--upstream-ibex-owner-thread-contract-2026-07-27 —
        // report the lifecycle policy honestly. The compatibility branch is
        // retained for older policy implementations.
        if self.warm_vms.enabled() {
            capability_manifest.vm_lifecycle =
                crate::manifest::VM_LIFECYCLE_WARM_POOLED_RESET.to_owned();
        }
        self.project_agent_safe_app_effective(&mut capability_manifest);
        capability_manifest
    }

    pub fn current_capability_manifest(&self) -> CapabilityManifest {
        self.served_capability_manifest(self.capability_gaps())
    }

    #[cfg(any(test, feature = "test-support"))]
    pub fn force_ibex_cli_unavailable_for_test(&mut self) {
        self.runtime.force_ibex_cli_unavailable_for_test();
        self.refresh_read_manifests();
    }

    fn project_agent_safe_app_effective(&self, manifest: &mut CapabilityManifest) {
        use crate::manifest::{AgentSafeCapabilityFactsV1, TargetCapabilityId};

        if !manifest
            .supported_capabilities
            .contains(&TargetCapabilityId::AgentSafeStorageV1)
            || !self
                .db
                .agent_safe_exact_operation_coverage_active()
                .unwrap_or(false)
        {
            return;
        }

        let target = &manifest.agent_safe.target;
        let mut effective = AgentSafeCapabilityFactsV1::missing();
        let mut ordinary_host_plan = false;
        let mut ordinary_ibex = false;
        let mut host_child_host_plan = false;
        let mut host_child_ibex = false;
        for function in &self.functions.functions {
            match (&function.kind, &function.runtime) {
                (
                    FunctionKind::Mutation,
                    FunctionRuntime::HostPlan(
                        HandlerPlan::Mutation(_) | HandlerPlan::WriteWithActivity(_),
                    ),
                ) => ordinary_host_plan = true,
                (FunctionKind::Mutation, FunctionRuntime::IbexModule(_)) => ordinary_ibex = true,
                (FunctionKind::Action, FunctionRuntime::HostPlan(HandlerPlan::Action(plan))) => {
                    for step in &plan.steps {
                        let ActionStep::RunMutation { name, .. } = step;
                        let Some(target_function) = self.functions.function(name) else {
                            continue;
                        };
                        match &target_function.runtime {
                            FunctionRuntime::HostPlan(
                                HandlerPlan::Mutation(_) | HandlerPlan::WriteWithActivity(_),
                            ) => host_child_host_plan = true,
                            FunctionRuntime::IbexModule(_)
                                if target_function.kind == FunctionKind::Mutation =>
                            {
                                host_child_ibex = true;
                            }
                            _ => {}
                        }
                    }
                }
                _ => {}
            }
        }
        if ordinary_host_plan {
            effective.envelope.ordinary_mutation.host_plan =
                target.envelope.ordinary_mutation.host_plan;
        }
        if ordinary_ibex {
            effective.envelope.ordinary_mutation.ibex_buffered =
                target.envelope.ordinary_mutation.ibex_buffered;
        }
        if host_child_host_plan {
            effective.envelope.host_child_mutation.host_plan =
                target.envelope.host_child_mutation.host_plan;
        }
        if host_child_ibex {
            effective.envelope.host_child_mutation.ibex_buffered =
                target.envelope.host_child_mutation.ibex_buffered;
        }
        let mut profiles = self
            .functions
            .functions
            .iter()
            .filter_map(|function| agent_safe_generated_owner_profile(function, self.db.schema()))
            .collect::<Vec<_>>();
        profiles.sort();
        profiles.dedup();
        effective.explanation.scoped_facts = profiles
            .into_iter()
            .filter(|_| ordinary_host_plan)
            .filter_map(|profile| {
                target
                    .explanation
                    .scoped_facts
                    .iter()
                    .find(|fact| fact.scope.profile == profile)
                    .cloned()
            })
            .collect();
        manifest.agent_safe.app_effective = effective;
    }

    fn capability_gaps(&self) -> Vec<String> {
        // The declared gap list is owned by the manifest module (the single
        // source the committed capability artifact is generated from —
        // LLP 0032 P2); only instance-live adjustments happen here.
        let mut capability_gaps = crate::manifest::local_v0_default_capability_gaps();
        if self.runtime.capabilities().ibex_cli.available {
            capability_gaps.retain(|gap| gap != "ibex_cli");
        } else {
            capability_gaps.push("ibex_cli".to_owned());
        }
        if crate::runtime::outbound_actions_enabled() {
            capability_gaps
                .retain(|gap| gap != "outbound_actions" && gap != "bounded_response_stream_v1");
        }
        capability_gaps
    }

    /// The persisted receipt of the last `RebuildMaintainedProjection` of
    /// `plan_id` (LLP 0080 §5 / the minimal 0081 slice): the verification
    /// surface the coupled suite consumes; `snapback migrate verify` is its
    /// operator-facing successor.
    pub fn projection_rebuild_receipt(
        &self,
        plan_id: &str,
    ) -> SnapbackResult<Option<crate::storage::ProjectionRebuildReceipt>> {
        self.db.projection_rebuild_receipt(plan_id)
    }

    pub fn invoke_query(&self, name: &str, input: HandlerInput) -> SnapbackResult<QueryOutput> {
        Ok(self
            .invoke_query_with_dependencies_from_source(name, input, InvocationSource::LocalQuery)?
            .output)
    }

    pub(crate) fn invoke_query_with_dependencies_from_source(
        &self,
        name: &str,
        input: HandlerInput,
        source: InvocationSource,
    ) -> SnapbackResult<QueryInvocation> {
        let authority = InvocationGate::prepare_admitted_dev_input(
            source,
            ServerProfile::Dev,
            &input,
            self.admission.admit_dev()?,
        )?;
        self.invoke_query_with_dependencies_prepared(name, input, authority)
    }

    pub(crate) fn invoke_query_with_dependencies_prepared(
        &self,
        name: &str,
        input: HandlerInput,
        authority: PreparedAuthority,
    ) -> SnapbackResult<QueryInvocation> {
        self.invoke_query_with_dependencies_prepared_generation(name, input, authority, None)
    }

    pub fn invoke_query_with_dependencies_prepared_generation(
        &self,
        name: &str,
        input: HandlerInput,
        authority: PreparedAuthority,
        expected_generation: Option<&ArtifactGeneration>,
    ) -> SnapbackResult<QueryInvocation> {
        self.validate_prepared_service_authority(&authority)?;
        let function = resolve_invocation_function(
            &self.function_generation_recovery_state,
            &self.functions,
            name,
            &[FunctionKind::Query, FunctionKind::LiveQuery],
        )?;
        self.validate_expected_generation(&authority, expected_generation)?;
        let prepared = InvocationGate::prepare_function(authority, function)?;
        let input = prepared.canonicalize_input(input);
        let correlation = telemetry_correlation(&input.correlation);
        let span = self.telemetry.start_classified_span(
            crate::telemetry_contract::OperationClassIdV1::FUNCTION_QUERY,
            name,
            correlation.as_deref(),
            prepared.telemetry_caller_details(),
        );
        let mut result =
            crate::runtime::with_runtime_log_telemetry(self.telemetry.clone(), correlation, || {
                execute_query_invocation(
                    Some(&self.db),
                    function,
                    name,
                    DbRead::Live(&self.db),
                    &self.permission_epochs,
                    input,
                    &prepared,
                    Some(&self.warm_vms),
                    Some(RelationalCursorAuthority {
                        app_id: &self.functions.app_id,
                        keyring: &self.resume_keyring,
                        schema_hash: self.db.schema().schema_hash.as_deref(),
                        function_bundle_hash: self.functions.bundle_hash.as_deref(),
                        function_publication_generation: self.app_generation,
                        target_profile: self.db.schema().target_profile.as_deref(),
                    }),
                    None,
                    None,
                )
            });
        finish_function_observation(span, &mut result);
        result
    }

    /// Ordinary finite query establishment with the optional LLP 0157 proof
    /// carrier. Proof-requested calls deliberately use the coherent app lane:
    /// result evaluation, witness capture, signing, and optional terminal
    /// page-set composition all complete before the HTTP response can publish.
    // @ref LLP 0094#llp-0157-finite-carrier-completeness-amendment--2026-08-04 — finite proof/witness/page-set members publish atomically.
    #[cfg_attr(not(test), allow(dead_code))]
    pub(crate) fn invoke_finite_query_prepared_generation(
        &self,
        name: &str,
        input: HandlerInput,
        authority: PreparedAuthority,
        expected_generation: Option<&ArtifactGeneration>,
        namespace: Option<&QueryNamespace>,
        prior_proofs: &[crate::completeness::CompletenessProofV1],
    ) -> SnapbackResult<crate::manifest::FiniteQueryOutput> {
        self.invoke_finite_query_with_dependencies_prepared_generation(
            name,
            input,
            authority,
            expected_generation,
            namespace,
            prior_proofs,
        )
        .map(|(output, _dependencies)| output)
    }

    /// Finite-query proof composition retains the same captured dependencies
    /// as the ordinary query lane so the app-data invocation ring can report
    /// D1 evidence without changing the public response carrier.
    pub fn invoke_finite_query_with_dependencies_prepared_generation(
        &self,
        name: &str,
        input: HandlerInput,
        authority: PreparedAuthority,
        expected_generation: Option<&ArtifactGeneration>,
        namespace: Option<&QueryNamespace>,
        prior_proofs: &[crate::completeness::CompletenessProofV1],
    ) -> SnapbackResult<(
        crate::manifest::FiniteQueryOutput,
        Vec<CapturedReadDependency>,
    )> {
        if namespace.is_none() && !prior_proofs.is_empty() {
            return Err(SnapbackError::error(
                "SNAPBACK_COMPLETENESS_PROOF_ISSUANCE_FAILED",
                "composition",
                "prior completeness proofs require completenessNamespace",
            ));
        }
        let proof_input = input.clone();
        let invocation = self.invoke_query_with_dependencies_prepared_generation(
            name,
            input,
            authority,
            expected_generation,
        )?;
        let function = self.function(name)?;
        let issued = self.issue_completeness_proof(
            function,
            &proof_input,
            &invocation.output,
            namespace,
            prior_proofs,
        )?;
        let read_dependencies = invocation.read_dependencies;
        let output = match issued {
            Some((proof, witness, page_set_manifest)) => crate::manifest::FiniteQueryOutput {
                output: invocation.output,
                completeness_proof: Some(proof),
                authorization_witness: Some(witness),
                page_set_manifest,
            },
            None => crate::manifest::FiniteQueryOutput::without_proof(invocation.output),
        };
        Ok((output, read_dependencies))
    }

