    /// Whether this target performs image finalization (the
    /// `asset-image-finalization` fact). Reads the declared capability
    /// facts block — the same single source the manifest embeds — so the
    /// runtime gate and the advertised claim can never disagree; the
    /// override exists for tests that pin the disabled posture.
    pub(crate) fn asset_image_finalization_enabled(&self) -> bool {
        static DECLARED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
        self.asset_image_finalization_override.unwrap_or_else(|| {
            *DECLARED.get_or_init(|| {
                crate::assets::AssetTargetFactsV1::local_v1()
                    .image
                    .is_some()
            })
        })
    }

    #[cfg(test)]
    pub(crate) fn set_asset_image_finalization_override(&mut self, enabled: bool) {
        self.asset_image_finalization_override = Some(enabled);
    }

    /// Whether this target performs video finalization (the
    /// `asset-video-finalization` fact) — the declared-facts read, exactly
    /// the image gate's shape.
    pub(crate) fn asset_video_finalization_enabled(&self) -> bool {
        static DECLARED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
        self.asset_video_finalization_override.unwrap_or_else(|| {
            *DECLARED.get_or_init(|| {
                crate::assets::AssetTargetFactsV1::local_v1()
                    .video
                    .is_some()
            })
        })
    }

    #[cfg(test)]
    pub(crate) fn set_asset_video_finalization_override(&mut self, enabled: bool) {
        self.asset_video_finalization_override = Some(enabled);
    }

    /// The experimental acknowledgement for cut-import application: the
    /// env var in production, the override in tests (env mutation is
    /// process-global and would race parallel tests).
    pub(crate) fn asset_import_experimental_acknowledged(&self) -> bool {
        self.asset_import_experimental_override.unwrap_or_else(|| {
            std::env::var("SNAPBACK_ASSET_IMPORT_EXPERIMENTAL").as_deref() == Ok("1")
        })
    }

    #[cfg(test)]
    pub(crate) fn set_asset_import_experimental_override(&mut self, enabled: bool) {
        self.asset_import_experimental_override = Some(enabled);
    }

    /// The app's reference-GC opt-in, admitted only where the declared
    /// target facts carry the reference-GC block: `None` disables the sweep
    /// entirely (LLP 0044 §Deletion — opt-in, never a default).
    pub(crate) fn asset_reference_gc_grace_ms(&self) -> Option<u64> {
        static DECLARED: std::sync::OnceLock<bool> = std::sync::OnceLock::new();
        let target_supports = *DECLARED.get_or_init(|| {
            crate::assets::AssetTargetFactsV1::local_v1()
                .reference_gc
                .is_some()
        });
        if !target_supports {
            return None;
        }
        self.db
            .schema()
            .assets
            .as_ref()?
            .reference_gc
            .as_ref()
            .map(|policy| policy.grace_ms)
    }

    /// Whether the declared facts advertise a delivery profile — the same
    /// single source the manifest embeds, so the runtime gate and the
    /// advertised claim can never disagree.
    pub(crate) fn asset_delivery_profile_declared(profile: &str) -> bool {
        static DECLARED: std::sync::OnceLock<Vec<String>> = std::sync::OnceLock::new();
        DECLARED
            .get_or_init(|| crate::assets::AssetTargetFactsV1::local_v1().delivery_profiles)
            .iter()
            .any(|declared| declared == profile)
    }

    /// The app logical quota, overridable in tests so exceed paths are
    /// exercisable without gigabyte fixtures.
    pub(crate) fn asset_app_quota(&self) -> u64 {
        self.asset_quota_override
            .unwrap_or(crate::assets::ASSET_APP_LOGICAL_QUOTA_BYTES)
    }

    #[cfg(test)]
    pub(crate) fn set_asset_quota_override(&mut self, quota: u64) {
        self.asset_quota_override = Some(quota);
    }

    /// The store-agnostic seam every production asset path uses. Selection
    /// is deployment configuration: `SNAPBACK_ASSET_STORE=s3` chooses the
    /// S3-compatible store. The unqualified refusal consults the same
    /// declared-facts source the manifest embeds: while the local target's
    /// `assetLifecycleStores` names the s3-compatible parameter (earned by
    /// the live MinIO qualification drill, 2026-08-03), selection is
    /// admitted; were the fact ever withdrawn, the refusal returns and only
    /// the experimental override acknowledges the unqualified posture.
    /// Default: local-fs.
    pub(crate) fn asset_store_obj(
        &self,
    ) -> SnapbackResult<std::sync::Arc<dyn crate::assets_store::AssetStore>> {
        match self.asset_store_config.backend()? {
            crate::assets_store::AssetStoreBackend::S3 => {
                // @ref LLP 0158#the-runtime-plane--where-the-real-design-is —
                // inherited provider credentials cannot turn a derived fork
                // into an outbound asset client.
                self.deny_derived_fork_egress(
                    crate::instance_fork::EgressFamily::AssetProvider,
                    now_millis(),
                )?;
                // @ref LLP 0044#capability-facts-and-implementation-slices —
                //   the runtime gate and the advertised claim share one
                //   source, so they can never disagree (the same pattern as
                //   `asset_delivery_profile_declared`).
                let s3_declared = crate::assets::AssetTargetFactsV1::local_v1()
                    .lifecycle_stores
                    .iter()
                    .any(|store| store == crate::assets_s3::ASSET_STORE_S3_COMPATIBLE);
                if !s3_declared && !self.asset_store_config.s3_experimental() {
                    return Err(SnapbackError::error(
                        "SNAPBACK_ASSET_STORE_UNQUALIFIED",
                        "assets",
                        "the s3-compatible store has no qualified target yet; \
                         set SNAPBACK_ASSET_S3_EXPERIMENTAL=1 to acknowledge \
                         an unqualified development posture",
                    ));
                }
                let config = self.asset_store_config.s3()?;
                Ok(std::sync::Arc::new(crate::assets_s3::AssetS3Store::new(
                    config,
                    Box::new(crate::assets_s3::UreqTransport),
                )))
            }
            crate::assets_store::AssetStoreBackend::LocalFs => {
                Ok(std::sync::Arc::new(self.asset_store()?))
            }
        }
    }

    pub(crate) fn asset_store(&self) -> SnapbackResult<crate::assets::AssetFsStore> {
        // File-backed instances root the store beside the database; memory
        // instances (tests, --memory) mint a per-instance temp root — the
        // same "will not persist" posture as the rest of a memory instance,
        // and never shared, so this instance's staging-orphan sweep can only
        // ever see files this instance's database owns.
        let dir = match self.db.database_path() {
            Some(path) => path
                .parent()
                .map(std::path::Path::to_path_buf)
                .unwrap_or_else(|| std::path::PathBuf::from(".")),
            None => self
                .asset_memory_store_root
                .get_or_init(|| {
                    std::env::temp_dir().join(format!(
                        "snapback-assets-{}-{}",
                        self.functions.app_id,
                        crate::assets::AssetFsStore::new_opaque_key()
                    ))
                })
                .clone(),
        };
        crate::assets::AssetFsStore::open(&dir)
    }

    /// The synthesized authorizer definition: kind Query for admission
    /// constraints, but executed through the dedicated asset runner (the
    /// authorizer's closed output contract is an object, not rows). Never
    /// inserted into any public function listing.
    fn asset_intent_definition(
        &self,
        intent: &crate::manifest::AssetUploadIntentDefinition,
    ) -> SnapbackResult<crate::manifest::FunctionDefinition> {
        serde_json::from_value(serde_json::json!({
            "id": intent.id,
            "name": format!("__assetIntentAuthorizer__{}", intent.name),
            "kind": "Query",
            "runtime": serde_json::to_value(&intent.runtime).map_err(|error| {
                SnapbackError::error(
                    "SNAPBACK_ASSET_RECORD_INVALID",
                    "assets",
                    format!("intent runtime does not serialize: {error}"),
                )
            })?,
            "authRequirement": intent.auth_requirement,
        }))
        .map_err(|error| {
            SnapbackError::error(
                "SNAPBACK_ASSET_RECORD_INVALID",
                "assets",
                format!("intent authorizer definition does not synthesize: {error}"),
            )
        })
    }

    fn asset_caller_principal(authority: &PreparedAuthority) -> Option<String> {
        match authority.resolved() {
            ResolvedAppAuthority::Session { user_id, .. }
            | ResolvedAppAuthority::RevalidatedPrincipal { user_id, .. } => Some(user_id.clone()),
            ResolvedAppAuthority::DevImpersonation { user_id, .. } => Some(user_id.clone()),
            ResolvedAppAuthority::ServicePrincipal {
                actor_user_id,
                effective_user_id,
                ..
            } => Some(
                effective_user_id
                    .clone()
                    .unwrap_or_else(|| actor_user_id.clone()),
            ),
            ResolvedAppAuthority::Anonymous
            | ResolvedAppAuthority::AdminBypass { .. }
            | ResolvedAppAuthority::System => None,
        }
    }

    /// Safe caller identity facts for the admission record: identity and
    /// generation only — never tokens, deadlines, or provider material.
    fn asset_auth_pair(authority: &PreparedAuthority) -> serde_json::Value {
        match authority.resolved() {
            ResolvedAppAuthority::Session {
                user_id,
                generation,
                authority_instance_id,
                ..
            } => serde_json::json!({
                "kind": "session",
                "userId": user_id,
                "generation": generation,
                "authorityInstanceId": authority_instance_id,
            }),
            ResolvedAppAuthority::DevImpersonation { user_id, .. } => {
                serde_json::json!({ "kind": "dev", "userId": user_id })
            }
            ResolvedAppAuthority::ServicePrincipal {
                actor_user_id,
                effective_user_id,
                grant_id,
                ..
            } => serde_json::json!({
                "kind": "servicePrincipal",
                "actorUserId": actor_user_id,
                "effectiveUserId": effective_user_id,
                "grantId": grant_id,
            }),
            other => serde_json::json!({ "kind": format!("{other:?}") }),
        }
    }

    pub fn asset_attempt_create(
        &mut self,
        authority: &PreparedAuthority,
        request: crate::assets::AssetAttemptCreateRequestV1,
    ) -> SnapbackResult<crate::assets::AssetAttemptCreateResponseV1> {
        use crate::assets;

        let intent = self.asset_intent(&request.intent_id)?.clone();
        let deployed_implementation_hash = intent
            .implementation_hash
            .as_deref()
            .filter(|hash| !hash.is_empty())
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_ASSET_INTENT_IDENTITY_INVALID",
                    "assets",
                    "the deployed upload intent is missing implementationHash",
                )
                .with_details(serde_json::json!({ "intentId": intent.id }))
            })?;
        // A stale or target-incompatible generated reference refuses before
        // reserving an asset id or writing staging bytes.
        if intent.intent_policy_hash != request.intent_policy_hash
            || request.implementation_hash.as_deref() != Some(deployed_implementation_hash)
        {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_INTENT_STALE",
                "assets",
                "the generated upload reference does not match the deployed intent policy and implementation",
            )
            .with_details(serde_json::json!({ "intentId": intent.id })));
        }
        // Defense in depth beside codegen's manifest-keyed admission: an
        // intent whose declared delivery profile this target does not
        // advertise refuses before any state exists (LLP 0044: "a target
        // advertises supported profiles and refuses an intent it cannot
        // honor").
        let profile_name = match intent.delivery.kind {
            assets::AssetDeliveryProfile::PublicImmutable => "public-immutable",
            assets::AssetDeliveryProfile::PrivateSigned => "private-signed",
            assets::AssetDeliveryProfile::PrivateStrict => "private-strict",
        };
        if !Self::asset_delivery_profile_declared(profile_name) {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_DELIVERY_PROFILE_UNSUPPORTED",
                "assets",
                format!("this target does not advertise the {profile_name} delivery profile"),
            ));
        }
        let declared_length = request.declared_length.ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_ASSET_DEFERRED_LENGTH_UNSUPPORTED",
                "assets",
                "every v1 lane requires a known total length at attempt creation",
            )
        })?;
        if declared_length > intent.accept.max_bytes {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_MEDIA_BOUNDS_EXCEEDED",
                "assets",
                format!(
                    "declared length {declared_length} exceeds the intent's maxBytes {}",
                    intent.accept.max_bytes
                ),
            ));
        }
        if (intent.image.is_some() || intent.video.is_some())
            && declared_length > assets::ASSET_BUFFERED_FINALIZE_MAX_BYTES
        {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_MEDIA_BOUNDS_EXCEEDED",
                "assets",
                format!(
                    "declared length {declared_length} exceeds the buffered finalizer ceiling {}",
                    assets::ASSET_BUFFERED_FINALIZE_MAX_BYTES
                ),
            )
            .with_details(serde_json::json!({
                "limit": assets::ASSET_BUFFERED_FINALIZE_MAX_BYTES,
                "observed": declared_length,
                "path": "buffered-finalizer",
            })));
        }
        if let Some(declared) = &request.declared_content_type
            && !asset_media_type_admitted(&intent.accept.media_types, declared)
        {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_MEDIA_TYPE_UNSUPPORTED",
                "assets",
                format!("declared content type {declared} is outside the intent's accept list"),
            ));
        }

        let caller = Self::asset_caller_principal(authority);
        // Every authorizer must declare an owner, so a caller without a
        // resolved principal is guaranteed to fail every later ownership check.
        if caller.is_none() {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_OWNER_CUSTODY_UNSATISFIABLE",
                "assets",
                "every upload attempt records the authorizer-declared owner principal, and each transfer, resume, finalize, and attach step must present that owner's resolved authority; an anonymous caller can never satisfy it, so this reservation could never complete. Reserve with real caller custody: an ordinary session (for local development, snapback session mint --email <email> behind a trusted broker) or operator impersonation (snapback assets put --user <handle>).",
            )
            .with_details(serde_json::json!({ "intentId": intent.id })));
        }

        // Run the generated authorizer under the protected profile, capturing
        // the complete LLP 0007 read-set witness.
        let definition = self.asset_intent_definition(&intent)?;
        let prepared = InvocationGate::prepare_function(authority.clone(), &definition)?;
        let module = match &intent.runtime {
            crate::manifest::FunctionRuntime::IbexModule(module) => module.clone(),
            _ => {
                return Err(SnapbackError::error(
                    "SNAPBACK_ASSET_INTENT_RUNTIME_UNSUPPORTED",
                    "assets",
                    "upload-intent authorizers run as Ibex modules in v1",
                ));
            }
        };
        let input = prepared.canonicalize_input(crate::manifest::HandlerInput {
            args: request.args.clone(),
            ..Default::default()
        });
        let run = self.db.query_reads_read().with_pinned_read_view(|db| {
            crate::runtime::run_ibex_asset_authorizer_prepared(
                &module,
                input.clone(),
                &prepared,
                db,
            )
        })?;

        let auth_pair = Self::asset_auth_pair(authority);
        let witness = serde_json::to_value(&run.read_dependencies).unwrap_or_default();
        let app_id = self.functions.app_id.clone();
        let now = now_millis();
        let store = self.asset_store_obj()?;
        let app_quota = self.asset_app_quota();

        let intent_artifact_json = serde_json::to_string(&intent).map_err(|error| {
            SnapbackError::error(
                "SNAPBACK_ASSET_RECORD_INVALID",
                "assets",
                format!("intent definition does not serialize for retention: {error}"),
            )
        })?;
        let response = self.db.asset_attempts().attempt_create(
            &intent,
            deployed_implementation_hash,
            &intent_artifact_json,
            now,
            &app_id,
            app_quota,
            &caller,
            declared_length,
            &request,
            &run.owner,
            &auth_pair,
            &witness,
        )?;
        let (attempt, predecessor) = response;
        if let Some(predecessor) = &predecessor {
            // Store-side fencing: the superseded attempt's staging object is
            // removed so late bytes have nowhere to land. Idempotent; a crash
            // here leaves an orphan the attempt-GC sweep reclaims.
            store.delete_staging_pair(&predecessor.staging_key)?;
        }
        let task = asset_task_state(&attempt, None);
        Ok(crate::assets::AssetAttemptCreateResponseV1 {
            transfer: crate::assets::AssetTusInstructionV1 {
                upload_url: format!("/assets/tus/{}", attempt.attempt_id),
                tus_resumable: crate::assets::ASSET_TUS_VERSION.to_owned(),
                upload_length: attempt.declared_length,
                expires_at_ms: attempt.expires_at_ms,
                checksum_algorithms: crate::assets::ASSET_TUS_CHECKSUM_ALGORITHMS
                    .iter()
                    .map(|algorithm| (*algorithm).to_owned())
                    .collect(),
                max_chunk_bytes: crate::assets::ASSET_MAX_CHUNK_BYTES,
            },
            task,
        })
    }

    /// Load an attempt for a caller, enforcing the auth-session lineage rule
    /// (the caller's server-resolved principal must be the admission's) and
    /// applying lazy TTL expiry.
    fn asset_attempt_for_caller(
        &mut self,
        authority: &PreparedAuthority,
        attempt_id: &str,
    ) -> SnapbackResult<crate::assets::AssetAttemptRecordV1> {
        let caller = Self::asset_caller_principal(authority);
        let now = now_millis();
        let (attempt, expired_staging) =
            self.db
                .asset_reads()
                .attempt_for_caller(caller.as_deref(), attempt_id, now)?;
        if let Some(staging_key) = expired_staging {
            self.asset_store_obj()?.delete_staging_pair(&staging_key)?;
        }
        Ok(attempt)
    }

    pub fn asset_attempt_inspect(
        &mut self,
        authority: &PreparedAuthority,
        attempt_id: &str,
    ) -> SnapbackResult<crate::assets::AssetTaskStateV1> {
        let attempt = self.asset_attempt_for_caller(authority, attempt_id)?;
        let asset = self.db.asset_reads().load_asset(&attempt.asset_id)?;
        Ok(asset_task_state(&attempt, asset.as_ref()))
    }

    /// The caller-facing asset metadata read (LLP 0044 §Asset read
    /// authorization): decides through the declared read-access policy —
    /// owner-only, or via-references over asset-sharing-declared analyzable
    /// row policies — and refuses without leaking whether a foreign asset
    /// exists differently from a missing one.
    pub fn asset_record_inspect(
        &mut self,
        authority: &PreparedAuthority,
        asset_id: &str,
    ) -> SnapbackResult<Value> {
        let caller = Self::asset_caller_principal(authority);
        let schema = self.db.schema().clone();
        self.db
            .asset_reads()
            .record_inspect(&schema, caller.as_deref(), asset_id)
    }

    /// One live projection run: the caller's authorized view of one asset
    /// record. Rows are `[record]` when readable and `[]` otherwise — absence
    /// and denial blank rather than error, so revocation delivers an empty
    /// replace instead of tearing the subscription down. The dependency
    /// vector is the delivery fingerprint: it starts with a synthetic row
    /// dependency carrying the record's observable facts, then the complete
    /// LLP 0053-classified read-decision capture, so "dependencies changed"
    /// is exactly "this subscriber must hear about it".
    fn asset_record_projection(
        &mut self,
        caller: Option<&str>,
        asset_id: &str,
    ) -> SnapbackResult<(Vec<Value>, Vec<CapturedReadDependency>)> {
        let schema = self.db.schema().clone();
        self.db
            .asset_reads()
            .record_projection(&schema, caller, asset_id)
    }

    /// Route one reserved native live query to its invocation. Every seam
    /// that recomputes a reserved subscription — subscribe, resume
    /// resnapshot, the witnessed episode, and both frame-loop rerun paths —
    /// dispatches through here so a new reserved projection cannot miss one.
    fn reserved_live_invocation(
        &mut self,
        authority: &PreparedAuthority,
        function: &str,
        input: &HandlerInput,
    ) -> SnapbackResult<QueryInvocation> {
        if function == ASSET_RECORD_LIVE_FUNCTION {
            self.asset_record_query_invocation(authority, input)
        } else if function == MY_MEMBERSHIPS_LIVE_FUNCTION {
            self.my_memberships_query_invocation(authority, input)
        } else {
            Err(SnapbackError::error(
                "SNAPBACK_FUNCTION_NOT_LIVE",
                "runtime",
                format!("{function} is not a reserved live query"),
            ))
        }
    }

    /// The caller's own membership rows for one declared membership
    /// (LLP 0056 self-projection). Dependencies are the rows read plus one
    /// query-range capture over the caller's principal slice — including the
    /// pinned empty capture, so a first grant moves the fingerprint and
    /// wakes a previously blank subscription through the conservative
    /// reserved-lane recompute.
    fn my_memberships_query_invocation(
        &mut self,
        authority: &PreparedAuthority,
        input: &HandlerInput,
    ) -> SnapbackResult<QueryInvocation> {
        let membership_id = input
            .args
            .get("membership")
            .and_then(Value::as_str)
            .map(str::to_owned)
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_MEMBERSHIP_LIVE_INPUT_INVALID",
                    "auth",
                    "the my-memberships projection requires a string `membership` argument",
                )
            })?;
        let schema = self.db.schema().clone();
        let declaration = schema
            .tables
            .iter()
            .find_map(|table| {
                table.membership.as_ref().and_then(|membership| {
                    (membership.effective_id(&table.name) == membership_id.as_str())
                        .then(|| (table.name.clone(), membership.clone()))
                })
            })
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_MEMBERSHIP_LIVE_INPUT_INVALID",
                    "auth",
                    format!("no membership declaration named {membership_id}"),
                )
            })?;
        let (table_name, membership) = declaration;
        let caller = Self::asset_caller_principal(authority);
        let version = self.db.versions_read().current_version()?;
        let (rows, read_dependencies) =
            self.my_memberships_projection(caller.as_deref(), &table_name, &membership)?;
        Ok(QueryInvocation {
            output: crate::manifest::QueryOutput {
                version,
                rows,
                cursor: None,
            },
            read_dependencies,
        })
    }

    fn my_memberships_projection(
        &mut self,
        caller: Option<&str>,
        table_name: &str,
        membership: &crate::manifest::MembershipManifest,
    ) -> SnapbackResult<(Vec<Value>, Vec<CapturedReadDependency>)> {
        self.db
            .membership_reads()
            .read_my_memberships_projection(caller, table_name, membership)
    }

    /// The reserved system live query's initial snapshot (LLP 0044 §Live
    /// asset lifecycle). Rides the ordinary subscribe machinery; only the
    /// execution is native.
    fn asset_record_query_invocation(
        &mut self,
        authority: &PreparedAuthority,
        input: &HandlerInput,
    ) -> SnapbackResult<QueryInvocation> {
        let asset_id = input
            .args
            .get("assetId")
            .and_then(Value::as_str)
            .map(str::to_owned)
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_ASSET_LIVE_INPUT_INVALID",
                    "assets",
                    "the asset record projection requires a string `assetId` argument",
                )
            })?;
        let caller = Self::asset_caller_principal(authority);
        let version = self.db.versions_read().current_version()?;
        let (rows, read_dependencies) =
            self.asset_record_projection(caller.as_deref(), &asset_id)?;
        Ok(QueryInvocation {
            output: crate::manifest::QueryOutput {
                version,
                rows,
                cursor: None,
            },
            read_dependencies,
        })
    }

    /// Re-run one reserved asset-record subscription inside a commit frame.
    /// Delivery is fingerprint-deduplicated: recompute, and enqueue a
    /// `live_replace` only when the dependency vector moved — an attach, a
    /// revocation, or a record transition all move it; an unrelated commit
    /// does not.
    fn rerun_asset_record_subscription(
        &mut self,
        subscription: &LiveSubscription,
        admission: &AdmissionLease,
        frame_version: u64,
    ) -> Option<bool> {
        let authority =
            match self.prepare_live_rerun_authority(&subscription.authority, admission.clone()) {
                Ok(authority) => authority,
                Err(error) => {
                    self.fail_subscription_fanout(
                        subscription,
                        "live_authority_ended",
                        error,
                        Some(frame_version),
                        admission,
                    );
                    return None;
                }
            };
        let query = match self.invoke_live_subscription_query(subscription, authority) {
            Ok(query) => query,
            Err(error) => {
                self.fail_subscription_fanout(
                    subscription,
                    "live_refresh_failed",
                    error,
                    Some(frame_version),
                    admission,
                );
                return None;
            }
        };
        let moved = self
            .subscriptions
            .get(&subscription.id)
            .is_none_or(|stored| stored.read_dependencies != query.read_dependencies);
        if !moved {
            self.live_delivery.total_skipped += 1;
            self.live_delivery.last_skipped += 1;
            return Some(false);
        }
        let payload = match serde_json::to_vec(&LiveEnvelope::LiveReplace {
            network_profile: None,
            subscription_id: subscription.id.clone(),
            function: subscription.function.clone(),
            version: query.output.version,
            rows: query.output.rows,
            resume: None,
        }) {
            Ok(payload) => payload,
            Err(error) => {
                self.fail_subscription_fanout(
                    subscription,
                    "live_serialize_failed",
                    SnapbackError::error(
                        "SNAPBACK_LIVE_UPDATE_SERIALIZE_FAILED",
                        "realtime",
                        "asset record update could not be serialized",
                    )
                    .with_details(json!({ "error": error.to_string() })),
                    Some(frame_version),
                    admission,
                );
                return None;
            }
        };
        let _publication = match admission.effect_guard("live replacement publication") {
            Ok(publication) => publication,
            Err(error) => {
                self.fail_subscription_fanout(
                    subscription,
                    "live_replacement_publication_failed",
                    error,
                    Some(frame_version),
                    admission,
                );
                return None;
            }
        };
        if let Some(stored) = self.subscriptions.get_mut(&subscription.id) {
            stored.read_dependencies = query.read_dependencies;
        }
        self.enqueue_subscription_durable(subscription, payload);
        self.live_delivery.total_deliveries += 1;
        self.live_delivery.last_deliveries += 1;
        Some(true)
    }

    /// The auth-scoped (sessions-mode) sibling of
    /// [`Self::rerun_asset_record_subscription`]: the same native recompute
    /// decides movement, but delivery rides the witnessed
    /// obligation/snapshot lane — an auth-scoped subscription never receives
    /// a plain replace, so quarantine, retry episodes, and ACK tickets apply
    /// to the reserved projection exactly as to ordinary queries.
    fn rerun_asset_record_subscription_witnessed(
        &mut self,
        subscription: &LiveSubscription,
        admission: &AdmissionLease,
        frame_version: u64,
    ) -> Option<bool> {
        let authority =
            match self.prepare_live_rerun_authority(&subscription.authority, admission.clone()) {
                Ok(authority) => authority,
                Err(error) => {
                    self.fail_subscription_fanout(
                        subscription,
                        "live_authority_ended",
                        error,
                        Some(frame_version),
                        admission,
                    );
                    return None;
                }
            };
        let probe = match self.invoke_live_subscription_query(subscription, authority) {
            Ok(query) => query,
            Err(error) => {
                self.fail_subscription_fanout(
                    subscription,
                    "live_refresh_failed",
                    error,
                    Some(frame_version),
                    admission,
                );
                return None;
            }
        };
        let moved = self
            .subscriptions
            .get(&subscription.id)
            .is_none_or(|stored| stored.read_dependencies != probe.read_dependencies);
        if !moved {
            self.live_delivery.total_skipped += 1;
            self.live_delivery.last_skipped += 1;
            return Some(false);
        }
        let Some(floor) = self
            .auth_invalidation
            .as_ref()
            .map(|state| state.witness(frame_version))
        else {
            self.fail_subscription_fanout(
                subscription,
                "authorization_invalidation_failed",
                SnapbackError::error(
                    "SNAPBACK_AUTH_INVALIDATION_UNAVAILABLE",
                    "auth",
                    "auth-scoped asset subscription requires installed invalidation state",
                ),
                Some(frame_version),
                admission,
            );
            return None;
        };
        let query = match self.invoke_authorization_resolution(subscription, floor, admission) {
            Ok(query) => query,
            Err(failure) => {
                self.fail_subscription_fanout_with_retry(
                    subscription,
                    "live_refresh_failed",
                    failure.error,
                    failure.retry_episode_id,
                    Some(frame_version),
                    admission,
                );
                return None;
            }
        };
        let read_dependencies = query.read_dependencies.clone();
        match self.deliver_authorization_snapshot(subscription, query, "replace", true, admission) {
            Ok(true) => {
                if let Some(stored) = self.subscriptions.get_mut(&subscription.id) {
                    stored.read_dependencies = read_dependencies;
                }
                self.live_delivery.total_deliveries += 1;
                self.live_delivery.last_deliveries += 1;
                Some(true)
            }
            Ok(false) => None,
            Err(error) => {
                self.fail_subscription_fanout(
                    subscription,
                    "authorization_invalidation_failed",
                    error,
                    Some(frame_version),
                    admission,
                );
                None
            }
        }
    }

    /// Asset system-table writes commit through typed storage-kernel operations,
    /// outside the app changeset that ordinarily feeds live fan-out. Every asset
    /// state transition an observer may care about funnels through here with
    /// the touched asset ids, synthesizing the change frame the ordinary
    /// notify path expects.
    pub(crate) fn notify_asset_record_change(&mut self, asset_ids: &[String]) {
        if asset_ids.is_empty() {
            return;
        }
        let changes: Vec<ChangedRow> = asset_ids
            .iter()
            .map(|asset_id| ChangedRow {
                table: ASSET_RECORDS_LIVE_TABLE.to_owned(),
                id: asset_id.clone(),
                op: crate::storage::ChangeOp::Update,
                row: None,
                changed_fields: Vec::new(),
            })
            .collect();
        self.notify_live_subscriptions(&changes);
    }

    /// The `snapback assets` operator surface (LLP 0044 §Seeds and agent DX):
    /// five host-ops operations over the same asset machinery the routes use.
    /// Authority is the `function.run` model — dev-admitted, optionally
    /// impersonating `userId` — so this is a dev/test operator surface, and
    /// sessions/prod deployments refuse at admission exactly like the direct
    /// runner.
    pub(crate) fn asset_host_op(
        &mut self,
        operation: &str,
        input: Option<&Value>,
        user_id: Option<&str>,
        profile: ServerProfile,
    ) -> SnapbackResult<Value> {
        match operation {
            "asset.put" => self.asset_host_put(input, user_id, profile),
            "asset.ensureSeedFixture" => {
                self.asset_host_ensure_seed_fixture(input, user_id, profile)
            }
            "asset.inspect" => self.asset_host_inspect(input, user_id),
            "asset.list" => self.asset_host_list(input),
            "asset.retry" => self.asset_host_retry(input),
            // @ref LLP 0044#deletion-retention-and-garbage-collection — the
            // operator drives the one canonical sweep with an injected clock;
            // the sweep retains the same per-reclamation semantic receipts as
            // the background runner.
            "asset.gcSweep" => {
                let parsed: AssetHostGcSweepInput = asset_host_input(input, operation)?;
                crate::manifest::validate_portable_timestamp_millis(parsed.now_ms)?;
                let report = self.asset_gc_sweep(parsed.now_ms)?;
                Ok(serde_json::json!({
                    "nowMs": parsed.now_ms,
                    "report": report,
                }))
            }
            "asset.delete" => {
                let parsed: AssetHostIdInput = asset_host_input(input, operation)?;
                let authority =
                    self.asset_host_authority(user_id, InvocationSource::HttpQuery, profile)?;
                self.asset_delete(&authority, &parsed.asset_id)
            }
            // The documented rotation path (LLP 0044 §Delivery profiles):
            // an operator action that invalidates every outstanding signed
            // URL; takes no input and returns no key identity.
            "asset.rotateSigningKey" => self.asset_rotate_signing_key(),
            // LLP 0044 consistent-cut export/import (dated design addition
            // 2026-07-31): admin operator surface, no impersonation
            // semantics — the cut is app-scoped system state.
            "asset.exportCut" => self.asset_host_export_cut(input),
            "asset.importCut" => self.asset_host_import_cut(input),
            _ => Err(SnapbackError::error(
                "SNAPBACK_ASSET_HOST_OP_UNKNOWN",
                "assets",
                format!("unknown asset host operation {operation}"),
            )),
        }
    }

    fn asset_host_export_cut(&mut self, input: Option<&Value>) -> SnapbackResult<Value> {
        use crate::assets_cut as cut;
        #[derive(serde::Deserialize)]
        #[serde(deny_unknown_fields, rename_all = "camelCase")]
        struct ExportCutInput {
            dir: String,
        }
        let parsed: ExportCutInput = asset_host_input(input, "asset.exportCut")?;
        let dir = std::path::PathBuf::from(&parsed.dir);
        if !dir.is_absolute() {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_EXPORT_TARGET_INVALID",
                "assets",
                "export dir must be an absolute path",
            ));
        }
        std::fs::create_dir_all(&dir).map_err(|error| {
            SnapbackError::error(
                "SNAPBACK_ASSET_EXPORT_TARGET_INVALID",
                "assets",
                format!("cannot create export dir: {error}"),
            )
        })?;
        let occupied = std::fs::read_dir(&dir)
            .map_err(|error| {
                SnapbackError::error(
                    "SNAPBACK_ASSET_EXPORT_TARGET_INVALID",
                    "assets",
                    format!("cannot read export dir: {error}"),
                )
            })?
            .next()
            .is_some();
        if occupied {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_EXPORT_TARGET_INVALID",
                "assets",
                "export dir must be empty",
            ));
        }
        let app_id = self.db.schema().app_id.clone();
        let now = now_millis();
        // One read transaction: the rows, the referenced blob set, and the
        // head commit version are one consistent picture (the cut witness).
        let capture = self.db.asset_reads().capture_export_cut(&app_id, now)?;
        // Blob objects copy after the row capture closes: blobs are
        // immutable, so a captured object can only disappear via GC — which
        // fails the export whole rather than shipping a partial component.
        let store = self.asset_store_obj()?;
        let blob_root = dir.join(cut::ASSET_CUT_BLOB_DIR);
        std::fs::create_dir_all(&blob_root).map_err(|error| {
            SnapbackError::error(
                "SNAPBACK_ASSET_EXPORT_TARGET_INVALID",
                "assets",
                format!("cannot create blob dir: {error}"),
            )
        })?;
        for (entry, key) in capture.manifest.blobs.iter().zip(&capture.blob_keys) {
            let bytes = store
                .read(crate::assets_store::AssetObjectRef::Blob(key))
                .map_err(|error| {
                    SnapbackError::error(
                        "SNAPBACK_ASSET_EXPORT_BLOB_MISSING",
                        "assets",
                        format!(
                            "blob {} is unreadable from the store: {}",
                            entry.blob_id, error.diagnostic.message
                        ),
                    )
                })?;
            let path = dir.join(&entry.object_path);
            std::fs::write(&path, &bytes).map_err(|error| {
                SnapbackError::error(
                    "SNAPBACK_ASSET_EXPORT_TARGET_INVALID",
                    "assets",
                    format!("cannot write blob object: {error}"),
                )
            })?;
            let observed = crate::assets_store::hash_path(&path)?;
            if observed.digest != entry.digest || observed.byte_length != entry.byte_length {
                return Err(SnapbackError::error(
                    "SNAPBACK_ASSET_EXPORT_BLOB_MISSING",
                    "assets",
                    format!(
                        "blob {} failed digest verification after copy",
                        entry.blob_id
                    ),
                ));
            }
        }
        let manifest_json =
            serde_json::to_string_pretty(&capture.manifest).expect("manifest serializes");
        std::fs::write(dir.join(cut::ASSET_CUT_MANIFEST_FILE), manifest_json).map_err(|error| {
            SnapbackError::error(
                "SNAPBACK_ASSET_EXPORT_TARGET_INVALID",
                "assets",
                format!("cannot write manifest: {error}"),
            )
        })?;
        let summary = cut::validation_summary(&capture.manifest);
        self.db.asset_reads().record_cut_exported(now, &summary)?;
        Ok(serde_json::json!({ "dir": parsed.dir, "cut": summary }))
    }

    fn asset_host_import_cut(&mut self, input: Option<&Value>) -> SnapbackResult<Value> {
        use crate::assets_cut as cut;
        #[derive(serde::Deserialize)]
        #[serde(deny_unknown_fields, rename_all = "camelCase")]
        struct ImportCutInput {
            dir: String,
            #[serde(default)]
            apply: bool,
        }
        let parsed: ImportCutInput = asset_host_input(input, "asset.importCut")?;
        let dir = std::path::PathBuf::from(&parsed.dir);
        // Refuse-partial validation: manifest digest plus every blob object.
        let manifest = cut::validate_export_dir(&dir)?;
        let app_id = self.db.schema().app_id.clone();
        if manifest.app_id != app_id {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_IMPORT_MANIFEST_INVALID",
                "assets",
                format!(
                    "cut belongs to app {} but this instance is {}",
                    manifest.app_id, app_id
                ),
            ));
        }
        let now = now_millis();
        let summary = cut::validation_summary(&manifest);
        if !parsed.apply {
            self.db
                .asset_reads()
                .record_cut_import_validated(now, &summary)?;
            return Ok(serde_json::json!({ "applied": false, "cut": summary }));
        }
        // Application is the experimental half: empty-target restore only,
        // behind the explicit acknowledgement (LLP 0044 dated design
        // addition 2026-07-31 — the restore-epoch machinery graduates with
        // evidence, not by default).
        if !self.asset_import_experimental_acknowledged() {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_IMPORT_EXPERIMENTAL_REQUIRED",
                "assets",
                "importCut apply requires SNAPBACK_ASSET_IMPORT_EXPERIMENTAL=1",
            ));
        }
        let store = self.asset_store_obj()?;
        // Objects land first under fresh opaque keys (idempotent puts);
        // the row transaction follows. A failure between the two leaves
        // orphaned objects that reset/wipe reclaims — the experimental
        // posture accepts that in exchange for never referencing an object
        // that is not durably present.
        let mut fresh_keys = Vec::with_capacity(manifest.blobs.len());
        for entry in &manifest.blobs {
            // Re-resolve immediately before the apply read so validation-only
            // and apply share the same lexical and symlink confinement.
            let path = cut::resolve_import_blob_path(&dir, &entry.object_path)?;
            let bytes = std::fs::read(path).map_err(|error| {
                SnapbackError::error(
                    "SNAPBACK_ASSET_IMPORT_INCOMPLETE",
                    "assets",
                    format!("blob object {} is unreadable: {error}", entry.object_path),
                )
            })?;
            let key = uuid::Uuid::now_v7().to_string();
            store.put_blob_idempotent(&key, &bytes)?;
            fresh_keys.push(key);
        }
        let store_kind = store.kind().to_owned();
        self.db.asset_reads().apply_import_cut(
            &manifest,
            &fresh_keys,
            &store_kind,
            now,
            &summary,
        )?;
        Ok(serde_json::json!({ "applied": true, "cut": summary }))
    }

    fn asset_host_authority(
        &self,
        user_id: Option<&str>,
        source: InvocationSource,
        profile: ServerProfile,
    ) -> SnapbackResult<PreparedAuthority> {
        let input = HandlerInput {
            auth: crate::manifest::AuthInput {
                user_id: user_id.map(str::to_owned),
                ..Default::default()
            },
            ..Default::default()
        };
        self.prepare_legacy_dev_authority(source, profile, &input)
    }

    /// The shared in-process ingestion engine: create → per-chunk-checksummed
    /// transfer → finalize with the whole-upload digest, under the declared
    /// intent's full policy. `asset.put` and seed-fixture ingestion (LLP 0109
    /// §17) both ride it, so a fixture can never bypass the trusted path.
    fn asset_ingest_bytes(
        &mut self,
        spec: AssetIngestSpec<'_>,
        user_id: Option<&str>,
        profile: ServerProfile,
    ) -> SnapbackResult<crate::assets::AssetTaskStateV1> {
        use sha2::Digest as _;

        let AssetIngestSpec {
            upload,
            bytes,
            file_name,
            content_type,
            args,
        } = spec;
        let intent = self.asset_intent(upload)?.clone();
        let creator = self.asset_host_authority(user_id, InvocationSource::HttpQuery, profile)?;
        let transfer =
            self.asset_host_authority(user_id, InvocationSource::AssetTransfer, profile)?;
        let created = self.asset_attempt_create(
            &creator,
            crate::assets::AssetAttemptCreateRequestV1 {
                intent_id: intent.id.clone(),
                intent_policy_hash: intent.intent_policy_hash.clone(),
                implementation_hash: intent.implementation_hash.clone(),
                args,
                declared_filename: file_name,
                declared_length: Some(bytes.len() as u64),
                declared_content_type: content_type,
                retry_of_asset_id: None,
            },
        )?;
        let attempt_id = created.task.attempt_id.clone();
        let chunk_len = (created.transfer.max_chunk_bytes.max(1)) as usize;
        let mut offset = 0u64;
        for chunk in bytes.chunks(chunk_len) {
            let checksum = base64::Engine::encode(
                &base64::engine::general_purpose::STANDARD,
                sha2::Sha256::digest(chunk),
            );
            self.asset_tus_patch(
                &transfer,
                &attempt_id,
                offset,
                chunk,
                Some(("sha256", checksum.as_str())),
            )?;
            offset = offset.saturating_add(chunk.len() as u64);
        }
        let whole_digest = sha2::Sha256::digest(bytes)
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>();
        let lifecycle_generation = self
            .db
            .asset_attempts()
            .attempt_ingest_load(&attempt_id)?
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_ASSET_ATTEMPT_UNKNOWN",
                    "assets",
                    format!("unknown attempt {attempt_id}"),
                )
            })?
            .lifecycle_generation;
        let finalized = self.asset_attempt_finalize(
            &creator,
            crate::assets::AssetFinalizeRequestV1 {
                attempt_id,
                lifecycle_generation,
                declared_digest: Some(whole_digest),
            },
        )?;
        Ok(finalized.task)
    }

    fn asset_host_put(
        &mut self,
        input: Option<&Value>,
        user_id: Option<&str>,
        profile: ServerProfile,
    ) -> SnapbackResult<Value> {
        let parsed: AssetHostPutInput = asset_host_input(input, "asset.put")?;
        let bytes = base64::Engine::decode(
            &base64::engine::general_purpose::STANDARD,
            parsed.bytes_base64.as_bytes(),
        )
        .map_err(|_| {
            SnapbackError::error(
                "SNAPBACK_ASSET_HOST_OP_INPUT_INVALID",
                "assets",
                "asset.put bytesBase64 is not valid base64",
            )
        })?;
        let task = self.asset_ingest_bytes(
            AssetIngestSpec {
                upload: &parsed.upload,
                bytes: &bytes,
                file_name: parsed.file_name,
                content_type: parsed.content_type,
                args: parsed
                    .args
                    .unwrap_or_else(|| Value::Object(Default::default())),
            },
            user_id,
            profile,
        )?;
        serde_json::to_value(&task)
            .map(|task| serde_json::json!({ "task": task }))
            .map_err(|error| {
                SnapbackError::error(
                    "SNAPBACK_ASSET_RECORD_INVALID",
                    "assets",
                    format!("task state does not serialize: {error}"),
                )
            })
    }

    /// LLP 0109 §17: idempotent seed-fixture ingestion. A matching mapping
    /// (same source digest, asset still present) is reused; anything else
    /// ingests through the ordinary trusted path and repoints the mapping.
    /// The superseded asset follows ordinary replacement/GC semantics.
    fn asset_host_ensure_seed_fixture(
        &mut self,
        input: Option<&Value>,
        user_id: Option<&str>,
        profile: ServerProfile,
    ) -> SnapbackResult<Value> {
        use sha2::Digest as _;

        let parsed: AssetHostEnsureSeedFixtureInput =
            asset_host_input(input, "asset.ensureSeedFixture")?;
        let bytes = base64::Engine::decode(
            &base64::engine::general_purpose::STANDARD,
            parsed.bytes_base64.as_bytes(),
        )
        .map_err(|_| {
            SnapbackError::error(
                "SNAPBACK_ASSET_HOST_OP_INPUT_INVALID",
                "assets",
                "asset.ensureSeedFixture bytesBase64 is not valid base64",
            )
        })?;
        let observed = format!(
            "sha256:{}",
            sha2::Sha256::digest(&bytes)
                .iter()
                .map(|byte| format!("{byte:02x}"))
                .collect::<String>()
        );
        if observed != parsed.source_digest {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_SEED_FIXTURE_DIGEST_MISMATCH",
                "assets",
                "fixture bytes do not match the declared sourceDigest",
            ));
        }
        let existing = self
            .db
            .asset_reads()
            .seed_fixture_existing(&parsed.fixture_id, &parsed.source_digest)?;
        if let Some(asset_id) = existing {
            return Ok(serde_json::json!({ "assetId": asset_id, "reused": true }));
        }
        let task = self.asset_ingest_bytes(
            AssetIngestSpec {
                upload: &parsed.upload,
                bytes: &bytes,
                file_name: parsed.file_name,
                content_type: Some(parsed.media_type.clone()),
                args: Value::Object(Default::default()),
            },
            user_id,
            profile,
        )?;
        if task.availability != crate::assets::AssetAvailability::Ready {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_SEED_FIXTURE_REJECTED",
                "assets",
                format!(
                    "fixture {} did not publish under intent {} (availability {:?}); the seed refuses rather than referencing an unusable asset",
                    parsed.fixture_id, parsed.upload, task.availability
                ),
            ));
        }
        let intent_id = self.asset_intent(&parsed.upload)?.id.clone();
        let asset_id = task.asset_id.clone();
        let now_ms = now_millis();
        self.db
            .asset_reads()
            .seed_fixture_upsert(&crate::assets::SeedFixtureMappingV1 {
                fixture_id: parsed.fixture_id.clone(),
                source_digest: parsed.source_digest.clone(),
                asset_id: asset_id.clone(),
                intent_id: intent_id.clone(),
                updated_at_ms: now_ms,
            })?;
        Ok(serde_json::json!({ "assetId": asset_id, "reused": false }))
    }

    fn asset_host_inspect(
        &mut self,
        input: Option<&Value>,
        user_id: Option<&str>,
    ) -> SnapbackResult<Value> {
        let parsed: AssetHostIdInput = asset_host_input(input, "asset.inspect")?;
        let caller = user_id.map(str::to_owned);
        let schema = self.db.schema().clone();
        self.db
            .asset_reads()
            .host_inspect(&schema, caller.as_deref(), &parsed.asset_id)
    }

    fn asset_host_list(&mut self, input: Option<&Value>) -> SnapbackResult<Value> {
        let parsed: AssetHostListInput = match input {
            None => AssetHostListInput::default(),
            Some(_) => asset_host_input(input, "asset.list")?,
        };
        let state = parsed
            .state
            .map(|state| {
                serde_json::from_value::<crate::assets::AssetAvailability>(Value::String(
                    state.clone(),
                ))
                .map_err(|_| {
                    SnapbackError::error(
                        "SNAPBACK_ASSET_HOST_OP_INPUT_INVALID",
                        "assets",
                        format!("asset.list state {state} is not an availability state"),
                    )
                })
            })
            .transpose()?;
        self.db.asset_reads().host_list(state)
    }

    /// Operator retry: a generation-fenced re-drive of pending publication
    /// and ledger work. It never reopens a terminal attempt or edits a
    /// receipt — it runs the same maintenance the runner runs, now.
    fn asset_host_retry(&mut self, input: Option<&Value>) -> SnapbackResult<Value> {
        let parsed: AssetHostIdInput = asset_host_input(input, "asset.retry")?;
        let asset = self.db.asset_reads().require_asset(&parsed.asset_id)?;
        if asset.availability == crate::assets::AssetAvailability::Deleted {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_RETRY_INELIGIBLE",
                "assets",
                "a deleted asset has no pending work to re-drive",
            ));
        }
        let now = now_millis();
        let maintenance = self.asset_publication_maintain(now)?;
        let runner = self.asset_runner_tick(now)?;
        let availability = self
            .db
            .asset_reads()
            .load_asset(&parsed.asset_id)?
            .map(|asset| asset.availability);
        Ok(serde_json::json!({
            "publication": {
                "staged": maintenance.staged,
                "condemned": maintenance.condemned,
                "retired": maintenance.retired,
                "objectsDeleted": maintenance.objects_deleted,
            },
            "runner": {
                "leasesReclaimed": runner.leases_reclaimed,
                "claimed": runner.claimed,
                "completed": runner.completed,
                "retried": runner.retried,
                "exhausted": runner.exhausted,
                "cancelled": runner.cancelled,
            },
            "availability": availability,
        }))
    }

    pub fn asset_attempt_cancel(
        &mut self,
        authority: &PreparedAuthority,
        request: crate::assets::AssetAttemptCancelRequestV1,
    ) -> SnapbackResult<crate::assets::AssetTaskStateV1> {
        // Enforces caller lineage and lazy expiry before the cancel proper.
        self.asset_attempt_for_caller(authority, &request.attempt_id)?;
        let now = now_millis();
        let (attempt, asset) = self.db.asset_attempts().attempt_cancel(&request, now)?;
        self.asset_store_obj()?
            .delete_staging_pair(&attempt.staging_key)?;
        Ok(asset_task_state(&attempt, asset.as_ref()))
    }

    pub fn asset_tus_head(
        &mut self,
        authority: &PreparedAuthority,
        attempt_id: &str,
    ) -> SnapbackResult<crate::assets::AssetAttemptRecordV1> {
        let attempt = self.asset_attempt_for_caller(authority, attempt_id)?;
        self.db.asset_attempts().attempt_require_current(&attempt)?;
        Ok(attempt)
    }

    pub(crate) fn asset_tus_patch(
        &mut self,
        authority: &PreparedAuthority,
        attempt_id: &str,
        offset: u64,
        chunk: &[u8],
        checksum: Option<(&str, &str)>,
    ) -> SnapbackResult<crate::assets::AssetAttemptRecordV1> {
        let ticket =
            self.asset_tus_patch_preflight(authority, attempt_id, offset, chunk, checksum)?;
        ticket.append(chunk)?;
        self.asset_tus_patch_commit(authority, ticket)
    }

    /// Validate one TUS chunk and freeze the exact record state its durable
    /// append is allowed to advance. The HTTP route releases Local after this
    /// preflight and carries only this owned ticket into the byte-store lane.
    pub fn asset_tus_patch_preflight(
        &mut self,
        authority: &PreparedAuthority,
        attempt_id: &str,
        offset: u64,
        chunk: &[u8],
        checksum: Option<(&str, &str)>,
    ) -> SnapbackResult<AssetTusPatchTicketV1> {
        use crate::assets;
        use sha2::Digest as _;

        let attempt = self.asset_attempt_for_caller(authority, attempt_id)?;
        let current_proof = self
            .db
            .asset_attempts()
            .attempt_require_current_proof(&attempt)?;
        if offset != attempt.acknowledged_offset {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_OFFSET_CONFLICT",
                "assets",
                format!(
                    "upload offset {offset} does not match the acknowledged offset {}",
                    attempt.acknowledged_offset
                ),
            ));
        }
        let new_offset = offset.saturating_add(chunk.len() as u64);
        if new_offset > attempt.declared_length {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_MEDIA_BOUNDS_EXCEEDED",
                "assets",
                "the chunk would exceed the declared upload length",
            ));
        }
        // Per-chunk checksum (TUS checksum extension): verified when
        // offered; a checksum-less chunk demotes the integrity grade fact.
        let mut all_checksummed = attempt.all_chunks_checksummed;
        match checksum {
            Some((algorithm, expected)) => {
                if !assets::ASSET_TUS_CHECKSUM_ALGORITHMS.contains(&algorithm) {
                    return Err(SnapbackError::error(
                        "SNAPBACK_ASSET_CHUNK_CHECKSUM_INVALID",
                        "assets",
                        format!("unsupported checksum algorithm {algorithm}"),
                    ));
                }
                let digest = sha2::Sha256::digest(chunk);
                let observed =
                    base64::Engine::encode(&base64::engine::general_purpose::STANDARD, digest);
                if observed != expected {
                    return Err(SnapbackError::error(
                        "SNAPBACK_ASSET_CHUNK_CHECKSUM_INVALID",
                        "assets",
                        "the chunk checksum does not match its bytes",
                    ));
                }
            }
            None => all_checksummed = false,
        }

        AssetTusPatchTicketV1::from_current_attempt(
            current_proof,
            new_offset,
            all_checksummed,
            self.asset_store_obj()?,
        )
    }

    /// Acknowledge a previously durable TUS append only when the attempt is
    /// still at the exact offset/checksum state observed by preflight.
    ///
    /// @ref LLP 0044#byte-stores-and-resumable-transfer — a durable append
    ///   without this CAS remains an incomplete, retryable PATCH; stale
    ///   `Upload-Offset` values never advance the attempt.
    pub fn asset_tus_patch_commit(
        &mut self,
        authority: &PreparedAuthority,
        ticket: AssetTusPatchTicketV1,
    ) -> SnapbackResult<crate::assets::AssetAttemptRecordV1> {
        let attempt = self.asset_attempt_for_caller(authority, ticket.attempt_id())?;
        self.db.asset_attempts().attempt_require_current(&attempt)?;
        if attempt.acknowledged_offset != ticket.expected_offset()
            || attempt.all_chunks_checksummed != ticket.expected_all_chunks_checksummed()
        {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_OFFSET_CONFLICT",
                "assets",
                format!(
                    "upload state moved before acknowledgement (expected offset {}, current offset {})",
                    ticket.expected_offset(),
                    attempt.acknowledged_offset
                ),
            ));
        }
        let now = now_millis();
        self.db.asset_attempts().attempt_tus_patch(
            ticket.attempt_id(),
            ticket.expected_offset(),
            ticket.expected_all_chunks_checksummed(),
            ticket.new_offset(),
            ticket.all_chunks_checksummed(),
            now,
        )
    }

    pub fn asset_tus_terminate(
        &mut self,
        authority: &PreparedAuthority,
        attempt_id: &str,
    ) -> SnapbackResult<()> {
        let request = crate::assets::AssetAttemptCancelRequestV1 {
            attempt_id: attempt_id.to_owned(),
            lifecycle_generation: self
                .asset_attempt_for_caller(authority, attempt_id)?
                .lifecycle_generation,
            discard_asset: false,
        };
        self.asset_attempt_cancel(authority, request)?;
        Ok(())
    }

    /// The trusted finalizer (LLP 0044 §Restricted staging and trusted
    /// finalization): nine steps from a transfer-complete attempt to a ready
    /// asset, over the write-ahead publication protocol. Idempotent on
    /// attempt id plus lifecycle generation — re-driving a crashed
    /// finalization resumes from its publication record, and finalizing a
    /// `complete` attempt returns its task state.
    pub(crate) fn asset_attempt_finalize(
        &mut self,
        authority: &PreparedAuthority,
        request: crate::assets::AssetFinalizeRequestV1,
    ) -> SnapbackResult<crate::assets::AssetFinalizeResponseV1> {
        let response = self.asset_attempt_finalize_inner(authority, request, None)?;
        // Availability may have moved (ready or rejected): fan the durable
        // transition out to reserved asset-record subscribers.
        self.notify_asset_record_change(std::slice::from_ref(&response.task.asset_id));
        Ok(response)
    }

    /// Lock-held half before repeatable byte preparation. This preserves the
    /// former finalize preamble exactly, then freezes all prepare/commit facts
    /// in a continuity ticket whose store handle owns no LocalSnapback borrow.
    pub fn asset_attempt_finalize_preflight(
        &mut self,
        authority: &PreparedAuthority,
        request: crate::assets::AssetFinalizeRequestV1,
    ) -> SnapbackResult<FinalizePreflightV1> {
        use crate::assets;

        let attempt = self.asset_attempt_for_caller(authority, &request.attempt_id)?;
        if attempt.lifecycle_generation != request.lifecycle_generation {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_GENERATION_STALE",
                "assets",
                "the request carries a stale lifecycle generation",
            ));
        }
        if attempt.state == assets::AssetAttemptState::Complete {
            let asset = self
                .db
                .asset_attempts()
                .attempt_finalize_load_asset(&attempt.asset_id)?;
            return Ok(FinalizePreflightV1::AlreadyComplete(
                crate::assets::AssetFinalizeResponseV1 {
                    task: asset_task_state(&attempt, asset.as_ref()),
                },
            ));
        }
        let current_proof = self
            .db
            .asset_attempts()
            .attempt_require_current_proof(&attempt)?;
        if attempt.acknowledged_offset != attempt.declared_length {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_TRANSFER_INCOMPLETE",
                "assets",
                format!(
                    "finalize requires a complete transfer ({} of {} bytes acknowledged)",
                    attempt.acknowledged_offset, attempt.declared_length
                ),
            ));
        }

        // Intent removal is a revocation trigger: nothing further finalizes.
        let intent = self
            .asset_intent(&attempt.intent_id)
            .map_err(|_| {
                SnapbackError::error(
                    "SNAPBACK_ASSET_INTENT_REVOKED",
                    "assets",
                    "this attempt's intent was removed from the deployed artifact",
                )
            })?
            .clone();
        // @ref LLP 0044#asset-intent-implementation-identity-the-helper-closure-joins-the-carrier-dated-decision-2026-08-03 —
        //   current code is eligible only when BOTH carrier hashes match the
        //   admission. Otherwise finalization selects and validates the
        //   generation-retained artifact. A policy-only legacy admission has
        //   no executable identity to freeze, so the upgrade refuses it
        //   rather than silently adopting current code.
        let admitted_implementation_hash = attempt
            .admission
            .implementation_hash
            .as_deref()
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_ASSET_ADMISSION_STALE",
                    "assets",
                    "this attempt predates the implementationHash carrier; retry to re-admit it under the current generation",
                )
                .with_details(serde_json::json!({
                    "legacyPolicyOnlyAdmission": true,
                    "policyGeneration": attempt.admission.policy_generation,
                }))
            })?;
        let current_implementation_hash = intent
            .implementation_hash
            .as_deref()
            .filter(|hash| !hash.is_empty())
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_ASSET_INTENT_IDENTITY_INVALID",
                    "assets",
                    "the deployed upload intent is missing implementationHash",
                )
            })?;
        let current_matches_admission = intent.intent_policy_hash
            == attempt.admission.intent_policy_hash
            && current_implementation_hash == admitted_implementation_hash;
        let frozen_intent: crate::manifest::AssetUploadIntentDefinition =
            if current_matches_admission {
                intent
            } else {
                self.db
                    .asset_attempts()
                    .attempt_finalize_load_intent_artifact(
                        &attempt.intent_id,
                        attempt.admission.policy_generation,
                    )?
                    .and_then(|json| serde_json::from_str(&json).ok())
                    .filter(|retained: &crate::manifest::AssetUploadIntentDefinition| {
                        retained.intent_policy_hash == attempt.admission.intent_policy_hash
                            && retained.implementation_hash.as_deref()
                                == Some(admitted_implementation_hash)
                    })
                    .ok_or_else(|| {
                        SnapbackError::error(
                            "SNAPBACK_ASSET_ADMISSION_STALE",
                            "assets",
                            "the frozen intent generation's retained artifact is missing or does not match the admitted implementation; retry to re-admit this asset under the current generation",
                        )
                        .with_details(serde_json::json!({
                            "missingRetainedArtifact": true,
                            "policyGeneration": attempt.admission.policy_generation,
                            "implementationHash": admitted_implementation_hash,
                        }))
                    })?
            };

        let revoked = self
            .db
            .asset_attempts()
            .attempt_finalize_generation_revoked(
                &attempt.intent_id,
                attempt.admission.policy_generation,
            )?;
        if revoked {
            return Err(asset_intent_generation_revoked_error());
        }

        let on_ready = frozen_intent.on.as_ref().and_then(|on| on.ready.clone());
        Ok(FinalizePreflightV1::Proceed(
            FinalizePrepareTicketV1::from_current_attempt(
                current_proof,
                request,
                frozen_intent,
                on_ready,
                self.asset_store_obj()?,
                self.asset_image_finalization_enabled(),
                self.asset_video_finalization_enabled(),
                self.functions.app_id.clone(),
                self.asset_app_quota(),
                self.db.schema().clone(),
            )?,
        ))
    }

    /// Lock-held Phase A. Revocation and lifecycle state are rechecked before
    /// the durable `planned` record commits.
    pub fn asset_attempt_finalize_plan(
        &mut self,
        authority: &PreparedAuthority,
        ticket: FinalizePrepareTicketV1,
        preparation: FinalizePreparationV1,
    ) -> SnapbackResult<FinalizePhaseAOutcomeV1> {
        self.asset_attempt_finalize_plan_inner(authority, ticket, preparation, None)
    }

    /// Lock-held Phase C/D. The attempt is reloaded before `staged` so a
    /// concurrent completion retains the ordinary idempotent retry outcome.
    pub fn asset_attempt_finalize_complete(
        &mut self,
        authority: &PreparedAuthority,
        ticket: FinalizeCommitTicketV1,
    ) -> SnapbackResult<crate::assets::AssetFinalizeResponseV1> {
        let response = self.asset_attempt_finalize_complete_inner(authority, ticket, None)?;
        self.notify_asset_record_change(std::slice::from_ref(&response.task.asset_id));
        Ok(response)
    }

    /// Render one declared variant off the canonical bytes and stage it
    /// through the write-ahead publication protocol: plan (attempt-less
    /// record) → idempotent object put → verify → staged. The commit half
    /// runs inside the publishing transaction; orphaned records from a
    /// crash here converge via the ordinary maintenance pass.
    fn asset_prepare_variant(
        &mut self,
        store: &dyn crate::assets_store::AssetStore,
        app_id: &str,
        canonical_bytes: &[u8],
        content_type: &str,
        variant: &crate::manifest::AssetImageVariant,
        recipe_version: u64,
    ) -> SnapbackResult<AssetPreparedVariant> {
        let prepared = crate::assets::prepare_asset_variant(
            canonical_bytes,
            content_type,
            variant,
            recipe_version,
        )?;
        self.asset_stage_prepared_variant(store, app_id, &prepared)
    }

    /// Commit-side companion to `assets::prepare_asset_variant`: record the
    /// write-ahead intent, put and verify its immutable object, then advance
    /// the record to `staged`. No media decode/render occurs in this half.
    fn asset_stage_prepared_variant(
        &mut self,
        store: &dyn crate::assets_store::AssetStore,
        app_id: &str,
        prepared: &crate::assets::AssetVariantPreparation,
    ) -> SnapbackResult<AssetPreparedVariant> {
        let now = now_millis();
        let mut publication =
            self.db
                .asset_attempts()
                .stage_prepared_variant_plan(app_id, &prepared.digest, now)?;
        store.put_blob_idempotent(&publication.planned_key, &prepared.rendered)?;
        let copied = store.hash(crate::assets_store::AssetObjectRef::Blob(
            &publication.planned_key,
        ))?;
        if copied.digest != prepared.digest || copied.byte_length != prepared.byte_length {
            let _ = store.delete_blob(&publication.planned_key);
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_STORE_UNAVAILABLE",
                "assets",
                "the published variant object did not verify",
            ));
        }
        self.db
            .asset_attempts()
            .stage_prepared_variant_commit_staged(&mut publication)?;
        Ok(AssetPreparedVariant {
            key: prepared.key.clone(),
            width: prepared.width,
            publication,
            digest: prepared.digest.clone(),
            byte_length: prepared.byte_length,
            content_type: prepared.content_type.clone(),
            recipe_version: prepared.recipe_version,
        })
    }

    pub(crate) fn asset_attempt_finalize_inner(
        &mut self,
        authority: &PreparedAuthority,
        request: crate::assets::AssetFinalizeRequestV1,
        crash_after: Option<AssetFinalizeCrashPoint>,
    ) -> SnapbackResult<crate::assets::AssetFinalizeResponseV1> {
        let ticket = match self.asset_attempt_finalize_preflight(authority, request)? {
            FinalizePreflightV1::AlreadyComplete(response) => return Ok(response),
            FinalizePreflightV1::Proceed(ticket) => ticket,
        };
        // PREPARE half (LLP 0199 owner #4): byte-store reads, whole-object
        // hashing/buffering, trusted detection, canonicalization, image/video
        // decode/inspection, ThumbHash, derived facts, and required-variant
        // renders. This helper owns no database handle and is deliberately
        // repeatable from restricted staging.
        //
        // @ref LLP 0044#local-finalize-lock-choreography-implemented-2026-08-09 —
        //   the route releases Local across this repeatable prepare and again
        //   across Phase B's canonical put; in-process callers may retain an
        //   outer guard while using this compatibility composition.
        let preparation = ticket.prepare()?;
        self.asset_attempt_finalize_commit_inner(authority, ticket, preparation, crash_after)
    }

    fn asset_attempt_finalize_commit_inner(
        &mut self,
        authority: &PreparedAuthority,
        ticket: FinalizePrepareTicketV1,
        preparation: FinalizePreparationV1,
        crash_after: Option<AssetFinalizeCrashPoint>,
    ) -> SnapbackResult<crate::assets::AssetFinalizeResponseV1> {
        match self.asset_attempt_finalize_plan_inner(authority, ticket, preparation, crash_after)? {
            FinalizePhaseAOutcomeV1::AlreadyComplete(response) => Ok(response),
            FinalizePhaseAOutcomeV1::Proceed(ticket) => {
                let ticket = Self::asset_attempt_finalize_put_inner(*ticket, crash_after)?;
                self.asset_attempt_finalize_complete_inner(authority, ticket, crash_after)
            }
        }
    }

    fn asset_attempt_finalize_plan_inner(
        &mut self,
        authority: &PreparedAuthority,
        ticket: FinalizePrepareTicketV1,
        preparation: FinalizePreparationV1,
        crash_after: Option<AssetFinalizeCrashPoint>,
    ) -> SnapbackResult<FinalizePhaseAOutcomeV1> {
        use crate::assets;

        // The old single-lock choreography made this check immovable between
        // preflight and Phase A. The split admits revocation in that window,
        // so the commit half must repeat it before creating durable state.
        let revoked = self
            .db
            .asset_attempts()
            .attempt_finalize_generation_revoked(
                &ticket.attempt().intent_id,
                ticket.attempt().admission.policy_generation,
            )?;
        if revoked {
            return Err(asset_intent_generation_revoked_error());
        }

        // A competing finalize/cancel may have committed while prepare ran.
        // Reload through the same caller/lifecycle gates as today's retry
        // path: complete is idempotent; every other terminal state keeps its
        // existing structured refusal from the closed transition table.
        let attempt = self.asset_attempt_for_caller(authority, &ticket.attempt().attempt_id)?;
        if attempt.lifecycle_generation != ticket.request().lifecycle_generation {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_GENERATION_STALE",
                "assets",
                "the request carries a stale lifecycle generation",
            ));
        }
        if attempt.state == assets::AssetAttemptState::Complete {
            let asset = self
                .db
                .asset_attempts()
                .attempt_finalize_load_asset(&attempt.asset_id)?;
            return Ok(FinalizePhaseAOutcomeV1::AlreadyComplete(
                crate::assets::AssetFinalizeResponseV1 {
                    task: asset_task_state(&attempt, asset.as_ref()),
                },
            ));
        }
        self.db.asset_attempts().attempt_require_current(&attempt)?;

        let prepared = match preparation {
            FinalizePreparationV1::Prepared(prepared) => prepared,
            FinalizePreparationV1::Refused(failure) => {
                return self.asset_fail_attempt(&attempt, failure.asset_outcome, failure.refusal);
            }
        };
        // The integrity grade is honest: end-to-end verified only when every
        // chunk carried a checksum or an authenticated whole-upload digest
        // matched; a freshly computed digest alone names the received bytes.
        let grade = if attempt.all_chunks_checksummed
            || ticket.request().declared_digest.as_deref() == Some(prepared.staged_digest.as_str())
        {
            assets::AssetIntegrityGrade::EndToEndVerified
        } else {
            assets::AssetIntegrityGrade::ReceivedBytesCanonical
        };

        // Phase A — record intent first: a durable `planned` publication
        // record (or the attempt's re-drivable record from a prior crash)
        // commits before any canonical object write.
        let now = now_millis();
        let attempt_id = attempt.attempt_id.clone();
        let digest = prepared.canonical.digest.clone();
        let publication_proof = self
            .db
            .asset_attempts()
            .attempt_finalize_commit_plan_proved(ticket.app_id(), &attempt_id, &digest, now)?;
        if crash_after == Some(AssetFinalizeCrashPoint::AfterPlanned) {
            return Err(asset_test_crash());
        }

        Ok(FinalizePhaseAOutcomeV1::Proceed(Box::new(
            FinalizePutTicketV1::from_planned_publication(
                publication_proof,
                ticket,
                prepared,
                grade,
            )?,
        )))
    }

    fn asset_attempt_finalize_put_inner(
        ticket: FinalizePutTicketV1,
        crash_after: Option<AssetFinalizeCrashPoint>,
    ) -> SnapbackResult<FinalizeCommitTicketV1> {
        // Phase B — the idempotent canonical object put and verification own
        // no LocalSnapback/database borrow. `planned` already committed.
        let ticket = ticket.put()?;
        if crash_after == Some(AssetFinalizeCrashPoint::AfterObjectPut) {
            return Err(asset_test_crash());
        }
        Ok(ticket)
    }

    fn asset_attempt_finalize_complete_inner(
        &mut self,
        authority: &PreparedAuthority,
        ticket: FinalizeCommitTicketV1,
        crash_after: Option<AssetFinalizeCrashPoint>,
    ) -> SnapbackResult<crate::assets::AssetFinalizeResponseV1> {
        use crate::assets;

        let (ticket, prepared, mut publication, grade) = ticket.into_put().into_parts();
        let attempt_id = ticket.attempt().attempt_id.clone();

        // Phase A releases Local before the put, so either finalizer may
        // complete first from their shared `planned` key. Reloading here
        // preserves the former serialized behavior for whichever arrives
        // second: it returns the ordinary idempotent completion and cannot
        // stage/publish again. Cancellation/expiry likewise retains its
        // existing closed-table refusal.
        let attempt = self.asset_attempt_for_caller(authority, &attempt_id)?;
        if attempt.lifecycle_generation != ticket.request().lifecycle_generation {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_GENERATION_STALE",
                "assets",
                "the request carries a stale lifecycle generation",
            ));
        }
        if attempt.state == assets::AssetAttemptState::Complete {
            let asset = self
                .db
                .asset_attempts()
                .attempt_finalize_load_asset(&attempt.asset_id)?;
            return Ok(crate::assets::AssetFinalizeResponseV1 {
                task: asset_task_state(&attempt, asset.as_ref()),
            });
        }
        self.db.asset_attempts().attempt_require_current(&attempt)?;

        let (
            _ticket_attempt,
            _ticket_request,
            frozen_intent,
            on_ready,
            store,
            image_finalization_enabled,
            _video_finalization_enabled,
            app_id,
            app_quota,
            schema,
        ) = ticket.into_parts();
        let detected = prepared.detected_content_type;
        let canonical = prepared.canonical;
        let image_media_facts = prepared.media_facts;
        let rendered_required = prepared.required_variants;
        let digest = canonical.digest.clone();
        let now = now_millis();

        // Phase C — the object write is acknowledged: `planned → staged`.
        if publication.state == assets::AssetPublicationState::Planned {
            publication = self.db.asset_attempts().attempt_finalize_commit_staged(
                &attempt_id,
                &publication,
                now,
            )?;
        }
        if crash_after == Some(AssetFinalizeCrashPoint::AfterStaged) {
            return Err(asset_test_crash());
        }

        // Declared variants (LLP 0044 §step 8/9): required ones were rendered
        // by the unlocked, repeatable prepare. Their publication plans and
        // object puts remain here, after the primary reached `staged`, so the
        // publishing transaction can commit them with the primary and switch
        // `ready` atomically with the last required publication. Optional
        // ones enqueue ledger work inside that same transaction and never
        // gate the asset.
        let declared_variants: Vec<crate::manifest::AssetImageVariant> = frozen_intent
            .image
            .as_ref()
            .map(|image| image.variants.clone())
            .unwrap_or_default();
        let variants_enabled = image_finalization_enabled
            && !declared_variants.is_empty()
            && matches!(detected, "image/jpeg" | "image/png");
        let mut prepared_required: Vec<AssetPreparedVariant> = Vec::new();
        if variants_enabled {
            for rendered in &rendered_required {
                match self.asset_stage_prepared_variant(store.as_ref(), &app_id, rendered) {
                    Ok(prepared) => prepared_required.push(prepared),
                    // Preserve the prior classification for commit-side
                    // publication failures: store errors stay retryable;
                    // deterministic non-store refusals reject.
                    Err(error) => {
                        let availability =
                            if error.diagnostic.code == "SNAPBACK_ASSET_STORE_UNAVAILABLE" {
                                assets::AssetAvailability::Pending
                            } else {
                                assets::AssetAvailability::Rejected
                            };
                        return self.asset_fail_attempt(&attempt, availability, error);
                    }
                }
            }
        }
        let optional_variants: Vec<crate::manifest::AssetImageVariant> = if variants_enabled {
            declared_variants
                .iter()
                .filter(|variant| !variant.required)
                .cloned()
                .collect()
        } else {
            Vec::new()
        };

        // Phase D — the publication transaction: witness re-validation, blob
        // uniqueness, rendition + availability, quota settlement, receipts —
        // one commit. Witness movement re-runs the authorizer and retries
        // once with the fresh witness validated inside the retry transaction.
        let mut witness: Vec<crate::storage::CapturedReadDependency> =
            serde_json::from_value(attempt.admission.witness.clone()).unwrap_or_default();
        let witness_input = HandlerInput {
            args: attempt.admission.args.clone(),
            auth: crate::manifest::AuthInput {
                user_id: Some(attempt.admission.owner_principal.clone()),
                ..Default::default()
            },
            ..Default::default()
        };
        let mut auth_moved = Self::asset_auth_pair(authority) != attempt.admission.auth;
        let mut revalidations = 0u8;
        let outcome = loop {
            let publication_id = publication.publication_id.clone();
            let witness_snapshot = witness.clone();
            let canonical_length = canonical.byte_length;
            let canonical_policy = canonical.policy;
            let image_facts = image_media_facts.clone();
            let detected_type = detected.to_owned();
            let app = app_id.clone();
            let digest_value = digest.clone();
            let required_variants = prepared_required.clone();
            let optional_keys = optional_variants.clone();
            let publish_attempt = self.db.asset_attempts().attempt_finalize_commit_completion(
                &attempt,
                attempt_id.clone(),
                publication_id,
                &schema,
                &witness_input,
                witness_snapshot,
                auth_moved,
                canonical_length,
                canonical_policy,
                image_facts,
                detected_type,
                app,
                digest_value,
                required_variants,
                optional_keys,
                app_quota,
                &on_ready,
                grade,
                now,
            );
            let result = match publish_attempt {
                Ok(result) => result,
                Err(error) if error.diagnostic.code == "SNAPBACK_ASSET_QUOTA_EXCEEDED" => {
                    // The transaction aborted whole; quota can free later,
                    // so the asset stays pending and retry-eligible.
                    return self.asset_fail_attempt(
                        &attempt,
                        assets::AssetAvailability::Pending,
                        error,
                    );
                }
                Err(error) => return Err(error),
            };
            match result {
                AssetPublishOutcome::Published {
                    attempt,
                    asset,
                    reused,
                } => {
                    break (*attempt, *asset, reused);
                }
                AssetPublishOutcome::WitnessMoved => {
                    // Re-validate, then refuse only on denial: re-run the
                    // FROZEN generation's retained authorizer under current
                    // authority; a materially identical admit (the
                    // schema-validated output DTO — exactly `{ owner }`)
                    // publishes, so benign churn never strands an upload,
                    // including across an ordinary intent redeploy.
                    revalidations += 1;
                    if revalidations > 2 {
                        return Err(SnapbackError::error(
                            "SNAPBACK_ASSET_ADMISSION_CONFLICT",
                            "assets",
                            "admission re-validation kept conflicting with concurrent writes",
                        ));
                    }
                    let definition = self.asset_intent_definition(&frozen_intent)?;
                    let prepared =
                        InvocationGate::prepare_function(authority.clone(), &definition)?;
                    let module = match &frozen_intent.runtime {
                        crate::manifest::FunctionRuntime::IbexModule(module) => module.clone(),
                        _ => {
                            return Err(SnapbackError::error(
                                "SNAPBACK_ASSET_INTENT_RUNTIME_UNSUPPORTED",
                                "assets",
                                "upload-intent authorizers run as Ibex modules in v1",
                            ));
                        }
                    };
                    let input = prepared.canonicalize_input(crate::manifest::HandlerInput {
                        args: attempt.admission.args.clone(),
                        ..Default::default()
                    });
                    let rerun = self.db.query_reads_read().with_pinned_read_view(|db| {
                        crate::runtime::run_ibex_asset_authorizer_prepared(
                            &module,
                            input.clone(),
                            &prepared,
                            db,
                        )
                    });
                    let rerun = match rerun {
                        Ok(rerun) => rerun,
                        Err(denial) => {
                            self.asset_fail_attempt(
                                &attempt,
                                assets::AssetAvailability::Pending,
                                SnapbackError::error(
                                    "SNAPBACK_ASSET_ADMISSION_REVOKED",
                                    "assets",
                                    "re-validation denied this admission under current authority",
                                )
                                .with_details(serde_json::json!({
                                    "denial": denial.diagnostic.code,
                                })),
                            )?;
                            unreachable!("asset_fail_attempt always errors");
                        }
                    };
                    if rerun.owner != attempt.admission.owner_principal {
                        self.asset_fail_attempt(
                            &attempt,
                            assets::AssetAvailability::Pending,
                            SnapbackError::error(
                                "SNAPBACK_ASSET_ADMISSION_REVOKED",
                                "assets",
                                "re-validation admitted a materially different decision",
                            ),
                        )?;
                        unreachable!("asset_fail_attempt always errors");
                    }
                    witness = rerun.read_dependencies;
                    auth_moved = false;
                }
            }
        };
        let (final_attempt, final_asset, reused) = outcome;

        // Step 9 — staging cleanup after the publication committed; the
        // reused path also removes its own now-condemned object. Both are
        // idempotent, and the reconciliation sweep backstops a crash here.
        store.delete_staging_pair(&final_attempt.staging_key)?;
        if reused {
            match store.delete_blob(&publication.planned_key) {
                Ok(()) => {}
                Err(error) => {
                    return Err(SnapbackError::error(
                        "SNAPBACK_ASSET_STORE_UNAVAILABLE",
                        "assets",
                        format!("cannot remove condemned object: {error}"),
                    ));
                }
            }
        }
        let attempt_ref = final_attempt.attempt_id.clone();
        let asset_ref = final_attempt.asset_id.clone();
        self.db
            .asset_attempts()
            .attempt_finalize_commit_staging_cleaned(&attempt_ref, &asset_ref)?;

        Ok(crate::assets::AssetFinalizeResponseV1 {
            task: asset_task_state(&final_attempt, Some(&final_asset)),
        })
    }

    /// Terminal refusal path shared by the byte/policy verification steps:
    /// the attempt fails with the refusal recorded, the asset takes the
    /// stated availability (`Pending` keeps it retry-eligible; `Rejected`
    /// is reserved for a policy the intent can never satisfy), receipts are
    /// written, and the refusal is returned. Always errors.
    fn asset_fail_attempt<T>(
        &mut self,
        attempt: &crate::assets::AssetAttemptRecordV1,
        asset_outcome: crate::assets::AssetAvailability,
        refusal: SnapbackError,
    ) -> SnapbackResult<T> {
        let now = now_millis();
        let attempt_id = attempt.attempt_id.clone();
        // The rejected callback resolves from the deployed intent; a removed
        // intent simply has no callback to deliver.
        let on_rejected: Option<String> = self
            .asset_intent(&attempt.intent_id)
            .ok()
            .and_then(|intent| intent.on.as_ref())
            .and_then(|on| on.rejected.clone());
        let refusal_facts = serde_json::json!({
            "code": refusal.diagnostic.code,
            "message": refusal.diagnostic.message,
        });
        let staging_key = self.db.asset_attempts().attempt_fail(
            &attempt_id,
            asset_outcome,
            &refusal_facts,
            on_rejected.as_deref(),
            now,
        )?;
        self.asset_store_obj()?.delete_staging_pair(&staging_key)?;
        Err(refusal)
    }

    /// The publication-record maintenance pass (LLP 0044 §Publication and
    /// crash recovery): recovery probes `planned` records at the
    /// acknowledged-put crash cut, condemns work that is no longer
    /// re-drivable, deletes condemned objects, and retires records whose
    /// evidence has moved on — each repair receipted. Callable; the L1-11
    /// runner drives it on a schedule.
    // The L1-11 ledger runner is the production caller; until it lands the
    // pass is exercised by the fault-injection tests only.
    #[allow(dead_code)]
    pub(crate) fn asset_publication_maintain(
        &mut self,
        now_ms: u64,
    ) -> SnapbackResult<AssetPublicationMaintenanceReport> {
        use crate::assets;
        let store = self.asset_store_obj()?;
        let mut report = AssetPublicationMaintenanceReport::default();

        // Planned records: probe the recorded key.
        let planned = self
            .db
            .asset_maintenance()
            .publication_records_in_state(assets::AssetPublicationState::Planned)?;
        for mut record in planned {
            let attempt = self.db.asset_maintenance().publication_attempt(&record)?;
            let re_drivable = attempt.as_ref().is_some_and(|a| a.state.is_current());
            let object = crate::assets_store::AssetObjectRef::Blob(&record.planned_key);
            let object_verifies = store.exists(object)?
                && store
                    .hash(object)
                    .map(|hashed| hashed.digest == record.digest)
                    .unwrap_or(false);
            if object_verifies {
                self.db
                    .asset_maintenance()
                    .publication_stage_verified_object(&mut record, attempt.as_ref(), now_ms)?;
                report.staged += 1;
                continue;
            }
            if !re_drivable {
                if store.exists(object)? {
                    // The object exists but does not verify: a torn put.
                    store.delete_blob(&record.planned_key).ok();
                    report.objects_deleted += 1;
                }
                self.db
                    .asset_maintenance()
                    .publication_condemn_not_redrivable(&mut record, attempt.as_ref(), now_ms)?;
                report.condemned += 1;
            }
        }

        // Staged records whose work is dead: condemn.
        let staged = self
            .db
            .asset_maintenance()
            .publication_records_in_state(assets::AssetPublicationState::Staged)?;
        for mut record in staged {
            let attempt = self.db.asset_maintenance().publication_attempt(&record)?;
            if attempt.as_ref().is_some_and(|a| a.state.is_current()) {
                continue;
            }
            self.db
                .asset_maintenance()
                .publication_condemn_terminal_work(&mut record, attempt.as_ref(), now_ms)?;
            report.condemned += 1;
        }

        // Condemned records: delete the object (if any), then retire.
        let condemned = self
            .db
            .asset_maintenance()
            .publication_records_in_state(assets::AssetPublicationState::Condemned)?;
        for record in condemned {
            let object = crate::assets_store::AssetObjectRef::Blob(&record.planned_key);
            // Never delete an object a live blob row owns (the reused-path
            // convergence shares digests, not keys, so this is exact).
            let owned_by_blob = self
                .db
                .asset_maintenance()
                .publication_key_owned_by_live_blob(&record.planned_key)?;
            if store.exists(object)? && !owned_by_blob {
                store.delete_blob(&record.planned_key)?;
                report.objects_deleted += 1;
            }
            self.db
                .asset_maintenance()
                .publication_retire_condemned(&record, now_ms)?;
            report.retired += 1;
        }

        // Committed records past the retention window: the blob row is the
        // durable evidence; retire the record so the ceiling stays clear.
        let committed = self
            .db
            .asset_maintenance()
            .publication_records_in_state(assets::AssetPublicationState::Committed)?;
        for record in committed {
            if now_ms.saturating_sub(record.updated_at_ms)
                < crate::assets::ASSET_PUBLICATION_RETENTION_MS
            {
                continue;
            }
            self.db
                .asset_maintenance()
                .publication_retire_committed(&record, now_ms)?;
            report.retired += 1;
        }
        Ok(report)
    }

    /// Resolve one strict-delivery request to a readable byte window.
    /// Every request — ordinary or range — re-authorizes through the
    /// declared read-access policy; nothing about a previous grant is
    /// cached (LLP 0044 §Delivery profiles, `private-strict`).
    /// Authorization/readiness probe shared by the on-demand width path:
    /// the same refusals `asset_deliver` produces, with no bytes touched —
    /// materialization must never run for a caller delivery would refuse.
    fn asset_strict_read_probe(
        &mut self,
        authority: &PreparedAuthority,
        asset_id: &str,
    ) -> SnapbackResult<()> {
        let caller = Self::asset_caller_principal(authority);
        let schema = self.db.schema().clone();
        self.db
            .asset_reads()
            .strict_read_probe(&schema, caller.as_deref(), asset_id)
    }

    // @ref LLP 0044#ceremony-floor-and-bounded-on-demand-widths-dated-amendment-2026-08-01 —
    //   `?width=N` resolves to a ladder rendition, materialized exactly once
    //   through the ordinary publication machinery; callers authorize BEFORE
    //   resolving so unauthorized requests never trigger processing.
    pub(crate) fn asset_resolve_width_variant(
        &mut self,
        asset_id: &str,
        requested_width: u64,
    ) -> SnapbackResult<String> {
        use crate::assets;
        if !self.asset_image_finalization_enabled() {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_WIDTH_UNSUPPORTED",
                "assets",
                "on-demand widths require the image-finalization capability",
            ));
        }
        let Some(width) = assets::normalize_on_demand_width(requested_width) else {
            return Err(SnapbackError::error(
                "SNAPBACK_ASSET_WIDTH_ABOVE_CEILING",
                "assets",
                format!(
                    "width {requested_width} exceeds the declared on-demand ceiling {}",
                    assets::ASSET_ON_DEMAND_MAX_WIDTH_PX
                ),
            ));
        };
        let key = format!("w{width}");
        let already = self
            .db
            .asset_attempts()
            .resolve_width_variant_is_ready(asset_id, &key)?;
        if already {
            return Ok(key);
        }
        let app_id = self.functions.app_id.clone();
        let app_quota = self.asset_app_quota();
        let store = self.asset_store_obj()?;
        let (primary_key, content_type) = self
            .db
            .asset_attempts()
            .resolve_width_variant_primary(asset_id)?;
        let canonical_bytes =
            store.read(crate::assets_store::AssetObjectRef::Blob(&primary_key))?;
        let variant = crate::manifest::AssetImageVariant {
            key: key.clone(),
            width,
            required: false,
        };
        let prepared = self.asset_prepare_variant(
            store.as_ref(),
            &app_id,
            &canonical_bytes,
            &content_type,
            &variant,
            1,
        )?;
        let now_ms = now_millis();
        self.db
            .asset_attempts()
            .resolve_width_variant_commit(&app_id, asset_id, &prepared, app_quota, now_ms)?;
        Ok(key)
    }

    pub fn asset_deliver(
        &mut self,
        authority: &PreparedAuthority,
        asset_id: &str,
        variant: &str,
        range_header: Option<&str>,
        max_width: Option<u64>,
        width: Option<u64>,
    ) -> SnapbackResult<AssetDeliveryOutcome> {
        let variant = if let Some(requested) = width {
            self.asset_strict_read_probe(authority, asset_id)?;
            self.asset_resolve_width_variant(asset_id, requested)?
        } else {
            variant.to_owned()
        };
        let caller = Self::asset_caller_principal(authority);
        let schema = self.db.schema().clone();
        let store = self.asset_store_obj()?;
        let now = now_millis();
        let range_header = range_header.map(str::to_owned);
        self.db.asset_reads().deliver_strict(
            &schema,
            caller.as_deref(),
            &store,
            asset_id,
            &variant,
            max_width,
            range_header.as_deref(),
            now,
        )
    }

    /// `private-signed` issuance: authorization happens here, per request;
    /// the minted URL is then a bearer capability until its TTL (LLP 0044
    /// §Delivery profiles). Only signed-profile assets issue.
    pub fn asset_signed_url_issue(
        &mut self,
        authority: &PreparedAuthority,
        asset_id: &str,
        request: crate::assets::AssetSignedUrlIssueRequestV1,
    ) -> SnapbackResult<crate::assets::AssetSignedUrlIssueResponseV1> {
        use crate::assets;
        let caller = Self::asset_caller_principal(authority);
        let schema = self.db.schema().clone();
        let now = now_millis();
        let ttl = match request.ttl_ms {
            None => assets::ASSET_SIGNED_URL_DEFAULT_TTL_MS,
            Some(ms) if ms == 0 || ms > assets::ASSET_SIGNED_URL_MAX_TTL_MS => {
                return Err(SnapbackError::error(
                    "SNAPBACK_ASSET_TTL_INVALID",
                    "assets",
                    format!(
                        "ttlMs must be between 1 and {}",
                        assets::ASSET_SIGNED_URL_MAX_TTL_MS
                    ),
                ));
            }
            Some(ms) => ms,
        };
        // On-demand width (LLP 0044 §Ceremony floor): authorize first via
        // the probe transaction below, resolve/materialize the ladder
        // rendition, then sign that concrete variant.
        let (issued_variant, validate_declared_variant) = if let Some(requested) = request.width_px
        {
            self.db
                .asset_reads()
                .signed_url_width_probe(&schema, caller.as_deref(), asset_id)?;
            (
                self.asset_resolve_width_variant(asset_id, requested)?,
                false,
            )
        } else {
            (
                request.variant.unwrap_or_else(|| "primary".to_owned()),
                true,
            )
        };
        self.db.asset_reads().signed_url_issue(
            &schema,
            caller.as_deref(),
            asset_id,
            &issued_variant,
            validate_declared_variant,
            ttl,
            now,
        )
    }

    /// Serve a signed bearer URL: signature, expiry, and current lifecycle
    /// generation validate; no per-request read authorization — that is the
    /// profile's declared bearer semantics.
    pub fn asset_deliver_signed(
        &mut self,
        asset_id: &str,
        variant: &str,
        token: &str,
        range_header: Option<&str>,
    ) -> SnapbackResult<AssetDeliveryOutcome> {
        let store = self.asset_store_obj()?;
        let now = now_millis();
        self.db
            .asset_reads()
            .deliver_signed(&store, asset_id, variant, token, range_header, now)
    }

    /// Serve a `public-immutable` alias: no authorization, immutable cache
    /// headers, and everything non-servable is indistinguishable from
    /// unknown — the public lane is never an existence oracle.
    pub fn asset_deliver_public(
        &mut self,
        asset_id: &str,
        variant: &str,
        range_header: Option<&str>,
        width: Option<u64>,
    ) -> SnapbackResult<AssetDeliveryOutcome> {
        let variant = if let Some(requested) = width {
            // Public-profile check first (masked), then resolve: anonymous
            // requests on non-public assets must never trigger
            // materialization or learn existence.
            self.db.asset_reads().public_width_probe(asset_id)?;
            self.asset_resolve_width_variant(asset_id, requested)?
        } else {
            variant.to_owned()
        };
        let store = self.asset_store_obj()?;
        let now = now_millis();
        self.db
            .asset_reads()
            .deliver_public(&store, asset_id, &variant, range_header, now)
    }

    /// Operator signing-key rotation: retires every prior key, so every
    /// outstanding signed URL stops validating (LLP 0044: an operator
    /// action, not per-principal revocation). No key ids in the result.
    pub(crate) fn asset_rotate_signing_key(&mut self) -> SnapbackResult<Value> {
        let now = now_millis();
        self.db.asset_reads().rotate_signing_key(now)
    }

    /// Explicit authorized delete: the one-transaction cascade of LLP 0044
    /// §Lifecycle transitions. Idempotent on an already-deleted asset.
    pub fn asset_delete(
        &mut self,
        authority: &PreparedAuthority,
        asset_id: &str,
    ) -> SnapbackResult<Value> {
        let outcome = self.asset_delete_inner(authority, asset_id, false)?;
        self.notify_asset_record_change(&[asset_id.to_owned()]);
        Ok(outcome)
    }

    pub(crate) fn asset_delete_inner(
        &mut self,
        authority: &PreparedAuthority,
        asset_id: &str,
        crash_mid_cascade: bool,
    ) -> SnapbackResult<Value> {
        let caller = Self::asset_caller_principal(authority);
        let now = now_millis();
        let crash = crash_mid_cascade.then_some(asset_test_crash as fn() -> SnapbackError);
        let fenced_staging =
            self.db
                .asset_reads()
                .delete(caller.as_deref(), asset_id, now, crash)?;
        if let Some(staging_key) = fenced_staging {
            self.asset_store_obj()?.delete_staging_pair(&staging_key)?;
        }
        self.db.asset_reads().delete_result(asset_id)
    }

    /// The mandatory GC sweep — one callable entry point for the L1-11
    /// runner: expired attempts, staging orphans, pending-asset grace
    /// reclamation, tombstone purge, blob condemnation/cleanup, and the
    /// publication maintenance pass. Every reclamation receipts.
    #[allow(dead_code)] // scheduled by the L1-11 runner; exercised in tests.
    pub fn asset_gc_sweep(&mut self, now_ms: u64) -> SnapbackResult<AssetGcReport> {
        use crate::assets;
        let store = self.asset_store_obj()?;
        let mut report = AssetGcReport::default();
        let mut reclaimed_asset_ids: Vec<String> = Vec::new();

        // Attempt GC: expire overdue current attempts, then fence staging.
        let expired = self
            .db
            .asset_maintenance()
            .gc_expired_current_attempts(now_ms)?;
        for mut attempt in expired {
            self.db
                .asset_maintenance()
                .gc_expire_attempt(&mut attempt, now_ms)?;
            store.delete_staging_pair(&attempt.staging_key)?;
            report.expired_attempts += 1;
        }

        // Staging orphans: files no current attempt owns (crash leftovers).
        let live: std::collections::HashSet<String> = self
            .db
            .asset_maintenance()
            .gc_live_staging_keys()?
            .into_iter()
            .collect();
        for key in store.list_staging_keys()? {
            if !live.contains(&key) {
                store.delete_staging_pair(&key)?;
                report.staging_orphans_removed += 1;
            }
        }

        // Pending-asset GC: unreferenced pending/rejected past grace transit
        // `deleted`; referenced failures stay visible for repair.
        let cutoff = now_ms.saturating_sub(assets::ASSET_PENDING_GRACE_MS);
        let reclaimable = self
            .db
            .asset_maintenance()
            .gc_reclaimable_pending_assets(cutoff)?;
        for mut asset in reclaimable {
            let staging = self
                .db
                .asset_maintenance()
                .gc_reclaim_pending_asset(&mut asset, now_ms)?;
            if let Some(staging_key) = staging {
                store.delete_staging_pair(&staging_key)?;
            }
            report.pending_reclaimed += 1;
            reclaimed_asset_ids.push(asset.asset_id.clone());
        }

        // Reference-tracked asset GC (opt-in, LLP 0044 §Deletion): ready
        // assets whose grace clock ran out reclaim through the same
        // deletion cascade, each reclamation receipted with the policy and
        // the grace window it survived. The candidate query is a prefilter;
        // edgelessness and the clock re-verify inside the reclamation
        // transaction so a racing attachment always wins.
        if let Some(grace_ms) = self.asset_reference_gc_grace_ms() {
            let cutoff = now_ms.saturating_sub(grace_ms);
            let candidates = self
                .db
                .asset_maintenance()
                .gc_reclaimable_reference_assets(cutoff)?;
            for mut asset in candidates {
                let reclaimed = self
                    .db
                    .asset_maintenance()
                    .gc_reclaim_reference_asset(&mut asset, grace_ms, now_ms)?;
                if reclaimed {
                    report.reference_reclaimed += 1;
                    reclaimed_asset_ids.push(asset.asset_id.clone());
                }
            }
        }

        // Tombstone purge after retention: the receipts remain as evidence.
        let tombstone_cutoff = now_ms.saturating_sub(assets::ASSET_TOMBSTONE_RETENTION_MS);
        let purgeable = self
            .db
            .asset_maintenance()
            .gc_purgeable_tombstones(tombstone_cutoff)?;
        for asset_id in purgeable {
            self.db.asset_maintenance().gc_purge_tombstone(&asset_id)?;
            report.tombstones_purged += 1;
        }

        // Delivery receipts arrive at read rate. Bound only that event class;
        // lifecycle, publication, processing, and GC evidence is unchanged.
        let delivery_receipt_cutoff =
            now_ms.saturating_sub(assets::ASSET_DELIVERY_RECEIPT_RETENTION_MS);
        report.delivery_receipts_purged = self
            .db
            .asset_maintenance()
            .gc_purge_delivery_receipts(delivery_receipt_cutoff)?;

        // Blob GC: condemn transactionally, delete the object, then drop the
        // condemned row — each step receipted and crash-recoverable (a
        // condemned row with a missing file is resolved on the next sweep).
        let blob_cutoff = now_ms.saturating_sub(assets::ASSET_BLOB_RETENTION_MS);
        let condemnable = self
            .db
            .asset_maintenance()
            .gc_condemnable_blobs(blob_cutoff)?;
        for blob in condemnable {
            let condemned = self.db.asset_maintenance().gc_condemn_blob(&blob, now_ms)?;
            if condemned {
                report.blobs_condemned += 1;
            }
        }
        for blob in self.db.asset_maintenance().gc_condemned_blobs()? {
            if store.exists(crate::assets_store::AssetObjectRef::Blob(
                &blob.physical_key,
            ))? {
                store.delete_blob(&blob.physical_key)?;
                report.blob_objects_deleted += 1;
            }
            self.db
                .asset_maintenance()
                .gc_purge_condemned_blob(&blob, now_ms)?;
            report.blob_rows_removed += 1;
        }

        // Retained-artifact GC: superseded intent generations whose last open
        // attempt has terminated release their authorizer artifacts, each
        // reclamation receipted (intent-scoped — no asset lineage).
        report.intent_artifacts_reclaimed = self
            .db
            .asset_maintenance()
            .gc_reclaim_intent_artifacts(now_ms)?;

        report.publication = self.asset_publication_maintain(now_ms)?;
        self.notify_asset_record_change(&reclaimed_asset_ids);
        Ok(report)
    }

    /// One compatibility-runner tick (LLP 0044 §Processing runner): reclaim
    /// expired leases, claim due ledger rows under the generation fence, and
    /// drive each claimed row to a terminal or re-enqueued state with its own
    /// per-item receipts. The 0028-style sweep loop is scheduler only — this
    /// function is the deterministic drive tests call directly, and it never
    /// records sweeper-level success as the work's success (LLP 0127's bar).
    pub fn asset_runner_tick(&mut self, now_ms: u64) -> SnapbackResult<AssetRunnerReport> {
        let mut report = AssetRunnerReport::default();

        // Phase A: expired leases become enqueued again — an explicit,
        // receipted transition, never a silent claim-metadata mutation.
        let reclaimed = self
            .db
            .asset_maintenance()
            .runner_reclaim_expired_leases(now_ms)?;
        report.leases_reclaimed = reclaimed;

        // Phase B: claim due rows. The generation fence and the deadline are
        // claim-time checks, so cancelled/exhausted rows never hold a lease.
        let (claimed, cancelled, exhausted) =
            self.db.asset_maintenance().runner_claim_due_work(now_ms)?;
        report.cancelled += cancelled;
        report.exhausted += exhausted;
        report.claimed = claimed.len() as u64;

        // Phase C: drive each claimed row by kind, then settle it with its
        // own receipt. Store effects run outside the settle transaction and
        // are idempotent, exactly like finalization's object puts.
        for mut row in claimed {
            let outcome = self.asset_execute_work(&row, now_ms);
            let (completed, retried, exhausted) = self
                .db
                .asset_maintenance()
                .runner_settle_work(&mut row, &outcome, now_ms)?;
            report.completed += completed;
            report.retried += retried;
            report.exhausted += exhausted;
        }
        Ok(report)
    }

    /// Execute one claimed ledger row by kind. Effects are idempotent; the
    /// caller settles the row's state and receipts.
    fn asset_execute_work(
        &mut self,
        row: &crate::assets::AssetWorkRowV1,
        now_ms: u64,
    ) -> SnapbackResult<Option<Value>> {
        use crate::assets;
        match row.kind.as_str() {
            // Condemned-object cleanup completes on observation: the pass
            // deletes any condemned publication object still on disk for
            // this asset, and Done means none remain (satisfied-by-sweep is
            // the same observation).
            assets::ASSET_WORK_KIND_CONDEMNED_CLEANUP => {
                let store = self.asset_store_obj()?;
                let condemned = self.db.asset_attempts().work_condemned_publications()?;
                for record in condemned
                    .iter()
                    .filter(|record| record.attempt_id.as_deref() == row.attempt_id.as_deref())
                {
                    if store.exists(crate::assets_store::AssetObjectRef::Blob(
                        &record.planned_key,
                    ))? {
                        store.delete_blob(&record.planned_key)?;
                    }
                }
                let _ = now_ms;
                Ok(None)
            }
            // A declared lifecycle callback: an ordinary generated mutation
            // invoked with typed facts (asset/rendition ids and safe
            // metadata — never byte authority, staging keys, or bearer
            // URLs). Dev mode preserves the asset-owner authority; sessions
            // mode uses the bearer-free per-app `asset-callbacks` service
            // principal. Idempotency rides the client-mutation ledger: the
            // stable id `asset-cb:{asset}:{event}:{generation}` makes a
            // re-driven ledger row a replay, so the callback's observable
            // effect never doubles (LLP 0044 §Processing runner).
            //
            // @ref LLP 0039#dated-amendment-sessions-asset-callback-execution-authority-2026-08-03
            //   — the sessions branch is explicitly service-principal
            //   authority, while both branches retain the ordinary staged
            //   mutation/commit-time validation path.
            assets::ASSET_WORK_KIND_LIFECYCLE_CALLBACK => {
                let params = row.params.clone().unwrap_or_default();
                let (Some(event), Some(handler)) = (
                    params
                        .get("event")
                        .and_then(serde_json::Value::as_str)
                        .map(str::to_owned),
                    params
                        .get("handler")
                        .and_then(serde_json::Value::as_str)
                        .map(str::to_owned),
                ) else {
                    return Err(SnapbackError::error(
                        "SNAPBACK_ASSET_WORK_PARAMS_INVALID",
                        "assets",
                        "lifecycle-callback work carries no usable params",
                    ));
                };
                let (asset, renditions) = self
                    .db
                    .asset_attempts()
                    .work_lifecycle_callback_facts(&row.asset_id)?;
                let facts = serde_json::json!({
                    "intentId": asset.intent_id,
                    "availability": asset.availability,
                    "lifecycleGeneration": asset.lifecycle_generation,
                    "renditions": renditions
                        .iter()
                        .map(|rendition| {
                            serde_json::json!({
                                "key": rendition.variant_key,
                                "state": rendition.state,
                            })
                        })
                        .collect::<Vec<_>>(),
                });
                let mut input = crate::manifest::HandlerInput {
                    args: serde_json::json!({
                        "event": event,
                        "assetId": row.asset_id,
                        "facts": facts,
                    }),
                    ..crate::manifest::HandlerInput::default()
                };
                let authority = match self.admission.diagnostic_snapshot().active_mode {
                    AuthMode::Dev => {
                        input.auth = crate::manifest::AuthInput {
                            user_id: Some(asset.owner_principal.clone()),
                            ..crate::manifest::AuthInput::default()
                        };
                        self.prepare_legacy_dev_authority(
                            InvocationSource::AssetCallback,
                            ServerProfile::Dev,
                            &input,
                        )?
                    }
                    AuthMode::Sessions => self.prepare_asset_callbacks_authority(&handler)?,
                };
                let authority_receipt = authority.asset_callbacks_service().map(|principal| {
                    serde_json::json!({
                        "actorKind": crate::storage::auth_asset_callbacks::ASSET_CALLBACKS_SERVICE_NAME,
                        "actorUserId": principal.actor_user_id.clone(),
                        "grantId": principal.grant_id.clone(),
                        "sessionId": null,
                    })
                });
                let idempotency_key = format!(
                    "asset-cb:{}:{event}:{}",
                    row.asset_id, row.lifecycle_generation
                );
                let authority_descriptor = if authority.active_mode() == AuthMode::Sessions {
                    let incarnation = self.db.ensure_authorization_stream_incarnation()?;
                    Some(crate::auth::invocation::descriptor_for_authority(
                        &authority,
                        incarnation.as_str(),
                    )?)
                } else {
                    None
                };
                let (_preflight, staged) = self.stage_recorded_authorization_mutation(
                    &handler,
                    input,
                    Some(idempotency_key),
                    authority_descriptor,
                    &[],
                    "asset-runner",
                    authority,
                )?;
                // The commit envelope carries the handler's own outcome
                // inside: a throwing callback is a work failure (retried
                // toward the ceiling), never a silent Done.
                let (outcome, _receipt) =
                    self.commit_staged_recorded_authorization_mutation(staged)?;
                outcome?;
                let _ = now_ms;
                Ok(authority_receipt)
            }
            // An optional declared rendition: render off the canonical
            // primary blob, stage through the publication protocol, and
            // settle with the generation-checked pointer switch. Idempotent
            // per re-drive; a quota refusal is a structured rendition
            // failure that never gates the ready primary.
            assets::ASSET_WORK_KIND_IMAGE_VARIANT => {
                let params = row.params.clone().unwrap_or_default();
                let (Some(key), Some(width), Some(content_type)) = (
                    params
                        .get("key")
                        .and_then(serde_json::Value::as_str)
                        .map(str::to_owned),
                    params.get("width").and_then(serde_json::Value::as_u64),
                    params
                        .get("contentType")
                        .and_then(serde_json::Value::as_str)
                        .map(str::to_owned),
                ) else {
                    return Err(SnapbackError::error(
                        "SNAPBACK_ASSET_WORK_PARAMS_INVALID",
                        "assets",
                        "image-variant work carries no usable params",
                    ));
                };
                let recipe_version = params
                    .get("recipeVersion")
                    .and_then(serde_json::Value::as_u64)
                    .unwrap_or(1);
                let app_id = self.functions.app_id.clone();
                let app_quota = self.asset_app_quota();
                let store = self.asset_store_obj()?;
                let asset_id = row.asset_id.clone();

                let already = self.db.asset_attempts().work_image_variant_is_current(
                    &asset_id,
                    &key,
                    recipe_version,
                )?;
                if already {
                    return Ok(None);
                }
                let primary_key = self
                    .db
                    .asset_attempts()
                    .work_image_variant_primary_key(&asset_id)?;
                let canonical_bytes =
                    store.read(crate::assets_store::AssetObjectRef::Blob(&primary_key))?;
                let variant = crate::manifest::AssetImageVariant {
                    key: key.clone(),
                    width,
                    required: false,
                };
                let prepared = match self.asset_prepare_variant(
                    store.as_ref(),
                    &app_id,
                    &canonical_bytes,
                    &content_type,
                    &variant,
                    recipe_version,
                ) {
                    Ok(prepared) => prepared,
                    // Deterministic processing refusals become durable
                    // rendition failures (work Done, optional never gates);
                    // store errors surface for retry.
                    Err(error) if error.diagnostic.code != "SNAPBACK_ASSET_STORE_UNAVAILABLE" => {
                        let work_id = row.work_id.clone();
                        self.db.asset_attempts().work_commit_rendition_failure(
                            &work_id,
                            &asset_id,
                            &key,
                            &error.diagnostic.code,
                            now_ms,
                        )?;
                        return Ok(None);
                    }
                    Err(error) => return Err(error),
                };
                let work_id = row.work_id.clone();
                self.db.asset_attempts().work_commit_prepared_variant(
                    &work_id, &app_id, &asset_id, &prepared, app_quota, now_ms,
                )?;
                Ok(None)
            }
            #[cfg(test)]
            assets::ASSET_WORK_KIND_TEST_TRANSIENT_FAILURE => Err(SnapbackError::error(
                "SNAPBACK_ASSET_TEST_TRANSIENT",
                "assets",
                "injected transient failure for runner tests",
            )),
            other => Err(SnapbackError::error(
                "SNAPBACK_ASSET_WORK_KIND_UNKNOWN",
                "assets",
                format!("unknown asset work kind {other}"),
            )),
        }
    }

    /// Execute the only full revalidation path permitted to mint an
    /// AuthorizedLease. Query result, data head, authorization pair,
    /// activation, issuer, and target-scoped obligation state are captured
    /// while the app instance is one coherent read. Signing happens only after
    /// this method releases the app lock; final reservation rechecks every
    /// fact.
    ///
    /// @ref LLP 0053#the-lease-the-only-mechanism-for-the-unreachable-client —
    /// opaque/undeclared queries cannot retain, and a pending invalidation
    /// capable of quarantining/deleting this exact query can never ride a
    /// lease-bearing snapshot; unrelated users' obligations do not fence it
    /// (ENG-24989).
    #[allow(dead_code)]
    pub(crate) fn capture_authorized_lease_query(
        &self,
        name: &str,
        input: HandlerInput,
        authority: PreparedAuthority,
        request: AuthorizedLeaseRequestIdentity,
    ) -> SnapbackResult<AuthorizedLeaseCapture> {
        self.capture_authorized_lease_query_generation(name, input, authority, request, None)
    }

    pub fn capture_authorized_lease_query_generation(
        &self,
        name: &str,
        input: HandlerInput,
        authority: PreparedAuthority,
        request: AuthorizedLeaseRequestIdentity,
        expected_generation: Option<&ArtifactGeneration>,
    ) -> SnapbackResult<AuthorizedLeaseCapture> {
        request.validate()?;
        authority.validate_admission("authorized lease full-query capture")?;
        let function = self.function(name)?;
        self.validate_expected_generation(&authority, expected_generation)?;
        if !function.is_user_scoped_retainable_query() {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTHORIZED_LEASE_QUERY_NOT_RETAINABLE",
                "auth",
                "authorized leases require a declared userId-only retainable query",
            ));
        }
        let (
            principal_id,
            session_id_at_issue,
            provider_key,
            session_not_after_ms,
            provider_not_after_ms,
            authority_instance_id,
        ) = match authority.resolved() {
            ResolvedAppAuthority::Session {
                user_id,
                session_id,
                provider,
                authority_instance_id,
                session_not_after_ms,
                provider_not_after_ms,
                ..
            } => (
                user_id.clone(),
                Some(session_id.clone()),
                Some(provider.clone()),
                Some(*session_not_after_ms),
                *provider_not_after_ms,
                Some(authority_instance_id.clone()),
            ),
            _ => {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTHORIZED_LEASE_AUTHORITY_INVALID",
                    "auth",
                    "authorized retained queries require resolved session authority",
                ));
            }
        };
        let invalidation = self.auth_invalidation.as_ref().ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_AUTHORIZED_LEASE_UNAVAILABLE",
                "auth",
                "authorization invalidation state is unavailable",
            )
        })?;
        let lease_target = QueryNamespace {
            client_store_id: request.client_store_id.clone(),
            query_key: request.query_key.clone(),
            query_instance_id: request.query_instance_id,
        };
        if invalidation.obligations.blocks_lease_target(&lease_target) {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_INVALIDATION_PENDING",
                "auth",
                "an authorization/query/connection obligation is pending for this query",
            ));
        }
        let deployment = self
            .db
            .auth_mode_snapshot()?
            .state
            .active_deployment
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_AUTHORIZED_LEASE_UNAVAILABLE",
                    "auth",
                    "active deployment identity is unavailable",
                )
            })?;
        if deployment.auth_mode != AuthMode::Sessions {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTHORIZED_LEASE_AUTHORITY_INVALID",
                "auth",
                "authorized leases are unavailable outside sessions mode",
            ));
        }
        let target_profile_id = self
            .db
            .schema()
            .target_profile
            .clone()
            .unwrap_or_else(|| TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX.to_owned());
        let issuer_id = invalidation.issuer.authenticated().issuer_id.clone();
        let authorization = invalidation.obligations.expectation().authorization.clone();
        let version_stream = invalidation.version_stream.clone();
        let admission = authority.admission_lease().clone();
        let proof_input = input.clone();
        let output = self
            .invoke_query_with_dependencies_prepared(name, input, authority)?
            .output;
        if output.version != self.db.versions_read().current_version()? {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTHORIZED_LEASE_STALE",
                "auth",
                "full query did not finish at the current data head",
            ));
        }
        // This guard covers the capture boundary. The cloned lease remains
        // live across signing and is consumed again at final reservation.
        {
            let _capture = admission.effect_guard("authorized lease full-query capture")?;
        }
        let completeness = self
            .issue_completeness_proof(function, &proof_input, &output, Some(&lease_target), &[])?
            .map(|(proof, witness, _)| FiniteCompletenessCarrier { proof, witness });
        Ok(AuthorizedLeaseCapture {
            issue: AuthorizedLeaseIssue {
                lease_id: crate::ids::mint_time_ordered(crate::ids::Kind::Lease),
                lease_request_id: request.lease_request_id,
                issuer_id,
                client_store_id: request.client_store_id,
                query_key: request.query_key,
                query_instance_id: request.query_instance_id,
                principal_id,
                session_id_at_issue,
                provider_key,
                authorization,
                data: AuthorizedLeaseData {
                    version_stream,
                    snapshot_commit_version: output.version,
                },
                activation_hash: authorized_lease_activation_hash(&deployment),
                session_not_after_ms,
                provider_not_after_ms,
                authority_instance_id,
            },
            output,
            completeness,
            target_profile_id,
            app_id: deployment.app_id,
            admission,
        })
    }

    /// Reacquire the app lane after keyring signing and consume the one-shot
    /// reservation only if the capture still exactly names the current head,
    /// auth pair, activation, issuer, and target-scoped empty obligation set.
    /// Rechecking here means an obligation for this exact query that races
    /// the capture/signing window still wins over the lease.
    pub fn reserve_captured_authorized_lease(
        &mut self,
        capture: AuthorizedLeaseCapture,
        lease: &AuthorizedLease,
        config: AuthorizedLeaseConfig,
        issued_at_server_ms: u64,
    ) -> SnapbackResult<QueryOutput> {
        capture
            .issue
            .require_issued_lease(lease, issued_at_server_ms)?;
        capture.admission.validate("authorized lease reservation")?;
        // @ref LLP 0053#the-lease-the-only-mechanism-for-the-unreachable-client —
        // the reservation proof blocks only obligations capable of
        // quarantining/deleting this exact query instance (ENG-24989).
        let lease_target = QueryNamespace {
            client_store_id: capture.issue.client_store_id.clone(),
            query_key: capture.issue.query_key.clone(),
            query_instance_id: capture.issue.query_instance_id,
        };
        let no_pending_obligation = self
            .auth_invalidation
            .as_ref()
            .is_some_and(|state| !state.obligations.blocks_lease_target(&lease_target));
        let current_issuer_id = self
            .auth_invalidation
            .as_ref()
            .map(|state| state.issuer.authenticated().issuer_id.clone())
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_AUTHORIZED_LEASE_UNAVAILABLE",
                    "auth",
                    "authorization invalidation state is unavailable",
                )
            })?;
        let _reservation = capture
            .admission
            .effect_guard("authorized lease reservation transaction")?;
        self.db.reserve_authorized_lease(
            lease,
            config,
            issued_at_server_ms,
            no_pending_obligation,
            &current_issuer_id,
        )?;
        Ok(capture.output)
    }

    pub fn invoke_mutation(
        &mut self,
        name: &str,
        input: HandlerInput,
    ) -> SnapbackResult<MutationOutput> {
        self.invoke_mutation_recording_from_source(name, input, InvocationSource::LocalMutation)
            .0
    }

    /// Prepare one private acceptance fixture with the actual public-carrier
    /// issuance and ordinary-mutation coverage state. This is deliberately
    /// crate-private and does not create a supported profile-off/on product
    /// switch; only the dated paired recorder calls it on a fresh database.
    ///
    /// @ref LLP 0162#measurement-gate — the active-path comparison must carry
    ///   authenticated issuance through the covered production choke point.
    pub fn prepare_agent_safe_active_lane_benchmark(
        &mut self,
        input: &HandlerInput,
    ) -> SnapbackResult<crate::commit_envelope::ClientIdentityRangeV1> {
        self.prepare_agent_safe_active_lane_benchmark_for_client(input, "agent-safe-bench-client")
            .map(|(_, range)| range)
    }

    /// Run one observation while retaining the exact armed storage connection
    /// used by the private active-lane fixture. The observer never receives
    /// the database: the rank-7 benchmark may sample process counters without
    /// gaining a raw commit capability over this instance.
    ///
    /// @ref LLP 0162#measurement-gate — setup work is outside the idle window;
    ///   the candidate holds the same storage object as the pre-profile twin.
    pub fn observe_agent_safe_active_idle<R>(
        self,
        range: &crate::commit_envelope::ClientIdentityRangeV1,
        observe: impl FnOnce() -> R,
    ) -> R {
        let database = self.db;
        let observation = observe();
        std::hint::black_box((&database, range));
        drop(database);
        observation
    }

    /// Prepare one independently identified writer for the concurrent
    /// request-to-COMMIT fixture. Returning the server-owned stream lets the
    /// recorder install the real promotion reservation on the exact stream
    /// that the subsequent storage transaction will check.
    pub fn prepare_agent_safe_active_lane_benchmark_for_client(
        &mut self,
        input: &HandlerInput,
        client_audience_id: &str,
    ) -> SnapbackResult<(String, crate::commit_envelope::ClientIdentityRangeV1)> {
        let authority = self.admission.admit_dev().and_then(|admission| {
            InvocationGate::prepare_admitted_dev_input(
                InvocationSource::LocalMutation,
                ServerProfile::Dev,
                input,
                admission,
            )
        })?;
        // The ordinary benchmark fixture predates identity streams; create
        // its server-owned stream before asking the public range issuer to
        // bind a range to it.
        let stream_id = self.db.data_version_stream()?;
        let range =
            self.issue_client_operation_identity_range(&authority, client_audience_id, None, None)?;
        self.db
            .activate_ordinary_mutation_coverage_for_evidence(now_millis())?;
        Ok((stream_id, range))
    }

    /// Invoke the same staged issuance-bearing mutation body used by the HTTP
    /// carrier after it has authenticated the request. Range and counter facts
    /// are server-issued; this helper never accepts a host identity.
    pub fn invoke_agent_safe_active_lane_benchmark_mutation(
        &mut self,
        name: &str,
        input: HandlerInput,
        range: &crate::commit_envelope::ClientIdentityRangeV1,
        counter: u64,
    ) -> SnapbackResult<MutationOutput> {
        if counter < range.range_start || counter >= range.range_end_exclusive {
            return Err(SnapbackError::error(
                "SNAPBACK_OPERATION_RANGE_EXHAUSTED",
                "protocol",
                "acceptance benchmark counter escaped its server-issued range",
            ));
        }
        let authority = self.admission.admit_dev().and_then(|admission| {
            InvocationGate::prepare_admitted_dev_input(
                InvocationSource::LocalMutation,
                ServerProfile::Dev,
                &input,
                admission,
            )
        })?;
        let issuance = crate::commit_envelope::OperationIssuanceV1::ClientRange {
            epoch_id: range.epoch_id.clone(),
            counter,
            range_start: range.range_start,
            range_end_exclusive: range.range_end_exclusive,
            authority_authenticator_digest: range.authority_authenticator_digest.clone(),
        };
        // Range counters are unique only inside their server-issued client
        // epoch. Include that epoch in the durable replay key so concurrent
        // acceptance writers can each start at counter zero without aliasing.
        let client_mutation_id = format!("agent-safe-bench-{}-{counter}", range.epoch_id);
        let (_preflight, staged) = self
            .stage_recorded_authorization_mutation_with_generation_and_settlement(
                name,
                input,
                Some(client_mutation_id),
                None,
                &[],
                "agent-safe-paired-recorder",
                authority,
                None,
                Some(issuance),
                MutationSettlement::default(),
            )?;
        self.commit_staged_recorded_authorization_mutation(staged)?
            .0
    }

