    pub(crate) fn invoke_mutation_with_authority(
        &mut self,
        name: &str,
        input: HandlerInput,
        authority: PreparedAuthority,
    ) -> SnapbackResult<MutationOutput> {
        self.invoke_mutation_recording_with_authority(name, input, None, "local", authority)
            .0
    }

    /// `function.run`'s direct/in-process sibling of the managed staged path.
    /// Preserve the exact commit dependency capture while retaining the
    /// ordinary mutation receipt/publication behavior.
    pub(crate) fn invoke_mutation_with_authority_and_dependencies(
        &mut self,
        name: &str,
        input: HandlerInput,
        authority: PreparedAuthority,
    ) -> (SnapbackResult<MutationOutput>, MutationDependencyCapture) {
        let (outcome, _receipt, capture) = self
            .invoke_mutation_recording_with_authority_and_dependencies(
                name, input, None, "local", authority,
            );
        (outcome, capture)
    }

    /// The mutation choke point with receipt emission (LLP 0034 §3.2,
    /// ENG-22478). Every mutation — HTTP, action-hosted, cron-driven —
    /// produces a MutationReceipt with the provider-owned fields; the opaque
    /// adapter correlation from the input is echoed verbatim. The receipt is
    /// retained in the global ring and returned so the HTTP handler can ride
    /// it on the response.
    pub fn invoke_mutation_recording(
        &mut self,
        name: &str,
        input: HandlerInput,
    ) -> (SnapbackResult<MutationOutput>, Receipt) {
        self.invoke_mutation_recording_from_source(name, input, InvocationSource::LocalMutation)
    }

    fn invoke_mutation_recording_from_source(
        &mut self,
        name: &str,
        input: HandlerInput,
        source: InvocationSource,
    ) -> (SnapbackResult<MutationOutput>, Receipt) {
        self.invoke_mutation_recording_with_id_from_source(name, input, None, "local", source)
    }

    pub fn invoke_mutation_recording_with_transport(
        &mut self,
        name: &str,
        input: HandlerInput,
        transport: &str,
    ) -> (SnapbackResult<MutationOutput>, Receipt) {
        self.invoke_mutation_recording_with_id_from_source(
            name,
            input,
            None,
            transport,
            InvocationSource::LocalMutation,
        )
    }

    pub fn invoke_mutation_recording_with_id(
        &mut self,
        name: &str,
        input: HandlerInput,
        client_mutation_id: Option<String>,
        transport: &str,
    ) -> (SnapbackResult<MutationOutput>, Receipt) {
        self.invoke_mutation_recording_with_id_from_source(
            name,
            input,
            client_mutation_id,
            transport,
            InvocationSource::LocalMutation,
        )
    }

    pub(crate) fn invoke_mutation_recording_with_id_from_source(
        &mut self,
        name: &str,
        input: HandlerInput,
        client_mutation_id: Option<String>,
        transport: &str,
        source: InvocationSource,
    ) -> (SnapbackResult<MutationOutput>, Receipt) {
        self.invoke_mutation_recording_with_id_and_descriptor_from_source(
            name,
            input,
            client_mutation_id,
            None,
            transport,
            source,
        )
    }

    pub(crate) fn invoke_mutation_recording_with_id_and_descriptor_from_source(
        &mut self,
        name: &str,
        input: HandlerInput,
        client_mutation_id: Option<String>,
        authority_descriptor: Option<AuthorityDescriptor>,
        transport: &str,
        source: InvocationSource,
    ) -> (SnapbackResult<MutationOutput>, Receipt) {
        let authority = self.admission.admit_dev().and_then(|admission| {
            InvocationGate::prepare_admitted_dev_input(
                source,
                ServerProfile::Dev,
                &input,
                admission,
            )
        });
        match authority {
            Ok(authority) => self.invoke_mutation_recording_with_authority_descriptor(
                name,
                input,
                client_mutation_id,
                authority_descriptor,
                transport,
                authority,
            ),
            Err(error) => {
                let correlation = capped_correlation(input.correlation.clone());
                let receipt_mutation_id = client_mutation_id
                    .unwrap_or_else(|| crate::ids::mint_time_ordered(crate::ids::Kind::Mutation));
                self.record_mutation_commit(
                    name,
                    transport,
                    correlation,
                    receipt_mutation_id,
                    &MutationSettlement::default(),
                    Err(error),
                    false,
                )
            }
        }
    }

    pub(crate) fn invoke_mutation_recording_with_authority(
        &mut self,
        name: &str,
        input: HandlerInput,
        client_mutation_id: Option<String>,
        transport: &str,
        authority: PreparedAuthority,
    ) -> (SnapbackResult<MutationOutput>, Receipt) {
        self.invoke_mutation_recording_with_authority_descriptor(
            name,
            input,
            client_mutation_id,
            None,
            transport,
            authority,
        )
    }

    /// Detailed sibling used by the D1 host-operation envelope. The receipt
    /// and publication semantics remain owned by the recording path; this
    /// carrier only stops that path from discarding the executed commit's
    /// captured dependencies.
    pub(crate) fn invoke_mutation_recording_with_authority_and_dependencies(
        &mut self,
        name: &str,
        input: HandlerInput,
        client_mutation_id: Option<String>,
        transport: &str,
        authority: PreparedAuthority,
    ) -> (
        SnapbackResult<MutationOutput>,
        Receipt,
        MutationDependencyCapture,
    ) {
        self.invoke_mutation_recording_with_authority_descriptor_and_dependencies(
            name,
            input,
            client_mutation_id,
            None,
            transport,
            authority,
        )
    }

    /// HTTP/Contract queued replay entry point. A live credential has already
    /// become `authority`; only then do we compare the non-authorizing
    /// descriptor. Session-mode queued work requires it, while dev-mode
    /// callers that predate protocol v1 remain compatible until they opt in.
    ///
    /// @ref LLP 0039#replay-parity-and-the-authority-instance-id — first and
    /// duplicate deliveries share one pre-effect descriptor check.
    pub(crate) fn invoke_mutation_recording_with_authority_descriptor(
        &mut self,
        name: &str,
        input: HandlerInput,
        client_mutation_id: Option<String>,
        authority_descriptor: Option<AuthorityDescriptor>,
        transport: &str,
        authority: PreparedAuthority,
    ) -> (SnapbackResult<MutationOutput>, Receipt) {
        let (outcome, receipt, _capture) = self
            .invoke_mutation_recording_with_authority_descriptor_and_dependencies(
                name,
                input,
                client_mutation_id,
                authority_descriptor,
                transport,
                authority,
            );
        (outcome, receipt)
    }

    #[allow(clippy::too_many_arguments)]
    fn invoke_mutation_recording_with_authority_descriptor_and_dependencies(
        &mut self,
        name: &str,
        input: HandlerInput,
        client_mutation_id: Option<String>,
        authority_descriptor: Option<AuthorityDescriptor>,
        transport: &str,
        authority: PreparedAuthority,
    ) -> (
        SnapbackResult<MutationOutput>,
        Receipt,
        MutationDependencyCapture,
    ) {
        // Managed transport/action hosts must stage outside Local themselves;
        // this compatibility path is only allowed to create a reservation
        // while the direct embedder owns the instance without a Local scope.
        if crate::exec_guard::local_write_scope_active() {
            return self
                .invoke_mutation_recording_with_authority_descriptor_in_scope_and_dependencies(
                    name,
                    input,
                    client_mutation_id,
                    authority_descriptor,
                    transport,
                    authority,
                );
        }

        let admission = authority.admission_lease().clone();
        let correlation = capped_correlation(input.correlation.clone());
        let receipt_mutation_id = client_mutation_id
            .clone()
            .unwrap_or_else(|| crate::ids::mint_time_ordered(crate::ids::Kind::Mutation));
        let staged = self.stage_recorded_authorization_mutation(
            name,
            input,
            client_mutation_id,
            authority_descriptor,
            &[],
            transport,
            authority,
        );
        let (preflight, staged) = match staged {
            Ok(staged) => staged,
            Err(error) => {
                let (outcome, receipt) = self.record_mutation_commit_after_publication_guard(
                    MutationReceiptPublication::new(
                        name,
                        transport,
                        correlation,
                        receipt_mutation_id,
                        &admission,
                    ),
                    Err(error),
                );
                return (outcome, receipt, MutationDependencyCapture::incomplete());
            }
        };
        let committed = self.try_with_direct_authorization_write(preflight, move |snapback| {
            snapback.commit_staged_recorded_authorization_mutation_with_dependencies(staged)
        });
        match committed {
            Ok(Ok(recorded)) => recorded,
            Ok(Err(error)) | Err(error) => {
                let (outcome, receipt) = self.record_mutation_commit_after_publication_guard(
                    MutationReceiptPublication::new(
                        name,
                        transport,
                        correlation,
                        receipt_mutation_id,
                        &admission,
                    ),
                    Err(error),
                );
                (outcome, receipt, MutationDependencyCapture::incomplete())
            }
        }
    }

    /// The already-staged/managed compatibility body. Callers reaching this
    /// under a Local scope are responsible for having installed a carrier;
    /// this method never performs an in-lock reservation fallback.
    #[allow(clippy::too_many_arguments)]
    fn invoke_mutation_recording_with_authority_descriptor_in_scope_and_dependencies(
        &mut self,
        name: &str,
        input: HandlerInput,
        client_mutation_id: Option<String>,
        authority_descriptor: Option<AuthorityDescriptor>,
        transport: &str,
        authority: PreparedAuthority,
    ) -> (
        SnapbackResult<MutationOutput>,
        Receipt,
        MutationDependencyCapture,
    ) {
        let admission = authority.admission_lease().clone();
        let correlation = capped_correlation(input.correlation.clone());
        let receipt_mutation_id = client_mutation_id
            .clone()
            .unwrap_or_else(|| crate::ids::mint_time_ordered(crate::ids::Kind::Mutation));
        let result = self.invoke_mutation_commit_with_id_and_authority(
            name,
            input,
            client_mutation_id,
            authority_descriptor,
            Some(receipt_mutation_id.as_str()),
            authority,
        );
        let capture = result
            .as_ref()
            .map(MutationDependencyCapture::from_commit)
            .unwrap_or_else(|_| MutationDependencyCapture::incomplete());
        let (outcome, receipt) = self.record_mutation_commit_after_publication_guard(
            MutationReceiptPublication::new(
                name,
                transport,
                correlation,
                receipt_mutation_id,
                &admission,
            ),
            result,
        );
        (outcome, receipt, capture)
    }

    /// HTTP queued-delivery entry point with receipt-proven piggyback ACKs.
    /// The shared function gate and descriptor comparison run before the ACK
    /// transaction, so a stale or malformed queued request has no settlement
    /// side effect. The ordinary mutation path above delegates with no ACKs.
    ///
    /// @ref LLP 0043#milestone-2-queued-mutation-replay — descriptor
    /// comparison precedes settlement lookup and every request effect.
    // These fields are deliberately independent wire/effect axes. Collapsing
    // them into an opaque options bag would weaken the queued replay seam for
    // the sake of Clippy's one-argument-over default.
    #[cfg(test)]
    #[allow(clippy::too_many_arguments)]
    pub(crate) fn invoke_mutation_recording_with_authority_descriptor_and_acknowledgements(
        &mut self,
        name: &str,
        input: HandlerInput,
        client_mutation_id: Option<String>,
        authority_descriptor: Option<AuthorityDescriptor>,
        acknowledged_client_mutation_ids: &[String],
        transport: &str,
        authority: PreparedAuthority,
    ) -> SnapbackResult<(SnapbackResult<MutationOutput>, Receipt)> {
        let function = self.function(name)?.clone();
        let prepared = InvocationGate::prepare_function(authority.clone(), &function)?;
        if client_mutation_id.is_some() {
            let incarnation = self.db.ensure_authorization_stream_incarnation()?;
            let expected = descriptor_for_authority(prepared.authority(), incarnation.as_str())?;
            if prepared.authority().active_mode() == AuthMode::Sessions
                || authority_descriptor.is_some()
            {
                require_current_descriptor(authority_descriptor.as_ref(), &expected)?;
            }
        }
        if !acknowledged_client_mutation_ids.is_empty() {
            self.acknowledge_client_mutations_with_authority(
                prepared.authority(),
                acknowledged_client_mutation_ids,
            )?;
        }
        Ok(self.invoke_mutation_recording_with_authority_descriptor(
            name,
            input,
            client_mutation_id,
            authority_descriptor,
            transport,
            authority,
        ))
    }

    /// Execute a mutation handler at most once, then preview only its stored
    /// plan or already-buffered effects to obtain the exact protected-room
    /// selector. The returned carrier owns no open SQLite transaction and can
    /// cross the off-Local room-quiescence phase safely.
    ///
    /// @ref LLP 0059#locking-and-linearization — exact room dependency
    ///   planning precedes both managed Local commit work and SQLite.
    #[allow(clippy::too_many_arguments)]
    pub fn stage_recorded_authorization_mutation(
        &mut self,
        name: &str,
        input: HandlerInput,
        client_mutation_id: Option<String>,
        authority_descriptor: Option<AuthorityDescriptor>,
        acknowledged_client_mutation_ids: &[String],
        transport: &str,
        authority: PreparedAuthority,
    ) -> SnapbackResult<(
        crate::storage::AuthorizationCommitPreflight,
        StagedRecordedMutation,
    )> {
        self.stage_recorded_authorization_mutation_with_generation(
            name,
            input,
            client_mutation_id,
            authority_descriptor,
            acknowledged_client_mutation_ids,
            transport,
            authority,
            None,
        )
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn stage_recorded_authorization_mutation_with_generation(
        &mut self,
        name: &str,
        input: HandlerInput,
        client_mutation_id: Option<String>,
        authority_descriptor: Option<AuthorityDescriptor>,
        acknowledged_client_mutation_ids: &[String],
        transport: &str,
        authority: PreparedAuthority,
        expected_generation: Option<&ArtifactGeneration>,
    ) -> SnapbackResult<(
        crate::storage::AuthorizationCommitPreflight,
        StagedRecordedMutation,
    )> {
        self.stage_recorded_authorization_mutation_with_generation_and_settlement(
            name,
            input,
            client_mutation_id,
            authority_descriptor,
            acknowledged_client_mutation_ids,
            transport,
            authority,
            expected_generation,
            None,
            MutationSettlement::default(),
        )
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn stage_recorded_authorization_mutation_with_generation_and_settlement(
        &mut self,
        name: &str,
        input: HandlerInput,
        client_mutation_id: Option<String>,
        authority_descriptor: Option<AuthorityDescriptor>,
        acknowledged_client_mutation_ids: &[String],
        transport: &str,
        authority: PreparedAuthority,
        expected_generation: Option<&ArtifactGeneration>,
        operation_issuance: Option<crate::commit_envelope::OperationIssuanceV1>,
        settlement: MutationSettlement,
    ) -> SnapbackResult<(
        crate::storage::AuthorizationCommitPreflight,
        StagedRecordedMutation,
    )> {
        self.stage_recorded_authorization_mutation_with_generation_and_settlement_inner(
            name,
            input,
            client_mutation_id,
            authority_descriptor,
            acknowledged_client_mutation_ids,
            transport,
            authority,
            expected_generation,
            operation_issuance,
            settlement,
            None,
            None,
            false,
        )
    }

    /// The finite HTTP mutation carrier has no connection lineage from which
    /// to inherit LLP 0094's negotiated version, so it presents the exact
    /// offer alongside the request. Internal and legacy callers continue
    /// through the offerless wrapper above.
    #[allow(clippy::too_many_arguments)]
    pub fn stage_recorded_authorization_mutation_with_wire_version(
        &mut self,
        name: &str,
        input: HandlerInput,
        client_mutation_id: Option<String>,
        authority_descriptor: Option<AuthorityDescriptor>,
        acknowledged_client_mutation_ids: &[String],
        transport: &str,
        authority: PreparedAuthority,
        expected_generation: Option<&ArtifactGeneration>,
        operation_issuance: Option<crate::commit_envelope::OperationIssuanceV1>,
        settlement: MutationSettlement,
        media_command: Option<crate::manifest::MediaCommandInvocationV1>,
        wire_version: Option<&str>,
    ) -> SnapbackResult<(
        crate::storage::AuthorizationCommitPreflight,
        StagedRecordedMutation,
    )> {
        self.stage_recorded_authorization_mutation_with_generation_and_settlement_inner(
            name,
            input,
            client_mutation_id,
            authority_descriptor,
            acknowledged_client_mutation_ids,
            transport,
            authority,
            expected_generation,
            operation_issuance,
            settlement,
            media_command,
            wire_version,
            false,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn stage_recorded_authorization_mutation_with_generation_and_settlement_inner(
        &mut self,
        name: &str,
        input: HandlerInput,
        client_mutation_id: Option<String>,
        authority_descriptor: Option<AuthorityDescriptor>,
        acknowledged_client_mutation_ids: &[String],
        transport: &str,
        authority: PreparedAuthority,
        expected_generation: Option<&ArtifactGeneration>,
        operation_issuance: Option<crate::commit_envelope::OperationIssuanceV1>,
        settlement: MutationSettlement,
        media_invocation: Option<crate::manifest::MediaCommandInvocationV1>,
        wire_version: Option<&str>,
        allow_host_issuance: bool,
    ) -> SnapbackResult<(
        crate::storage::AuthorizationCommitPreflight,
        StagedRecordedMutation,
    )> {
        let negotiated_wire_version = match crate::wire_version::classify_open_offer(
            wire_version,
            crate::wire_version::SUPPORTED_WIRE_VERSIONS,
        ) {
            crate::wire_version::OpenWireVersionOffer::Absent => None,
            crate::wire_version::OpenWireVersionOffer::Known(token) => Some(token),
            crate::wire_version::OpenWireVersionOffer::Unknown => {
                return Err(SnapbackError::error(
                    "SNAPBACK_WIRE_VERSION_UNSUPPORTED",
                    "protocol",
                    "the offered mutation wireVersion is not supported by this server; \
                     supported versions: snapback.v1",
                ));
            }
        };
        if operation_issuance.is_some() && client_mutation_id.is_none() {
            return Err(SnapbackError::error(
                "SNAPBACK_OPERATION_IDENTITY_REQUIRES_CLIENT_MUTATION_ID",
                "protocol",
                "operationIssuance extends clientMutationId and cannot be sent alone",
            ));
        }
        if !allow_host_issuance
            && matches!(
                operation_issuance,
                Some(crate::commit_envelope::OperationIssuanceV1::HostIncarnation { .. })
            )
        {
            return Err(SnapbackError::error(
                "SNAPBACK_OPERATION_HOST_IDENTITY_FORBIDDEN",
                "protocol",
                "client mutation transport cannot mint the host operation namespace",
            ));
        }
        let artifact_generation = if operation_issuance.is_some() {
            expected_generation.cloned().or_else(|| {
                DeploymentIdentity::from_manifests(
                    authority.active_mode(),
                    self.db.schema(),
                    &self.functions,
                )
                .ok()
                .map(|identity| ArtifactGeneration {
                    schema_version: identity.schema_version,
                    app_id: identity.app_id,
                    schema_hash: identity.schema_hash,
                    bundle_hash: identity.bundle_hash,
                    inputs_hash: identity.inputs_hash,
                })
            }).ok_or_else(|| SnapbackError::error(
                "SNAPBACK_ARTIFACT_IDENTITY_MISMATCH",
                "runtime",
                "issuance-bearing mutation requires a derivable selected artifact generation",
            ))?.into()
        } else {
            None
        };
        let bind_operation = |mut identity: ClientMutationIdentity| {
            if let Some(generation) = artifact_generation.as_ref() {
                identity = identity.with_artifact_generation(generation);
            }
            if let Some(issuance) = operation_issuance.clone() {
                identity = identity.with_operation_issuance(issuance);
            }
            identity
        };
        let bind_request = |identity: ClientMutationIdentity| {
            let identity = if let Some(invocation) = media_invocation.as_ref() {
                identity.with_media_command(invocation)
            } else {
                identity
            };
            bind_operation(identity)
        };
        // @ref LLP 0043#settlement-consumption-and-acknowledgement-lifecycle-2026-08-01
        // A committed settlement is independent of the continued existence
        // of executable code. Re-attest the live authority and the exact
        // durable identity first; only a cache miss proceeds to active
        // function selection. This path never dispatches a handler.
        if let Some(id) = client_mutation_id.as_ref() {
            authority.validate_admission("client mutation settlement recovery")?;
            self.persist_and_validate_prepared_service_authority(&authority)?;
            let incarnation = self.db.ensure_authorization_stream_incarnation()?;
            let expected = descriptor_for_authority(&authority, incarnation.as_str())?;
            if authority.active_mode() == AuthMode::Sessions || authority_descriptor.is_some() {
                require_current_descriptor(authority_descriptor.as_ref(), &expected)?;
            }
            let mut canonical_input = input.clone();
            canonical_input.auth = authority.canonical_auth_input();
            let identity = bind_request(ClientMutationIdentity::for_authority_with_settlement(
                id.clone(),
                name.to_owned(),
                &canonical_input,
                expected.authority_instance_id,
                &settlement,
            ));
            if let Some(output) = self
                .db
                .settlement_read()
                .client_mutation_result(&identity)?
            {
                if !acknowledged_client_mutation_ids.is_empty() {
                    self.acknowledge_client_mutations_with_authority(
                        &authority,
                        acknowledged_client_mutation_ids,
                    )?;
                }
                let admission = authority.admission_lease().clone();
                let correlation = capped_correlation(input.correlation.clone());
                let sequence_allocations = output.settlement_sequence_allocations.clone();
                let commit = MutationCommit {
                    output,
                    changes: Vec::new(),
                    read_dependencies: Vec::new(),
                    write_dependencies: Vec::new(),
                    job_enqueues: Vec::new(),
                    job_changes: Vec::new(),
                    asset_changes: Vec::new(),
                    sequence_allocations,
                    authorization: None,
                    authority_transitions: Vec::new(),
                    network_egress: Default::default(),
                };
                let recorded = self.record_mutation_commit_after_publication_guard(
                    MutationReceiptPublication::new(
                        name,
                        transport,
                        correlation,
                        id.clone(),
                        &admission,
                    )
                    .with_settlement(settlement.clone()),
                    Ok(commit),
                );
                return Ok((
                    self.authorization_commit_preflight_for_changes(Vec::new()),
                    StagedRecordedMutation::Done(Box::new(recorded)),
                ));
            }
        }
        // @ref LLP 0081#dated-amendment-mutation-wire-artifact-identity-2026-08-10 —
        //   exact-settlement recovery stays first; a fresh blind write then
        //   proves the active schema generation before selection, ACKs, or
        //   handler effects can cross a successor-only retention floor.
        self.validate_blind_mutation_generation_at_migration_floor(
            &input,
            expected_generation,
            negotiated_wire_version,
        )?;
        let function = self.function(name)?.clone();
        let input = input;
        let media_command = prepare_media_command_invocation(
            &function,
            &input,
            media_invocation.clone(),
            client_mutation_id.as_deref(),
        )?;
        let settlement_time = admitted_settlement_time_policy(&function, &settlement);
        self.validate_expected_generation(&authority, expected_generation)?;
        let prepared = InvocationGate::prepare_function(authority.clone(), &function)?;
        // The live credential/grant is authorizing; the queued descriptor is
        // only a non-authorizing replay axis. Preserve the ordinary mutation
        // gate order so credential-generation drift cannot be disguised as a
        // descriptor mismatch.
        self.persist_and_validate_prepared_service_authority(prepared.authority())?;
        preflight_host_plan_authority_writes(&prepared, &function, self.db.schema())?;
        if client_mutation_id.is_some() {
            let incarnation = self.db.ensure_authorization_stream_incarnation()?;
            let expected = descriptor_for_authority(prepared.authority(), incarnation.as_str())?;
            if prepared.authority().active_mode() == AuthMode::Sessions
                || authority_descriptor.is_some()
            {
                require_current_descriptor(authority_descriptor.as_ref(), &expected)?;
            }
        }
        if !acknowledged_client_mutation_ids.is_empty() {
            self.acknowledge_client_mutations_with_authority(
                prepared.authority(),
                acknowledged_client_mutation_ids,
            )?;
        }

        let admission = prepared.admission_lease().clone();
        let correlation = capped_correlation(input.correlation.clone());
        let receipt_mutation_id = client_mutation_id
            .clone()
            .unwrap_or_else(|| crate::ids::mint_time_ordered(crate::ids::Kind::Mutation));
        let error_correlation = correlation.clone();
        let error_receipt_mutation_id = receipt_mutation_id.clone();
        let staged = (|| -> SnapbackResult<_> {
            let mut input = prepared.canonicalize_input(input);
            let identity = if let Some(id) = client_mutation_id {
                let incarnation = self.db.ensure_authorization_stream_incarnation()?;
                let expected =
                    descriptor_for_authority(prepared.authority(), incarnation.as_str())?;
                Some(bind_request(
                    ClientMutationIdentity::for_authority_with_settlement(
                        id,
                        name.to_owned(),
                        &input,
                        expected.authority_instance_id,
                        &settlement,
                    ),
                ))
            } else {
                None
            };
            if let Some(identity) = identity.as_ref()
                && let Some(output) = self.db.settlement_read().client_mutation_result(identity)?
            {
                crate::result_contract::validate_handler_result(&function, &output.result)?;
                let sequence_allocations = output.settlement_sequence_allocations.clone();
                let commit = MutationCommit {
                    output,
                    changes: Vec::new(),
                    read_dependencies: Vec::new(),
                    write_dependencies: Vec::new(),
                    job_enqueues: Vec::new(),
                    job_changes: Vec::new(),
                    asset_changes: Vec::new(),
                    sequence_allocations,
                    authorization: None,
                    authority_transitions: Vec::new(),
                    network_egress: Default::default(),
                };
                let recorded = self.record_mutation_commit_after_publication_guard(
                    MutationReceiptPublication::new(
                        name,
                        transport,
                        correlation.clone(),
                        receipt_mutation_id.clone(),
                        &admission,
                    )
                    .with_settlement(settlement.clone()),
                    Ok(commit),
                );
                return Ok((
                    self.authorization_commit_preflight_for_changes(Vec::new()),
                    StagedRecordedMutation::Done(Box::new(recorded)),
                ));
            }
            // @ref LLP 0131#runtime-ingress-validation — the staged HTTP
            // settlement lane keeps replay recovery first, then validates the
            // served argument contract before any handler byte or plan step.
            crate::args_contract::validate_function_args(&function, &input.args)?;
            let telemetry_correlation = telemetry_correlation(&input.correlation);
            let mut observation = Some(self.telemetry.start_classified_span(
                crate::telemetry_contract::OperationClassIdV1::FUNCTION_MUTATION,
                name,
                telemetry_correlation.as_deref(),
                prepared.telemetry_caller_details(),
            ));
            let telemetry = self.telemetry.clone();
            let mut execution = crate::runtime::with_runtime_log_telemetry(
                telemetry,
                telemetry_correlation,
                || {
                    (|| -> SnapbackResult<_> {
                        let client_mutation_digest = identity
                            .as_ref()
                            .map(ClientMutationIdentity::activity_digest);
                        if settlement.lane == SettlementLane::ReDerive {
                            // The client ledger remains part of immutable request
                            // identity, but it cannot answer the authoritative run. The
                            // host-plan preview below records one server-owned clock/id
                            // sample and the commit replays only that internal sample.
                            // @ref LLP 0133#re-derivation-semantics-lane-l — lane L
                            //   discards client ctx answers before authoritative execution.
                            input.ctx_ledger = None;
                        }
                        input.auth = input.auth.with_client_mutation_settlement(
                            identity.as_ref().map(|identity| identity.id.as_str()),
                            client_mutation_digest.as_deref(),
                        );
                        let epoch_scopes = evaluate_permission_epoch_scopes(&function, &input)?;
                        let (preflight, execution) = match &function.runtime {
                            FunctionRuntime::HostPlan(HandlerPlan::Mutation(plan))
                            | FunctionRuntime::HostPlan(HandlerPlan::WriteWithActivity(
                                crate::manifest::WriteWithActivityPlan { mutation: plan, .. },
                            )) => {
                                let preview = if let Some(media_command) = media_command.as_ref() {
                                    self.db
                                        .mutation_writes()
                                        .dry_run_media_command_mutation_with_settlement_time(
                                        plan,
                                        &input,
                                        identity.as_ref().expect(
                                            "validated media command carries a mutation identity",
                                        ),
                                        media_command,
                                        settlement_time.as_ref(),
                                    )?
                                } else {
                                    self.db
                                        .mutation_writes()
                                        .dry_run_mutation_with_settlement_time(
                                            plan,
                                            &input,
                                            settlement_time.as_ref(),
                                        )?
                                };
                                crate::result_contract::validate_handler_result(
                                    &function,
                                    &preview.commit.output.result,
                                )?;
                                input.ctx_ledger = Some(CtxAnswerLedger {
                                    version: ctx_ledger_version(),
                                    ids: preview.generated_ids,
                                    now: preview.now_ms,
                                    auth_fingerprint: None,
                                });
                                (
                                    self.authorization_commit_preflight_for_changes(
                                        preview.commit.changes,
                                    ),
                                    StagedMutationExecution::HostPlan(plan.clone()),
                                )
                            }
                            FunctionRuntime::IbexModule(module) => {
                                let mut executed = crate::runtime::execute_ibex_mutation_prepared(
                                    module,
                                    input.clone(),
                                    &prepared,
                                    DbRead::Live(&self.db),
                                    Some(&self.warm_vms),
                                    None,
                                )?;
                                let expected_media_projection_binding =
                                    expected_media_projection_binding(
                                        &prepared,
                                        &input,
                                        &executed,
                                        identity.as_ref(),
                                    )?;
                                let membership_plans =
                                    executed.authorize_membership_commands(&mut self.db)?;
                                // Callee admission for buffered enqueues happens before
                                // any commit work: an inadmissible callee fails the whole
                                // mutation (rollback schedules nothing).
                                let (job_enqueues, job_producer) = admit_job_enqueues(
                                    &self.functions,
                                    executed.job_enqueues,
                                    &receipt_mutation_id,
                                    name,
                                    input.auth.user_id.clone(),
                                )?;
                                let payload = BufferedCommitPayload {
                                    writes: executed.writes,
                                    sequence_allocations: executed.sequence_allocations,
                                    membership_plans,
                                    read_dependencies: executed.reads,
                                    result: executed.result,
                                    ctx_ledger: executed.ctx_ledger,
                                    job_enqueues,
                                    job_producer,
                                    asset_admissions: executed.asset_admissions,
                                    asset_grant_ops: executed.asset_grant_ops,
                                    media_projection_proof: executed.media_projection_proof,
                                    expected_media_projection_binding,
                                };
                                crate::result_contract::validate_handler_result(
                                    &function,
                                    &payload.result,
                                )?;
                                let preview = if let Some(media_command) = media_command.as_ref() {
                                    self.db
                                        .mutation_writes()
                                        .dry_run_media_command_buffered_payload(
                                        &input,
                                        &payload,
                                        identity.as_ref().expect(
                                            "validated media command carries a mutation identity",
                                        ),
                                        media_command,
                                    )?
                                } else {
                                    self.db
                                        .mutation_writes()
                                        .dry_run_buffered_writes_with_jobs(
                                            &input,
                                            payload.writes.clone(),
                                            payload.sequence_allocations.clone(),
                                            payload.membership_plans.clone(),
                                            payload.read_dependencies.clone(),
                                            payload.result.clone(),
                                            payload.ctx_ledger.clone(),
                                            payload.job_enqueues.clone(),
                                            payload.job_producer.clone(),
                                            payload.asset_admissions.clone(),
                                            payload.asset_grant_ops.clone(),
                                            payload.media_projection_proof.as_ref(),
                                            payload.expected_media_projection_binding.as_ref(),
                                        )?
                                };
                                (
                                    self.authorization_commit_preflight_for_changes(
                                        preview.changes,
                                    ),
                                    StagedMutationExecution::Buffered(Box::new(payload)),
                                )
                            }
                            _ => {
                                return Err(SnapbackError::error(
                                    "SNAPBACK_FUNCTION_KIND_MISMATCH",
                                    "runtime",
                                    format!("{name} is not a mutation"),
                                ));
                            }
                        };
                        Ok((
                            preflight,
                            StagedRecordedMutation::Ready(Box::new(StagedRecordedMutationCommit {
                                name: name.to_owned(),
                                transport: transport.to_owned(),
                                correlation,
                                receipt_mutation_id,
                                input,
                                settlement: settlement.clone(),
                                prepared,
                                identity,
                                media_command,
                                settlement_time,
                                epoch_scopes,
                                execution,
                                // @ref LLP 0154#d2--the-observation-span-classification-registry-and-phase-1-kinds
                                // Staging is admission, not a successful terminal.
                                // The authoritative guarded commit owns completion.
                                observation: observation
                                    .take()
                                    .expect("fresh staged mutation observation"),
                            })),
                        ))
                    })()
                },
            );
            if let Some(observation) = observation {
                finish_function_observation(observation, &mut execution);
            }
            execution
        })();

        match staged {
            Ok(staged) => Ok(staged),
            Err(error) => {
                let recorded = self.record_mutation_commit_after_publication_guard(
                    MutationReceiptPublication::new(
                        name,
                        transport,
                        error_correlation,
                        error_receipt_mutation_id,
                        &admission,
                    )
                    .with_settlement(settlement),
                    Err(error),
                );
                Ok((
                    self.authorization_commit_preflight_for_changes(Vec::new()),
                    StagedRecordedMutation::Done(Box::new(recorded)),
                ))
            }
        }
    }

    pub fn commit_staged_recorded_authorization_mutation(
        &mut self,
        staged: StagedRecordedMutation,
    ) -> SnapbackResult<(SnapbackResult<MutationOutput>, Receipt)> {
        let (result, receipt, _network_egress) =
            self.commit_staged_recorded_authorization_mutation_with_network_egress(staged)?;
        Ok((result, receipt))
    }

    /// Commit one staged mutation while retaining the dependency capture that
    /// the ordinary `(result, receipt)` compatibility carrier historically
    /// discarded.
    pub fn commit_staged_recorded_authorization_mutation_with_dependencies(
        &mut self,
        staged: StagedRecordedMutation,
    ) -> SnapbackResult<(
        SnapbackResult<MutationOutput>,
        Receipt,
        MutationDependencyCapture,
    )> {
        let (result, receipt, _network_egress, capture) = self
            .commit_staged_recorded_authorization_mutation_with_network_egress_and_dependencies(
                staged,
            )?;
        Ok((result, receipt, capture))
    }

    /// HTTP's prepared-egress carrier sibling. Keeping the carrier beside the
    /// server-only staged result avoids adding implementation metadata to the
    /// schema-generated Receipt wire type.
    ///
    /// @ref LLP 0167#observation-semantics--what-a-delay-means — the response
    ///   leaves Local with bytes/facts plus one immutable deadline basis.
    pub(crate) fn commit_staged_recorded_authorization_mutation_with_network_egress(
        &mut self,
        staged: StagedRecordedMutation,
    ) -> SnapbackResult<(
        SnapbackResult<MutationOutput>,
        Receipt,
        crate::network_profile::MutationEgressBasis,
    )> {
        let (result, receipt, network_egress, _capture) = self
            .commit_staged_recorded_authorization_mutation_with_network_egress_and_dependencies(
                staged,
            )?;
        Ok((result, receipt, network_egress))
    }

    pub fn commit_staged_recorded_authorization_mutation_with_network_egress_and_dependencies(
        &mut self,
        staged: StagedRecordedMutation,
    ) -> SnapbackResult<(
        SnapbackResult<MutationOutput>,
        Receipt,
        crate::network_profile::MutationEgressBasis,
        MutationDependencyCapture,
    )> {
        let staged = match staged {
            StagedRecordedMutation::Done(recorded) => {
                let (result, receipt) = *recorded;
                return Ok((
                    result,
                    receipt,
                    crate::network_profile::MutationEgressBasis::ResultReady,
                    MutationDependencyCapture::incomplete(),
                ));
            }
            StagedRecordedMutation::Ready(staged) => staged,
        };
        // A stale stamp from an earlier non-serving commit must never pair
        // with this invocation's settlement: only a commit-ack stamped by
        // THIS turn's `finish_mutation_commit` may survive to the taker.
        self.last_commit_ack_at = None;
        let StagedRecordedMutationCommit {
            name,
            transport,
            correlation,
            receipt_mutation_id,
            input,
            settlement,
            prepared,
            identity,
            media_command,
            settlement_time,
            epoch_scopes,
            execution,
            observation,
        } = *staged;
        let trace_identity = crate::spike_trace::MutationTraceIdentity::capture(
            &input,
            identity.as_ref(),
            Some(&receipt_mutation_id),
        );
        let admission = prepared.admission_lease().clone();
        if let Err(mut error) = self.ensure_permission_epoch_capacity(&epoch_scopes) {
            observation.finish_error(Some(500), &mut error, None);
            return Err(error);
        }
        let result = match execution {
            StagedMutationExecution::HostPlan(plan) if media_command.is_some() => self
                .db
                .mutation_writes()
                .execute_media_command_mutation_idempotent_guarded_with_settlement_time(
                    &plan,
                    &input,
                    identity
                        .as_ref()
                        .expect("validated media command carries a mutation identity"),
                    media_command.as_ref().expect("matched media command"),
                    settlement_time.as_ref(),
                    || prepared.effect_guard("media command mutation transaction"),
                ),
            StagedMutationExecution::HostPlan(plan) => match identity.as_ref() {
                Some(identity)
                    if matches!(
                        identity.operation_issuance.as_ref(),
                        Some(crate::commit_envelope::OperationIssuanceV1::HostIncarnation { .. })
                    ) =>
                {
                    self.db
                        .mutation_writes()
                        .execute_host_mutation_guarded_with_settlement_time(
                            &plan,
                            &input,
                            Some(identity),
                            settlement_time.as_ref(),
                            || Ok(()),
                            || prepared.effect_guard("host child mutation transaction"),
                        )
                }
                Some(identity) => self
                    .db
                    .mutation_writes()
                    .execute_mutation_idempotent_guarded_with_settlement_time(
                        &plan,
                        &input,
                        identity,
                        settlement_time.as_ref(),
                        || prepared.effect_guard("idempotent mutation transaction"),
                    ),
                None => self
                    .db
                    .mutation_writes()
                    .execute_mutation_guarded_with_settlement_time(
                        &plan,
                        &input,
                        settlement_time.as_ref(),
                        || Ok(()),
                        || prepared.effect_guard("mutation transaction"),
                    ),
            },
            StagedMutationExecution::Buffered(payload) if media_command.is_some() => self
                .db
                .mutation_writes()
                .commit_media_command_buffered_writes_idempotent_guarded(
                    &input,
                    *payload,
                    identity.as_ref(),
                    media_command.as_ref().expect("matched media command"),
                    || Ok(()),
                    || prepared.effect_guard("media command ibex transaction"),
                ),
            StagedMutationExecution::Buffered(payload) => {
                let payload = *payload;
                if identity.as_ref().is_some_and(|identity| {
                    matches!(
                        identity.operation_issuance.as_ref(),
                        Some(crate::commit_envelope::OperationIssuanceV1::HostIncarnation { .. })
                    )
                }) {
                    self.db
                        .mutation_writes()
                        .commit_buffered_host_writes_guarded(
                            &input,
                            payload,
                            identity.as_ref(),
                            || Ok(()),
                            || prepared.effect_guard("host child ibex mutation transaction"),
                        )
                } else {
                    self.db
                        .mutation_writes()
                        .commit_buffered_writes_idempotent_guarded(
                            &input,
                            payload,
                            identity.as_ref(),
                            || Ok(()),
                            || prepared.effect_guard("ibex mutation transaction"),
                        )
                }
            }
        }
        .and_then(|commit| {
            self.finish_mutation_commit(&name, &trace_identity, epoch_scopes, commit, &admission)
        });
        let network_egress = result
            .as_ref()
            .map(|commit| commit.network_egress.clone())
            .unwrap_or(crate::network_profile::MutationEgressBasis::ResultReady);
        let capture = result
            .as_ref()
            .map(MutationDependencyCapture::from_commit)
            .unwrap_or_else(|_| MutationDependencyCapture::incomplete());
        let mut recorded = self.record_mutation_commit_after_publication_guard(
            MutationReceiptPublication::new(
                &name,
                &transport,
                correlation,
                receipt_mutation_id,
                &admission,
            )
            .with_settlement(settlement),
            result,
        );
        // @ref LLP 0133#re-derivation-semantics-lane-l — only the final
        // guarded, recorded settlement is authoritative; preview is evidence.
        finish_function_observation(observation, &mut recorded.0);
        Ok((recorded.0, recorded.1, network_egress, capture))
    }

    // Receipt recording deliberately keeps the mutation identity, settlement
    // policy, durable outcome, and retention decision visible at this fan-out
    // boundary; grouping them would obscure which values may be redacted.
    #[allow(clippy::too_many_arguments)]
    fn record_mutation_commit(
        &mut self,
        name: &str,
        transport: &str,
        correlation: Option<Value>,
        receipt_mutation_id: String,
        settlement: &MutationSettlement,
        result: SnapbackResult<MutationCommit>,
        retain: bool,
    ) -> (SnapbackResult<MutationOutput>, Receipt) {
        // @ref LLP 0240#d3-generate-the-ordinary-roster-and-role-surface
        // — only a codegen-stamped generated mutation may publish the
        // post-commit authority-transition side channel. Matching names and
        // profile dependencies are deliberately insufficient.
        let expose_authority_transitions = self.functions.function(name).is_some_and(|function| {
            function.kind == FunctionKind::Mutation
                && function
                    .generated_authority_operation
                    .as_ref()
                    .is_some_and(|identity| identity.operation.is_mutation())
        });
        // affectedTables from DECLARED writes; a function that declares none
        // yields an EXPLICITLY-unknown receipt (`affectedTables: null`),
        // never a silently-empty list (LLP 0034 §3.2 / Exact 0263 honesty).
        let affected_tables: Option<Vec<String>> = self
            .functions
            .function(name)
            .map(|function| function.write_set_summary.tables.clone())
            .filter(|tables| !tables.is_empty());
        let (
            outcome,
            rollback_reason,
            snapshot_version,
            claim_ledger,
            id_map,
            enqueues,
            sequence_allocations,
            result,
        ) = match result {
            Ok(mut commit) => {
                if !expose_authority_transitions {
                    commit.output.authority_transitions.clear();
                }
                (
                    MutationReceiptOutcome::Confirmed,
                    None,
                    Some(commit.output.version),
                    settlement_claim_ledger(
                        settlement,
                        commit.output.ctx_ledger.as_ref(),
                        &commit.output.settlement_mint_observations,
                        commit.output.settlement_time_observation.as_ref(),
                    ),
                    settlement_id_map(settlement, &commit.output.settlement_mint_observations),
                    commit.job_enqueues.clone(),
                    commit.sequence_allocations.clone(),
                    Ok(commit),
                )
            }
            Err(error) => match self.db.versions_read().current_version() {
                Ok(version) => (
                    MutationReceiptOutcome::Rejected,
                    // The diagnostic CODE only — messages may embed argument
                    // values (§3.3 privacy).
                    Some(error.diagnostic.code.clone()),
                    Some(version),
                    settlement_claim_ledger(settlement, None, &[], None),
                    settlement_id_map(settlement, &[]),
                    Vec::new(),
                    Vec::new(),
                    Err(error),
                ),
                Err(version_error) => (
                    MutationReceiptOutcome::Rejected,
                    Some(version_error.diagnostic.code.clone()),
                    None,
                    settlement_claim_ledger(settlement, None, &[], None),
                    settlement_id_map(settlement, &[]),
                    Vec::new(),
                    Vec::new(),
                    Err(version_error),
                ),
            },
        };
        let receipt = Receipt::Mutation {
            mutation_id: receipt_mutation_id,
            mutation: name.to_owned(),
            outcome,
            // @ref LLP 0133#the-two-settlement-lanes — the capture-time lane
            //   selects policy per mutation and is echoed as observed fact.
            settlement_lane: settlement.lane,
            claim_ledger: Some(claim_ledger),
            id_map,
            rollback_reason,
            affected_tables,
            snapshot_version,
            enqueues,
            sequence_allocations,
            transport: transport.to_owned(),
            correlation: correlation.unwrap_or(Value::Null),
            received_at_ms: now_millis(),
        };
        if retain {
            // @ref LLP 0133#receipts — the global receipt ring is a fan-out
            //   boundary and must never retain submitting-authority claims.
            self.receipts
                .push_global(receipt.clone().into_fanout_value());
        }
        (result.map(|commit| commit.output), receipt)
    }

    /// Publish a mutation receipt without allowing a post-COMMIT admission
    /// failure to rewrite durable truth. A failed publication guard suppresses
    /// retention and caller-visible output, but an existing commit still
    /// produces a Confirmed receipt at its exact version.
    fn record_mutation_commit_after_publication_guard(
        &mut self,
        publication: MutationReceiptPublication<'_>,
        result: SnapbackResult<MutationCommit>,
    ) -> (SnapbackResult<MutationOutput>, Receipt) {
        let MutationReceiptPublication {
            name,
            transport,
            correlation,
            mutation_id,
            settlement,
            admission,
            effect,
        } = publication;
        match admission.effect_guard(effect) {
            Ok(_publication) => self.record_mutation_commit(
                name,
                transport,
                correlation,
                mutation_id,
                &settlement,
                result,
                true,
            ),
            Err(publication_error) => {
                self.record_attached_diagnostics(vec![publication_error.diagnostic.clone()]);
                match result {
                    Ok(commit) => {
                        let (_, receipt) = self.record_mutation_commit(
                            name,
                            transport,
                            correlation,
                            mutation_id,
                            &settlement,
                            Ok(commit),
                            false,
                        );
                        (Err(publication_error), receipt)
                    }
                    Err(_) => self.record_mutation_commit(
                        name,
                        transport,
                        correlation,
                        mutation_id,
                        &settlement,
                        Err(publication_error),
                        false,
                    ),
                }
            }
        }
    }

    /// Host-plan mutation invoked from a detached action. Plan/data iteration
    /// remains outside the action commit gate and polls the shared lifecycle;
    /// `before_commit` returns the guard held only across SQLite COMMIT.
    pub fn invoke_host_plan_mutation_guarded<G, Check, BeforeCommit>(
        &mut self,
        name: &str,
        input: HandlerInput,
        prepared: PreparedInvocation,
        identity: Option<ClientMutationIdentity>,
        check_live: Check,
        before_commit: BeforeCommit,
    ) -> SnapbackResult<MutationOutput>
    where
        Check: Fn() -> SnapbackResult<()>,
        BeforeCommit: FnOnce() -> SnapbackResult<G>,
    {
        prepared.validate_admission("nested host-plan mutation")?;
        let admission = prepared.admission_lease().clone();
        let input = prepared.canonicalize_input(input);
        let correlation = capped_correlation(input.correlation.clone());
        let receipt_mutation_id = crate::ids::mint_time_ordered(crate::ids::Kind::Mutation);
        let result = self.invoke_host_plan_mutation_commit_guarded(
            name,
            input,
            &prepared,
            identity.as_ref(),
            check_live,
            before_commit,
        );
        self.record_mutation_commit_after_publication_guard(
            MutationReceiptPublication::new(
                name,
                "local",
                correlation,
                receipt_mutation_id,
                &admission,
            )
            .with_effect("nested mutation receipt publication"),
            result,
        )
        .0
    }

    /// Receipt retention surface (LLP 0034 §3 / ENG-22478): the bounded rings,
    /// filtered to one connection when requested. Dev/debug read — served by
    /// the admin API (LLP 0031 SystemApi class).
    pub fn receipts_snapshot(&self, connection_id: Option<&str>) -> Value {
        self.receipts.snapshot(connection_id)
    }

    fn invoke_mutation_commit_with_id_and_authority(
        &mut self,
        name: &str,
        input: HandlerInput,
        client_mutation_id: Option<String>,
        authority_descriptor: Option<AuthorityDescriptor>,
        // The caller's pre-minted receipt mutation id, when a receipt will be
        // emitted for this commit — job rows stamp it as their producer so
        // the two association halves name the same identity (0127 decision 7).
        receipt_mutation_id: Option<&str>,
        authority: PreparedAuthority,
    ) -> SnapbackResult<MutationCommit> {
        self.invoke_mutation_commit_with_id_authority_and_branch(
            name,
            input,
            client_mutation_id,
            authority_descriptor,
            receipt_mutation_id,
            authority,
            None,
            Self::ensure_permission_epoch_capacity,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn invoke_mutation_commit_with_id_authority_and_branch(
        &mut self,
        name: &str,
        input: HandlerInput,
        client_mutation_id: Option<String>,
        authority_descriptor: Option<AuthorityDescriptor>,
        receipt_mutation_id: Option<&str>,
        authority: PreparedAuthority,
        branch_operation: Option<&crate::fork_promotion::BranchMutationCommitV1>,
        permission_epoch_preflight: fn(&LocalSnapback, &BTreeSet<String>) -> SnapbackResult<()>,
    ) -> SnapbackResult<MutationCommit> {
        // @ref LLP 0043#settlement-consumption-and-acknowledgement-lifecycle-2026-08-01
        // Recovery of an already-committed identity is non-executing and does
        // not depend on the old function remaining in the active bundle.
        if let Some(id) = client_mutation_id.as_ref() {
            authority.validate_admission("client mutation settlement recovery")?;
            self.persist_and_validate_prepared_service_authority(&authority)?;
            let incarnation = self.db.ensure_authorization_stream_incarnation()?;
            let expected = descriptor_for_authority(&authority, incarnation.as_str())?;
            if authority.active_mode() == AuthMode::Sessions || authority_descriptor.is_some() {
                require_current_descriptor(authority_descriptor.as_ref(), &expected)?;
            }
            let mut canonical_input = input.clone();
            canonical_input.auth = authority.canonical_auth_input();
            let identity = ClientMutationIdentity::for_authority(
                id.clone(),
                name.to_owned(),
                &canonical_input,
                expected.authority_instance_id,
            );
            if let Some(output) = self
                .db
                .settlement_read()
                .client_mutation_result(&identity)?
            {
                let sequence_allocations = output.settlement_sequence_allocations.clone();
                return Ok(MutationCommit {
                    output,
                    changes: Vec::new(),
                    read_dependencies: Vec::new(),
                    write_dependencies: Vec::new(),
                    job_enqueues: Vec::new(),
                    job_changes: Vec::new(),
                    asset_changes: Vec::new(),
                    sequence_allocations,
                    authorization: None,
                    authority_transitions: Vec::new(),
                    network_egress: Default::default(),
                });
            }
        }
        // @ref LLP 0058#gate-algorithm — fresh execution still performs
        // function lookup and requirement enforcement before every effect.
        let function = self.function(name)?.clone();
        let prepared = InvocationGate::prepare_function(authority, &function)?;
        self.persist_and_validate_prepared_service_authority(prepared.authority())?;
        preflight_host_plan_authority_writes(&prepared, &function, self.db.schema())?;
        let admission = prepared.admission_lease().clone();
        let mut input = prepared.canonicalize_input(input);
        let identity = if let Some(id) = client_mutation_id {
            let incarnation = self.db.ensure_authorization_stream_incarnation()?;
            let expected = descriptor_for_authority(prepared.authority(), incarnation.as_str())?;
            if prepared.authority().active_mode() == AuthMode::Sessions
                || authority_descriptor.is_some()
            {
                require_current_descriptor(authority_descriptor.as_ref(), &expected)?;
            }
            Some(ClientMutationIdentity::for_authority(
                id,
                name.to_owned(),
                &input,
                expected.authority_instance_id,
            ))
        } else {
            None
        };
        if let Some(identity) = identity.as_ref()
            && let Some(output) = self.db.settlement_read().client_mutation_result(identity)?
        {
            crate::result_contract::validate_handler_result(&function, &output.result)?;
            let sequence_allocations = output.settlement_sequence_allocations.clone();
            return Ok(MutationCommit {
                output,
                changes: Vec::new(),
                read_dependencies: Vec::new(),
                write_dependencies: Vec::new(),
                job_enqueues: Vec::new(),
                job_changes: Vec::new(),
                asset_changes: Vec::new(),
                sequence_allocations,
                authorization: None,
                authority_transitions: Vec::new(),
                network_egress: Default::default(),
            });
        }
        // @ref LLP 0131#runtime-ingress-validation — fresh mutation admission
        // validates the declared argument contract after the replay-settlement
        // lookup (exact replay releases the original bytes without re-running
        // ingress validation — LLP 0108's replay identity posture) and before
        // any plan step, handler dispatch, or buffered write.
        crate::args_contract::validate_function_args(&function, &input.args)?;
        let client_mutation_digest = identity
            .as_ref()
            .map(ClientMutationIdentity::activity_digest);
        input.auth = input.auth.with_client_mutation_settlement(
            identity.as_ref().map(|identity| identity.id.as_str()),
            client_mutation_digest.as_deref(),
        );
        let trace_identity =
            crate::spike_trace::MutationTraceIdentity::capture(&input, identity.as_ref(), None);
        // Legacy function-declared permission-epoch scopes are evaluated
        // BEFORE the mutation executes. This compatibility resync map is not
        // LLP 0053's durable global AuthorizationVersion, which advances in
        // the storage transaction hook.
        // (ENG-23329): scope evaluation can fail (missing auth user, missing
        // arg, empty scope), and an error raised after `tx.commit()` would
        // report a durably-committed mutation as rejected and skip the live
        // fan-out entirely. Failing fast here means no write ever happens for
        // a mutation whose declared epoch bumps cannot be resolved, and the
        // post-commit path below is infallible by construction.
        let epoch_scopes = evaluate_permission_epoch_scopes(&function, &input)?;
        permission_epoch_preflight(self, &epoch_scopes)?;
        let correlation = telemetry_correlation(&input.correlation);
        let span = self.telemetry.start_classified_span(
            crate::telemetry_contract::OperationClassIdV1::FUNCTION_MUTATION,
            name,
            correlation.as_deref(),
            prepared.telemetry_caller_details(),
        );
        let mut result = (|| {
            let commit = match &function.runtime {
                FunctionRuntime::HostPlan(HandlerPlan::Mutation(plan))
                | FunctionRuntime::HostPlan(HandlerPlan::WriteWithActivity(
                    crate::manifest::WriteWithActivityPlan { mutation: plan, .. },
                )) => {
                    // Validate the exact dry-run result while all writes remain
                    // provisional. Reuse its ctx ledger so generated ids/time are
                    // identical when the guarded transaction executes.
                    let preview = self.db.mutation_writes().dry_run_mutation(plan, &input)?;
                    crate::result_contract::validate_handler_result(
                        &function,
                        &preview.commit.output.result,
                    )?;
                    input.ctx_ledger = Some(CtxAnswerLedger {
                        version: ctx_ledger_version(),
                        ids: preview.generated_ids,
                        now: preview.now_ms,
                        auth_fingerprint: None,
                    });
                    match (branch_operation, identity.as_ref()) {
                        (Some(branch_operation), None) => {
                            self.db.branch_ops().execute_branch_mutation_guarded(
                                plan,
                                &input,
                                branch_operation,
                                || prepared.effect_guard("branch mutation transaction"),
                            )?
                        }
                        (Some(_), Some(_)) => {
                            return Err(SnapbackError::error(
                                "SNAPBACK_BRANCH_OPERATION_INVALID",
                                "storage",
                                "branch mutation carrier cannot compose with a second client identity",
                            ));
                        }
                        (None, Some(identity)) => self
                            .db
                            .mutation_writes()
                            .execute_mutation_idempotent_guarded(plan, &input, identity, || {
                                prepared.effect_guard("idempotent mutation transaction")
                            })?,
                        (None, None) => self.db.mutation_writes().execute_mutation_guarded(
                            plan,
                            &input,
                            || Ok(()),
                            || prepared.effect_guard("mutation transaction"),
                        )?,
                    }
                }
                FunctionRuntime::IbexModule(module) => {
                    let mut executed = crate::runtime::with_runtime_log_telemetry(
                        self.telemetry.clone(),
                        correlation.clone(),
                        || {
                            crate::runtime::execute_ibex_mutation_prepared(
                                module,
                                input.clone(),
                                &prepared,
                                DbRead::Live(&self.db),
                                Some(&self.warm_vms),
                                None,
                            )
                        },
                    )?;
                    let expected_media_projection_binding = expected_media_projection_binding(
                        &prepared,
                        &input,
                        &executed,
                        identity.as_ref(),
                    )?;
                    crate::result_contract::validate_handler_result(&function, &executed.result)?;
                    let membership_plans = executed.authorize_membership_commands(&mut self.db)?;
                    let producer_mutation_id = receipt_mutation_id
                        .map(ToOwned::to_owned)
                        .or_else(|| identity.as_ref().map(|identity| identity.id.clone()))
                        .unwrap_or_else(|| {
                            crate::ids::mint_time_ordered(crate::ids::Kind::Mutation)
                        });
                    let (job_enqueues, job_producer) = admit_job_enqueues(
                        &self.functions,
                        executed.job_enqueues,
                        &producer_mutation_id,
                        name,
                        input.auth.user_id.clone(),
                    )?;
                    let payload = BufferedCommitPayload {
                        writes: executed.writes,
                        sequence_allocations: executed.sequence_allocations,
                        membership_plans,
                        read_dependencies: executed.reads,
                        result: executed.result,
                        ctx_ledger: executed.ctx_ledger,
                        job_enqueues,
                        job_producer,
                        asset_admissions: executed.asset_admissions,
                        asset_grant_ops: executed.asset_grant_ops,
                        media_projection_proof: executed.media_projection_proof,
                        expected_media_projection_binding,
                    };
                    match (branch_operation, identity.as_ref()) {
                        (Some(branch_operation), None) => {
                            self.db.branch_ops().commit_branch_buffered_writes_guarded(
                                &input,
                                payload,
                                branch_operation,
                                || prepared.effect_guard("branch ibex mutation transaction"),
                            )?
                        }
                        (Some(_), Some(_)) => {
                            return Err(SnapbackError::error(
                                "SNAPBACK_BRANCH_OPERATION_INVALID",
                                "storage",
                                "branch mutation carrier cannot compose with a second client identity",
                            ));
                        }
                        (None, identity) => self
                            .db
                            .mutation_writes()
                            .commit_buffered_writes_idempotent_guarded(
                                &input,
                                payload,
                                identity,
                                || Ok(()),
                                || prepared.effect_guard("ibex mutation transaction"),
                            )?,
                    }
                }
                _ => {
                    return Err(SnapbackError::error(
                        "SNAPBACK_FUNCTION_KIND_MISMATCH",
                        "runtime",
                        format!("{name} is not a mutation"),
                    ));
                }
            };

            self.finish_mutation_commit(name, &trace_identity, epoch_scopes, commit, &admission)
        })();
        finish_function_observation(span, &mut result);
        result
    }

    fn invoke_host_plan_mutation_commit_guarded<G, Check, BeforeCommit>(
        &mut self,
        name: &str,
        input: HandlerInput,
        prepared: &PreparedInvocation,
        identity: Option<&ClientMutationIdentity>,
        check_live: Check,
        before_commit: BeforeCommit,
    ) -> SnapbackResult<MutationCommit>
    where
        Check: Fn() -> SnapbackResult<()>,
        BeforeCommit: FnOnce() -> SnapbackResult<G>,
    {
        prepared.validate_admission("nested host-plan mutation execution")?;
        self.persist_and_validate_prepared_service_authority(prepared.authority())?;
        check_live()?;
        let function = self.function(name)?.clone();
        if function.kind != FunctionKind::Mutation {
            return Err(SnapbackError::error(
                "SNAPBACK_FUNCTION_KIND_MISMATCH",
                "runtime",
                format!("{name} is not a mutation"),
            ));
        }
        preflight_host_plan_authority_writes(prepared, &function, self.db.schema())?;
        // @ref LLP 0131#runtime-ingress-validation — nested host-plan
        // mutations (runMutation from actions) are fresh executions and see
        // the same seam as every other evaluator lane.
        crate::args_contract::validate_function_args(&function, &input.args)?;
        let epoch_scopes = evaluate_permission_epoch_scopes(&function, &input)?;
        self.ensure_permission_epoch_capacity(&epoch_scopes)?;
        let plan = match &function.runtime {
            FunctionRuntime::HostPlan(HandlerPlan::Mutation(plan)) => plan,
            FunctionRuntime::HostPlan(HandlerPlan::WriteWithActivity(plan)) => &plan.mutation,
            _ => {
                return Err(SnapbackError::error(
                    "SNAPBACK_FUNCTION_KIND_MISMATCH",
                    "runtime",
                    format!("{name} is not a host-plan mutation"),
                ));
            }
        };
        let correlation = telemetry_correlation(&input.correlation);
        let trace_identity =
            crate::spike_trace::MutationTraceIdentity::capture(&input, identity, None);
        let span = self.telemetry.start_classified_span(
            crate::telemetry_contract::OperationClassIdV1::FUNCTION_MUTATION,
            name,
            correlation.as_deref(),
            prepared.telemetry_caller_details(),
        );
        let mut result =
            crate::runtime::with_runtime_log_telemetry(self.telemetry.clone(), correlation, || {
                let commit = self.db.mutation_writes().execute_host_mutation_guarded(
                    plan,
                    &input,
                    identity,
                    &check_live,
                    || {
                        let admission_guard = prepared
                            .admission_lease()
                            .effect_guard("nested host-plan transaction")?;
                        let caller_guard = before_commit()?;
                        Ok((admission_guard, caller_guard))
                    },
                )?;
                self.finish_mutation_commit(
                    name,
                    &trace_identity,
                    epoch_scopes,
                    commit,
                    prepared.admission_lease(),
                )
            });
        finish_function_observation(span, &mut result);
        result
    }

    /// Take the commit-ack instant stamped by the mutation commit that just
    /// finished under this same Local critical section. §2.1's settlement
    /// milestone is measured against this instant at the HTTP boundary.
    pub fn take_last_commit_ack_at(&mut self) -> Option<Instant> {
        self.last_commit_ack_at.take()
    }

    /// Shared handle to the commit-ack→settlement counters; the serving
    /// mutation path records into it after the response leaves the Local lock.
    pub fn live_settlement_stats_cell(&self) -> Arc<std::sync::Mutex<LiveSettlementStats>> {
        Arc::clone(&self.live_settlement_stats)
    }

    fn finish_mutation_commit(
        &mut self,
        mutation: &str,
        trace_identity: &crate::spike_trace::MutationTraceIdentity,
        epoch_scopes: BTreeSet<String>,
        mut commit: MutationCommit,
        admission: &AdmissionLease,
    ) -> SnapbackResult<MutationCommit> {
        // Stamp immediately after the storage call returns from COMMIT. A
        // successful no-op/replay has no observable state commit and keeps
        // the result-readiness basis.
        //
        // @ref LLP 0167#observation-semantics--what-a-delay-means — ack and
        //   deltas from a real commit share one commit-relative jitter sample.
        let commit_durable_ms = crate::spike_trace::timestamp_ms();
        // @ref LLP 0200#21-settlement-is-decoupled-from-subscriber-work —
        // commit-ack is milestone 1; the serving mutation path takes this
        // stamp inside the same Local turn to measure the settlement gap.
        self.last_commit_ack_at = Some(Instant::now());
        let has_observable_effect = !commit.changes.is_empty()
            || !commit.job_changes.is_empty()
            || !commit.asset_changes.is_empty()
            || !commit.job_enqueues.is_empty()
            || !commit.sequence_allocations.is_empty();
        if !commit.job_changes.is_empty() {
            // The enqueue is already durable. Arm the autonomous worker before
            // this Local authority can be released so a concurrent empty-queue
            // refresh cannot overwrite the wakeup.
            self.jobs_active.store(true, Ordering::Relaxed);
        }
        commit.network_egress = if commit.authorization.is_some() && has_observable_effect {
            self.network_profiles
                .admit_commit(Instant::now())
                .map(crate::network_profile::MutationEgressBasis::ProfiledCommit)
                .unwrap_or(crate::network_profile::MutationEgressBasis::NormalCommit)
        } else {
            crate::network_profile::MutationEgressBasis::ResultReady
        };
        self.current_live_network_egress = match &commit.network_egress {
            crate::network_profile::MutationEgressBasis::ProfiledCommit(group) => Some(Some(
                group.for_lane(crate::network_profile::NetworkEgressLane::LiveDelta),
            )),
            crate::network_profile::MutationEgressBasis::NormalCommit => Some(None),
            crate::network_profile::MutationEgressBasis::ResultReady => None,
        };
        #[cfg(test)]
        BEFORE_MUTATION_POSTCOMMIT_HOOK.with(|slot| {
            if let Some(hook) = slot.borrow_mut().take() {
                hook();
            }
        });
        let frame_version = commit.output.version;
        crate::spike_trace::commit(
            commit_durable_ms,
            mutation,
            frame_version,
            commit.changes.len() + commit.job_changes.len() + commit.asset_changes.len(),
            trace_identity,
        );
        // This is internal invalidation truth derived from the already-durable
        // commit, not an app-visible publication. Capacity was proved before
        // execution, so it must advance even if the caller's admission lease
        // ends immediately after COMMIT.
        let permission_changes = if commit.output.changed_count > 0 {
            self.advance_permission_epochs(&epoch_scopes)
        } else {
            Vec::new()
        };
        if !permission_changes.is_empty() {
            self.refresh_read_epochs();
        }
        // Normal mutation serving publishes through the in-frame fan-out
        // below rather than `notify_live_subscriptions`, so durable watches
        // must enter the same post-commit change stream here. Authorization
        // commits conservatively wake every active watch for fresh principal
        // and basis validation; ordinary data commits use exact live-query
        // dependency matching.
        // @ref LLP 0204#d93--durable-watches-end-user-automations — invalidation-driven durable
        // evaluation, including instant authority-revocation observation.
        if commit
            .authorization
            .as_ref()
            .is_some_and(|authorization| authorization.event)
        {
            self.schedule_invalidated_watches(&[]);
        } else if !commit.changes.is_empty() {
            self.schedule_invalidated_watches(&commit.changes);
        }
        let postcommit = (|| -> SnapbackResult<()> {
            // The transaction already committed. Re-read only to prove that
            // the durable head still names this exact frame; corruption or an
            // impossible mismatch suppresses publication but cannot turn the
            // confirmed mutation into a rejection.
            let observed = self.db.versions_read().current_version()?;
            if observed != frame_version {
                return Err(SnapbackError::error(
                    "SNAPBACK_STORAGE_VERSION_CORRUPT",
                    "storage",
                    "post-commit storage head does not match the committed mutation version",
                )
                .with_details(json!({
                    "committedVersion": frame_version,
                    "observedVersion": observed,
                })));
            }
            let authorization_event = commit
                .authorization
                .as_ref()
                .filter(|authorization| authorization.event && self.auth_invalidation.is_some());
            if !permission_changes.is_empty()
                || !commit.changes.is_empty()
                || !commit.job_changes.is_empty()
                || !commit.asset_changes.is_empty()
                || authorization_event.is_some()
            {
                self.begin_live_delivery_frame(self.subscriptions.len());
                let mut resynced = self.notify_permission_resyncs_in_frame(
                    &permission_changes,
                    frame_version,
                    admission,
                )?;
                if let Some(authorization) = authorization_event {
                    resynced.extend(self.notify_authorization_event_in_frame(
                        authorization,
                        frame_version,
                        admission,
                    )?);
                }
                if !commit.changes.is_empty()
                    || !commit.job_changes.is_empty()
                    || !commit.asset_changes.is_empty()
                    || authorization_event.is_some()
                {
                    // Job-state rows ride the same frame as app changes so a
                    // declared job-status subscription observes its enqueue;
                    // they never touch OCC/projection/search consumers, which
                    // read `commit.changes` upstream of here.
                    //
                    // Serving commits enqueue this data behind any permission
                    // or authority work above. An absent scheduler retains the
                    // legacy inline order.
                    if commit.job_changes.is_empty() && commit.asset_changes.is_empty() {
                        self.dispatch_live_data_fanout(
                            &commit.changes,
                            &resynced,
                            frame_version,
                            admission,
                        )?;
                    } else {
                        let mut frame_changes = commit.changes.clone();
                        frame_changes.extend(commit.job_changes.iter().cloned());
                        // @ref LLP 0210#d5--recipient-scoped-authority-recipe-now-grant-ops-as-the-paved-spelling —
                        // a grant-only commit invalidates the governed asset
                        // projection so revoke can publish a blank snapshot.
                        frame_changes.extend(commit.asset_changes.iter().map(|asset_id| {
                            ChangedRow {
                                table: ASSET_RECORDS_LIVE_TABLE.to_owned(),
                                id: asset_id.clone(),
                                op: crate::storage::ChangeOp::Update,
                                row: None,
                                changed_fields: Vec::new(),
                            }
                        }));
                        self.dispatch_live_data_fanout(
                            &frame_changes,
                            &resynced,
                            frame_version,
                            admission,
                        )?;
                    }
                }
            }
            Ok(())
        })();
        self.current_live_network_egress = None;
        if let Err(error) = postcommit {
            self.record_attached_diagnostics(vec![error.diagnostic]);
        }
        Ok(commit)
    }

    #[allow(
        clippy::too_many_arguments,
        reason = "the detached commit gate keeps independent authority and lifecycle checks explicit"
    )]
    pub fn commit_detached_ibex_mutation_guarded<G, Check, BeforeCommit>(
        &mut self,
        name: &str,
        input: HandlerInput,
        binding: DetachedMutationBinding,
        mut executed: ExecutedIbexMutation,
        identity: Option<ClientMutationIdentity>,
        check_live: Check,
        before_commit: BeforeCommit,
    ) -> SnapbackResult<MutationOutput>
    where
        Check: Fn() -> SnapbackResult<()>,
        BeforeCommit: FnOnce() -> SnapbackResult<G>,
    {
        let admission = binding.invocation.admission_lease().clone();
        admission.validate("detached nested mutation commit")?;
        self.persist_and_validate_prepared_service_authority(binding.invocation.authority())?;
        check_live()?;
        let mut input = binding.invocation.canonicalize_input(input);
        bind_authoritative_client_mutation_identity(&mut input, identity.as_ref());
        let trace_identity =
            crate::spike_trace::MutationTraceIdentity::capture(&input, identity.as_ref(), None);
        let function = self.function(name)?.clone();
        if function != binding.function
            || self.db.schema() != &binding.schema
            || self.app_generation != binding.app_generation
        {
            return Err(SnapbackError::error(
                "SNAPBACK_MUTATION_CONFLICT",
                "runtime",
                format!(
                    "app code or schema changed while action-hosted mutation {name} was running"
                ),
            ));
        }
        crate::result_contract::validate_handler_result(&function, &executed.result)?;
        let expected_media_projection_binding = expected_media_projection_binding(
            &binding.invocation,
            &input,
            &executed,
            identity.as_ref(),
        )?;
        let membership_plans = executed.authorize_membership_commands(&mut self.db)?;
        // Action-hosted nested mutations may enqueue (LLP 0070: actions
        // enqueue follow-up work only through an explicit mutation). The
        // nested commit mints its own producer identity in the receipt id
        // domain.
        let producer_mutation_id = crate::ids::mint_time_ordered(crate::ids::Kind::Mutation);
        let (job_enqueues, job_producer) = admit_job_enqueues(
            &self.functions,
            executed.job_enqueues,
            &producer_mutation_id,
            name,
            input.auth.user_id.clone(),
        )?;
        self.ensure_permission_epoch_capacity(&binding.epoch_scopes)?;
        let commit = self
            .db
            .mutation_writes()
            .commit_buffered_host_writes_guarded(
                &input,
                BufferedCommitPayload {
                    writes: executed.writes,
                    sequence_allocations: executed.sequence_allocations,
                    membership_plans,
                    read_dependencies: executed.reads,
                    result: executed.result,
                    ctx_ledger: executed.ctx_ledger,
                    job_enqueues,
                    job_producer,
                    asset_admissions: executed.asset_admissions,
                    asset_grant_ops: executed.asset_grant_ops,
                    media_projection_proof: executed.media_projection_proof,
                    expected_media_projection_binding,
                },
                identity.as_ref(),
                check_live,
                || {
                    let admission_guard =
                        admission.effect_guard("detached nested mutation transaction")?;
                    let caller_guard = before_commit()?;
                    Ok((admission_guard, caller_guard))
                },
            )?;
        Ok(self
            .finish_mutation_commit(
                name,
                &trace_identity,
                binding.epoch_scopes,
                commit,
                &admission,
            )?
            .output)
    }

    /// `mutationDryRun` (LLP 0051 D8 / Increment 4): execute the mutation
    /// through the SAME tier path as a commit — the IR step loop or the real
    /// Ibex handler over the buffered ctx — and discard the writes. No epoch
    /// advance, no live fan-out, no receipt: nothing observed a change.
    ///
    /// Execution-level failures fold into the outcome (`wouldCommit: false`
    /// plus the same diagnostic a real commit would raise); `Err` here means
    /// the dry-run could not even be attempted (unknown function, wrong
    /// kind).
    ///
    /// @ref LLP 0051#d8-the-agent-surface-dry-run-becomes-cheap-and-trustworthy —
    ///   execute-and-discard on the buffered substrate with ledgers.
    pub fn dry_run_mutation(
        &mut self,
        name: &str,
        input: HandlerInput,
    ) -> SnapbackResult<MutationDryRunOutcome> {
        let authority = InvocationGate::prepare_admitted_dev_input(
            InvocationSource::LocalMutation,
            ServerProfile::Dev,
            &input,
            self.admission.admit_dev()?,
        )?;
        self.dry_run_mutation_with_authority(name, input, authority)
    }

    pub(crate) fn dry_run_mutation_with_authority(
        &mut self,
        name: &str,
        input: HandlerInput,
        authority: PreparedAuthority,
    ) -> SnapbackResult<MutationDryRunOutcome> {
        let function = self.function(name)?.clone();
        let prepared = InvocationGate::prepare_function(authority, &function)?;
        let input = prepared.canonicalize_input(input);
        let snapshot_version = self.db.versions_read().current_version()?;
        let read_set_checked = !input.read_set.is_empty();
        let tier = match &function.runtime {
            FunctionRuntime::HostPlan(HandlerPlan::Mutation(_)) => "hostPlan",
            FunctionRuntime::IbexModule(_) => "ibexModule",
            _ => {
                return Err(SnapbackError::error(
                    "SNAPBACK_FUNCTION_KIND_MISMATCH",
                    "runtime",
                    format!("{name} is not a mutation"),
                ));
            }
        };
        // The same pre-execution gate as a real commit (ENG-23329): a
        // mutation whose declared epoch bumps cannot be resolved is denied
        // before any step executes.
        if let Err(error) = evaluate_permission_epoch_scopes(&function, &input) {
            return Ok(MutationDryRunOutcome {
                tier,
                would_commit: false,
                denied: true,
                failure: Some(error.diagnostic),
                read_set_validation: "notChecked",
                snapshot_version,
                result: Value::Null,
                changes: Vec::new(),
                read_dependencies: Vec::new(),
                ledger: None,
                diagnostics: Vec::new(),
            });
        }
        let execution = match &function.runtime {
            FunctionRuntime::HostPlan(HandlerPlan::Mutation(plan))
            | FunctionRuntime::HostPlan(HandlerPlan::WriteWithActivity(
                crate::manifest::WriteWithActivityPlan { mutation: plan, .. },
            )) => {
                self.db.mutation_writes().dry_run_mutation(plan, &input).map(|execution| {
                    let mut diagnostics = Vec::new();
                    // The IR ledger honors D1's declared id bound: past it the
                    // ledger is elided (with a diagnostic), never truncated —
                    // a partial `deterministicInputs` would read as complete.
                    let ledger = if execution.generated_ids.len() > CTX_ANSWER_LEDGER_MAX_IDS {
                        diagnostics.push(
                            Diagnostic::warning(
                                "SNAPBACK_DRY_RUN_LEDGER_ELIDED",
                                "runtime",
                                format!(
                                    "dry-run generated {} ids, past the declared ledger bound ({}); deterministicInputs elided",
                                    execution.generated_ids.len(),
                                    CTX_ANSWER_LEDGER_MAX_IDS
                                ),
                            ),
                        );
                        None
                    } else {
                        Some(CtxAnswerLedger {
                            version: ctx_ledger_version(),
                            ids: execution.generated_ids,
                            now: execution.now_ms,
                            auth_fingerprint: None,
                        })
                    };
                    (execution.commit, ledger, diagnostics)
                })
            }
            FunctionRuntime::IbexModule(module) => crate::runtime::dry_run_ibex_mutation_prepared(
                &self.runtime,
                module,
                input.clone(),
                &prepared,
                &mut self.db,
                Some(&self.warm_vms),
            )
            .map(|mut commit| {
                let ledger = commit.output.ctx_ledger.take();
                (commit, ledger, Vec::new())
            }),
            _ => unreachable!("tier matched above"),
        };
        let execution = execution.and_then(|tuple| {
            crate::result_contract::validate_handler_result(&function, &tuple.0.output.result)?;
            Ok(tuple)
        });
        match execution {
            Ok((commit, ledger, diagnostics)) => Ok(MutationDryRunOutcome {
                tier,
                would_commit: true,
                denied: false,
                failure: None,
                read_set_validation: if read_set_checked || !commit.read_dependencies.is_empty() {
                    "valid"
                } else {
                    "notChecked"
                },
                snapshot_version,
                result: commit.output.result.clone(),
                changes: commit.changes,
                read_dependencies: commit.read_dependencies,
                ledger,
                diagnostics,
            }),
            Err(error) => {
                // Read-set validation runs first inside the transaction, so a
                // conflict code means "stale baseline"; any later failure
                // implies the checked baseline (if any) validated.
                let stale = error.diagnostic.code == "SNAPBACK_MUTATION_CONFLICT";
                Ok(MutationDryRunOutcome {
                    tier,
                    would_commit: false,
                    denied: false,
                    failure: Some(error.diagnostic),
                    read_set_validation: if stale {
                        "stale"
                    } else if read_set_checked {
                        "valid"
                    } else {
                        "notChecked"
                    },
                    snapshot_version,
                    result: Value::Null,
                    changes: Vec::new(),
                    read_dependencies: Vec::new(),
                    ledger: None,
                    diagnostics: Vec::new(),
                })
            }
        }
    }

    /// The local-arm `generation` digest (LLP 0091 §0A.6): content-derived
    /// from the served manifests and resume-relevant config, recomputed after
    /// every ensure (the generation-activation coordinator clears the cache).
    /// A no-op
    /// ensure reproduces identical components and therefore an identical
    /// digest, so dev-loop ensures do not needlessly refuse tokens.
    pub fn rqs_generation_digest(&mut self) -> SnapbackResult<String> {
        if let Some(generation) = &self.rqs_generation {
            return Ok(generation.clone());
        }
        let canonical_identity = |value: &Value| -> SnapbackResult<String> {
            crate::rqs_contract::sha256_identity(value).map_err(|_| {
                SnapbackError::error(
                    "SNAPBACK_RESUME_GENERATION_UNAVAILABLE",
                    "realtime",
                    "served manifest could not be canonically hashed for the resume generation",
                )
            })
        };
        let deployment_identity = format!("local:{}", env!("CARGO_PKG_VERSION"));
        let schema_identity = self
            .db
            .schema()
            .schema_hash
            .clone()
            .unwrap_or_else(|| "absent".to_owned());
        let manifest_value = |value: Result<Value, serde_json::Error>| -> SnapbackResult<Value> {
            value.map_err(|error| {
                SnapbackError::error(
                    "SNAPBACK_RESUME_GENERATION_UNAVAILABLE",
                    "realtime",
                    "served manifest could not be serialized for the resume generation",
                )
                .with_details(json!({ "error": error.to_string() }))
            })
        };
        let functions_identity =
            canonical_identity(&manifest_value(serde_json::to_value(&self.functions))?)?;
        let capability_manifest = self.served_capability_manifest(self.capability_gaps());
        let capability_identity =
            canonical_identity(&manifest_value(serde_json::to_value(&capability_manifest))?)?;
        let auth_mode = self.db.auth_mode_snapshot()?.state.active.as_str();
        // The journal prune policy is a per-call maintenance argument rather
        // than a named durable policy; its identity stays a pinned literal
        // until that artifact exists, so changing the model rotates the
        // generation through this string. `routeManifestHash` is the served
        // route manifest's canonical hash (LLP 0092 §0C.1), or the pinned
        // "absent" literal when no route manifest is served.
        let route_manifest_hash = self
            .routes_manifest_hash
            .clone()
            .unwrap_or_else(|| "absent".to_owned());
        let resume_config = crate::rqs::resume_config_identity(
            "caller-supplied-v0",
            auth_mode,
            &route_manifest_hash,
        );
        let generation = crate::rqs::generation_digest(
            &deployment_identity,
            &schema_identity,
            &functions_identity,
            &capability_identity,
            &resume_config,
        );
        self.rqs_generation = Some(generation.clone());
        Ok(generation)
    }

    /// Install the served route→query manifest (LLP 0092 §0C.1 admission on
    /// the local arm's ensure path): shape validation, then validation
    /// against the served functions manifest. Installing (or replacing) the
    /// manifest rotates the RQS `generation` through `routeManifestHash`.
    pub fn install_routes_manifest(
        &mut self,
        manifest: crate::bundle::RoutesManifest,
    ) -> SnapbackResult<()> {
        self.validate_routes_manifest(&manifest)?;
        let value = serde_json::to_value(&manifest).map_err(|error| {
            routes_manifest_error(format!("routes manifest is not serializable: {error}"))
        })?;
        let hash = crate::rqs_contract::sha256_identity(&value).map_err(|_| {
            routes_manifest_error("routes manifest is not canonically hashable".to_owned())
        })?;
        self.routes = Some(manifest);
        self.routes_manifest_hash = Some(hash);
        // Route-manifest identity is a `generation` component (LLP 0091
        // §0A.6 resumeConfig): outstanding tokens minted under the previous
        // route manifest refuse stale rather than resuming across it.
        self.rqs_generation = None;
        Ok(())
    }

    /// The served route manifest, if any (the bundle endpoint and tests).
    pub fn routes_manifest(&self) -> Option<&crate::bundle::RoutesManifest> {
        self.routes.as_ref()
    }

    /// LLP 0092 §0C.1 install-time validation against the served functions
    /// manifest: every named function exists and is a query; every `$param`
    /// reference targets a typable object-reachable arg position (AST-derived
    /// at depth 1, argument-contract-derived below it); and every arg the
    /// query's plan reads is covered by the mapping. Failures refuse the
    /// manifest with the coded load error — per 0090 D1.4, manifest presence
    /// authorizes preload selection only.
    fn validate_routes_manifest(
        &self,
        manifest: &crate::bundle::RoutesManifest,
    ) -> SnapbackResult<()> {
        Self::validate_routes_manifest_against(manifest, &self.functions, self.db.schema())
    }

    fn validate_routes_manifest_against(
        manifest: &crate::bundle::RoutesManifest,
        functions: &FunctionManifest,
        schema: &SchemaManifest,
    ) -> SnapbackResult<()> {
        crate::bundle::validate_routes_manifest_shape(manifest).map_err(routes_manifest_error)?;
        if manifest.app != functions.app_id {
            return Err(routes_manifest_error(format!(
                "routes manifest app {:?} does not match the served functions manifest app {:?}",
                manifest.app, functions.app_id
            )));
        }
        for entry in &manifest.routes {
            if entry.mixed_group_eligible {
                let profile = entry.mixed_profile.as_ref().ok_or_else(|| {
                    routes_manifest_error("mixed route lacks mixedProfile".to_owned())
                })?;
                crate::bundle::admit_mixed_profile_v2(
                    entry,
                    Some(2),
                    Some("mixed-route.v2"),
                    Some(&profile.plan_hash),
                    |name| functions.function(name).cloned(),
                )
                .map_err(|code| {
                    routes_manifest_error(format!(
                        "route {:?} carries an invalid mixed LLP 0157 identity ({code})",
                        entry.route
                    ))
                })?;
            }
            for spec in &entry.queries {
                let Some(function) = functions.function(&spec.function) else {
                    return Err(routes_manifest_error(format!(
                        "route {:?} names unknown function {:?}",
                        entry.route, spec.function
                    )));
                };
                if !matches!(
                    function.kind,
                    crate::manifest::FunctionKind::Query | crate::manifest::FunctionKind::LiveQuery
                ) {
                    return Err(routes_manifest_error(format!(
                        "route {:?} names non-query function {:?}",
                        entry.route, spec.function
                    )));
                }
                if entry.register_group_eligible
                    && function.kind != crate::manifest::FunctionKind::LiveQuery
                {
                    return Err(routes_manifest_error(format!(
                        "route {:?} asserts registerGroupEligible but query {:?} is not a LiveQuery",
                        entry.route, spec.function
                    )));
                }
                if entry.register_group_eligible
                    && matches!(
                        &function.runtime,
                        crate::manifest::FunctionRuntime::HostPlan(
                            crate::manifest::HandlerPlan::SearchQuery(_)
                        )
                    )
                {
                    // @ref LLP 0136#client-composition-llp-0112--llp-0114 —
                    // a literal AST cannot bypass codegen and enter register
                    // mode before the cursor/ceiling path is implemented.
                    return Err(routes_manifest_error(format!(
                        "route {:?} asserts registerGroupEligible but query {:?} is a live-search child",
                        entry.route, spec.function
                    )));
                }
                let arg_types = crate::bundle::function_route_arg_types(function, schema);
                let nested_arg_types = crate::bundle::function_nested_route_arg_types(function);
                let reference_paths = object_reachable_route_param_paths(&spec.args).map_err(
                    |_| {
                        routes_manifest_error(format!(
                            "route {:?} query {:?} has a param reference at the mapping root or inside an array literal",
                            entry.route, spec.function
                        ))
                    },
                )?;
                for path in reference_paths {
                    let target_type = if path.len() == 1 {
                        arg_types.get(path[0].as_str())
                    } else {
                        nested_arg_types.get(&path)
                    };
                    if target_type.is_none() {
                        if path.len() == 1 {
                            let key = &path[0];
                            return Err(routes_manifest_error(format!(
                                "route {:?} query {:?} references param into arg {:?}, which has no schema-derived string/number/boolean type",
                                entry.route, spec.function, key
                            )));
                        }
                        return Err(routes_manifest_error(format!(
                            "route {:?} query {:?} references param into {}, which has no contract-derived string/number/boolean type",
                            entry.route,
                            spec.function,
                            path.join(".")
                        )));
                    }
                    if (entry.register_group_eligible || entry.mixed_group_eligible)
                        && target_type != Some(&crate::bundle::RouteParamType::String)
                    {
                        let target = if path.len() == 1 {
                            path[0].clone()
                        } else {
                            path.join(".")
                        };
                        return Err(routes_manifest_error(format!(
                            "route {:?} asserts registerGroupEligible but query {:?} param target {:?} is not string-typed",
                            entry.route, spec.function, target
                        )));
                    }
                }
                // Coverage: every arg the plan's filters read must appear in
                // the mapping (LLP 0092 §0E.6's required-arg rule, over the
                // AST-derived required set).
                if let crate::manifest::FunctionRuntime::HostPlan(
                    crate::manifest::HandlerPlan::Query(plan),
                ) = &function.runtime
                {
                    let mut required = std::collections::BTreeSet::new();
                    for filter in &plan.filters {
                        collect_value_expr_arg_names(&filter.value, &mut required);
                    }
                    for name in required {
                        let covered =
                            matches!(&spec.args, Value::Object(map) if map.contains_key(&name));
                        if !covered {
                            return Err(routes_manifest_error(format!(
                                "route {:?} query {:?} does not cover required arg {:?}",
                                entry.route, spec.function, name
                            )));
                        }
                    }
                }
            }
        }
        Ok(())
    }

    /// Mint one shared resume token at `(queryArtifact, argsHash, version,
    /// contentDigest)` (LLP 0090 D1: one mint per result-change, shared
    /// across the fan-out — the optional `cache` carries the sharing within
    /// one commit frame). Returns `None` on any mint impediment: minting is
    /// best-effort and its absence only costs a future resume.
    fn mint_resume_wire(
        &mut self,
        query_artifact: &str,
        args_hash: &str,
        version: u64,
        digest_kind: crate::rqs_contract::DigestKind,
        content_digest: String,
    ) -> Option<ResumeWire> {
        let app = self.functions.app_id.clone();
        let generation = self.rqs_generation_digest().ok()?;
        let version_stream = self.db.data_version_stream().ok()?;
        let now = now_millis();
        let (key_id, key) = self
            .resume_keyring
            .write()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .active(now)?;
        let body = crate::rqs::ResumeTokenBody {
            app: app.clone(),
            generation: generation.clone(),
            version_stream: version_stream.clone(),
            version,
            query_artifact: query_artifact.to_owned(),
            args_hash: args_hash.to_owned(),
            digest_kind: digest_kind.as_str().to_owned(),
            content_digest: content_digest.clone(),
            issued_at: now,
            auth_partition: None,
        };
        let token = crate::rqs::mint_token_wire(key.as_ref(), &key_id, &body);
        if token.len() > crate::rqs::RESUME_TOKEN_MAX_WIRE_BYTES {
            // A token the server itself would refuse must never be minted.
            return None;
        }
        self.live_delivery.resume.tokens_minted += 1;
        Some(ResumeWire {
            token,
            meta: ResumeMeta {
                app,
                version,
                content_digest,
                generation,
                version_stream,
                query_artifact: query_artifact.to_owned(),
                args_hash: args_hash.to_owned(),
            },
        })
    }

    /// LLP 0090 D1.1 admission for a presented resume token: cryptographic
    /// verification, then every identity axis against the served instance
    /// and the subscription being opened. Any `Err` answers with rung 3
    /// under its per-cause code — never a subscribe failure.
    fn admit_resume_token(
        &mut self,
        presented: &ResumeFromToken,
        function: &FunctionDefinition,
        args: &Value,
        eligibility: Option<crate::rqs_contract::DigestKind>,
    ) -> Result<crate::rqs::ResumeTokenBody, &'static str> {
        use crate::rqs::refusal;
        let now = now_millis();
        let body = crate::rqs::decode_and_verify(
            &presented.resume.token,
            &self
                .resume_keyring
                .read()
                .unwrap_or_else(|poisoned| poisoned.into_inner()),
            now,
            crate::rqs::RESUME_TOKEN_MAX_AGE_MS,
        )?;
        if body.auth_partition.is_some() {
            // Reserved v2 door: absent in v1 (LLP 0091 §0A.1). A partitioned
            // token cannot be admitted by a v1 server.
            return Err(refusal::TOKEN_MALFORMED);
        }
        if body.app != self.functions.app_id {
            return Err(refusal::APP_MISMATCH);
        }
        let generation = self
            .rqs_generation_digest()
            .map_err(|_| refusal::GENERATION_STALE)?;
        if body.generation != generation {
            return Err(refusal::GENERATION_STALE);
        }
        let version_stream = self
            .db
            .data_version_stream()
            .map_err(|_| refusal::STREAM_MISMATCH)?;
        if body.version_stream != version_stream {
            return Err(refusal::STREAM_MISMATCH);
        }
        let query_artifact = serde_json::to_value(function)
            .ok()
            .and_then(|value| crate::rqs_contract::query_artifact_hash(&value).ok())
            .ok_or(refusal::QUERY_MISMATCH)?;
        if body.query_artifact != query_artifact {
            return Err(refusal::QUERY_MISMATCH);
        }
        let args_hash =
            crate::rqs_contract::args_hash(args).map_err(|_| refusal::QUERY_MISMATCH)?;
        if body.args_hash != args_hash {
            return Err(refusal::QUERY_MISMATCH);
        }
        // Interim eligibility, tightened by ENG-25448 (cluster 0C).
        let Some(kind) = eligibility else {
            return Err(refusal::NOT_ELIGIBLE);
        };
        if body.digest_kind != kind.as_str()
            || !body
                .content_digest
                .starts_with(&format!("{}:", kind.as_str()))
        {
            return Err(refusal::DIGEST_KIND_MISMATCH);
        }
        let head = self
            .db
            .versions_read()
            .current_version()
            .map_err(|_| refusal::VERSION_IMPLAUSIBLE)?;
        if body.version > head {
            return Err(refusal::VERSION_IMPLAUSIBLE);
        }
        Ok(body)
    }

    /// Rung-2 delta replay for an admitted `mset1` token with a membership
    /// witness (LLP 0090 D1.3, rollout steps 5a+6). Preconditions the caller
    /// established: the token passed D1.1 admission, its `version` is within
    /// the journal floor, the query is DK-3-analyzable unordered (`mset1`),
    /// and a fresh token was mintable at head.
    ///
    /// Sequence: (1) enforce the witness caps, (2) decode fail-closed, (3)
    /// verify the witness aggregate equals the MAC-bound `contentDigest`
    /// root BEFORE any replay — token and witness are jointly verifiable and
    /// the keyed leaf defeats hash permutation, (4) diff the witnessed old
    /// membership against the current post-image result over exactly the
    /// journal-affected row ids (exits are derivable because the witness
    /// names old hashes), under the replay-vs-replace policy threshold, and
    /// (5) require the updated accumulator — witnessed leaves subtracted and
    /// post-image leaves added for affected ids only, untouched leaves kept
    /// — to reproduce the fresh head digest. Any refusal answers rung 3: a
    /// full replacement, which by construction can never suppress a removal.
    ///
    /// @ref LLP 0090#d13-replay-admission-ladder — rung-2 witness semantics
    ///   and the accumulator-update rule this implements.
    fn rqs_attempt_delta_replay(
        &self,
        witness: &crate::live_wire::MembershipWitnessWire,
        body: &crate::rqs::ResumeTokenBody,
        function: &FunctionDefinition,
        state: &RqsLiveState,
        current_rows: &[Value],
    ) -> Result<Vec<LiveDeltaWireOp>, &'static str> {
        use crate::rqs::refusal;
        let wire_bytes = serde_json::to_vec(witness)
            .map(|bytes| bytes.len())
            .unwrap_or(usize::MAX);
        if wire_bytes > self.rqs_replay_policy.max_witness_bytes {
            return Err(refusal::WITNESS_OVERSIZE);
        }
        let pairs =
            crate::rqs::decode_witness(witness, self.rqs_replay_policy.max_witness_entries)?;
        let mut accumulator = crate::rqs::witness_state(&pairs);
        if accumulator.root() != body.content_digest {
            return Err(refusal::WITNESS_ROOT_MISMATCH);
        }
        // The eligibility gate guarantees an analyzable single-table plan.
        let FunctionRuntime::HostPlan(HandlerPlan::Query(plan)) = &function.runtime else {
            return Err(refusal::WITNESS_INVALID);
        };
        let threshold = std::cmp::max(
            1,
            (pairs.len() as u64)
                .saturating_mul(u64::from(self.rqs_replay_policy.replay_affected_percent))
                / 100,
        ) as usize;
        let affected = self
            .db
            .versions_read()
            .changed_row_ids_for_table_since(&plan.table, body.version, threshold)
            .map_err(|_| refusal::JOURNAL_FLOOR)?;
        if affected.len() > threshold {
            return Err(refusal::POLICY_REPLACED);
        }
        let witnessed: HashMap<&str, &[u8; 32]> = pairs
            .iter()
            .map(|pair| (pair.id.as_str(), &pair.row_hash))
            .collect();
        let current_by_id: HashMap<&str, &Value> = current_rows
            .iter()
            .filter_map(|row| crate::rqs_contract::row_wire_id(row).map(|id| (id, row)))
            .collect();
        let mut ops = Vec::new();
        for id in &affected {
            let old_hash = witnessed.get(id.as_str()).copied();
            let new_hash = state.digest.row_hash_for(id);
            match (old_hash, new_hash) {
                // Touched, but in the result on neither side (never matched
                // the predicate, or entered and left inside the gap).
                (None, None) => {}
                // Predicate exit or delete while offline: exactly removed.
                (Some(old_hash), None) => {
                    accumulator.remove_leaf(&crate::rqs_contract::leaf(id, old_hash));
                    ops.push(LiveDeltaWireOp {
                        op: LiveDeltaOpKind::Remove,
                        id: id.clone(),
                        row: None,
                    });
                }
                // Entered the result while offline.
                (None, Some(new_hash)) => {
                    let Some(row) = current_by_id.get(id.as_str()) else {
                        return Err(refusal::WITNESS_REPLAY_DIVERGED);
                    };
                    accumulator.add_leaf(&crate::rqs_contract::leaf(id, new_hash));
                    ops.push(LiveDeltaWireOp {
                        op: LiveDeltaOpKind::Add,
                        id: id.clone(),
                        row: Some((*row).clone()),
                    });
                }
                // Held on both sides: an op only when the content changed
                // (a touched-but-reverted row stays silent).
                (Some(old_hash), Some(new_hash)) => {
                    if old_hash != new_hash {
                        let Some(row) = current_by_id.get(id.as_str()) else {
                            return Err(refusal::WITNESS_REPLAY_DIVERGED);
                        };
                        accumulator.remove_leaf(&crate::rqs_contract::leaf(id, old_hash));
                        accumulator.add_leaf(&crate::rqs_contract::leaf(id, new_hash));
                        ops.push(LiveDeltaWireOp {
                            op: LiveDeltaOpKind::Update,
                            id: id.clone(),
                            row: Some((*row).clone()),
                        });
                    }
                }
            }
        }
        // The minted root must still contain every untouched witness leaf
        // and nothing else — any divergence (journal incompleteness, an
        // impure query, a wrong-but-root-matching witness) refuses to rung 3
        // instead of ratifying a wrong replay.
        if accumulator.root() != state.digest.published() {
            return Err(refusal::WITNESS_REPLAY_DIVERGED);
        }
        Ok(ops)
    }

    /// Resolve a bundle request's route entry (LLP 0092 §0C.1/§0D.1): while
    /// a route manifest is served it is the ONLY source of entries — the
    /// endpoint matches the presented pattern by string equality and the
    /// inline `devManifestEntry` form is refused by design. Without a served
    /// manifest the clearly-marked inline dev/test form is required.
    pub fn resolve_bundle_route(
        &self,
        route: &str,
        dev_manifest_entry: Option<&crate::bundle::BundleRouteEntry>,
    ) -> SnapbackResult<crate::bundle::BundleRouteEntry> {
        use crate::bundle::code;
        let refuse = |code: &'static str, message: &str| {
            SnapbackError::error(code, "realtime", message.to_owned())
        };
        match &self.routes {
            Some(manifest) => {
                if dev_manifest_entry.is_some() {
                    return Err(refuse(
                        code::ENTRY_INVALID,
                        "devManifestEntry is refused while a served route manifest exists (LLP 0092 §0C.1)",
                    ));
                }
                manifest
                    .routes
                    .iter()
                    .find(|entry| entry.route == route)
                    .cloned()
                    .ok_or_else(|| {
                        refuse(
                            code::ROUTE_UNKNOWN,
                            "route pattern is absent from the served route manifest",
                        )
                    })
            }
            None => dev_manifest_entry.cloned().ok_or_else(|| {
                refuse(
                    code::ROUTE_UNKNOWN,
                    "no served route manifest holds this route (inline devManifestEntry required on an instance serving no route manifest)",
                )
            }),
        }
    }

    /// The anonymous-read admission fact (LLP 0092 §0D.1): every query the
    /// entry names carries the codegen-compiled `publicInline` disclosure
    /// fact in the served functions manifest. Checked against the served
    /// facts, never the route-manifest author's word (0090 Authorization
    /// scope).
    pub fn bundle_entry_public_inline(&self, entry: &crate::bundle::BundleRouteEntry) -> bool {
        !entry.queries.is_empty()
            && entry.queries.iter().all(|spec| {
                self.functions
                    .function(&spec.function)
                    .is_some_and(|function| function.public_inline)
            })
    }

    /// Dev-authority read-mode bundle evaluation (the library/test seam,
    /// mirroring [`Self::subscribe_live`]). Production HTTP composition
    /// prepares its authority in the route middleware and calls
    /// `evaluate_bundle` directly.
    pub fn app_bundle_read_dev(
        &mut self,
        entry: &crate::bundle::BundleRouteEntry,
        params: &std::collections::BTreeMap<String, String>,
        request_route: &str,
        auth: &AuthInput,
    ) -> SnapbackResult<crate::bundle::BundleResponse> {
        let admission = self.admission.admit_dev()?;
        let authority = InvocationGate::prepare_admitted_authority(
            InvocationSource::HttpQuery,
            AuthMode::Dev,
            ServerProfile::Dev,
            admission,
            &WireAuthorityFields::default(),
            ResolvedAppAuthority::dev_from_auth(auth),
            None,
        )?;
        self.evaluate_bundle(entry, params, request_route, auth, &authority, None)
    }

    /// Evaluate one bundle route entry — every query at one commit cut
    /// (LLP 0090 D1.2's single-commit invariant; LLP 0092 §0D.5). On this
    /// arm the cut is the instance's exclusive borrow: every mutation path
    /// requires the same `&mut LocalSnapback` access this method holds, so
    /// no commit can fall between entry evaluations. Read mode therefore
    /// runs on the serialized lane rather than the concurrent read lane —
    /// correctness-identical to §0D.5's pinned-read-snapshot phrasing, with
    /// the read-lane concurrency left as follow-up work.
    ///
    /// Atomic failure: any coded refusal returns with **no** entry results;
    /// in register mode the caller-supplied connection's topology is purged
    /// before returning, so a failed bundle strands no server state
    /// (LLP 0031 dated amendment).
    ///
    /// @ref LLP 0092#0d2-atomicity-limits-and-the-snapback_bundle_-registry —
    ///   limits and per-cause codes; the closed per-entry union of §0D.1.
    pub fn evaluate_bundle(
        &mut self,
        entry: &crate::bundle::BundleRouteEntry,
        params: &std::collections::BTreeMap<String, String>,
        request_route: &str,
        auth: &AuthInput,
        authority: &PreparedAuthority,
        register: Option<crate::local::BundleRegisterTarget>,
    ) -> SnapbackResult<crate::bundle::BundleResponse> {
        use crate::bundle::{self, code};
        let refuse = |code: &'static str, message: &str| {
            SnapbackError::error(code, "realtime", message.to_owned())
        };
        let started = std::time::Instant::now();
        bundle::validate_entry_against_params(entry, request_route, params)
            .map_err(|code| refuse(code, "bundle route entry refused"))?;
        if register
            .as_ref()
            .and_then(|target| target.mixed_children.as_ref())
            .is_some()
        {
            return self.evaluate_mixed_bundle_v2(entry, params, auth, authority, register);
        }
        let commit_version = self
            .db
            .versions_read()
            .current_version()
            .map_err(|_| refuse(code::QUERY_FAILED, "bundle commit version unavailable"))?;
        let generation = self
            .rqs_generation_digest()
            .map_err(|_| refuse(code::QUERY_FAILED, "bundle generation unavailable"))?;
        let version_stream = self
            .db
            .data_version_stream()
            .map_err(|_| refuse(code::QUERY_FAILED, "bundle version stream unavailable"))?;

        let mut entries = Vec::with_capacity(entry.queries.len());
        let mut total_rows = 0_usize;
        let mut total_bytes = 0_usize;
        // Register-mode unwind: purge the freshly minted connection's whole
        // topology, retiring any auth scopes the partial registration
        // created. The connection exists only for this bundle, so purging it
        // is exactly the amendment's "strands no server state".
        let unwind = |snapback: &mut Self, error: SnapbackError| -> SnapbackError {
            if let Some(target) = &register {
                snapback.purge_connection_topology(&target.connection_id, &target.effect_fence);
            }
            error
        };
        let result = (|snapback: &mut Self| -> SnapbackResult<Vec<crate::bundle::BundleEntry>> {
            for (query_index, spec) in entry.queries.iter().enumerate() {
                if started.elapsed().as_millis() as u64 > bundle::BUNDLE_MAX_EVAL_MS {
                    return Err(refuse(
                        code::LIMIT_TIME,
                        "bundle evaluation wall time exceeded",
                    ));
                }
                let function = snapback
                    .function(&spec.function)
                    .map_err(|_| {
                        refuse(
                            code::ENTRY_INVALID,
                            "bundle entry names an unknown function",
                        )
                    })?
                    .clone();
                let is_query =
                    matches!(function.kind, FunctionKind::Query | FunctionKind::LiveQuery);
                if !is_query {
                    return Err(refuse(
                        code::ENTRY_INVALID,
                        "bundle entries may name queries only",
                    ));
                }
                if register.is_some() && function.kind != FunctionKind::LiveQuery {
                    return Err(refuse(
                        code::ENTRY_INVALID,
                        "register mode requires live queries",
                    ));
                }
                if let Some(target) = &register {
                    let supplied_namespace = target
                        .authorization_namespaces
                        .get(query_index)
                        .and_then(Option::as_ref);
                    if authority.active_mode() == AuthMode::Sessions {
                        if owner_admits_authority_independence(&function)
                            && supplied_namespace.is_some()
                        {
                            return Err(refuse(
                                code::ENTRY_INVALID,
                                "authority-independent registered children require a null authorization namespace",
                            ));
                        }
                        if !owner_admits_authority_independence(&function)
                            && supplied_namespace.is_none()
                        {
                            return Err(refuse(
                                code::ENTRY_INVALID,
                                "auth-scoped registered children require an authorization namespace",
                            ));
                        }
                    }
                }
                // Schema-driven per-arg decode (LLP 0092 §0E.6): references
                // decode from the unchanged AST type at depth 1 and the
                // carried argument contract below it.
                let arg_types = bundle::function_route_arg_types(&function, snapback.db.schema());
                let nested_arg_types = bundle::function_nested_route_arg_types(&function);
                let args =
                    bundle::substitute_params_v1(&spec.args, params, &arg_types, &nested_arg_types)
                        .map_err(|code| refuse(code, "bundle args mapping refused"))?;
                let (rows, resume, subscription_id, authorization) = match &register {
                    None => {
                        let input = HandlerInput {
                            args: args.clone(),
                            auth: auth.clone(),
                            read_set: Vec::new(),
                            correlation: None,
                            ctx_ledger: None,
                        };
                        let invocation = snapback
                            .invoke_query_with_dependencies_prepared(
                                &spec.function,
                                input,
                                authority.clone(),
                            )
                            .map_err(|error| {
                                refuse(code::QUERY_FAILED, "bundle entry evaluation failed")
                                    .with_details(json!({
                                        "function": spec.function,
                                        "cause": error.diagnostic.code,
                                    }))
                            })?;
                        let rows = invocation.output.rows;
                        // `resume` presence keys on the interim `rqsEligible`
                        // predicate and nothing else (LLP 0092 §0D.1).
                        let resume = rqs_eligibility(&function).and_then(|kind| {
                            let digest = crate::rqs::ResultDigest::from_rows(kind, &rows).ok()?;
                            let query_artifact =
                                serde_json::to_value(&function).ok().and_then(|value| {
                                    crate::rqs_contract::query_artifact_hash(&value).ok()
                                })?;
                            let args_hash = crate::rqs_contract::args_hash(&args).ok()?;
                            snapback.mint_resume_wire(
                                &query_artifact,
                                &args_hash,
                                commit_version,
                                kind,
                                digest.published(),
                            )
                        });
                        (rows, resume, None, None)
                    }
                    Some(target) => {
                        let admission = snapback
                            .admission
                            .admit_for_mode(authority.active_mode())
                            .map_err(|error| {
                                refuse(code::QUERY_FAILED, "bundle admission unavailable")
                                    .with_details(json!({ "cause": error.diagnostic.code }))
                            })?;
                        let sub_authority = snapback
                            .prepare_resolved_authority(
                                InvocationSource::LiveInitialQuery,
                                authority.active_mode(),
                                authority.profile(),
                                admission,
                                &WireAuthorityFields::default(),
                                authority.resolved().clone(),
                                now_millis(),
                            )
                            .map_err(|error| {
                                refuse(code::QUERY_FAILED, "bundle register authority refused")
                                    .with_details(json!({ "cause": error.diagnostic.code }))
                            })?;
                        let sub_input = LiveSubscribeInput {
                            connection_id: target.connection_id.clone(),
                            input: HandlerInput {
                                args: args.clone(),
                                auth: auth.clone(),
                                read_set: Vec::new(),
                                correlation: None,
                                ctx_ledger: None,
                            },
                            authorization_namespace: register.as_ref().and_then(|target| {
                                target
                                    .authorization_namespaces
                                    .get(query_index)
                                    .cloned()
                                    .flatten()
                            }),
                            supersedes: None,
                            resume_from_token: None,
                        };
                        let invalidation = LiveInvalidationAdmission {
                            connection: target.invalidation_connection.clone(),
                            effect_fence: Some(target.effect_fence.clone()),
                            #[cfg(any(test, feature = "test-support"))]
                            session_mode: false,
                        };
                        let output = snapback
                            .subscribe_live_prepared_with_invalidation(
                                &spec.function,
                                sub_input,
                                sub_authority,
                                invalidation,
                            )
                            .map_err(|error| {
                                refuse(code::QUERY_FAILED, "bundle registration failed")
                                    .with_details(json!({
                                        "function": spec.function,
                                        "cause": error.diagnostic.code,
                                    }))
                            })?;
                        let rows = output
                            .snapshot
                            .map(|snapshot| snapshot.rows)
                            .unwrap_or_default();
                        let authorization = output.authorization_scope.map(|scope| {
                            crate::bundle::BundleAuthorization {
                                scope,
                                invalidation: output.authorization_invalidation,
                            }
                        });
                        (
                            rows,
                            output.resume,
                            Some(output.subscription_id),
                            authorization,
                        )
                    }
                };
                total_rows += rows.len();
                if total_rows > bundle::BUNDLE_MAX_ROWS {
                    return Err(refuse(code::LIMIT_ROWS, "bundle row limit exceeded"));
                }
                total_bytes += serde_json::to_vec(&rows)
                    .map(|bytes| bytes.len())
                    .unwrap_or(0);
                if total_bytes > bundle::BUNDLE_MAX_BYTES {
                    return Err(refuse(code::LIMIT_BYTES, "bundle byte limit exceeded"));
                }
                if started.elapsed().as_millis() as u64 > bundle::BUNDLE_MAX_EVAL_MS {
                    return Err(refuse(
                        code::LIMIT_TIME,
                        "bundle evaluation wall time exceeded",
                    ));
                }
                entries.push(crate::bundle::BundleEntry {
                    function: spec.function.clone(),
                    args,
                    rows,
                    resume,
                    subscription_id,
                    authorization,
                    delivery: None,
                });
            }
            Ok(entries)
        })(self);
        let entries = match result {
            Ok(entries) => entries,
            Err(error) => return Err(unwind(self, error)),
        };
        Ok(crate::bundle::BundleResponse {
            format_version: None,
            profile: None,
            plan_hash: None,
            commit_version,
            generation,
            version_stream,
            entries,
            connection: None,
            aggregate: None,
        })
    }

    /// LLP 0090 mixed-route successor. All children execute against one
    /// pinned read transaction. Live registrations consume those exact
    /// invocations; ordinary Query children retain no server owner and carry
    /// an explicit read-only delivery fact.
    ///
    /// @ref LLP 0157#d4--capability-classification — child liveness comes only from
    ///   the admitted NodePlanRecord capability binding supplied by the
    ///   codegen/served-manifest cross-check.
    fn evaluate_mixed_bundle_v2(
        &mut self,
        entry: &crate::bundle::BundleRouteEntry,
        params: &std::collections::BTreeMap<String, String>,
        auth: &AuthInput,
        authority: &PreparedAuthority,
        register: Option<crate::local::BundleRegisterTarget>,
    ) -> SnapbackResult<crate::bundle::BundleResponse> {
        use crate::bundle::{self, code};
        let refuse = |code: &'static str, message: &str| {
            SnapbackError::error(code, "realtime", message.to_owned())
        };
        let started = std::time::Instant::now();
        let target = register
            .ok_or_else(|| refuse(code::MODE_INVALID, "mixed-route.v2 requires register mode"))?;
        let admitted = target.mixed_children.clone().ok_or_else(|| {
            refuse(
                code::ENTRY_INVALID,
                "mixed-route.v2 lacks admitted child identities",
            )
        })?;
        if admitted.len() != entry.queries.len() {
            return Err(refuse(
                code::ENTRY_INVALID,
                "mixed-route.v2 child identity count does not match the route",
            ));
        }
        let profile = entry
            .mixed_profile
            .as_ref()
            .ok_or_else(|| refuse(code::ENTRY_INVALID, "mixed-route.v2 lacks its route plan"))?;
        let generation = self
            .rqs_generation_digest()
            .map_err(|_| refuse(code::QUERY_FAILED, "bundle generation unavailable"))?;
        let version_stream = self
            .db
            .data_version_stream()
            .map_err(|_| refuse(code::QUERY_FAILED, "bundle version stream unavailable"))?;

        let mut prepared_children = Vec::with_capacity(entry.queries.len());
        for (position, (spec, admission)) in entry.queries.iter().zip(&admitted).enumerate() {
            let namespace = target
                .authorization_namespaces
                .get(position)
                .and_then(Option::as_ref);
            let function = self
                .function(&spec.function)
                .map_err(|_| refuse(code::ENTRY_INVALID, "mixed child is unknown"))?
                .clone();
            let kind_live = function.kind == FunctionKind::LiveQuery;
            if kind_live != admission.live {
                return Err(refuse(
                    code::ENTRY_INVALID,
                    "mixed child capability binding does not match its served export kind",
                ));
            }
            if authority.active_mode() == AuthMode::Sessions {
                if !admission.live && namespace.is_some() {
                    return Err(refuse(
                        code::ENTRY_INVALID,
                        "read-only mixed children require a null authorization namespace",
                    ));
                }
                if admission.live
                    && owner_admits_authority_independence(&function)
                    && namespace.is_some()
                {
                    return Err(refuse(
                        code::ENTRY_INVALID,
                        "authority-independent live children require a null authorization namespace",
                    ));
                }
                if admission.live
                    && !owner_admits_authority_independence(&function)
                    && namespace.is_none()
                {
                    return Err(refuse(
                        code::ENTRY_INVALID,
                        "auth-scoped live children require an authorization namespace",
                    ));
                }
            }
            let arg_types = bundle::function_route_arg_types(&function, self.db.schema());
            let nested_arg_types = bundle::function_nested_route_arg_types(&function);
            let args =
                bundle::substitute_params_v1(&spec.args, params, &arg_types, &nested_arg_types)
                    .map_err(|code| refuse(code, "mixed bundle args mapping refused"))?;
            let invocation_authority = if admission.live {
                let lease = self
                    .admission
                    .admit_for_mode(authority.active_mode())
                    .map_err(|error| {
                        refuse(code::QUERY_FAILED, "mixed live admission unavailable")
                            .with_details(json!({ "cause": error.diagnostic.code }))
                    })?;
                self.prepare_resolved_authority(
                    InvocationSource::LiveInitialQuery,
                    authority.active_mode(),
                    authority.profile(),
                    lease,
                    &WireAuthorityFields::default(),
                    authority.resolved().clone(),
                    now_millis(),
                )
                .map_err(|error| {
                    refuse(code::QUERY_FAILED, "mixed live authority refused")
                        .with_details(json!({ "cause": error.diagnostic.code }))
                })?
            } else {
                authority.clone()
            };
            let prepared =
                InvocationGate::prepare_function(invocation_authority.clone(), &function).map_err(
                    |error| {
                        refuse(code::QUERY_FAILED, "mixed child invocation refused").with_details(
                            json!({ "function": spec.function, "cause": error.diagnostic.code }),
                        )
                    },
                )?;
            let input = prepared.canonicalize_input(HandlerInput {
                args: args.clone(),
                auth: auth.clone(),
                read_set: Vec::new(),
                correlation: None,
                ctx_ledger: None,
            });
            prepared_children.push((
                position,
                spec.function.clone(),
                function,
                args,
                invocation_authority,
                prepared,
                input,
                admission.clone(),
            ));
        }

        let permission_epochs = &self.permission_epochs;
        let warm_vms = &self.warm_vms;
        let app_id = self.functions.app_id.clone();
        let keyring = &self.resume_keyring;
        let schema_hash = self.db.schema().schema_hash.clone();
        let bundle_hash = self.functions.bundle_hash.clone();
        let app_generation = self.app_generation;
        let target_profile = self.db.schema().target_profile.clone();
        let mut invocations = self
            .db
            .query_reads_read()
            .with_pinned_read_view(|view| {
                prepared_children
                    .iter()
                    .map(|(_, name, function, _, _, prepared, input, _)| {
                        execute_query_invocation(
                            Some(&self.db),
                            function,
                            name,
                            view.reborrow(),
                            permission_epochs,
                            input.clone(),
                            prepared,
                            Some(warm_vms),
                            Some(RelationalCursorAuthority {
                                app_id: &app_id,
                                keyring,
                                schema_hash: schema_hash.as_deref(),
                                function_bundle_hash: bundle_hash.as_deref(),
                                function_publication_generation: app_generation,
                                target_profile: target_profile.as_deref(),
                            }),
                            None,
                            None,
                        )
                        .map_err(|error| {
                            refuse(code::QUERY_FAILED, "mixed child evaluation failed")
                                .with_details(json!({
                                    "function": name,
                                    "cause": error.diagnostic.code,
                                }))
                        })
                    })
                    .collect::<SnapbackResult<Vec<_>>>()
            })
            .inspect_err(|_| {
                self.purge_connection_topology(&target.connection_id, &target.effect_fence);
            })?;
        let commit_version = invocations
            .first()
            .map(|invocation| invocation.output.version)
            .ok_or_else(|| refuse(code::ENTRY_INVALID, "mixed route has no children"))?;
        if invocations
            .iter()
            .any(|invocation| invocation.output.version != commit_version)
        {
            self.purge_connection_topology(&target.connection_id, &target.effect_fence);
            return Err(refuse(
                code::QUERY_FAILED,
                "mixed children did not report one pinned snapshot version",
            ));
        }

        let mut entries = Vec::with_capacity(prepared_children.len());
        let mut total_rows = 0_usize;
        let mut total_bytes = 0_usize;
        let mut live_children = 0_usize;
        let result = (|| -> SnapbackResult<()> {
            for (child, invocation) in prepared_children.into_iter().zip(invocations.drain(..)) {
                let (position, name, function, args, child_authority, _, input, admission) = child;
                let (rows, resume, subscription_id, authorization, delivery) = if admission.live {
                    live_children += 1;
                    let output = self
                        .subscribe_live_prepared_from_pinned_bundle(
                            &name,
                            LiveSubscribeInput {
                                connection_id: target.connection_id.clone(),
                                input,
                                authorization_namespace: target
                                    .authorization_namespaces
                                    .get(position)
                                    .cloned()
                                    .flatten(),
                                supersedes: None,
                                resume_from_token: None,
                            },
                            child_authority,
                            LiveInvalidationAdmission {
                                connection: target.invalidation_connection.clone(),
                                effect_fence: Some(target.effect_fence.clone()),
                                #[cfg(any(test, feature = "test-support"))]
                                session_mode: false,
                            },
                            invocation,
                        )
                        .map_err(|error| {
                            refuse(code::QUERY_FAILED, "mixed live registration failed")
                                .with_details(json!({
                                    "function": name,
                                    "cause": error.diagnostic.code,
                                }))
                        })?;
                    let rows = output
                        .snapshot
                        .map(|snapshot| snapshot.rows)
                        .unwrap_or_default();
                    let authorization = output.authorization_scope.map(|scope| {
                        crate::bundle::BundleAuthorization {
                            scope,
                            invalidation: output.authorization_invalidation,
                        }
                    });
                    (
                        rows,
                        output.resume,
                        Some(output.subscription_id),
                        authorization,
                        crate::bundle::MixedBundleDeliveryV2::RegisteredLive {
                            node_plan_hash: admission.node_plan_hash,
                        },
                    )
                } else {
                    let rows = invocation.output.rows;
                    let resume = rqs_eligibility(&function).and_then(|kind| {
                        let digest = crate::rqs::ResultDigest::from_rows(kind, &rows).ok()?;
                        let query_artifact =
                            serde_json::to_value(&function).ok().and_then(|value| {
                                crate::rqs_contract::query_artifact_hash(&value).ok()
                            })?;
                        let args_hash = crate::rqs_contract::args_hash(&args).ok()?;
                        self.mint_resume_wire(
                            &query_artifact,
                            &args_hash,
                            commit_version,
                            kind,
                            digest.published(),
                        )
                    });
                    (
                        rows,
                        resume,
                        None,
                        None,
                        crate::bundle::MixedBundleDeliveryV2::ReadOnly {
                            node_plan_hash: admission.node_plan_hash,
                        },
                    )
                };
                total_rows += rows.len();
                total_bytes += serde_json::to_vec(&rows)
                    .map(|bytes| bytes.len())
                    .unwrap_or(0);
                if total_rows > bundle::BUNDLE_MAX_ROWS {
                    return Err(refuse(code::LIMIT_ROWS, "mixed bundle row limit exceeded"));
                }
                if total_bytes > bundle::BUNDLE_MAX_BYTES {
                    return Err(refuse(
                        code::LIMIT_BYTES,
                        "mixed bundle byte limit exceeded",
                    ));
                }
                if started.elapsed().as_millis() as u64 > bundle::BUNDLE_MAX_EVAL_MS {
                    return Err(refuse(code::LIMIT_TIME, "mixed bundle time limit exceeded"));
                }
                entries.push(crate::bundle::BundleEntry {
                    function: name,
                    args,
                    rows,
                    resume,
                    subscription_id,
                    authorization,
                    delivery: Some(delivery),
                });
            }
            Ok(())
        })();
        if let Err(error) = result {
            self.purge_connection_topology(&target.connection_id, &target.effect_fence);
            return Err(error);
        }
        let read_only_children = entries.len().saturating_sub(live_children);
        Ok(crate::bundle::BundleResponse {
            format_version: Some(2),
            profile: Some("mixed-route.v2".to_owned()),
            plan_hash: Some(profile.plan_hash.clone()),
            commit_version,
            generation,
            version_stream,
            entries,
            connection: None,
            aggregate: Some(crate::bundle::MixedBundleAggregateV2 {
                kind: "mixed".to_owned(),
                weakest: "read-only".to_owned(),
                live_children,
                read_only_children,
            }),
        })
    }

    pub fn subscribe_live(
        &mut self,
        name: &str,
        input: LiveSubscribeInput,
    ) -> SnapbackResult<LiveSubscribeOutput> {
        // The live-subscribe lane consults the persisted migration fence
        // (LLP 0081 §4's lane registry).
        self.db.ensure_migration_lane_open()?;
        let admission = self.admission.admit_dev()?;
        let authority = InvocationGate::prepare_admitted_authority(
            InvocationSource::LiveInitialQuery,
            AuthMode::Dev,
            ServerProfile::Dev,
            admission,
            &WireAuthorityFields::default(),
            ResolvedAppAuthority::dev_from_auth(&input.input.auth),
            None,
        )?;
        self.subscribe_live_prepared_with_invalidation(
            name,
            input,
            authority,
            LiveInvalidationAdmission::default(),
        )
    }

    // Compatibility seam for direct prepared callers; production needs the
    // richer invalidation admission and calls the method below.
    #[allow(dead_code)]
    pub(crate) fn subscribe_live_prepared(
        &mut self,
        name: &str,
        input: LiveSubscribeInput,
        authority: PreparedAuthority,
    ) -> SnapbackResult<LiveSubscribeOutput> {
        self.subscribe_live_prepared_with_invalidation(
            name,
            input,
            authority,
            LiveInvalidationAdmission::default(),
        )
    }

    /// Compatibility scaffold for engine-owned protocol unit tests. Cross-crate
    /// tests use the HostPlan-only wrapper in `test_support` so enabling the
    /// feature cannot expose a caller-selected JavaScript evaluator.
    #[cfg(any(test, feature = "test-support"))]
    pub(crate) fn subscribe_live_with_invalidation(
        &mut self,
        name: &str,
        input: LiveSubscribeInput,
        invalidation: LiveInvalidationAdmission,
    ) -> SnapbackResult<LiveSubscribeOutput> {
        self.subscribe_live_with_invalidation_generation(name, input, invalidation, None)
    }

    #[cfg(feature = "test-support")]
    // @ref LLP 0283#f-1--the-authorization-model-is-not-closed-blocking-publication — a caller-selectable feature may expose declarative fixtures, never an executable-code evaluator.
    pub(crate) fn require_host_plan_for_test_support(&self, name: &str) -> SnapbackResult<()> {
        let function = self.function(name)?;
        if matches!(function.runtime, FunctionRuntime::HostPlan(_)) {
            return Ok(());
        }
        Err(SnapbackError::error(
            "SNAPBACK_TEST_SUPPORT_RUNTIME_FORBIDDEN",
            "runtime",
            "the public test-support surface only admits declarative HostPlan functions",
        ))
    }

    #[cfg(any(test, feature = "test-support"))]
    fn subscribe_live_with_invalidation_generation(
        &mut self,
        name: &str,
        input: LiveSubscribeInput,
        invalidation: LiveInvalidationAdmission,
        expected_generation: Option<&ArtifactGeneration>,
    ) -> SnapbackResult<LiveSubscribeOutput> {
        let active_mode = if invalidation.session_mode {
            AuthMode::Sessions
        } else {
            AuthMode::Dev
        };
        let resolved = if active_mode == AuthMode::Sessions {
            ResolvedAppAuthority::Anonymous
        } else {
            ResolvedAppAuthority::dev_from_auth(&input.input.auth)
        };
        let authority = InvocationGate::prepare_authority(
            InvocationSource::LiveInitialQuery,
            active_mode,
            ServerProfile::Test,
            0,
            0,
            &WireAuthorityFields::default(),
            resolved,
        )?;
        self.subscribe_live_prepared_with_invalidation_generation(
            name,
            input,
            authority,
            invalidation,
            expected_generation,
            None,
        )
    }

    fn stage_local_live_effect<T>(
        &mut self,
        connection_id: String,
        effect_fence: crate::ephemeral::ConnectionEffectFence,
        reserved_subscription_slots: usize,
        reservation_keys: impl IntoIterator<Item = String>,
        plan: T,
    ) -> SnapbackResult<StagedLocalLiveEffect<T>> {
        let stale_stage_ids = self
            .pending_local_live_effects
            .iter()
            .filter_map(|(stage_id, registration)| {
                let stale = registration.control.upgrade().is_none_or(|control| {
                    matches!(
                        control.state.load(Ordering::Acquire),
                        LOCAL_LIVE_STAGE_ABANDONED
                            | LOCAL_LIVE_STAGE_TERMINAL
                            | LOCAL_LIVE_STAGE_FINALIZED
                    )
                });
                stale.then(|| stage_id.clone())
            })
            .collect::<Vec<_>>();
        for stage_id in stale_stage_ids {
            self.pending_local_live_effects.remove(&stage_id);
        }
        if self.pending_local_live_effects.len() >= MAX_PENDING_LOCAL_LIVE_EFFECTS {
            return Err(SnapbackError::error(
                "SNAPBACK_LIVE_STAGE_CAPACITY",
                "realtime",
                "the pending local live-effect registry is at capacity",
            )
            .with_details(json!({ "limit": MAX_PENDING_LOCAL_LIVE_EFFECTS })));
        }
        let reservation_keys = reservation_keys.into_iter().collect::<BTreeSet<_>>();
        if self
            .pending_local_live_effects
            .values()
            .any(|registration| !registration.reservation_keys.is_disjoint(&reservation_keys))
        {
            return Err(SnapbackError::error(
                "SNAPBACK_LIVE_STAGE_CONFLICT",
                "realtime",
                "another staged live effect owns the same subscription or obligation precondition",
            ));
        }
        if reserved_subscription_slots > 0 {
            let pending_global = self
                .pending_local_live_effects
                .values()
                .map(|registration| registration.reserved_subscription_slots)
                .sum::<usize>();
            if self
                .subscriptions
                .len()
                .saturating_add(pending_global)
                .saturating_add(reserved_subscription_slots)
                > MAX_LIVE_SUBSCRIPTIONS
            {
                return Err(SnapbackError::error(
                    "SNAPBACK_SUBSCRIPTION_GLOBAL_LIMIT",
                    "realtime",
                    format!(
                        "the durable subscription registry is limited to {MAX_LIVE_SUBSCRIPTIONS} rows"
                    ),
                )
                .with_details(json!({ "limit": MAX_LIVE_SUBSCRIPTIONS })));
            }
            let published_connection = self
                .subscriptions
                .values()
                .filter(|subscription| subscription.connection_id == connection_id)
                .count();
            let pending_connection = self
                .pending_local_live_effects
                .values()
                .filter(|registration| registration.connection_id == connection_id)
                .map(|registration| registration.reserved_subscription_slots)
                .sum::<usize>();
            if published_connection
                .saturating_add(pending_connection)
                .saturating_add(reserved_subscription_slots)
                > MAX_LIVE_SUBSCRIPTIONS_PER_CONNECTION
            {
                return Err(SnapbackError::error(
                    "SNAPBACK_SUBSCRIPTION_CONNECTION_LIMIT",
                    "realtime",
                    format!(
                        "one connection is limited to {MAX_LIVE_SUBSCRIPTIONS_PER_CONNECTION} durable subscriptions"
                    ),
                )
                .with_details(json!({ "limit": MAX_LIVE_SUBSCRIPTIONS_PER_CONNECTION })));
            }
        }
        let stage_id = crate::ids::mint_time_ordered(crate::ids::Kind::Stage);
        let control = Arc::new(LocalLiveStageControl {
            state: AtomicU8::new(LOCAL_LIVE_STAGE_PENDING),
            connection_id: connection_id.clone(),
            effect_fence: effect_fence.clone(),
        });
        let replaced = self.pending_local_live_effects.insert(
            stage_id.clone(),
            PendingLocalLiveEffectRegistration {
                connection_id,
                effect_fence,
                reserved_subscription_slots,
                reservation_keys,
                control: Arc::downgrade(&control),
            },
        );
        debug_assert!(replaced.is_none(), "UUIDv7 live stage id was reused");
        Ok(StagedLocalLiveEffect {
            stage_id,
            control,
            plan: Arc::new(plan),
        })
    }

    fn claim_local_live_effect<T>(
        &mut self,
        stage: &StagedLocalLiveEffect<T>,
    ) -> SnapbackResult<LocalLiveFinalizationClaim> {
        let registered = self
            .pending_local_live_effects
            .get(&stage.stage_id)
            .and_then(|registration| registration.control.upgrade())
            .is_some_and(|control| Arc::ptr_eq(&control, &stage.control));
        if !registered {
            return Err(local_live_stage_unavailable());
        }
        match stage.control.state.compare_exchange(
            LOCAL_LIVE_STAGE_COMMITTED,
            LOCAL_LIVE_STAGE_FINALIZING,
            Ordering::AcqRel,
            Ordering::Acquire,
        ) {
            Ok(_) => Ok(LocalLiveFinalizationClaim {
                control: stage.control.clone(),
                completed: false,
            }),
            Err(LOCAL_LIVE_STAGE_ABANDONED | LOCAL_LIVE_STAGE_TERMINAL) => {
                Err(local_live_stage_unavailable())
            }
            Err(_) => Err(local_live_stage_corrupt()),
        }
    }

    fn complete_local_live_effect<T>(
        &mut self,
        stage: &StagedLocalLiveEffect<T>,
        claim: LocalLiveFinalizationClaim,
    ) -> SnapbackResult<()> {
        let registered = self
            .pending_local_live_effects
            .get(&stage.stage_id)
            .and_then(|registration| registration.control.upgrade())
            .is_some_and(|control| Arc::ptr_eq(&control, &stage.control));
        if !registered || !Arc::ptr_eq(&claim.control, &stage.control) {
            return Err(local_live_stage_corrupt());
        }
        claim.complete()?;
        self.pending_local_live_effects.remove(&stage.stage_id);
        Ok(())
    }

    pub fn abandon_prepared_live_effect<T>(&mut self, stage: &StagedLocalLiveEffect<T>) {
        stage.abandon();
        if matches!(
            stage.control.state.load(Ordering::Acquire),
            LOCAL_LIVE_STAGE_ABANDONED | LOCAL_LIVE_STAGE_TERMINAL
        ) {
            self.pending_local_live_effects.remove(&stage.stage_id);
        }
    }

    #[cfg(any(test, feature = "test-support"))]
    pub fn staged_live_effect_counts_for_test(&self) -> (usize, usize) {
        (
            self.pending_local_live_effects.len(),
            self.subscriptions.len(),
        )
    }

    fn finalize_prepared_live_effect<T: Clone, R>(
        &mut self,
        stage: &StagedLocalLiveEffect<T>,
        operation: impl FnOnce(&mut Self, T) -> SnapbackResult<R>,
    ) -> SnapbackResult<R> {
        let claim = self.claim_local_live_effect(stage)?;
        let plan = stage.plan().clone();
        let result = operation(self, plan);
        // An operation error is a consumed connection act, not a retryable
        // committed stage. Marking it finalized also releases reservations.
        self.complete_local_live_effect(stage, claim)?;
        result
    }

    fn terminalize_local_live_effects(
        &mut self,
        connection_id: &str,
        effect_fence: Option<&crate::ephemeral::ConnectionEffectFence>,
    ) {
        let terminal_stage_ids = self
            .pending_local_live_effects
            .iter()
            .filter(|(_, registration)| {
                registration.connection_id == connection_id
                    && effect_fence.is_none_or(|expected| &registration.effect_fence == expected)
            })
            .map(|(stage_id, _)| stage_id.clone())
            .collect::<Vec<_>>();
        for stage_id in terminal_stage_ids {
            if let Some(registration) = self.pending_local_live_effects.remove(&stage_id)
                && let Some(control) = registration.control.upgrade()
            {
                loop {
                    let observed = control.state.load(Ordering::Acquire);
                    if matches!(
                        observed,
                        LOCAL_LIVE_STAGE_ABANDONED
                            | LOCAL_LIVE_STAGE_TERMINAL
                            | LOCAL_LIVE_STAGE_FINALIZED
                    ) {
                        break;
                    }
                    if observed == LOCAL_LIVE_STAGE_FINALIZING {
                        // Finalization and topology purge both require
                        // `&mut LocalSnapback`, so this state cannot be
                        // observed by another local owner.
                        debug_assert!(false, "live stage finalization overlapped terminal purge");
                        break;
                    }
                    if control
                        .state
                        .compare_exchange(
                            observed,
                            LOCAL_LIVE_STAGE_TERMINAL,
                            Ordering::AcqRel,
                            Ordering::Acquire,
                        )
                        .is_ok()
                    {
                        break;
                    }
                }
            }
        }
    }

    fn terminalize_all_local_live_effects(&mut self) {
        let registrations = std::mem::take(&mut self.pending_local_live_effects);
        for registration in registrations.into_values() {
            if let Some(control) = registration.control.upgrade() {
                let _ =
                    control
                        .state
                        .fetch_update(
                            Ordering::AcqRel,
                            Ordering::Acquire,
                            |observed| match observed {
                                LOCAL_LIVE_STAGE_PENDING | LOCAL_LIVE_STAGE_COMMITTED => {
                                    Some(LOCAL_LIVE_STAGE_TERMINAL)
                                }
                                _ => None,
                            },
                        );
            }
        }
    }

    pub(crate) fn subscribe_live_prepared_with_invalidation(
        &mut self,
        name: &str,
        input: LiveSubscribeInput,
        authority: PreparedAuthority,
        invalidation: LiveInvalidationAdmission,
    ) -> SnapbackResult<LiveSubscribeOutput> {
        self.subscribe_live_prepared_with_invalidation_generation(
            name,
            input,
            authority,
            invalidation,
            None,
            None,
        )
    }

    /// Install a live child from rows/dependencies already evaluated inside
    /// the mixed bundle's shared pinned snapshot. Registration must consume
    /// this invocation rather than silently execute a second snapshot.
    fn subscribe_live_prepared_from_pinned_bundle(
        &mut self,
        name: &str,
        input: LiveSubscribeInput,
        authority: PreparedAuthority,
        invalidation: LiveInvalidationAdmission,
        invocation: QueryInvocation,
    ) -> SnapbackResult<LiveSubscribeOutput> {
        self.subscribe_live_prepared_with_invalidation_generation(
            name,
            input,
            authority,
            invalidation,
            None,
            Some(invocation),
        )
    }

    fn subscribe_live_prepared_with_invalidation_generation(
        &mut self,
        name: &str,
        input: LiveSubscribeInput,
        authority: PreparedAuthority,
        invalidation: LiveInvalidationAdmission,
        expected_generation: Option<&ArtifactGeneration>,
        pinned_bundle_invocation: Option<QueryInvocation>,
    ) -> SnapbackResult<LiveSubscribeOutput> {
        if authority.source() != InvocationSource::LiveInitialQuery {
            return Err(SnapbackError::error(
                "SNAPBACK_INVOCATION_SOURCE_INVALID",
                "auth",
                "live subscribe requires LiveInitialQuery authority",
            ));
        }
        authority.validate_admission("live subscribe preparation")?;
        let effect_fence = invalidation.effect_fence.clone();
        let authority_subject = authority.resolved().invalidation_subject();
        let reserved_live = is_reserved_live_function(name);
        // Sessions-mode establishment is admitted (2026-07-31): LLP 0053's
        // §Asset read-authorization inputs classification already covers every
        // input the projection reads, and the sealed sessions caller flows
        // through `asset_caller_principal` like any other resolved authority.
        // The projection is deliberately not `authority_independent`, so in
        // sessions mode it is auth-scoped below: protocol negotiation, a
        // query namespace, obligation registration, and the witnessed
        // re-run/drain lane all apply — never a plain unwitnessed replace.
        let function = match reserved_live_definition(name) {
            Some(definition) => definition?,
            None => self.function(name)?.clone(),
        };
        let proof_namespace = input.authorization_namespace.clone();
        self.validate_expected_generation(&authority, expected_generation)?;
        if function.kind != FunctionKind::LiveQuery {
            return Err(SnapbackError::error(
                "SNAPBACK_FUNCTION_NOT_LIVE",
                "runtime",
                format!("{name} is not a live query"),
            ));
        }
        let prepared_invocation = InvocationGate::prepare_function(authority.clone(), &function)?;
        let retained_authority = prepared_invocation.retain_live_owner()?;
        let caller_details = retained_authority.telemetry_caller_details();
        // @ref LLP 0055#audit — establishment derives the block once from the
        // retained (immutable) authority; renew/resubscribe re-answers this
        // exact block rather than re-deriving from the presenting caller.
        let attribution = retained_authority.function_attribution();
        self.prepare_live_rerun_authority(
            &retained_authority,
            authority.admission_lease().clone(),
        )?;
        let publication_authority = authority.clone();
        // @ref LLP 0053#invalidation-is-an-obligation-not-a-message — an
        // auth-scoped live subscription is admitted only when its connection
        // negotiated the exact protocol and supplied a stable query namespace.
        self.touch_connection(&input.connection_id, now_millis());
        let auth_scoped = authority.active_mode() == AuthMode::Sessions
            && !owner_admits_authority_independence(&function);
        if auth_scoped && self.auth_invalidation.is_none() {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_INVALIDATION_UNAVAILABLE",
                "auth",
                "session-mode auth-scoped live queries require the installed invalidation protocol",
            ));
        }
        let authorization_admission = if auth_scoped {
            let connection = invalidation.connection.ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_AUTH_INVALIDATION_CLIENT_UNSUPPORTED",
                    "auth",
                    "open the connection with `authInvalidationProtocol: 1` \
                     (or configure SnapbackClient with that option) before subscribing \
                     to an auth-scoped live query",
                )
            })?;
            if connection.protocol_version
                != crate::auth::invalidation::AUTH_INVALIDATION_PROTOCOL_VERSION
            {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_INVALIDATION_CLIENT_UNSUPPORTED",
                    "auth",
                    "open the connection with `authInvalidationProtocol: 1` \
                     (or configure SnapbackClient with that option) before subscribing \
                     to an auth-scoped live query",
                ));
            }
            let namespace = input.authorization_namespace.clone().ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_AUTH_INVALIDATION_NAMESPACE_REQUIRED",
                    "auth",
                    "set `authorizationNamespace` to an object with `clientStoreId`, \
                     canonical `queryKey`, and positive `queryInstanceId` before \
                     subscribing to an auth-scoped live query",
                )
            })?;
            namespace.validate()?;
            let state = self
                .auth_invalidation
                .as_ref()
                .expect("auth-scoped admission checked installed state");
            if !state.accepts_connection(&connection) {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_INVALIDATION_CLIENT_UNSUPPORTED",
                    "auth",
                    "reopen the connection with `authInvalidationProtocol: 1`: \
                     its authorization-invalidation expectation is no longer current",
                ));
            }
            Some((connection, namespace))
        } else {
            None
        };

        let subscription_input = retained_authority.canonicalize_input(input.input);
        if matches!(
            function.runtime,
            FunctionRuntime::HostPlan(HandlerPlan::BoundedChildrenQuery(_))
        ) && subscription_input
            .args
            .get("cursor")
            .is_some_and(|cursor| !cursor.is_null())
        {
            return Err(SnapbackError::error(
                "SNAPBACK_BOUNDED_CHILDREN_LIVE_CURSOR_UNSUPPORTED",
                "query",
                "bounded children live subscriptions support the first page only",
            ));
        }
        if matches!(
            function.runtime,
            FunctionRuntime::HostPlan(
                HandlerPlan::SnapshotBatch(_) | HandlerPlan::SnapshotBatchV2(_)
            )
        ) && subscription_input
            .args
            .get("cursor")
            .is_some_and(|cursor| !cursor.is_null())
        {
            return Err(SnapbackError::error(
                "SNAPBACK_SNAPSHOT_BATCH_LIVE_CURSOR_UNSUPPORTED",
                "query",
                "snapshot batch live subscriptions support only the cursor-free first page",
            ));
        }

        // RQS eligibility + token admission (LLP 0090 D1.1 / rollout step 1).
        // Eligibility keys minting AND admission alike; auth-scoped
        // subscriptions can never be eligible, so minting is suppressed for
        // them by construction. Every token refusal answers with rung 3.
        let rqs_eligibility = rqs_eligibility(&function);
        let mut resume_refusal: Option<&'static str> = None;
        let mut admitted_resume: Option<crate::rqs::ResumeTokenBody> = None;
        if let Some(presented) = input.resume_from_token.as_ref() {
            self.live_delivery.resume.attempted += 1;
            match self.admit_resume_token(
                presented,
                &function,
                &subscription_input.args,
                rqs_eligibility,
            ) {
                Ok(body) => admitted_resume = Some(body),
                Err(code) => {
                    resume_refusal = Some(code);
                    *self
                        .live_delivery
                        .resume
                        .refused
                        .entry(code.to_owned())
                        .or_default() += 1;
                }
            }
        }

        // A valid explicit supersession is a net-zero replacement. Identify
        // it before admission, but do not remove it until the new snapshot
        // succeeds: a query failure must leave the old live authority intact.
        // Unknown ids remain the protocol's documented quiet no-op and do not
        // release capacity. Known foreign owners fail closed.
        let supersession_requested = input.supersedes.is_some();
        let superseded_subscription_id = match input.supersedes.as_ref() {
            Some(old_id) => match self.subscriptions.get(old_id) {
                Some(existing)
                    if existing.connection_id == input.connection_id
                        && existing.is_owned_by(&authority, effect_fence.as_ref()) =>
                {
                    Some(old_id.clone())
                }
                Some(existing) => {
                    return Err(live_owner_mismatch(&existing.id, &authority));
                }
                None => None,
            },
            None => None,
        };
        let release = usize::from(superseded_subscription_id.is_some());

        // @ref LLP 0032#phase-3--lifecycle-and-resource-hardening — retained
        // resource tables must have hard refusal limits. Check before running
        // the initial query so a caller at capacity cannot spend handler/DB
        // work on a snapshot the server is forbidden to retain.
        if self.subscriptions.len().saturating_sub(release) >= MAX_LIVE_SUBSCRIPTIONS {
            return Err(SnapbackError::error(
                "SNAPBACK_SUBSCRIPTION_GLOBAL_LIMIT",
                "realtime",
                format!(
                    "the durable subscription registry is limited to {MAX_LIVE_SUBSCRIPTIONS} rows"
                ),
            )
            .with_details(json!({ "limit": MAX_LIVE_SUBSCRIPTIONS })));
        }
        let connection_subscriptions = self
            .subscriptions
            .values()
            .filter(|subscription| subscription.connection_id == input.connection_id)
            .count()
            .saturating_sub(release);
        if connection_subscriptions >= MAX_LIVE_SUBSCRIPTIONS_PER_CONNECTION {
            return Err(SnapbackError::error(
                "SNAPBACK_SUBSCRIPTION_CONNECTION_LIMIT",
                "realtime",
                format!(
                    "one connection is limited to {MAX_LIVE_SUBSCRIPTIONS_PER_CONNECTION} durable subscriptions"
                ),
            )
            .with_details(json!({
                "limit": MAX_LIVE_SUBSCRIPTIONS_PER_CONNECTION,
            })));
        }

        let eval_queue_ms = crate::spike_trace::timestamp_ms();
        let eval_start_ms = crate::spike_trace::timestamp_ms();
        let query = if let Some(query) = pinned_bundle_invocation {
            query
        } else if reserved_live {
            self.reserved_live_invocation(&authority, name, &subscription_input)?
        } else {
            let correlation = telemetry_correlation(&subscription_input.correlation);
            let span = self.telemetry.start_classified_span(
                crate::telemetry_contract::OperationClassIdV1::FUNCTION_QUERY,
                name,
                correlation.as_deref(),
                caller_details.clone(),
            );
            let mut result = crate::runtime::with_runtime_log_telemetry(
                self.telemetry.clone(),
                correlation,
                || {
                    execute_query_invocation(
                        Some(&self.db),
                        &function,
                        name,
                        DbRead::Live(&self.db),
                        &self.permission_epochs,
                        subscription_input.clone(),
                        &prepared_invocation,
                        Some(&self.warm_vms),
                        Some(RelationalCursorAuthority {
                            app_id: &self.functions.app_id,
                            keyring: &self.resume_keyring,
                            schema_hash: self.db.schema().schema_hash.as_deref(),
                            function_bundle_hash: self.functions.bundle_hash.as_deref(),
                            function_publication_generation: self.app_generation,
                            target_profile: self.db.schema().target_profile.as_deref(),
                        }),
                        if proof_namespace
                            .as_ref()
                            .is_some_and(|namespace| namespace.query_key.starts_with("qmk1."))
                            && rqs_eligibility.is_some()
                        {
                            Some(1_024)
                        } else {
                            None
                        },
                        None,
                    )
                },
            );
            finish_function_observation(span, &mut result);
            result?
        };
        let eval_finish_ms = crate::spike_trace::timestamp_ms();
        let permission_epochs = permission_epochs_from_dependencies(&query.read_dependencies);

        // Server-held RQS digest state for eligible subscriptions, the fresh
        // token, and the admission-ladder rung (LLP 0090 D1.3, rungs 1 & 3).
        // Everything from proof to registration happens under this one &mut
        // cut — the local arm's serialization cut — so no commit can fall
        // between proof, registration, and the answer (the atomicity rule).
        let head_version = query.output.version;
        let rqs_state = rqs_eligibility.and_then(|kind| {
            let query_artifact = serde_json::to_value(&function)
                .ok()
                .and_then(|value| crate::rqs_contract::query_artifact_hash(&value).ok());
            let args_hash = crate::rqs_contract::args_hash(&subscription_input.args).ok();
            match (
                query_artifact,
                args_hash,
                crate::rqs::ResultDigest::from_rows(kind, &query.output.rows),
            ) {
                (Some(query_artifact), Some(args_hash), Ok(digest)) => Some(RqsLiveState {
                    query_artifact,
                    args_hash,
                    digest,
                }),
                _ => {
                    // Mint-time refusal (LLP 0091 §0A.2): no token, never a
                    // wrong digest.
                    self.live_delivery.resume.mint_refusals += 1;
                    None
                }
            }
        });
        let mut fresh_resume = rqs_state.as_ref().and_then(|state| {
            self.mint_resume_wire(
                &state.query_artifact,
                &state.args_hash,
                head_version,
                state.digest.kind,
                state.digest.published(),
            )
        });
        let mut answer_current_as_of = false;
        let mut answer_delta: Option<Vec<LiveDeltaWireOp>> = None;
        if let Some(body) = admitted_resume.as_ref() {
            let distance = head_version.saturating_sub(body.version);
            self.live_delivery.resume.last_journal_distance = distance;
            self.live_delivery.resume.max_journal_distance =
                self.live_delivery.resume.max_journal_distance.max(distance);
            let current_digest = rqs_state.as_ref().map(|state| state.digest.published());
            let refuse = |stats: &mut LiveDeliveryStats, code: &'static str| {
                *stats.resume.refused.entry(code.to_owned()).or_default() += 1;
                Some(code)
            };
            if body.version == head_version
                && current_digest.as_deref() == Some(body.content_digest.as_str())
                && fresh_resume.is_some()
            {
                // Rung 1, global no-commit proof: nothing committed since the
                // token's version, so the caller's held rows are current.
                answer_current_as_of = true;
            } else if body.version == head_version {
                // Same version, different digest: the result is not a pure
                // function of (state, args) after all — fail closed to rung 3
                // (counted under the policy-replacement code; the registry
                // has no more specific cause).
                resume_refusal = refuse(
                    &mut self.live_delivery,
                    crate::rqs::refusal::POLICY_REPLACED,
                );
            } else {
                match self.journal_resume_requires_resnapshot(body.version) {
                    Ok(false) => {
                        // The journal floor holds. Rung 2 (LLP 0090 D1.3,
                        // steps 5a+6): a DK-3-analyzable unordered (`mset1`)
                        // query with a client membership witness replays
                        // exact deltas; without a witness (or for `seq1`)
                        // the rung-1 table-set arm still always falls
                        // through to rung 3 — no complete certified
                        // dependency-summary artifact exists yet (cluster
                        // 0C) — under its own telemetry cause.
                        let witness = input
                            .resume_from_token
                            .as_ref()
                            .and_then(|presented| presented.membership_witness.as_ref());
                        let replay = match (witness, rqs_state.as_ref(), fresh_resume.as_ref()) {
                            (Some(witness), Some(state), Some(_))
                                if state.digest.kind == crate::rqs_contract::DigestKind::Mset1 =>
                            {
                                Some(self.rqs_attempt_delta_replay(
                                    witness,
                                    body,
                                    &function,
                                    state,
                                    &query.output.rows,
                                ))
                            }
                            _ => None,
                        };
                        match replay {
                            Some(Ok(ops)) if ops.is_empty() => {
                                // Every journal-affected row reverted or
                                // never intersected the result: the held
                                // rows are current at head — the verified
                                // witness upgrades the answer to rung 1.
                                answer_current_as_of = true;
                            }
                            Some(Ok(ops)) => answer_delta = Some(ops),
                            Some(Err(code)) => {
                                resume_refusal = refuse(&mut self.live_delivery, code);
                            }
                            None => {
                                self.live_delivery.resume.no_certified_summary += 1;
                            }
                        }
                    }
                    _ => {
                        resume_refusal =
                            refuse(&mut self.live_delivery, crate::rqs::refusal::JOURNAL_FLOOR);
                    }
                }
            }
        }
        if input.resume_from_token.is_some() {
            if answer_current_as_of {
                self.live_delivery.resume.current_as_of_answers += 1;
            } else if answer_delta.is_some() {
                self.live_delivery.resume.delta_replay_answers += 1;
            } else {
                self.live_delivery.resume.fresh_replace_answers += 1;
            }
        }
        let answered_without_rows = answer_current_as_of || answer_delta.is_some();
        // LLP 0094 declares LiveSubscribeOutput open and explicitly permits
        // additive optional server fields. Existing classes still require
        // response-carried bytes. The single-table adoption class is the one
        // narrow exception: the server has re-evaluated the exact result at
        // this serialization cut, while the client proves it holds those same
        // bytes before atomically switching stores.
        // @ref LLP 0166#d6--resume-delta-and-the-shipped-rqs-machinery — a
        // rung-1/rung-2 established result may carry the ordinary proof used
        // by the connected prove arm.
        let prove_held_single_table = answered_without_rows
            && rqs_eligibility.is_some()
            && proof_namespace
                .as_ref()
                .is_some_and(|namespace| namespace.query_key.starts_with("qmk1."));
        // Mint before publishing any subscription/supersession effect so
        // issuance refusal stays atomic.
        let (completeness_proof, authorization_witness) =
            if answered_without_rows && !prove_held_single_table {
                (None, None)
            } else {
                self.issue_completeness_proof(
                    &function,
                    &subscription_input,
                    &query.output,
                    proof_namespace.as_ref(),
                    &[],
                )?
                .map_or((None, None), |(proof, witness, _)| {
                    (Some(proof), Some(witness))
                })
            };
        // @ref LLP 0032#phase-1--safety-floor-and-confirmed-defects — S2:
        // subscription ids are unguessable bearer capabilities, not enumerable
        // counters; they share the runtime's UUIDv7 id source.
        let subscription_id = crate::ids::mint_time_ordered(crate::ids::Kind::Subscription);
        if crate::spike_trace::enabled() {
            let (initial_frame_kind, initial_frame_bytes) = if answer_current_as_of {
                ("current_as_of", 0)
            } else if let Some(ops) = answer_delta.as_ref() {
                (
                    "live_delta",
                    serde_json::to_vec(ops)
                        .map(|payload| payload.len())
                        .unwrap_or(0),
                )
            } else {
                (
                    "snapshot",
                    serde_json::to_vec(&query.output.rows)
                        .map(|payload| payload.len())
                        .unwrap_or(0),
                )
            };
            crate::spike_trace::eval(
                &subscription_id,
                &input.connection_id,
                &[],
                eval_queue_ms,
                eval_start_ms,
                eval_finish_ms,
                initial_frame_bytes,
                Some(initial_frame_kind),
                head_version,
                "finish",
                None,
            );
        }
        let _publication = publication_authority.effect_guard("live subscribe publication")?;
        self.touch_connection(&input.connection_id, now_millis());
        let mut authorization_scope = None;
        let mut authorization_invalidation = None;
        let mut scope_retirements = Vec::new();
        let mut registered_scope_cleanup = None;
        let mut subscription_quarantine_entry = None;
        let subscription_authorization =
            if let Some((connection, namespace)) = authorization_admission {
                let state = self
                    .auth_invalidation
                    .as_mut()
                    .expect("auth-scoped admission checked installed state");
                let scope_id = ScopeId::Subscription {
                    issuer_id: connection.issuer_id.clone(),
                    namespace: namespace.clone(),
                    scope_sequence: state.issuer.reserve_scope_sequence()?,
                    connection_generation: connection.connection_generation,
                    subscription_id: subscription_id.clone(),
                };
                let connection_scope = ScopeId::Connection {
                    issuer_id: connection.issuer_id,
                    connection_generation: connection.connection_generation,
                };
                let owner_continuity_id =
                    crate::ids::mint_time_ordered(crate::ids::Kind::OwnerContinuity);
                let registration = (|| {
                    state
                        .obligations
                        .register_live_scope(scope_id.clone(), owner_continuity_id.clone())?;
                    let (inherited, entered) = state
                        .obligations
                        .register_connection_child_with_quarantine_lifecycle(
                            &connection_scope,
                            scope_id.clone(),
                        )?;
                    if entered {
                        subscription_quarantine_entry = inherited.clone();
                    }
                    #[cfg(test)]
                    if FAIL_NEXT_LIVE_SCOPE_REGISTRATION.with(|fail| fail.replace(false)) {
                        return Err(SnapbackError::error(
                            "SNAPBACK_TEST_LIVE_SCOPE_REGISTRATION_FAILED",
                            "test",
                            "injected failure after live scope child registration",
                        ));
                    }
                    if inherited.is_some() {
                        let witness = CompositeWitness {
                            authorization: state.obligations.expectation().authorization.clone(),
                            data: Some(DataWitness {
                                version_stream: state.version_stream.clone(),
                                min_commit_version: query.output.version,
                            }),
                        };
                        let snapshot_identity =
                            authorization_resolution_snapshot_identity(&query.output)?;
                        state.obligations.issue_resolution(
                            &scope_id,
                            ResolutionKind::Snapshot,
                            witness,
                            &snapshot_identity,
                        )?;
                        authorization_invalidation = state.obligations.projection(&scope_id);
                    }
                    Ok::<(), SnapbackError>(())
                })();
                if let Err(error) = registration {
                    state
                        .obligations
                        .rollback_unpublished_live_scope(&scope_id, &connection_scope);
                    return Err(error);
                }
                registered_scope_cleanup = Some((scope_id.clone(), connection_scope));
                authorization_scope = Some(scope_id.clone());
                Some(LiveSubscriptionAuthorization {
                    scope_id,
                    namespace,
                    authority_subject,
                    owner_continuity_id,
                })
            } else {
                None
            };

        // Superseded-subscription GC, EXPLICIT protocol (LLP 0034 §10.1
        // residual; ENG-22478 review fix A): the kit names the subscription
        // its own resubscribe replaces and the server disposes exactly that
        // id — never inferred from matching identity, so two legitimate
        // identical subscribers (two components sharing a query on one
        // connection) coexist. An unknown id is a quiet no-op: reconnects
        // race disconnect teardown, which may have dropped it already.
        let superseded_witness = superseded_subscription_id.clone();
        let supersession_refusal = (supersession_requested && superseded_subscription_id.is_none())
            .then_some("SNAPBACK_LIVE_SUPERSESSION_TARGET_UNKNOWN".to_owned());
        if let Some(old_id) = superseded_subscription_id {
            let retired_scope = self
                .subscriptions
                .get(&old_id)
                .and_then(|subscription| subscription.authorization.as_ref())
                .cloned()
                .map(|authorization| authorization.scope_id);
            let prepared_retirement =
                match (self.auth_invalidation.as_ref(), retired_scope.as_ref()) {
                    (Some(state), Some(scope)) => {
                        match state.prepare_scope_retirement_authenticated(scope) {
                            Ok((candidate, retirement)) => {
                                Some((scope.clone(), candidate, retirement))
                            }
                            Err(error) => {
                                if let (Some(state), Some((scope, connection_scope))) = (
                                    self.auth_invalidation.as_mut(),
                                    registered_scope_cleanup.as_ref(),
                                ) {
                                    state
                                        .obligations
                                        .rollback_unpublished_live_scope(scope, connection_scope);
                                }
                                return Err(error);
                            }
                        }
                    }
                    _ => None,
                };
            if let Some(retired) = self.subscriptions.remove(&old_id) {
                retired.observation.finish(200, None, "superseded");
            }
            self.pending_live_fanout
                .evaluation_memo
                .retire_subscription(&old_id);
            if let (Some(state), Some((scope, candidate, retirement))) =
                (self.auth_invalidation.as_mut(), prepared_retirement)
            {
                state.commit_scope_retirement(&scope, &candidate);
                scope_retirements.extend(retirement);
            }
            let receipt = Receipt::Subscription {
                event: SubscriptionReceiptEvent::Disposed,
                reason: Some("superseded".to_owned()),
                subscription_id: Some(old_id),
                superseded_by: Some(subscription_id.clone()),
                lane: None,
                binding_id: None,
                collection: None,
                removed: None,
                scope: subscription_input.args.clone(),
                snapshot_version: Some(query.output.version),
                correlation: None,
                received_at_ms: now_millis(),
            }
            .into_value();
            self.receipts.push_connection(&input.connection_id, receipt);
        }

        if subscription_authorization.is_some() {
            // Publish demand before the durable-live registration becomes
            // externally visible. A transient false positive only takes the
            // conservative writer path; a false negative could skip a
            // required level-triggered rerun.
            self.premark_auth_scoped_live_connection(&input.connection_id);
        }
        let observation = LiveSubscriptionObservation::new(self.telemetry.start_classified_span(
            crate::telemetry_contract::OperationClassIdV1::LIVE_SUBSCRIBE,
            name,
            Some(&input.connection_id),
            caller_details,
        ));
        self.subscriptions.insert(
            subscription_id.clone(),
            LiveSubscription {
                id: subscription_id.clone(),
                connection_id: input.connection_id.clone(),
                function: name.to_owned(),
                expected_generation: expected_generation.cloned(),
                authority: retained_authority,
                input: subscription_input.clone(),
                read_dependencies: query.read_dependencies,
                authorization: subscription_authorization,
                effect_fence,
                observation,
                rqs: rqs_state,
            },
        );
        if let Some(obligation) = subscription_quarantine_entry.as_ref() {
            self.record_quarantine_entry(obligation, true);
        }
        self.refresh_auth_scoped_live_connections();
        // A new subscription can arm a demand-gated cron job (L5).
        self.refresh_cron_active();

        // Server half of the 'established' receipt (LLP 0034 §3.2): scope is
        // REQUIRED (the subscription's routing/scope args); the adapter's
        // opaque correlation is echoed verbatim; transport is a kit fact and
        // is stitched there.
        let receipt = Receipt::Subscription {
            event: SubscriptionReceiptEvent::Established,
            reason: None,
            subscription_id: Some(subscription_id.clone()),
            superseded_by: None,
            lane: None,
            binding_id: None,
            collection: None,
            removed: None,
            scope: subscription_input.args.clone(),
            snapshot_version: Some(query.output.version),
            // Always present on established receipts (null when the adapter
            // sent none) — the pre-typed wire emitted the key unconditionally.
            correlation: Some(
                capped_correlation(subscription_input.correlation.clone()).unwrap_or(Value::Null),
            ),
            received_at_ms: now_millis(),
        };
        self.receipts
            .push_connection(&input.connection_id, receipt.clone().into_value());

        // Rung-1 answer: enqueue the `current_as_of` durable envelope (with
        // its mandatory fresh token) in the same &mut cut that registered the
        // subscription, and omit rows from the subscribe output entirely —
        // the caller's held rows are current as of `head_version`.
        if answer_current_as_of {
            let envelope = LiveEnvelope::CurrentAsOf {
                network_profile: None,
                subscription_id: subscription_id.clone(),
                function: name.to_owned(),
                version: head_version,
                resume: Some(
                    fresh_resume
                        .take()
                        .expect("rung-1 admission requires a minted fresh token"),
                ),
            };
            if let Ok(payload) = serde_json::to_vec(&envelope)
                && let Some(subscription) = self.subscriptions.get(&subscription_id).cloned()
            {
                self.enqueue_subscription_durable(&subscription, payload);
            }
        } else if let Some(ops) = answer_delta.take() {
            // Rung-2 answer (LLP 0090 D1.3): the exact replay frame — with
            // its mandatory fresh token minted from the updated accumulator
            // — rides the durable lane inside the same registration cut; the
            // subscribe output carries no rows.
            self.live_delivery.resume.replay_ops += ops.len() as u64;
            // Bytes-avoided estimate compares payload content only (rows vs
            // ops); envelope overhead and the fresh token are identical
            // between a rung-2 and a rung-3 answer.
            let replaced_bytes = serde_json::to_vec(&query.output.rows)
                .map(|bytes| bytes.len() as u64)
                .unwrap_or(0);
            let replay_bytes = serde_json::to_vec(&ops)
                .map(|bytes| bytes.len() as u64)
                .unwrap_or(replaced_bytes);
            self.live_delivery.resume.replay_bytes_avoided +=
                replaced_bytes.saturating_sub(replay_bytes);
            let envelope = LiveEnvelope::LiveDelta {
                network_profile: None,
                subscription_id: subscription_id.clone(),
                function: name.to_owned(),
                version: head_version,
                ops,
                resume: Some(
                    fresh_resume
                        .take()
                        .expect("rung-2 admission requires a minted fresh token"),
                ),
            };
            if let Ok(payload) = serde_json::to_vec(&envelope)
                && let Some(subscription) = self.subscriptions.get(&subscription_id).cloned()
            {
                self.enqueue_subscription_durable(&subscription, payload);
            }
        }

        Ok(LiveSubscribeOutput {
            subscription_id,
            facts: self.function_invocation_facts(authority.active_mode())?,
            snapshot: (!answered_without_rows).then_some(query.output),
            completeness_proof,
            authorization_witness,
            resume: fresh_resume,
            resume_refusal: resume_refusal.map(str::to_owned),
            superseded: superseded_witness,
            supersession_refusal,
            permission_epochs,
            receipt: Some(receipt),
            authorization_scope,
            authorization_invalidation,
            scope_retirements,
            attribution,
        })
    }

    /// Reserve a connection-bound subscribe without running the initial query
    /// or mutating live/obligation state. The query runs only after the exact
    /// connection act commits, so pending subscriptions cannot miss mutation
    /// fanout between preparation and publication.
    #[allow(dead_code)]
    pub(crate) fn prepare_subscribe_live_for_transport(
        &mut self,
        name: String,
        input: LiveSubscribeInput,
        authority: PreparedAuthority,
        invalidation: LiveInvalidationAdmission,
    ) -> SnapbackResult<PreparedLiveSubscribe> {
        self.prepare_subscribe_live_for_transport_generation(
            name,
            input,
            authority,
            invalidation,
            None,
        )
    }

    pub fn prepare_subscribe_live_for_transport_generation(
        &mut self,
        name: String,
        input: LiveSubscribeInput,
        authority: PreparedAuthority,
        invalidation: LiveInvalidationAdmission,
        expected_generation: Option<ArtifactGeneration>,
    ) -> SnapbackResult<PreparedLiveSubscribe> {
        if authority.source() != InvocationSource::LiveInitialQuery {
            return Err(SnapbackError::error(
                "SNAPBACK_INVOCATION_SOURCE_INVALID",
                "auth",
                "live subscribe requires LiveInitialQuery authority",
            ));
        }
        authority.validate_admission("live subscribe staging")?;
        let effect_fence = invalidation.effect_fence.clone().ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_LIVE_STAGE_FENCE_REQUIRED",
                "realtime",
                "transport live subscribe staging requires an exact connection effect fence",
            )
        })?;
        let mut reservation_keys = Vec::new();
        let reserved_subscription_slots = match input.supersedes.as_ref() {
            Some(subscription_id) => match self.subscriptions.get(subscription_id) {
                Some(subscription)
                    if subscription.connection_id == input.connection_id
                        && subscription.is_owned_by(&authority, Some(&effect_fence)) =>
                {
                    reservation_keys.push(format!("subscription:{subscription_id}"));
                    0
                }
                Some(subscription) => {
                    return Err(live_owner_mismatch(&subscription.id, &authority));
                }
                None => 1,
            },
            None => 1,
        };
        self.stage_local_live_effect(
            input.connection_id.clone(),
            effect_fence,
            reserved_subscription_slots,
            reservation_keys,
            PreparedLiveSubscribePlan {
                name,
                input,
                expected_generation,
                authority,
                invalidation,
            },
        )
    }

    pub fn finalize_subscribe_live_for_transport(
        &mut self,
        staged: &PreparedLiveSubscribe,
    ) -> SnapbackResult<LiveTransportPublication<LiveSubscribeOutput>> {
        self.finalize_prepared_live_effect(staged, |snapback, plan| {
            snapback.subscribe_live_for_transport_generation(
                &plan.name,
                plan.input,
                plan.authority,
                plan.invalidation,
                plan.expected_generation.as_ref(),
            )
        })
    }

    #[allow(dead_code)]
    pub(crate) fn subscribe_live_for_transport(
        &mut self,
        name: &str,
        input: LiveSubscribeInput,
        authority: PreparedAuthority,
        invalidation: LiveInvalidationAdmission,
    ) -> SnapbackResult<LiveTransportPublication<LiveSubscribeOutput>> {
        self.subscribe_live_for_transport_generation(name, input, authority, invalidation, None)
    }

    fn subscribe_live_for_transport_generation(
        &mut self,
        name: &str,
        input: LiveSubscribeInput,
        authority: PreparedAuthority,
        invalidation: LiveInvalidationAdmission,
        expected_generation: Option<&ArtifactGeneration>,
    ) -> SnapbackResult<LiveTransportPublication<LiveSubscribeOutput>> {
        let output = self.subscribe_live_prepared_with_invalidation_generation(
            name,
            input,
            authority,
            invalidation,
            expected_generation,
            None,
        )?;
        let authorization = output.authorization_scope.as_ref().and_then(|_| {
            self.auth_invalidation
                .as_ref()
                .map(|state| state.obligations.expectation().authorization.clone())
        });
        Ok(LiveTransportPublication {
            output,
            authorization,
        })
    }

    /// Explicit unsubscribe (LLP 0034 §10.1 residual, ENG-22478): dispose one
    /// live subscription. Ownership mirrors `resume_live` — once a principal
    /// owns the subscription the caller must present that principal.
    pub fn unsubscribe_live(
        &mut self,
        name: &str,
        input: LiveUnsubscribeInput,
    ) -> SnapbackResult<LiveUnsubscribeOutput> {
        let admission = self.admission.admit_dev()?;
        let authority = InvocationGate::prepare_admitted_authority(
            InvocationSource::LiveUnsubscribe,
            AuthMode::Dev,
            ServerProfile::Dev,
            admission,
            &WireAuthorityFields::default(),
            ResolvedAppAuthority::dev_from_auth(&input.auth),
            None,
        )?;
        self.unsubscribe_live_prepared(name, input, authority, None)
    }

    pub(crate) fn unsubscribe_live_prepared(
        &mut self,
        name: &str,
        input: LiveUnsubscribeInput,
        authority: PreparedAuthority,
        effect_fence: Option<&crate::ephemeral::ConnectionEffectFence>,
    ) -> SnapbackResult<LiveUnsubscribeOutput> {
        if authority.source() != InvocationSource::LiveUnsubscribe {
            return Err(SnapbackError::error(
                "SNAPBACK_INVOCATION_SOURCE_INVALID",
                "auth",
                "live unsubscribe requires LiveUnsubscribe authority",
            ));
        }
        authority.validate_admission("live unsubscribe preparation")?;
        let subscription = self
            .subscriptions
            .get(&input.subscription_id)
            .cloned()
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_UNKNOWN_SUBSCRIPTION",
                    "realtime",
                    format!("unknown live subscription {}", input.subscription_id),
                )
            })?;
        if subscription.function != name {
            return Err(SnapbackError::error(
                "SNAPBACK_LIVE_RESUME_FUNCTION_MISMATCH",
                "realtime",
                format!(
                    "subscription {} belongs to {}, not {name}",
                    subscription.id, subscription.function
                ),
            ));
        }
        if !subscription.is_owned_by(&authority, effect_fence) {
            return Err(live_owner_mismatch(&subscription.id, &authority));
        }

        let snapshot_version = self.db.versions_read().current_version()?;
        let _publication = authority.effect_guard("live unsubscribe publication")?;
        let prepared_retirement = match (
            self.auth_invalidation.as_ref(),
            subscription.authorization.as_ref(),
        ) {
            (Some(state), Some(authorization)) => {
                let (candidate, retirement) =
                    state.prepare_scope_retirement_authenticated(&authorization.scope_id)?;
                Some((authorization.scope_id.clone(), candidate, retirement))
            }
            _ => None,
        };
        // No fallible step remains after the retained producer is removed.
        self.touch_connection(&input.connection_id, now_millis());
        self.subscriptions.remove(&subscription.id);
        self.pending_live_fanout
            .evaluation_memo
            .retire_subscription(&subscription.id);
        subscription.observation.finish(200, None, "unsubscribed");
        self.refresh_auth_scoped_live_connections();
        let scope_retirement = match (self.auth_invalidation.as_mut(), prepared_retirement) {
            (Some(state), Some((scope, candidate, retirement))) => {
                state.commit_scope_retirement(&scope, &candidate);
                retirement
            }
            _ => None,
        };
        // Losing the last watcher of a demand-gated live query disarms cron.
        self.refresh_cron_active();
        let receipt = Receipt::Subscription {
            event: SubscriptionReceiptEvent::Disposed,
            reason: Some("unsubscribed".to_owned()),
            subscription_id: Some(subscription.id.clone()),
            superseded_by: None,
            lane: None,
            binding_id: None,
            collection: None,
            removed: None,
            scope: subscription.input.args.clone(),
            snapshot_version: Some(snapshot_version),
            correlation: None,
            received_at_ms: now_millis(),
        };
        self.receipts
            .push_connection(&subscription.connection_id, receipt.clone().into_value());
        Ok(LiveUnsubscribeOutput {
            subscription_id: subscription.id,
            disposed: true,
            receipt: Some(receipt),
            scope_retirement,
        })
    }

    pub fn prepare_unsubscribe_live_for_transport(
        &mut self,
        name: String,
        input: LiveUnsubscribeInput,
        authority: PreparedAuthority,
        effect_fence: crate::ephemeral::ConnectionEffectFence,
    ) -> SnapbackResult<PreparedLiveUnsubscribe> {
        if authority.source() != InvocationSource::LiveUnsubscribe {
            return Err(SnapbackError::error(
                "SNAPBACK_INVOCATION_SOURCE_INVALID",
                "auth",
                "live unsubscribe requires LiveUnsubscribe authority",
            ));
        }
        authority.validate_admission("live unsubscribe staging")?;
        self.stage_local_live_effect(
            input.connection_id.clone(),
            effect_fence.clone(),
            0,
            [format!("subscription:{}", input.subscription_id)],
            PreparedLiveUnsubscribePlan {
                name,
                input,
                authority,
                effect_fence,
            },
        )
    }

    pub fn finalize_unsubscribe_live_for_transport(
        &mut self,
        staged: &PreparedLiveUnsubscribe,
    ) -> SnapbackResult<LiveUnsubscribeOutput> {
        self.finalize_prepared_live_effect(staged, |snapback, plan| {
            snapback.unsubscribe_live_prepared(
                &plan.name,
                plan.input,
                plan.authority,
                Some(&plan.effect_fence),
            )
        })
    }

    /// The request itself is the client's assertion that its serialized
    /// disposition/snapshot transition committed. There is deliberately no
    /// caller-controlled `applied` boolean: only an exact token bound to this
    /// negotiated connection can compare-and-discharge the current revision.
    pub(crate) fn acknowledge_authorization_invalidation(
        &mut self,
        input: AuthorizationInvalidationAckInput,
        connection: AuthorizationInvalidationConnection,
        admission: &AdmissionLease,
    ) -> SnapbackResult<AuthorizationInvalidationAckOutput> {
        let _publication = admission.effect_guard("authorization invalidation acknowledgement")?;
        self.touch_connection(&input.connection_id, now_millis());
        let state = self.auth_invalidation.as_mut().ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_AUTH_INVALIDATION_UNAVAILABLE",
                "auth",
                "authorization invalidation is not installed",
            )
        })?;
        if !state.accepts_connection(&connection) {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_INVALIDATION_CLIENT_UNSUPPORTED",
                "auth",
                "reopen the connection with `authInvalidationProtocol: 1`: \
                 its authorization-invalidation expectation is no longer current",
            ));
        }
        let accepted_resolution = state
            .obligations
            .resolution_for_ack_token(&input.ack_token)
            .cloned();
        let outcome = state.obligations.acknowledge_subscription(
            &connection.issuer_id,
            connection.connection_generation,
            &input.ack_token,
        )?;
        if outcome == crate::auth::invalidation::AcknowledgeOutcome::Discharged
            && let Some(resolution) = accepted_resolution.as_ref()
        {
            self.record_quarantine_exit(resolution);
        }
        Ok(AuthorizationInvalidationAckOutput {
            outcome: match outcome {
                crate::auth::invalidation::AcknowledgeOutcome::Discharged => "discharged",
                crate::auth::invalidation::AcknowledgeOutcome::Duplicate => "duplicate",
                crate::auth::invalidation::AcknowledgeOutcome::Stale => "stale",
            }
            .to_owned(),
        })
    }

    pub fn prepare_authorization_invalidation_ack_for_transport(
        &mut self,
        input: AuthorizationInvalidationAckInput,
        connection: AuthorizationInvalidationConnection,
        admission: AdmissionLease,
        effect_fence: crate::ephemeral::ConnectionEffectFence,
    ) -> SnapbackResult<PreparedAuthorizationInvalidationAck> {
        self.stage_local_live_effect(
            input.connection_id.clone(),
            effect_fence,
            0,
            [format!(
                "authorization-ack:{}:{}:{}:{}:{}",
                connection.issuer_id.authorization_incarnation,
                connection.issuer_id.boot_sequence,
                connection.issuer_id.boot_nonce,
                connection.connection_generation,
                input.ack_token
            )],
            PreparedAuthorizationInvalidationAckPlan {
                input,
                connection,
                admission,
            },
        )
    }

    pub fn finalize_authorization_invalidation_ack_for_transport(
        &mut self,
        staged: &PreparedAuthorizationInvalidationAck,
    ) -> SnapbackResult<AuthorizationInvalidationAckOutput> {
        self.finalize_prepared_live_effect(staged, |snapback, plan| {
            snapback.acknowledge_authorization_invalidation(
                plan.input,
                plan.connection,
                &plan.admission,
            )
        })
    }

    /// Open a new bounded retry episode only through an explicit, exact-owner
    /// operation. Reconnect, subscribe, resume, revision changes, and ordinary
    /// re-fire all remain attached to the exhausted durable episode.
    ///
    /// @ref LLP 0053#invalidation-is-an-obligation-not-a-message — manual retry
    /// is authority-checked and idempotent, and replaces the same durable key.
    pub(crate) fn manual_retry_authorization_invalidation(
        &mut self,
        input: AuthorizationInvalidationManualRetryInput,
        connection: AuthorizationInvalidationConnection,
        authority: PreparedAuthority,
    ) -> SnapbackResult<AuthorizationInvalidationManualRetryOutput> {
        if authority.source() != InvocationSource::InvalidationAcknowledgement {
            return Err(SnapbackError::error(
                "SNAPBACK_INVOCATION_SOURCE_INVALID",
                "auth",
                "authorization invalidation manual retry requires invalidation acknowledgement authority",
            ));
        }
        authority.validate_admission("authorization invalidation manual retry")?;
        self.touch_connection(&input.connection_id, now_millis());
        let subscription = self
            .subscriptions
            .get(&input.subscription_id)
            .cloned()
            .ok_or_else(auth_resnapshot_required)?;
        if subscription.connection_id != input.connection_id
            || !subscription.authority.matches(&authority)
        {
            return Err(SnapbackError::error(
                "SNAPBACK_LIVE_RESUME_OWNERSHIP",
                "realtime",
                "authorization invalidation retry belongs to a different live owner",
            ));
        }
        let subscription_authorization = subscription.authorization.as_ref().ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_AUTH_INVALIDATION_UNAVAILABLE",
                "auth",
                "manual authorization retry requires an auth-scoped subscription",
            )
        })?;
        let state = self.auth_invalidation.as_ref().ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_AUTH_INVALIDATION_UNAVAILABLE",
                "auth",
                "authorization invalidation is not installed",
            )
        })?;
        if !state.accepts_connection(&connection)
            || !matches!(
                &subscription_authorization.scope_id,
                ScopeId::Subscription {
                    issuer_id,
                    connection_generation,
                    ..
                } if issuer_id == &connection.issuer_id
                    && *connection_generation == connection.connection_generation
            )
        {
            return Err(auth_resnapshot_required());
        }
        let witness_floor = state
            .obligations
            .pending(&subscription_authorization.scope_id)
            .map(|pending| pending.witness.clone())
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_AUTH_RETRY_NOT_PENDING",
                    "auth",
                    "manual retry requires a current unresolved authorization obligation",
                )
            })?;
        let key = Self::authorization_retry_key(&subscription)
            .expect("auth-scoped subscription has a retry key");
        let reservation = {
            let _effect =
                authority.effect_guard("authorization manual retry reservation transaction")?;
            self.db
                .reserve_manual_invalidation_retry(&key, input.manual_retry_id, now_millis())?
        };
        let episode = match reservation {
            RetryReservation::Attached(episode) => {
                return Ok(AuthorizationInvalidationManualRetryOutput {
                    outcome: "attached".to_owned(),
                    retry_episode_id: Some(episode.episode_id),
                });
            }
            RetryReservation::Reserved(episode) => episode,
            RetryReservation::Exhausted(_) => {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_RETRY_EXHAUSTED",
                    "auth",
                    "manual retry reservation remained exhausted",
                ));
            }
        };
        let retry_episode_id = episode.episode_id.clone();
        match self.invoke_authorization_resolution_with_episode(
            &subscription,
            witness_floor,
            authority.admission_lease(),
            key,
            episode,
        ) {
            Ok(query) => {
                let _ = self.deliver_authorization_snapshot(
                    &subscription,
                    query,
                    "manual_retry",
                    false,
                    authority.admission_lease(),
                )?;
                Ok(AuthorizationInvalidationManualRetryOutput {
                    outcome: "resolved".to_owned(),
                    retry_episode_id: Some(retry_episode_id),
                })
            }
            Err(failure) => {
                let terminal = failure.error.is_trusted_permission_denial();
                self.fail_subscription_fanout_with_retry(
                    &subscription,
                    if terminal {
                        "authorization_manual_retry_denied"
                    } else {
                        "authorization_manual_retry_failed"
                    },
                    failure.error,
                    failure.retry_episode_id.clone(),
                    None,
                    authority.admission_lease(),
                );
                Ok(AuthorizationInvalidationManualRetryOutput {
                    outcome: if terminal { "denied" } else { "exhausted" }.to_owned(),
                    retry_episode_id: failure.retry_episode_id,
                })
            }
        }
    }

    pub fn prepare_authorization_invalidation_manual_retry_for_transport(
        &mut self,
        input: AuthorizationInvalidationManualRetryInput,
        connection: AuthorizationInvalidationConnection,
        authority: PreparedAuthority,
        effect_fence: crate::ephemeral::ConnectionEffectFence,
    ) -> SnapbackResult<PreparedAuthorizationInvalidationManualRetry> {
        if authority.source() != InvocationSource::InvalidationAcknowledgement {
            return Err(SnapbackError::error(
                "SNAPBACK_INVOCATION_SOURCE_INVALID",
                "auth",
                "authorization invalidation manual retry requires invalidation acknowledgement authority",
            ));
        }
        authority.validate_admission("authorization invalidation manual retry staging")?;
        self.stage_local_live_effect(
            input.connection_id.clone(),
            effect_fence.clone(),
            0,
            [format!("subscription:{}", input.subscription_id)],
            PreparedAuthorizationInvalidationManualRetryPlan {
                input,
                connection,
                authority,
                effect_fence,
            },
        )
    }

    pub fn finalize_authorization_invalidation_manual_retry_for_transport(
        &mut self,
        staged: &PreparedAuthorizationInvalidationManualRetry,
    ) -> SnapbackResult<AuthorizationInvalidationManualRetryOutput> {
        self.finalize_prepared_live_effect(staged, |snapback, plan| {
            let subscription = snapback
                .subscriptions
                .get(&plan.input.subscription_id)
                .ok_or_else(auth_resnapshot_required)?;
            if subscription.connection_id != plan.input.connection_id
                || !subscription.is_owned_by(&plan.authority, Some(&plan.effect_fence))
            {
                return Err(live_owner_mismatch(
                    &plan.input.subscription_id,
                    &plan.authority,
                ));
            }
            snapback.manual_retry_authorization_invalidation(
                plan.input,
                plan.connection,
                plan.authority,
            )
        })
    }

    /// @ref LLP 0020#remaining-phase-4-design-dependency-vocabulary-and-auth-epochs — retained resume compares client-recorded permission epochs before trusting retained rows.
    /// @ref LLP 0053#invalidation-is-an-obligation-not-a-message — an
    /// auth-scoped reconnect gets a fresh connection-bound scope and snapshot;
    /// any pending obligation transfers instead of disappearing with the socket.
    pub fn resume_live(
        &mut self,
        name: &str,
        input: LiveResumeInput,
    ) -> SnapbackResult<LiveResumeOutput> {
        // The live-resume lane consults the persisted migration fence
        // (LLP 0081 §4's lane registry).
        self.db.ensure_migration_lane_open()?;
        let admission = self.admission.admit_dev()?;
        let authority = InvocationGate::prepare_admitted_authority(
            InvocationSource::LiveResume,
            AuthMode::Dev,
            ServerProfile::Dev,
            admission,
            &WireAuthorityFields::default(),
            ResolvedAppAuthority::dev_from_auth(&input.auth),
            None,
        )?;
        self.resume_live_prepared_with_invalidation(
            name,
            input,
            authority,
            LiveInvalidationAdmission::default(),
        )
    }

    // Compatibility seam matching subscribe_live_prepared; production binds
    // invalidation state explicitly through the method below.
    #[allow(dead_code)]
    pub(crate) fn resume_live_prepared(
        &mut self,
        name: &str,
        input: LiveResumeInput,
        authority: PreparedAuthority,
    ) -> SnapbackResult<LiveResumeOutput> {
        self.resume_live_prepared_with_invalidation(
            name,
            input,
            authority,
            LiveInvalidationAdmission::default(),
        )
    }

    pub(crate) fn resume_live_prepared_with_invalidation(
        &mut self,
        name: &str,
        input: LiveResumeInput,
        authority: PreparedAuthority,
        invalidation: LiveInvalidationAdmission,
    ) -> SnapbackResult<LiveResumeOutput> {
        if authority.source() != InvocationSource::LiveResume {
            return Err(SnapbackError::error(
                "SNAPBACK_INVOCATION_SOURCE_INVALID",
                "auth",
                "live resume requires LiveResume authority",
            ));
        }
        authority.validate_admission("live resume preparation")?;
        self.touch_connection(&input.connection_id, now_millis());
        let mut subscription = self
            .subscriptions
            .get(&input.subscription_id)
            .cloned()
            .ok_or_else(|| {
                if authority.active_mode() == AuthMode::Sessions {
                    auth_resnapshot_required()
                } else {
                    SnapbackError::error(
                        "SNAPBACK_UNKNOWN_SUBSCRIPTION",
                        "realtime",
                        format!("unknown live subscription {}", input.subscription_id),
                    )
                }
            })?;
        if subscription.function != name {
            return Err(SnapbackError::error(
                "SNAPBACK_LIVE_RESUME_FUNCTION_MISMATCH",
                "realtime",
                format!(
                    "subscription {} belongs to {}, not {name}",
                    subscription.id, subscription.function
                ),
            ));
        }

        if !subscription.is_owned_by(&authority, invalidation.effect_fence.as_ref()) {
            return Err(live_owner_mismatch(&subscription.id, &authority));
        }
        self.validate_expected_generation(&authority, subscription.expected_generation.as_ref())?;
        // The establishment block, not the presenting caller's: a renewal
        // resubscribe carries the subscription's immutable metadata.
        // @ref LLP 0055#audit — attribution is copied, never re-synthesized.
        let attribution = subscription.authority.function_attribution();
        let predecessor_subscription = subscription.clone();

        // @ref LLP 0059#durable-and-ephemeral-outboxes — reconnect stages the
        // successor connection and exact effect fence privately, then moves
        // the retained producer before any successor-owned frame is exposed.
        subscription.connection_id = input.connection_id.clone();
        if invalidation.effect_fence.is_some() {
            subscription.effect_fence = invalidation.effect_fence.clone();
        }

        if let Some(mut authorization) = subscription.authorization.take() {
            if authority.active_mode() != AuthMode::Sessions {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_INVALIDATION_UNAVAILABLE",
                    "auth",
                    "an auth-scoped subscription cannot resume outside its session authority",
                ));
            }
            let connection = invalidation.connection.ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_AUTH_INVALIDATION_CLIENT_UNSUPPORTED",
                    "auth",
                    "open the connection with `authInvalidationProtocol: 1` \
                     (or configure SnapbackClient with that option) before resuming \
                     an auth-scoped live query",
                )
            })?;
            let state = self.auth_invalidation.as_ref().ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_AUTH_INVALIDATION_UNAVAILABLE",
                    "auth",
                    "authorization invalidation is not installed",
                )
            })?;
            if !state.accepts_connection(&connection) {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_INVALIDATION_CLIENT_UNSUPPORTED",
                    "auth",
                    "reopen the connection with `authInvalidationProtocol: 1`: \
                     its authorization-invalidation expectation is no longer current",
                ));
            }

            let connection_changed = !matches!(
                &authorization.scope_id,
                ScopeId::Subscription {
                    issuer_id,
                    connection_generation,
                    ..
                } if issuer_id == &connection.issuer_id
                    && *connection_generation == connection.connection_generation
            );
            // Read the durable floor before changing retained ownership. A read
            // failure must leave the exact predecessor scope/fence untouched.
            let floor = self.db.versions_read().current_version()?;
            let retry_floor = state.witness(floor);
            let predecessor_scope = authorization.scope_id.clone();
            let replacement_stage = if connection_changed {
                // Register a quarantined successor without retiring or
                // repointing the retained predecessor. It is private staging:
                // no successor-fenced frame is enqueued until the fresh query,
                // authenticated retirement proof, and retry resolution are all
                // ready to commit. Failed staging is removed in O(log N), while
                // its reserved identity remains spent.
                let state = self
                    .auth_invalidation
                    .as_mut()
                    .expect("resume checked installed invalidation state");
                let previous = state.obligations.pending(&predecessor_scope).cloned();
                let replacement = ScopeId::Subscription {
                    issuer_id: connection.issuer_id.clone(),
                    namespace: authorization.namespace.clone(),
                    scope_sequence: state.issuer.reserve_scope_sequence()?,
                    connection_generation: connection.connection_generation,
                    subscription_id: subscription.id.clone(),
                };
                let connection_scope = ScopeId::Connection {
                    issuer_id: connection.issuer_id.clone(),
                    connection_generation: connection.connection_generation,
                };
                let owner_continuity_id =
                    crate::ids::mint_time_ordered(crate::ids::Kind::OwnerContinuity);
                let transfer_cause = if previous.is_some() {
                    Some(state.reserve_cause_sequence()?)
                } else {
                    None
                };
                let fresh_cause = state.reserve_cause_sequence()?;
                let mut quarantine_entry = None;
                let staged = (|| {
                    state
                        .obligations
                        .register_live_scope(replacement.clone(), owner_continuity_id.clone())?;
                    let (inherited, entered) = state
                        .obligations
                        .register_connection_child_with_quarantine_lifecycle(
                            &connection_scope,
                            replacement.clone(),
                        )?;
                    if entered {
                        quarantine_entry = inherited;
                    }
                    if let (Some(previous), Some(cause)) = (previous, transfer_cause) {
                        let (obligation, entered) =
                            state.obligations.raise_with_quarantine_lifecycle(
                                replacement.clone(),
                                cause,
                                format!("resume:transfer:{cause}"),
                                previous.max_disposition,
                                previous.witness,
                                previous.retry_episode_id,
                            )?;
                        if entered {
                            quarantine_entry = Some(obligation);
                        }
                    }
                    let (obligation, entered) = state.obligations.raise_with_quarantine_lifecycle(
                        replacement.clone(),
                        fresh_cause,
                        format!("resume:fresh:{fresh_cause}"),
                        InvalidationDisposition::Quarantine,
                        retry_floor.clone(),
                        None,
                    )?;
                    if entered {
                        quarantine_entry = Some(obligation);
                    }
                    Ok::<(), SnapbackError>(())
                })();
                if let Err(error) = staged {
                    state
                        .obligations
                        .rollback_unpublished_live_scope(&replacement, &connection_scope);
                    return Err(error);
                }
                authorization.owner_continuity_id = owner_continuity_id;
                authorization.scope_id = replacement.clone();
                Some((replacement, connection_scope, quarantine_entry))
            } else {
                let (obligation, entered) = {
                    let state = self
                        .auth_invalidation
                        .as_mut()
                        .expect("resume checked installed invalidation state");
                    let cause = state.reserve_cause_sequence()?;
                    state.obligations.raise_with_quarantine_lifecycle(
                        authorization.scope_id.clone(),
                        cause,
                        format!("resume:fresh:{cause}"),
                        InvalidationDisposition::Quarantine,
                        retry_floor.clone(),
                        None,
                    )?
                };
                self.record_quarantine_entry(&obligation, entered);
                None
            };

            subscription.authorization = Some(authorization.clone());
            let query = match self.invoke_authorization_resolution(
                &subscription,
                retry_floor,
                authority.admission_lease(),
            ) {
                Ok(query) => query,
                Err(failure) => {
                    let error = failure.error.clone();
                    if let Some((replacement, connection_scope, _)) = replacement_stage.as_ref() {
                        self.auth_invalidation
                            .as_mut()
                            .expect("state remains installed")
                            .obligations
                            .rollback_unpublished_live_scope(replacement, connection_scope);
                    }
                    // The failed attempt exposed no replacement identity. Keep
                    // the exact retained predecessor as cleanup/delivery owner
                    // and make its already-known client view fail closed.
                    self.fail_subscription_fanout_with_retry(
                        &predecessor_subscription,
                        "authorization_resume_failed",
                        failure.error,
                        failure.retry_episode_id,
                        None,
                        authority.admission_lease(),
                    );
                    return Err(error);
                }
            };
            let permission_epochs = permission_epochs_from_dependencies(&query.read_dependencies);
            let _publication = match authority.effect_guard("live authorization resume publication")
            {
                Ok(publication) => publication,
                Err(error) => {
                    if let Some((replacement, connection_scope, _)) = replacement_stage.as_ref() {
                        self.auth_invalidation
                            .as_mut()
                            .expect("state remains installed")
                            .obligations
                            .rollback_unpublished_live_scope(replacement, connection_scope);
                    }
                    return Err(error);
                }
            };
            let resolution_witness = self
                .auth_invalidation
                .as_ref()
                .expect("state remains installed")
                .witness(query.output.version);
            let snapshot_identity = authorization_resolution_snapshot_identity(&query.output)?;
            let resolution = {
                let state = self
                    .auth_invalidation
                    .as_mut()
                    .expect("state remains installed");
                state.obligations.issue_resolution(
                    &authorization.scope_id,
                    ResolutionKind::Snapshot,
                    resolution_witness.clone(),
                    &snapshot_identity,
                )
            };
            if let Err(error) = resolution {
                if let Some((replacement, connection_scope, _)) = replacement_stage.as_ref() {
                    self.auth_invalidation
                        .as_mut()
                        .expect("state remains installed")
                        .obligations
                        .rollback_unpublished_live_scope(replacement, connection_scope);
                }
                return Err(error);
            }
            let (retirement_candidate, retirement) = if connection_changed {
                let state = self
                    .auth_invalidation
                    .as_ref()
                    .expect("state remains installed");
                let candidate = state
                    .obligations
                    .preview_scope_retirement(&predecessor_scope);
                let retirement = candidate
                    .as_ref()
                    .map(|candidate| {
                        state.issuer.authenticate_scope_retirement(
                            candidate.namespace.clone(),
                            candidate.retire_through_scope_sequence,
                        )
                    })
                    .transpose();
                match retirement {
                    Ok(retirement) => (candidate, retirement),
                    Err(error) => {
                        if let Some((replacement, connection_scope, _)) = replacement_stage.as_ref()
                        {
                            self.auth_invalidation
                                .as_mut()
                                .expect("state remains installed")
                                .obligations
                                .rollback_unpublished_live_scope(replacement, connection_scope);
                        }
                        return Err(error);
                    }
                }
            } else {
                (None, None)
            };
            let authorization_invalidation = self
                .auth_invalidation
                .as_ref()
                .expect("state remains installed")
                .obligations
                .projection(&authorization.scope_id)
                .expect("fresh quarantine and snapshot resolution remain projected");
            let invalidation_payload = match serde_json::to_vec(
                &LiveEnvelope::authorization_invalidation(
                    authorization_invalidation.obligation.clone(),
                    // This durable frame is only a level-triggered wake hint.
                    // The complete snapshot ticket and its rows travel
                    // together in the successful resume response below.
                    None,
                    None,
                ),
            ) {
                Ok(payload) => payload,
                Err(error) => {
                    if let Some((replacement, connection_scope, _)) = replacement_stage.as_ref() {
                        self.auth_invalidation
                            .as_mut()
                            .expect("state remains installed")
                            .obligations
                            .rollback_unpublished_live_scope(replacement, connection_scope);
                    }
                    return Err(SnapbackError::error(
                        "SNAPBACK_AUTH_INVALIDATION_SERIALIZE_FAILED",
                        "realtime",
                        "authorization resume invalidation could not be serialized",
                    )
                    .with_details(json!({ "error": error.to_string() })));
                }
            };
            let predecessor_is_current =
                self.subscriptions
                    .get(&subscription.id)
                    .is_some_and(|stored| {
                        stored.connection_id == predecessor_subscription.connection_id
                            && stored.effect_fence == predecessor_subscription.effect_fence
                            && stored.authorization.as_ref().is_some_and(|authorization| {
                                authorization.scope_id == predecessor_scope
                            })
                    });
            let precommit = if !predecessor_is_current {
                Err(SnapbackError::error(
                    "SNAPBACK_AUTH_INVALIDATION_CORRUPT",
                    "auth",
                    "retained live predecessor changed before resume transfer commit",
                ))
            } else if connection_changed {
                self.auth_invalidation
                    .as_ref()
                    .expect("state remains installed")
                    .obligations
                    .require_scope_retirement_preview(&predecessor_scope, &retirement_candidate)
            } else {
                Ok(())
            };
            if let Err(error) = precommit {
                if let Some((replacement, connection_scope, _)) = replacement_stage.as_ref() {
                    self.auth_invalidation
                        .as_mut()
                        .expect("state remains installed")
                        .obligations
                        .rollback_unpublished_live_scope(replacement, connection_scope);
                }
                return Err(error);
            }
            if let Err(error) = self.resolve_authorization_retry_episode(
                &subscription,
                &resolution_witness,
                &_publication,
            ) {
                if let Some((replacement, connection_scope, _)) = replacement_stage.as_ref() {
                    self.auth_invalidation
                        .as_mut()
                        .expect("state remains installed")
                        .obligations
                        .rollback_unpublished_live_scope(replacement, connection_scope);
                }
                return Err(error);
            }

            // No fallible step remains. Retire and persist the predecessor only
            // after the authenticated frontier and complete successor response
            // are ready, then expose the successor fence and obligation as one
            // commit. A response that returns Err never exposes a replacement
            // scope and therefore owes the client no retirement frontier.
            if connection_changed {
                let actual = self
                    .auth_invalidation
                    .as_mut()
                    .expect("state remains installed")
                    .obligations
                    .retire_scope(&predecessor_scope);
                assert_eq!(
                    actual, retirement_candidate,
                    "validated live scope retirement frontier changed during commit"
                );
            }
            self.premark_auth_scoped_live_connection(&input.connection_id);
            let stored = self
                .subscriptions
                .get_mut(&subscription.id)
                .expect("preflight validated retained live predecessor presence");
            stored.connection_id = input.connection_id.clone();
            stored.read_dependencies = query.read_dependencies;
            stored.authorization = Some(authorization.clone());
            stored.effect_fence = subscription.effect_fence.clone();
            self.renew_live_subscription_observation(&subscription.id, name, &input.connection_id);
            self.refresh_auth_scoped_live_connections();
            self.enqueue_subscription_durable(&subscription, invalidation_payload);
            if let Some((_, _, Some(obligation))) = replacement_stage.as_ref() {
                self.record_quarantine_entry(obligation, true);
            }
            return Ok(LiveResumeOutput {
                subscription_id: subscription.id,
                mode: "resnapshot".to_owned(),
                reason: Some("authorization_revalidation".to_owned()),
                snapshot: Some(query.output),
                permission_epochs,
                authorization_scope: Some(authorization.scope_id.clone()),
                authorization_invalidation: Some(authorization_invalidation),
                scope_retirements: retirement.into_iter().collect(),
                attribution,
            });
        }

        // @ref LLP 0032#phase-1--safety-floor-and-confirmed-defects — S2:
        // resume re-points a subscription's stream, so once a principal owns
        // the subscription the caller must present that principal; the
        // unguessable id alone is not ownership.
        if !subscription.authority.matches(&authority) {
            return Err(SnapbackError::error(
                "SNAPBACK_LIVE_RESUME_OWNERSHIP",
                "realtime",
                format!(
                    "subscription {} is owned by a different principal",
                    subscription.id
                ),
            ));
        }

        if self.resume_requires_resnapshot(&subscription, &input.recorded_permission_epochs) {
            let rerun = self.prepare_live_rerun_authority(
                &subscription.authority,
                authority.admission_lease().clone(),
            )?;
            let query = if is_reserved_live_function(&subscription.function) {
                self.reserved_live_invocation(&rerun, &subscription.function, &subscription.input)?
            } else {
                self.invoke_query_with_dependencies_prepared(
                    &subscription.function,
                    subscription.input.clone(),
                    rerun,
                )?
            };
            let permission_epochs = permission_epochs_from_dependencies(&query.read_dependencies);
            let _publication = authority.effect_guard("live resume resnapshot publication")?;
            self.touch_connection(&input.connection_id, now_millis());
            if let Some(stored) = self.subscriptions.get_mut(&subscription.id) {
                stored.connection_id = input.connection_id.clone();
                stored.read_dependencies = query.read_dependencies;
                stored.effect_fence = subscription.effect_fence.clone();
            }
            self.renew_live_subscription_observation(&subscription.id, name, &input.connection_id);
            return Ok(LiveResumeOutput {
                subscription_id: subscription.id,
                mode: "resnapshot".to_owned(),
                reason: Some("permission_epoch_changed".to_owned()),
                snapshot: Some(query.output),
                permission_epochs,
                authorization_scope: None,
                authorization_invalidation: None,
                scope_retirements: Vec::new(),
                attribution,
            });
        }

        let permission_epochs =
            current_permission_epochs_for_dependencies(&subscription.read_dependencies, |scope| {
                self.permission_epoch(scope)
            });
        let _publication = authority.effect_guard("live resume publication")?;
        self.touch_connection(&input.connection_id, now_millis());
        if let Some(stored) = self.subscriptions.get_mut(&subscription.id) {
            stored.connection_id = input.connection_id.clone();
            stored.effect_fence = subscription.effect_fence;
        }
        self.renew_live_subscription_observation(&subscription.id, name, &input.connection_id);
        Ok(LiveResumeOutput {
            subscription_id: subscription.id,
            mode: "retained".to_owned(),
            reason: None,
            snapshot: None,
            permission_epochs,
            authorization_scope: None,
            authorization_invalidation: None,
            scope_retirements: Vec::new(),
            attribution,
        })
    }

    pub fn prepare_resume_live_for_transport(
        &mut self,
        name: String,
        input: LiveResumeInput,
        authority: PreparedAuthority,
        invalidation: LiveInvalidationAdmission,
    ) -> SnapbackResult<PreparedLiveResume> {
        if authority.source() != InvocationSource::LiveResume {
            return Err(SnapbackError::error(
                "SNAPBACK_INVOCATION_SOURCE_INVALID",
                "auth",
                "live resume requires LiveResume authority",
            ));
        }
        authority.validate_admission("live resume staging")?;
        let effect_fence = invalidation.effect_fence.clone().ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_LIVE_STAGE_FENCE_REQUIRED",
                "realtime",
                "transport live resume staging requires an exact connection effect fence",
            )
        })?;
        self.stage_local_live_effect(
            input.connection_id.clone(),
            effect_fence,
            0,
            [format!("subscription:{}", input.subscription_id)],
            PreparedLiveResumePlan {
                name,
                input,
                authority,
                invalidation,
            },
        )
    }

    pub fn finalize_resume_live_for_transport(
        &mut self,
        staged: &PreparedLiveResume,
    ) -> SnapbackResult<LiveTransportPublication<LiveResumeOutput>> {
        self.finalize_prepared_live_effect(staged, |snapback, plan| {
            snapback.resume_live_for_transport(
                &plan.name,
                plan.input,
                plan.authority,
                plan.invalidation,
            )
        })
    }

    pub(crate) fn resume_live_for_transport(
        &mut self,
        name: &str,
        input: LiveResumeInput,
        authority: PreparedAuthority,
        invalidation: LiveInvalidationAdmission,
    ) -> SnapbackResult<LiveTransportPublication<LiveResumeOutput>> {
        let output =
            self.resume_live_prepared_with_invalidation(name, input, authority, invalidation)?;
        let authorization = output.authorization_scope.as_ref().and_then(|_| {
            self.auth_invalidation
                .as_ref()
                .map(|state| state.obligations.expectation().authorization.clone())
        });
        Ok(LiveTransportPublication {
            output,
            authorization,
        })
    }

    /// Read a page of a table through the schema-aware storage layer for the
    /// admin data explorer.
    ///
    /// @ref LLP 0017#durable-data-exploration-and-edits — read-only exploration
    /// is the paved path; raw engine access is a separate opt-out.
    pub fn scan_table(
        &self,
        table: &str,
        limit: usize,
        offset: usize,
    ) -> SnapbackResult<TableScan> {
        self.db.query_reads_read().scan_table(table, limit, offset)
    }

    /// Run a generated query or mutation through the *same* invocation path as
    /// generated clients, returning a unified envelope with the declared
    /// read/write sets, timing, and any diagnostic instead of an HTTP error — so
    /// the runner can show conflicts and failures inline.
    ///
    /// @ref LLP 0017#function-runner-and-code-runner — generated-function runner
    /// over the normal invocation path; not an arbitrary-JavaScript eval.
    pub fn run_function(&mut self, name: &str, input: HandlerInput) -> FunctionRunResult {
        let authority = match self.admission.admit_dev().and_then(|admission| {
            InvocationGate::prepare_admitted_dev_input(
                InvocationSource::DirectAdminRunner,
                ServerProfile::Dev,
                &input,
                admission,
            )
        }) {
            Ok(authority) => authority,
            Err(error) => return function_run_admission_failure(name, error),
        };
        self.run_function_with_authority(name, input, authority)
    }

    pub fn run_function_with_authority(
        &mut self,
        name: &str,
        input: HandlerInput,
        authority: PreparedAuthority,
    ) -> FunctionRunResult {
        use crate::conformance::{DeclarationConformance, DependencyProvenance};
        let started = Instant::now();
        let definition = match resolve_invocation_function(
            &self.function_generation_recovery_state,
            &self.functions,
            name,
            &[],
        )
        .cloned()
        {
            Ok(definition) => definition,
            Err(error) => {
                return FunctionRunResult {
                    ok: false,
                    function: name.to_owned(),
                    kind: None,
                    reads: Vec::new(),
                    writes: Vec::new(),
                    captured_reads: Vec::new(),
                    captured_writes: Vec::new(),
                    conformance: Some(DeclarationConformance::without_capture(
                        DependencyProvenance::Incomplete,
                    )),
                    admin_bypass: false,
                    elapsed_ms: elapsed_ms(started),
                    version: None,
                    changed_count: None,
                    rows: None,
                    result: None,
                    diagnostic: Some(error.diagnostic),
                };
            }
        };
        let prepared = match InvocationGate::prepare_function(authority, &definition) {
            Ok(prepared) => prepared,
            Err(error) => {
                return FunctionRunResult {
                    ok: false,
                    function: name.to_owned(),
                    kind: Some(definition.kind.clone()),
                    reads: Vec::new(),
                    writes: Vec::new(),
                    captured_reads: Vec::new(),
                    captured_writes: Vec::new(),
                    conformance: Some(DeclarationConformance::without_capture(
                        DependencyProvenance::Incomplete,
                    )),
                    admin_bypass: false,
                    elapsed_ms: elapsed_ms(started),
                    version: None,
                    changed_count: None,
                    rows: None,
                    result: None,
                    diagnostic: Some(error.diagnostic),
                };
            }
        };
        let input = prepared.canonicalize_input(input);

        let (reads, writes) = plan_io(&definition);
        // D1 report (LLP 0146): compute the class-tagged conformance deltas
        // against the same declared sets the result reports. Provenance is
        // per-path: success paths carry an authoritative capture, failure
        // paths do not, and actions construct no capture by design.
        let report = |captured_reads: &[CapturedReadDependency],
                      captured_writes: &[CapturedWriteDependency],
                      read_provenance: DependencyProvenance,
                      write_provenance: DependencyProvenance,
                      schema: &SchemaManifest| {
            Some(crate::conformance::conformance_report(
                &reads,
                &writes,
                captured_reads,
                captured_writes,
                read_provenance,
                write_provenance,
                schema,
            ))
        };
        let kind = definition.kind.clone();
        let base = FunctionRunResult {
            ok: true,
            function: name.to_owned(),
            kind: Some(kind.clone()),
            reads: reads.clone(),
            writes: writes.clone(),
            captured_reads: Vec::new(),
            captured_writes: Vec::new(),
            conformance: None,
            admin_bypass: false,
            elapsed_ms: 0,
            version: None,
            changed_count: None,
            rows: None,
            result: None,
            diagnostic: None,
        };

        match kind {
            FunctionKind::Query | FunctionKind::LiveQuery => {
                match self.invoke_query_with_dependencies_prepared(
                    name,
                    input,
                    prepared.authority().clone(),
                ) {
                    Ok(invocation) => FunctionRunResult {
                        elapsed_ms: elapsed_ms(started),
                        version: Some(invocation.output.version),
                        rows: Some(invocation.output.rows),
                        conformance: report(
                            &invocation.read_dependencies,
                            &[],
                            DependencyProvenance::Complete,
                            DependencyProvenance::Complete,
                            self.db.schema(),
                        ),
                        captured_reads: invocation.read_dependencies,
                        ..base
                    },
                    Err(error) => FunctionRunResult {
                        ok: false,
                        elapsed_ms: elapsed_ms(started),
                        diagnostic: Some(error.diagnostic),
                        conformance: report(
                            &[],
                            &[],
                            DependencyProvenance::Incomplete,
                            DependencyProvenance::Incomplete,
                            self.db.schema(),
                        ),
                        ..base
                    },
                }
            }
            FunctionKind::Mutation => match self.invoke_mutation_commit_with_id_and_authority(
                name,
                input,
                None,
                None,
                None,
                prepared.authority().clone(),
            ) {
                Ok(commit) => FunctionRunResult {
                    elapsed_ms: elapsed_ms(started),
                    version: Some(commit.output.version),
                    changed_count: Some(commit.output.changed_count),
                    result: Some(commit.output.result),
                    conformance: report(
                        &commit.read_dependencies,
                        &commit.write_dependencies,
                        DependencyProvenance::Complete,
                        DependencyProvenance::Complete,
                        self.db.schema(),
                    ),
                    captured_reads: commit.read_dependencies,
                    captured_writes: commit.write_dependencies,
                    ..base
                },
                Err(error) => FunctionRunResult {
                    ok: false,
                    elapsed_ms: elapsed_ms(started),
                    diagnostic: Some(error.diagnostic),
                    conformance: report(
                        &[],
                        &[],
                        DependencyProvenance::Incomplete,
                        DependencyProvenance::Incomplete,
                        self.db.schema(),
                    ),
                    ..base
                },
            },
            FunctionKind::Action => {
                let metadata = manual_action_metadata("admin", name);
                // Successful actions construct empty captured sets by design;
                // the provenance vocabulary exists exactly so this path never
                // reports a conformant verdict from an empty capture. A throw
                // is instead incomplete because execution started but did not
                // yield a complete dependency witness.
                let conformance = report(
                    &[],
                    &[],
                    DependencyProvenance::Unsupported,
                    DependencyProvenance::Unsupported,
                    self.db.schema(),
                );
                match self.invoke_action_prepared(name, input, metadata, prepared) {
                    Ok(result) => FunctionRunResult {
                        elapsed_ms: elapsed_ms(started),
                        result: Some(result),
                        conformance,
                        ..base
                    },
                    Err(error) => FunctionRunResult {
                        ok: false,
                        elapsed_ms: elapsed_ms(started),
                        diagnostic: Some(error.diagnostic),
                        conformance: report(
                            &[],
                            &[],
                            DependencyProvenance::Incomplete,
                            DependencyProvenance::Incomplete,
                            self.db.schema(),
                        ),
                        ..base
                    },
                }
            }
        }
    }

    pub fn function_declared_read_tables(&self, name: &str) -> Vec<String> {
        self.functions
            .function(name)
            .map(|definition| plan_io(definition).0)
            .unwrap_or_default()
    }

    /// The D1 conformance report for one invocation of `name` against the
    /// active schema (LLP 0146 D1 surface 1). The caller supplies the
    /// captured sets it holds and the per-class provenance its seam can
    /// honestly claim; a seam that discarded the capture passes empty sets
    /// with `Incomplete`, never `Complete`.
    pub fn conformance_for_invocation(
        &self,
        name: &str,
        captured_reads: &[CapturedReadDependency],
        captured_writes: &[CapturedWriteDependency],
        read_provenance: crate::conformance::DependencyProvenance,
        write_provenance: crate::conformance::DependencyProvenance,
    ) -> Option<crate::conformance::DeclarationConformance> {
        let definition = self.functions.function(name)?;
        let (reads, writes) = plan_io(definition);
        Some(crate::conformance::conformance_report(
            &reads,
            &writes,
            captured_reads,
            captured_writes,
            read_provenance,
            write_provenance,
            self.db.schema(),
        ))
    }

    pub fn authorization_reservation_snapshot(
        &self,
    ) -> SnapbackResult<(u64, crate::storage::AuthorizationVersion)> {
        self.db.authorization_reservation_snapshot()
    }

    pub(crate) fn authorization_commit_preflight_for_changes(
        &self,
        changes: Vec<ChangedRow>,
    ) -> crate::storage::AuthorizationCommitPreflight {
        if crate::storage::app_writes_are_authorization_event(self.db.schema(), &changes) {
            crate::storage::AuthorizationCommitPreflight::AppWrites {
                schema: Box::new(self.db.schema().clone()),
                changes,
            }
        } else {
            crate::storage::AuthorizationCommitPreflight::NoAuthorizationEvent
        }
    }

    pub(crate) fn authorization_commit_preflight_for_seed(
        &mut self,
        seed: &SeedData,
    ) -> SnapbackResult<crate::storage::AuthorizationCommitPreflight> {
        let changes = self.db.schema_seed().preview_seed_changes(seed.clone())?;
        Ok(self.authorization_commit_preflight_for_changes(changes))
    }

    /// Run an app-data action through the normal action invocation path without
    /// borrowing the admin function runner's metadata. Non-actions return a
    /// diagnostic envelope and are never executed.
    ///
    /// @ref LLP 0028#open-questions — actions are useful
    /// for app-triggered egress, not only scheduled cron runs.
    pub fn run_app_action(&mut self, name: &str, input: HandlerInput) -> FunctionRunResult {
        let started = Instant::now();
        let authority = match self.admission.admit_dev().and_then(|admission| {
            InvocationGate::prepare_admitted_dev_input(
                InvocationSource::LocalAction,
                ServerProfile::Dev,
                &input,
                admission,
            )
        }) {
            Ok(authority) => authority,
            Err(error) => {
                return action_run_result(
                    name,
                    Vec::new(),
                    Vec::new(),
                    elapsed_ms(started),
                    Err(error),
                );
            }
        };
        let stage = match self.stage_app_action_with_authority(name, authority) {
            StagedAppAction::Done(result) => return *result,
            StagedAppAction::Ready(stage) => stage,
        };
        let metadata = manual_action_metadata("action", name);
        let result = match stage.mode {
            StagedAction::HostPlan(prepared) => {
                self.invoke_action_prepared(name, input, metadata, prepared)
            }
            StagedAction::Detached(action) => {
                self.invoke_action_prepared(name, input, metadata, action.invocation.clone())
            }
        };
        action_run_result(name, stage.reads, stage.writes, elapsed_ms(started), result)
    }

    /// Stage an app-action run: resolve the function, reject non-actions with
    /// a ready envelope, and clone out what a detached execution needs. Runs
    /// under the global mutex; the returned stage does not borrow the
    /// instance (ENG-23324).
    pub fn stage_app_action_with_authority(
        &mut self,
        name: &str,
        authority: PreparedAuthority,
    ) -> StagedAppAction {
        self.stage_app_action_with_authority_generation(name, authority, None)
    }

    pub fn stage_app_action_with_authority_generation(
        &mut self,
        name: &str,
        authority: PreparedAuthority,
        expected_generation: Option<&ArtifactGeneration>,
    ) -> StagedAppAction {
        let started = Instant::now();
        // The action lane (the only egress-capable class) consults the
        // persisted migration fence at staging (LLP 0081 §4).
        if let Err(error) = self.db.ensure_migration_lane_open() {
            return StagedAppAction::Done(Box::new(FunctionRunResult {
                ok: false,
                function: name.to_owned(),
                kind: None,
                reads: Vec::new(),
                writes: Vec::new(),
                captured_reads: Vec::new(),
                captured_writes: Vec::new(),
                conformance: Some(crate::conformance::DeclarationConformance::without_capture(
                    crate::conformance::DependencyProvenance::Incomplete,
                )),
                admin_bypass: false,
                elapsed_ms: elapsed_ms(started),
                version: None,
                changed_count: None,
                rows: None,
                result: None,
                diagnostic: Some(error.diagnostic),
            }));
        }
        let definition = match resolve_invocation_function(
            &self.function_generation_recovery_state,
            &self.functions,
            name,
            &[FunctionKind::Action],
        )
        .cloned()
        {
            Ok(definition) => definition,
            Err(error) => {
                return StagedAppAction::Done(Box::new(FunctionRunResult {
                    ok: false,
                    function: name.to_owned(),
                    kind: None,
                    reads: Vec::new(),
                    writes: Vec::new(),
                    captured_reads: Vec::new(),
                    captured_writes: Vec::new(),
                    conformance: Some(crate::conformance::DeclarationConformance::without_capture(
                        crate::conformance::DependencyProvenance::Incomplete,
                    )),
                    admin_bypass: false,
                    elapsed_ms: elapsed_ms(started),
                    version: None,
                    changed_count: None,
                    rows: None,
                    result: None,
                    diagnostic: Some(error.diagnostic),
                }));
            }
        };

        if let Err(error) = self.validate_expected_generation(&authority, expected_generation) {
            return StagedAppAction::Done(Box::new(FunctionRunResult {
                ok: false,
                function: name.to_owned(),
                kind: Some(definition.kind.clone()),
                reads: Vec::new(),
                writes: Vec::new(),
                captured_reads: Vec::new(),
                captured_writes: Vec::new(),
                conformance: Some(crate::conformance::DeclarationConformance::without_capture(
                    crate::conformance::DependencyProvenance::Incomplete,
                )),
                admin_bypass: false,
                elapsed_ms: elapsed_ms(started),
                version: None,
                changed_count: None,
                rows: None,
                result: None,
                diagnostic: Some(error.diagnostic),
            }));
        }

        let (reads, writes) = plan_io(&definition);
        let prepared = match InvocationGate::prepare_function(authority, &definition) {
            Ok(prepared) => prepared,
            Err(error) => {
                return StagedAppAction::Done(Box::new(FunctionRunResult {
                    ok: false,
                    function: name.to_owned(),
                    kind: Some(definition.kind.clone()),
                    reads,
                    writes,
                    captured_reads: Vec::new(),
                    captured_writes: Vec::new(),
                    conformance: Some(crate::conformance::DeclarationConformance::without_capture(
                        crate::conformance::DependencyProvenance::Incomplete,
                    )),
                    admin_bypass: false,
                    elapsed_ms: elapsed_ms(started),
                    version: None,
                    changed_count: None,
                    rows: None,
                    result: None,
                    diagnostic: Some(error.diagnostic),
                }));
            }
        };
        if let Err(error) =
            self.persist_and_validate_prepared_service_authority(prepared.authority())
        {
            return StagedAppAction::Done(Box::new(FunctionRunResult {
                ok: false,
                function: name.to_owned(),
                kind: Some(definition.kind.clone()),
                reads,
                writes,
                captured_reads: Vec::new(),
                captured_writes: Vec::new(),
                conformance: Some(crate::conformance::DeclarationConformance::without_capture(
                    crate::conformance::DependencyProvenance::Incomplete,
                )),
                admin_bypass: false,
                elapsed_ms: elapsed_ms(started),
                version: None,
                changed_count: None,
                rows: None,
                result: None,
                diagnostic: Some(error.diagnostic),
            }));
        }
        if !matches!(definition.kind, FunctionKind::Action) {
            return StagedAppAction::Done(Box::new(FunctionRunResult {
                ok: false,
                function: name.to_owned(),
                kind: Some(definition.kind.clone()),
                reads,
                writes,
                captured_reads: Vec::new(),
                captured_writes: Vec::new(),
                conformance: Some(crate::conformance::DeclarationConformance::without_capture(
                    crate::conformance::DependencyProvenance::Incomplete,
                )),
                admin_bypass: false,
                elapsed_ms: elapsed_ms(started),
                version: None,
                changed_count: None,
                rows: None,
                result: None,
                diagnostic: Some(
                    SnapbackError::error(
                        "SNAPBACK_FUNCTION_KIND_MISMATCH",
                        "runtime",
                        format!("{name} is not an action"),
                    )
                    .diagnostic,
                ),
            }));
        }

        let mode = self.staged_mode(&definition, prepared, None);
        StagedAppAction::Ready(AppActionStage {
            reads,
            writes,
            mode,
        })
    }

    /// Stage one action invocation for the cron flow (no envelope shaping):
    /// unknown functions and non-actions are `SnapbackError`s, exactly as
    /// `invoke_action` would report them (ENG-23324).
    #[cfg(any(test, feature = "test-support"))]
    pub fn stage_action_invocation(&mut self, name: &str) -> SnapbackResult<StagedAction> {
        let admission = self.admission.admit()?;
        self.stage_action_invocation_with_admission(name, admission)
    }

    pub fn stage_action_invocation_with_admission(
        &mut self,
        name: &str,
        admission: AdmissionLease,
    ) -> SnapbackResult<StagedAction> {
        let function = self.function(name)?.clone();
        admission.validate("cron action staging")?;
        let active_mode = admission
            .active_mode()
            .expect("LocalSnapback admissions are always controller-managed");
        let authority = InvocationGate::prepare_admitted_authority(
            InvocationSource::Cron,
            active_mode,
            ServerProfile::Dev,
            admission,
            &WireAuthorityFields::default(),
            ResolvedAppAuthority::System,
            None,
        )?;
        let prepared = InvocationGate::prepare_function(authority, &function)?;
        Ok(self.staged_mode(&function, prepared, None))
    }

    pub fn stage_job_action_invocation_with_admission(
        &mut self,
        name: &str,
        admission: AdmissionLease,
        deferred_push_grant: Option<crate::push::PushDeferredGrantV1>,
        deferred_rehearsal_authority: crate::jobs::DeferredRehearsalAuthority,
    ) -> SnapbackResult<StagedAction> {
        let function = self.function(name)?.clone();
        admission.validate("job action staging")?;
        let active_mode = admission
            .active_mode()
            .expect("LocalSnapback admissions are always controller-managed");
        let authority = InvocationGate::prepare_admitted_authority(
            InvocationSource::Cron,
            active_mode,
            ServerProfile::Dev,
            admission,
            &WireAuthorityFields::default(),
            ResolvedAppAuthority::System,
            None,
        )?;
        let authority = match &self.auth_rehearsal_authority_binding {
            Some(binding) => binding.bind(authority, Some(deferred_rehearsal_authority))?,
            None if !deferred_rehearsal_authority.is_present() => authority,
            None => {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_REHEARSAL_AUTHORITY_ENDED",
                    "auth-rehearsal",
                    "deferred rehearsal work has no admitted process-live authority binding",
                ));
            }
        };
        let prepared = InvocationGate::prepare_function(authority, &function)?;
        Ok(self.staged_mode(&function, prepared, deferred_push_grant))
    }

    fn staged_mode(
        &mut self,
        definition: &FunctionDefinition,
        invocation: PreparedInvocation,
        deferred_push_grant: Option<crate::push::PushDeferredGrantV1>,
    ) -> StagedAction {
        match &definition.runtime {
            FunctionRuntime::IbexModule(module) => {
                StagedAction::Detached(Box::new(DetachedIbexAction {
                    function_name: definition.name.clone(),
                    function_id: definition.id.clone(),
                    stream: definition.stream,
                    stream_initiator: match invocation.authority().resolved() {
                        ResolvedAppAuthority::Session { user_id, .. }
                        | ResolvedAppAuthority::RevalidatedPrincipal { user_id, .. }
                        | ResolvedAppAuthority::DevImpersonation { user_id, .. } => Some(
                            crate::stream_attempt::StreamInitiator::SessionUser(user_id.clone()),
                        ),
                        ResolvedAppAuthority::ServicePrincipal { credential_id, .. } => {
                            Some(crate::stream_attempt::StreamInitiator::ServiceCredential(
                                credential_id.clone(),
                            ))
                        }
                        _ => None,
                    },
                    stream_started: None,
                    ephemeral: self.ephemeral_api(),
                    connected_clients: ConnectedClientObserver {
                        registry: self.connected_clients.clone(),
                    },
                    connected_client_predicate_available: self.db.schema().effective_auth_mode()
                        == AuthMode::Sessions,
                    telemetry: self.telemetry.clone(),
                    module: module.clone(),
                    // @ref LLP 0036#runtime-exposure-d5-d8 — grants are
                    // computed per invocation from the function's `uses`
                    // declaration, at staging time, under the lock.
                    grants: self.config_grants(definition),
                    // Preserve the same staging-time secret identities for
                    // diagnostic scrubbing even if config rotates/unsets while
                    // this detached invocation is running.
                    redactor: self.config.secret_redactor_for(&definition.uses),
                    runtime: self.runtime.clone(),
                    invocation,
                    app_generation: self.app_generation,
                    app_generation_fence: self.app_generation_fence.clone(),
                    deferred_push_grant,
                }))
            }
            _ => StagedAction::HostPlan(invocation),
        }
    }

    pub fn stage_nested_mutation(
        &mut self,
        name: &str,
        input: &HandlerInput,
        authority: PreparedAuthority,
        identity: Option<&ClientMutationIdentity>,
    ) -> SnapbackResult<StagedNestedMutation> {
        let function = self.function(name)?.clone();
        let invocation = InvocationGate::prepare_function(authority, &function)?;
        self.persist_and_validate_prepared_service_authority(invocation.authority())?;
        let mut canonical_input = invocation.canonicalize_input(input.clone());
        bind_authoritative_client_mutation_identity(&mut canonical_input, identity);
        // @ref LLP 0131#runtime-ingress-validation — action-hosted nested
        // mutations validate at staging, before any dry run, handler byte,
        // or detached effect.
        crate::args_contract::validate_function_args(&function, &canonical_input.args)?;
        match &function.runtime {
            FunctionRuntime::HostPlan(HandlerPlan::Mutation(plan))
            | FunctionRuntime::HostPlan(HandlerPlan::WriteWithActivity(
                crate::manifest::WriteWithActivityPlan { mutation: plan, .. },
            )) => {
                preflight_host_plan_authority_writes(&invocation, &function, self.db.schema())?;
                let _epoch_scopes = evaluate_permission_epoch_scopes(&function, &canonical_input)?;
                let preview = self
                    .db
                    .mutation_writes()
                    .dry_run_mutation(plan, &canonical_input)?;
                let mut replay_input = canonical_input;
                replay_input.ctx_ledger = Some(CtxAnswerLedger {
                    version: ctx_ledger_version(),
                    ids: preview.generated_ids,
                    now: preview.now_ms,
                    auth_fingerprint: None,
                });
                Ok(StagedNestedMutation::InLock(StagedHostPlanNestedMutation {
                    preflight: self
                        .authorization_commit_preflight_for_changes(preview.commit.changes),
                    input: replay_input,
                    invocation,
                }))
            }
            FunctionRuntime::IbexModule(_) => {
                // Preserve the ordinary mutation contract: resolve and
                // validate permission-epoch scopes before any handler code
                // executes. The resolved set rides the detached effect to its
                // bounded commit window.
                let epoch_scopes = evaluate_permission_epoch_scopes(&function, &canonical_input)?;
                let read = if self.db.reader_pool().is_some() {
                    DetachedMutationRead::Lane(self.read_lane())
                } else {
                    DetachedMutationRead::Snapshot(Box::new(self.db.detached_read_snapshot()?))
                };
                Ok(StagedNestedMutation::Detached(Box::new(
                    DetachedIbexMutation {
                        binding: DetachedMutationBinding {
                            function,
                            invocation,
                            schema: self.db.schema().clone(),
                            app_generation: self.app_generation,
                            epoch_scopes,
                        },
                        read,
                    },
                )))
            }
            _ => Err(SnapbackError::error(
                "SNAPBACK_FUNCTION_KIND_MISMATCH",
                "runtime",
                format!("{name} is not a mutation"),
            )),
        }
    }

    /// Preview one already-executed detached Ibex mutation in the short Local
    /// window after handler execution. This derives the exact room selector
    /// without opening a transaction that survives the return.
    ///
    /// @ref LLP 0059#authorization-write-handoff — a one-shot Ibex handler is
    ///   buffered once, previewed under Local, then quiesced with Local absent.
    pub fn preview_detached_nested_authorization_mutation(
        &mut self,
        name: &str,
        input: &HandlerInput,
        binding: &DetachedMutationBinding,
        executed: &mut ExecutedIbexMutation,
        identity: Option<&ClientMutationIdentity>,
    ) -> SnapbackResult<crate::storage::AuthorizationCommitPreflight> {
        binding
            .invocation
            .validate_admission("detached nested mutation preview")?;
        self.persist_and_validate_prepared_service_authority(binding.invocation.authority())?;
        let function = self.function(name)?.clone();
        if function != binding.function
            || self.db.schema() != &binding.schema
            || self.app_generation != binding.app_generation
        {
            return Err(SnapbackError::error(
                "SNAPBACK_MUTATION_CONFLICT",
                "runtime",
                format!(
                    "app code or schema changed while action-hosted mutation {name} was running"
                ),
            ));
        }
        let mut canonical_input = binding.invocation.canonicalize_input(input.clone());
        bind_authoritative_client_mutation_identity(&mut canonical_input, identity);
        let expected_media_projection_binding = expected_media_projection_binding(
            &binding.invocation,
            &canonical_input,
            executed,
            identity,
        )?;
        let membership_plans = executed.preview_membership_commands(&mut self.db)?;
        let preview = self
            .db
            .mutation_writes()
            .dry_run_buffered_writes_with_jobs(
                &canonical_input,
                executed.writes.clone(),
                executed.sequence_allocations.clone(),
                membership_plans,
                executed.reads.clone(),
                executed.result.clone(),
                executed.ctx_ledger.clone(),
                Vec::new(),
                None,
                executed.asset_admissions.clone(),
                executed.asset_grant_ops.clone(),
                executed.media_projection_proof.as_ref(),
                expected_media_projection_binding.as_ref(),
            )?;
        Ok(self.authorization_commit_preflight_for_changes(preview.changes))
    }
    /// Validate declared config entries fail-closed, validate per-function
    /// `uses` grants, and run the one-time deprecated env-blob import.
    ///
    /// @ref LLP 0036#declared-configuration-in-the-manifest — manifest load
    /// rejects invalid declarations the way cron validation does; a rejected
    /// entry is removed from the effective declaration set rather than half
    /// working.
    fn reconcile_config(&mut self) -> Vec<Diagnostic> {
        let mut diagnostics = Vec::new();
        let mut accepted: Vec<crate::manifest::ConfigEntryDefinition> = Vec::new();
        let mut seen = std::collections::BTreeSet::new();

        for entry in self.functions.config.clone() {
            if entry.name.is_empty()
                || !entry
                    .name
                    .chars()
                    .all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-')
            {
                diagnostics.push(
                    SnapbackError::error(
                        "SNAPBACK_CONFIG_ENTRY_INVALID",
                        "config",
                        format!(
                            "config entry name {:?} is invalid; entry names use [A-Za-z0-9_-]",
                            entry.name
                        ),
                    )
                    .diagnostic,
                );
                continue;
            }
            if !seen.insert(entry.name.clone()) {
                diagnostics.push(
                    SnapbackError::error(
                        "SNAPBACK_CONFIG_ENTRY_INVALID",
                        "config",
                        format!("config entry {} is declared more than once", entry.name),
                    )
                    .diagnostic,
                );
                continue;
            }
            // @ref LLP 0036#implementation-order — the v1 slice is secret
            // entries only; non-secret entries fail closed at validation (the
            // cron Backoff precedent), never half-work.
            if !entry.secret {
                diagnostics.push(
                    SnapbackError::error(
                        "SNAPBACK_CONFIG_NON_SECRET_UNIMPLEMENTED",
                        "config",
                        format!(
                            "config entry {} declares secret: false, but non-secret config \
                             entries are not implemented yet; declare it secret or remove it",
                            entry.name
                        ),
                    )
                    .diagnostic,
                );
                continue;
            }
            if entry.default.is_some() {
                diagnostics.push(
                    SnapbackError::error(
                        "SNAPBACK_CONFIG_DEFAULT_UNIMPLEMENTED",
                        "config",
                        format!(
                            "config entry {} declares a default, which only non-secret entries \
                             may carry — and those are not implemented yet",
                            entry.name
                        ),
                    )
                    .diagnostic,
                );
                continue;
            }
            if let Some(probe) = &entry.probe {
                match self.functions.function(probe) {
                    Some(function) if matches!(function.kind, FunctionKind::Action) => {}
                    Some(_) => {
                        diagnostics.push(
                            SnapbackError::error(
                                "SNAPBACK_CONFIG_PROBE_INVALID",
                                "config",
                                format!(
                                    "config entry {} names probe {probe}, which is not an action",
                                    entry.name
                                ),
                            )
                            .diagnostic,
                        );
                        continue;
                    }
                    None => {
                        diagnostics.push(
                            SnapbackError::error(
                                "SNAPBACK_CONFIG_PROBE_INVALID",
                                "config",
                                format!(
                                    "config entry {} names unknown probe function {probe}",
                                    entry.name
                                ),
                            )
                            .diagnostic,
                        );
                        continue;
                    }
                }
            }
            accepted.push(entry);
        }

        let declared: std::collections::BTreeSet<&str> =
            accepted.iter().map(|entry| entry.name.as_str()).collect();
        for function in &self.functions.functions {
            for name in &function.uses {
                if !declared.contains(name.as_str()) {
                    diagnostics.push(
                        SnapbackError::error(
                            "SNAPBACK_CONFIG_USES_UNKNOWN",
                            "config",
                            format!(
                                "function {} declares uses: {name}, which is not a declared \
                                 config entry; access will fail with SNAPBACK_CONFIG_UNDECLARED",
                                function.name
                            ),
                        )
                        .diagnostic,
                    );
                }
            }
        }
        self.functions.config = accepted;

        // One-time import from the deprecated env blob (LLP 0036 v1 slice
        // item 2): declared names only, never after the store's first write.
        if let Ok(blob_raw) = std::env::var("SNAPBACK_ACTION_SECRETS")
            && !blob_raw.trim().is_empty()
        {
            diagnostics.push(Diagnostic::warning(
                "SNAPBACK_ACTION_SECRETS_DEPRECATED",
                "config",
                "SNAPBACK_ACTION_SECRETS is deprecated; values are imported once into the \
                 config store — manage them via the setup wizard or /_snapback/api/config/*",
            ));
            match serde_json::from_str::<Value>(&blob_raw) {
                Ok(Value::Object(blob)) => {
                    let declared_names: Vec<String> = self
                        .functions
                        .config
                        .iter()
                        .map(|entry| entry.name.clone())
                        .collect();
                    match self
                        .config
                        .import_env_blob(&blob, &declared_names, now_millis())
                    {
                        Ok(outcome) => {
                            if !outcome.imported.is_empty() || !outcome.ignored.is_empty() {
                                diagnostics.push(
                                    Diagnostic::info(
                                        "SNAPBACK_CONFIG_ENV_IMPORTED",
                                        "config",
                                        "imported deprecated SNAPBACK_ACTION_SECRETS values into \
                                         the config store",
                                    )
                                    .with_details(json!({
                                        "imported": outcome.imported,
                                        "ignored": outcome.ignored,
                                        "skippedExistingStore": outcome.skipped_existing_store,
                                    })),
                                );
                            }
                        }
                        Err(error) => diagnostics.push(error.diagnostic),
                    }
                }
                _ => diagnostics.push(Diagnostic::warning(
                    "SNAPBACK_ACTION_SECRETS_INVALID",
                    "config",
                    "SNAPBACK_ACTION_SECRETS is set but is not a JSON object; nothing imported",
                )),
            }
        }

        let missing = self.required_missing_config();
        if !missing.is_empty() {
            diagnostics.push(
                Diagnostic::warning(
                    "SNAPBACK_CONFIG_REQUIRED_MISSING",
                    "config",
                    format!(
                        "{} required config entr{} missing ({}); open the setup wizard at \
                         /_snapback/admin/setup",
                        missing.len(),
                        if missing.len() == 1 {
                            "y is"
                        } else {
                            "ies are"
                        },
                        missing.join(", ")
                    ),
                )
                .with_details(json!({ "entries": missing })),
            );
        }

        diagnostics
    }

    /// Names of required, declared entries with no stored value.
    pub fn required_missing_config(&self) -> Vec<String> {
        self.functions
            .config
            .iter()
            .filter(|entry| entry.required && self.config.values(&entry.name).is_none())
            .map(|entry| entry.name.clone())
            .collect()
    }

    fn config_definition(
        &self,
        name: &str,
    ) -> SnapbackResult<&crate::manifest::ConfigEntryDefinition> {
        self.functions
            .config
            .iter()
            .find(|entry| entry.name == name)
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_CONFIG_UNDECLARED",
                    "config",
                    format!("{name} is not a declared config entry"),
                )
            })
    }

    /// The full LLP 0036 status primitive: declared × set × verified ×
    /// applied, names and states only — never values.
    pub fn config_status(&self) -> ConfigStatus {
        let entries = self
            .functions
            .config
            .iter()
            .map(|def| {
                let stored = self.config.entry(&def.name);
                ConfigEntryStatus {
                    name: def.name.clone(),
                    description: def.description.clone(),
                    purpose: def.purpose.clone(),
                    secret: def.secret,
                    required: def.required,
                    pool: def.pool,
                    probe: def.probe.clone(),
                    how_to_get: def.how_to_get.clone(),
                    acquisition: def.acquisition.clone(),
                    set: stored.is_some(),
                    member_count: stored.map(|entry| entry.member_count()).unwrap_or(0),
                    last_changed_ms: stored.map(|entry| entry.set_at_ms),
                    source: stored.map(|entry| entry.source.clone()),
                    verified: stored
                        .and_then(|entry| entry.verified.as_ref())
                        .map(ConfigVerificationStatus::from),
                    // v1 is local-file-immediate: every write applies at once.
                    apply_state: "applied".to_owned(),
                }
            })
            .collect();
        ConfigStatus {
            generation: self.config.generation(),
            backend_class: if self.config.is_persistent() {
                "local-file-immediate".to_owned()
            } else {
                "in-memory".to_owned()
            },
            app_provisioned: self.functions_loaded,
            entries,
            required_missing: self.required_missing_config(),
        }
    }

    pub fn set_telemetry_config(
        &mut self,
        config: crate::telemetry::TelemetryConfig,
    ) -> SnapbackResult<crate::config::WriteOutcome> {
        let previous = self.config.telemetry_config().clone();
        // @ref LLP 0154#d4--maintenance-rides-the-flush-path-no-cron — the
        // retention floor is monotonic, so a policy must be durable before
        // the telemetry sibling is allowed to advance it.
        let outcome = self.config.set_telemetry_config(config.clone())?;
        match self.telemetry.update_config(config) {
            Ok(()) => Ok(outcome),
            Err(runtime_error) => {
                if let Err(compensation_error) = self.config.set_telemetry_config(previous) {
                    // Neither durable config value can now be trusted as a
                    // description of the live sibling policy. Close admission
                    // until restart performs a fresh durable rebind.
                    self.telemetry.begin_generation_transition();
                    return Err(SnapbackError::error(
                        "SNAPBACK_TELEMETRY_CONFIG_TRANSITION_FAILED",
                        "telemetry",
                        "the telemetry runtime rejected a durable config transition and the previous durable config could not be restored; telemetry admission is closed until restart",
                    )
                    .with_details(json!({
                        "runtimeCode": runtime_error.diagnostic.code,
                        "compensationCode": compensation_error.diagnostic.code,
                    })));
                }
                Err(runtime_error)
            }
        }
    }

    /// `config.plan` facts for this target: v1 is always the in-server,
    /// immediately-applying `local-file-immediate` locus, and saying so pins
    /// the contract hosted backends will answer differently.
    ///
    /// @ref LLP 0036#operations-and-projections-llp-0024 — dry-run: no write.
    pub fn config_plan(
        &self,
        entry: Option<&str>,
        value_writes_accepted: bool,
    ) -> SnapbackResult<ConfigPlan> {
        if let Some(name) = entry {
            self.config_definition(name)?;
        }
        Ok(ConfigPlan {
            backend_class: if self.config.is_persistent() {
                "local-file-immediate".to_owned()
            } else {
                "in-memory".to_owned()
            },
            write_locus: "in-server".to_owned(),
            applies_immediately: true,
            value_writes_accepted,
            generation: self.config.generation(),
            entry: entry.map(str::to_owned),
            would_apply_state: "applied".to_owned(),
        })
    }

    /// Set a declared entry (replace, or append a pool member). Audit facts —
    /// never values — land in the diagnostics ring.
    pub fn set_config_entry(
        &mut self,
        name: &str,
        values: Vec<String>,
        append: bool,
        source: &str,
    ) -> SnapbackResult<ConfigWriteOutcome> {
        let pool = self.config_definition(name)?.pool;
        if !pool && (values.len() > 1 || append) {
            return Err(SnapbackError::error(
                "SNAPBACK_CONFIG_VALUE_INVALID",
                "config",
                format!("config entry {name} is not a pool; set exactly one value"),
            ));
        }
        let outcome = self
            .config
            .set(name, values, append, source, now_millis())?;
        self.record_attached_diagnostics(vec![
            Diagnostic::info(
                "SNAPBACK_CONFIG_WRITE",
                "config",
                format!("config entry {name} set via {source}"),
            )
            .with_details(json!({
                "entry": name,
                "operation": "set",
                "valueChanged": outcome.value_changed,
                "source": source,
            })),
        ]);
        Ok(ConfigWriteOutcome {
            entry: name.to_owned(),
            apply_state: "applied".to_owned(),
            value_changed: outcome.value_changed,
            generation: outcome.generation,
        })
    }

    /// Remove an entry's stored value. Deliberately works for names that are
    /// no longer declared, so stale values can always be cleaned up.
    pub fn unset_config_entry(
        &mut self,
        name: &str,
        source: &str,
    ) -> SnapbackResult<ConfigWriteOutcome> {
        let outcome = self.config.unset(name)?;
        self.record_attached_diagnostics(vec![
            Diagnostic::info(
                "SNAPBACK_CONFIG_WRITE",
                "config",
                format!("config entry {name} unset via {source}"),
            )
            .with_details(json!({
                "entry": name,
                "operation": "unset",
                "valueChanged": outcome.value_changed,
                "source": source,
            })),
        ]);
        Ok(ConfigWriteOutcome {
            entry: name.to_owned(),
            apply_state: "applied".to_owned(),
            value_changed: outcome.value_changed,
            generation: outcome.generation,
        })
    }

    /// Run an entry's probe action and record the verification outcome, all
    /// under the caller's borrow. The server route instead stages with
    /// [`Self::stage_config_verify`], runs an Ibex probe detached under the
    /// action watchdog, and records with [`Self::finish_config_verify`]
    /// (ENG-23493); this in-lock convenience remains for embedded use and
    /// tests.
    ///
    /// @ref LLP 0036#operations-and-projections-llp-0024 — probes run only on
    /// explicit verify, under cooldown, as ordinary actions with no special
    /// network powers; results land in verification state, never raw in logs.
    pub fn verify_config_entry(&mut self, name: &str) -> SnapbackResult<ConfigVerifyOutcome> {
        match self.stage_config_verify(name)? {
            StagedConfigVerify::Done(outcome) => Ok(*outcome),
            StagedConfigVerify::Ready(stage) => {
                let admission = stage.admission.clone();
                let result = match stage.mode {
                    StagedAction::HostPlan(prepared) => self.invoke_action_prepared(
                        &stage.probe,
                        stage.input,
                        stage.metadata,
                        prepared,
                    ),
                    StagedAction::Detached(action) => self.invoke_action_prepared(
                        &stage.probe,
                        stage.input,
                        stage.metadata,
                        action.invocation,
                    ),
                };
                self.finish_config_verify(
                    name,
                    stage.entry_revision,
                    stage.started_ms,
                    result,
                    admission,
                )
            }
        }
    }

    /// Stage a config-verify probe run: entry checks and the cooldown claim
    /// happen here, under the global mutex, so concurrent verifies linearize
    /// through the cooldown stamp even when the probe itself runs off-lock
    /// (ENG-23493).
    pub fn stage_config_verify(&mut self, name: &str) -> SnapbackResult<StagedConfigVerify> {
        let admission = self.admission.admit()?;
        let definition = self.config_definition(name)?.clone();
        let Some(probe) = definition.probe.clone() else {
            return Err(SnapbackError::error(
                "SNAPBACK_CONFIG_PROBE_MISSING",
                "config",
                format!("config entry {name} declares no probe action"),
            ));
        };
        if self.config.values(name).is_none() {
            return Err(SnapbackError::error(
                "SNAPBACK_CONFIG_MISSING",
                "config",
                format!("config entry {name} has no value set; set it before verifying"),
            ));
        }
        let entry_revision = self.config.entry_revision(name).ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_CONFIG_MISSING",
                "config",
                format!("config entry {name} disappeared before verification staged"),
            )
        })?;
        let now = now_millis();
        {
            let _claim = admission.effect_guard("config verification cooldown claim")?;
            self.config.check_verify_cooldown(name, now)?;
        }
        let metadata = CronRunMetadata {
            job_name: format!("config-verify:{name}"),
            run_id: format!("config-verify:{name}:{now}"),
            scheduled_at_ms: None,
            due_at_ms: now,
            idempotency_key: format!("config-verify:{name}:{now}"),
            slot_key: format!("config-verify:{name}"),
            attempt: 1,
            trigger: CronRunTrigger::Manual,
        };
        let input = HandlerInput {
            args: json!({ "entry": name }),
            auth: Default::default(),
            read_set: Vec::new(),
            correlation: None,
            ctx_ledger: None,
        };
        let mode = match self.stage_action_invocation_with_admission(&probe, admission.clone()) {
            Ok(mode) => mode,
            // A probe that cannot stage (unknown function, non-action) is a
            // failed verification, exactly as the in-lock run reported it.
            Err(error) => {
                return Ok(StagedConfigVerify::Done(Box::new(
                    self.finish_config_verify(name, entry_revision, now, Err(error), admission)?,
                )));
            }
        };
        Ok(StagedConfigVerify::Ready(Box::new(ConfigVerifyStage {
            probe,
            entry_revision,
            started_ms: now,
            input,
            metadata,
            mode,
            admission,
        })))
    }

    /// Record the outcome of a probe run — in-lock or detached — as the
    /// entry's verification state and shape the `config.verify` envelope.
    pub fn finish_config_verify(
        &mut self,
        name: &str,
        entry_revision: u64,
        at_ms: u64,
        result: SnapbackResult<Value>,
        admission: AdmissionLease,
    ) -> SnapbackResult<ConfigVerifyOutcome> {
        #[cfg(test)]
        BEFORE_CONFIG_VERIFY_PUBLICATION_HOOK.with(|slot| {
            if let Some(hook) = slot.borrow_mut().take() {
                hook();
            }
        });
        let _publication = admission.effect_guard("config verification publication")?;
        let record = match result {
            Ok(value) => match value.get("ok").and_then(Value::as_bool) {
                Some(true) => VerificationRecord {
                    ok: true,
                    at_ms,
                    diagnostic: None,
                },
                Some(false) => VerificationRecord {
                    ok: false,
                    at_ms,
                    diagnostic: Some(
                        self.config.redact_text(
                            value
                                .get("message")
                                .and_then(Value::as_str)
                                .unwrap_or("probe reported failure"),
                        ),
                    ),
                },
                None => VerificationRecord {
                    ok: false,
                    at_ms,
                    diagnostic: Some(
                        "probe did not return the closed { ok: boolean } result shape".to_owned(),
                    ),
                },
            },
            Err(error) => {
                let error = self.config.redact_diagnostic(error.diagnostic);
                VerificationRecord {
                    ok: false,
                    at_ms,
                    diagnostic: Some(format!("{}: {}", error.code, error.message)),
                }
            }
        };
        if !self
            .config
            .record_verification_if_revision(name, entry_revision, record.clone())?
        {
            return Err(SnapbackError::error(
                "SNAPBACK_CONFIG_VERIFY_STALE",
                "config",
                format!(
                    "config entry {name} changed while its probe was running; the result was discarded"
                ),
            ));
        }
        self.record_attached_diagnostics(vec![
            Diagnostic::info(
                "SNAPBACK_CONFIG_VERIFY",
                "config",
                format!(
                    "config entry {name} verification {}",
                    if record.ok { "succeeded" } else { "failed" }
                ),
            )
            .with_details(json!({ "entry": name, "ok": record.ok })),
        ]);
        Ok(ConfigVerifyOutcome {
            entry: name.to_owned(),
            ok: record.ok,
            verified: ConfigVerificationStatus::from(&record),
            generation: self.config.generation(),
        })
    }

    /// The granted-config payload for one action invocation: the function's
    /// `uses` entries (plus the entry a probe verifies, implicitly), with
    /// value material and a rotation cursor for pools.
    ///
    /// @ref LLP 0036#runtime-exposure-d5-d8 — grants are computed host-side
    /// per invocation; handler code never sees undeclared entries.
    fn config_grants(&mut self, function: &crate::manifest::FunctionDefinition) -> Value {
        let mut names: Vec<String> = function.uses.clone();
        for entry in &self.functions.config {
            if entry.probe.as_deref() == Some(function.name.as_str())
                && !names.contains(&entry.name)
            {
                names.push(entry.name.clone());
            }
        }
        let granted_defs: Vec<(String, bool)> = names
            .iter()
            .filter_map(|name| {
                self.functions
                    .config
                    .iter()
                    .find(|entry| &entry.name == name)
                    .map(|entry| (entry.name.clone(), entry.pool))
            })
            .collect();
        let mut entries = serde_json::Map::new();
        for (name, pool) in granted_defs {
            let values: Option<Vec<String>> = self.config.values(&name).map(<[String]>::to_vec);
            let granted = match values {
                Some(values) if !values.is_empty() => {
                    let cursor = if pool {
                        self.config.next_rotation_cursor(&name)
                    } else {
                        0
                    };
                    json!({ "set": true, "values": values, "cursor": cursor })
                }
                _ => json!({ "set": false }),
            };
            entries.insert(name, granted);
        }
        json!({ "entries": entries })
    }

    /// The kind of a loaded function, if any. Used by the admin function runner
    /// to decide whether a run is a read (query) or a write (mutation).
    pub fn function_kind(&self, name: &str) -> Option<FunctionKind> {
        self.functions
            .function(name)
            .map(|function| function.kind.clone())
    }

    pub fn register_ephemeral_collection(
        &mut self,
        collection: EphemeralCollection,
    ) -> Result<(), crate::ephemeral::EphemeralError> {
        validate_collection_definitions(std::slice::from_ref(&collection))?;
        // @ref LLP 0053#ephemeral-room-authority-invalidation — dynamic
        // registration must preserve the same permissionFields/projection
        // closure as manifest publication or invalidation can miss a room.
        validate_collection_permission_backing(
            std::slice::from_ref(&collection),
            &self.db.schema().tables,
            self.db.schema().effective_auth_mode() == AuthMode::Sessions,
        )?;
        self.ephemeral.register_collection(collection)
    }

    pub fn ensure_ephemeral_collections(
        &mut self,
        collections: Vec<EphemeralCollection>,
    ) -> Result<CollectionEnsureOutcome, crate::ephemeral::EphemeralError> {
        validate_collection_definitions(&collections)?;
        validate_collection_permission_backing(
            &collections,
            &self.db.schema().tables,
            self.db.schema().effective_auth_mode() == AuthMode::Sessions,
        )?;
        self.ephemeral.ensure_collections(collections)
    }

    pub fn publish_ephemeral(
        &mut self,
        request: PublishRequest,
        now_ms: u64,
    ) -> Result<PublishOutcome, crate::ephemeral::EphemeralError> {
        // The ephemeral-publish lane consults the persisted migration fence
        // (LLP 0081 §4's lane registry); the typed storage refusal maps to
        // the lane's own error vocabulary.
        if let Err(error) = self.db.ensure_migration_lane_open() {
            return Err(crate::ephemeral::EphemeralError::migration_fenced(
                error.diagnostic.message,
            ));
        }
        self.touch_connection(&request.connection_id, now_ms);
        self.ephemeral.publish(request, now_ms)
    }

    pub fn subscribe_ephemeral(
        &mut self,
        request: SubscribeRequest,
        now_ms: u64,
    ) -> Result<EphemeralMessage, crate::ephemeral::EphemeralError> {
        self.touch_connection(&request.connection_id, now_ms);
        self.ephemeral.subscribe(request, now_ms)
    }

    pub fn delete_ephemeral(
        &mut self,
        request: DeleteRequest,
        now_ms: u64,
    ) -> Result<crate::ephemeral::DeleteSettlement, crate::ephemeral::EphemeralError> {
        self.touch_connection(&request.connection_id, now_ms);
        self.ephemeral.delete(request, now_ms)
    }

    /// Direct-library compatibility orchestrator. Production transport code
    /// uses the explicit [`EphemeralApi::disconnect`] and
    /// [`Self::disconnect_topology_for_transport`] phases because it owns a
    /// `LocalSnapbackWriteScope`; invoking this compatibility seam from such a
    /// scope fails loudly in debug/test builds.
    pub fn disconnect(&mut self, connection_id: &str, now_ms: u64) {
        crate::exec_guard::debug_assert_local_snapback_write_scope_inactive(
            "LocalSnapback::disconnect compatibility orchestration",
        );
        let ephemeral = self.ephemeral_api();
        ephemeral.disconnect(connection_id, now_ms);
        let topology = self.disconnect_topology_for_transport(connection_id, now_ms);
        ephemeral.enqueue_disconnected_subscription_resync(connection_id, &topology);
    }

    /// Direct-library compatibility form of generation-guarded teardown. The
    /// production WebSocket path performs its guarded ephemeral phase before
    /// taking LocalSnapback and calls only the topology method below.
    pub fn disconnect_guarded(&mut self, connection_id: &str, now_ms: u64) {
        crate::exec_guard::debug_assert_local_snapback_write_scope_inactive(
            "LocalSnapback::disconnect_guarded compatibility orchestration",
        );
        let ephemeral = self.ephemeral_api();
        ephemeral.disconnect_guarded(connection_id, now_ms);
        self.disconnect_topology_for_transport(connection_id, now_ms);
    }

    /// Retire only LocalSnapback-owned connection topology. Callers must run
    /// the [`EphemeralApi`] disconnect phase outside Local before entering
    /// this method; no activity, notifier, room, outbox, or rate-bucket lock
    /// is acquired here.
    pub fn disconnect_topology_for_transport(
        &mut self,
        connection_id: &str,
        now_ms: u64,
    ) -> DisconnectedConnectionTopology {
        self.terminalize_local_live_effects(connection_id, None);
        // A connection's durable live subscriptions are dead once the connection
        // goes away — there is no way to deliver further deltas. Dropping them lets
        // a demand-activated cron job deactivate when its last watcher leaves.
        // @ref LLP 0028#activation-policy — whileLive activation must report
        //   inactive:no-demand once no subscription to the named live query remains.
        // Disposed-by-disconnect markers go to the GLOBAL ring (the
        // connection's own ring dies with it) — LLP 0034 §3 / ENG-22478.
        // No storage read here: disconnect runs on the WebSocket teardown
        // path (an async worker; the L7 exec guard forbids rusqlite there),
        // and a version-at-death fact is cosmetic — null is the honest value.
        let mut dropped_subscriptions = 0_usize;
        let dropped_effect_fences = self
            .subscriptions
            .values()
            .filter(|subscription| subscription.connection_id == connection_id)
            .filter_map(|subscription| subscription.effect_fence.clone())
            .collect::<BTreeSet<_>>();
        let retired_authorization_scopes = self
            .subscriptions
            .values()
            .filter(|subscription| subscription.connection_id == connection_id)
            .filter_map(|subscription| {
                subscription
                    .authorization
                    .as_ref()
                    .map(|authorization| authorization.scope_id.clone())
            })
            .collect::<Vec<_>>();
        let retired_subscription_ids = self
            .subscriptions
            .values()
            .filter(|subscription| subscription.connection_id == connection_id)
            .map(|subscription| subscription.id.clone())
            .collect::<Vec<_>>();
        for subscription in self
            .subscriptions
            .values()
            .filter(|subscription| subscription.connection_id == connection_id)
        {
            dropped_subscriptions += 1;
            subscription.observation.finish(200, None, "disconnected");
            self.receipts.push_global(
                Receipt::Subscription {
                    event: SubscriptionReceiptEvent::Disposed,
                    reason: Some("disconnected".to_owned()),
                    subscription_id: Some(subscription.id.clone()),
                    superseded_by: None,
                    lane: None,
                    binding_id: None,
                    collection: None,
                    removed: None,
                    scope: subscription.input.args.clone(),
                    snapshot_version: None,
                    correlation: None,
                    received_at_ms: now_ms,
                }
                .into_value(),
            );
        }
        self.subscriptions
            .retain(|_, subscription| subscription.connection_id != connection_id);
        for subscription_id in retired_subscription_ids {
            self.pending_live_fanout
                .evaluation_memo
                .retire_subscription(&subscription_id);
        }
        self.refresh_auth_scoped_live_connections();
        if let Some(state) = self.auth_invalidation.as_mut() {
            for scope in retired_authorization_scopes {
                let _ = state.obligations.retire_scope(&scope);
            }
        }
        self.receipts.drop_connection(connection_id);
        // Losing the last watcher of a demand-gated live query disarms its cron
        // job (L5).
        self.refresh_cron_active();
        DisconnectedConnectionTopology {
            dropped_subscriptions,
            dropped_effect_fences,
        }
    }

    /// Ephemeral delivery diagnostics for the receipts surface (LLP 0034
    /// §3.2: coalesced_updates as a receipt-visible fact).
    pub fn ephemeral_diagnostics(&mut self) -> EphemeralDiagnostics {
        self.ephemeral.diagnostics()
    }

    pub fn cleanup_ephemeral(&mut self, now_ms: u64) {
        self.ephemeral.cleanup_expired(now_ms);
    }

    /// Tick the cron scheduler, routing the tick machinery's *own* errors
    /// (claim/persist failures) into the diagnostics ring with a counter
    /// instead of dropping them. Failed cron *runs* already record diagnostics
    /// inside `execute_cron_claims`; this closes the gap where `tick_cron`'s
    /// Err was silently swallowed by the 1s ticker.
    ///
    /// @ref LLP 0032#phase-1--safety-floor-and-confirmed-defects — S5.D11.
    pub fn tick_cron_recording(&mut self, now_ms: u64) -> Vec<CronRunRecord> {
        match self.tick_cron(now_ms) {
            Ok(records) => records,
            Err(error) => {
                self.record_cron_tick_error(error, DiagnosticBoundary::Standalone);
                Vec::new()
            }
        }
    }

    /// Count of swallowed-then-recorded cron tick errors, surfaced for tests
    /// and inspection.
    pub fn cron_tick_errors(&self) -> u64 {
        self.cron_tick_errors
    }

    pub fn tick_cron(&mut self, now_ms: u64) -> SnapbackResult<Vec<CronRunRecord>> {
        let claims = self.claim_due_cron_runs(now_ms)?;
        self.execute_cron_claims(claims)
    }

    /// Claim (and persist) the due cron runs without executing them. The
    /// server's detached cron flow uses this as the first lock window; the
    /// claims then execute off the global mutex and land back through
    /// [`Self::finish_cron_claim`] (ENG-23324).
    pub fn claim_due_cron_runs(&mut self, now_ms: u64) -> SnapbackResult<Vec<AdmittedCronClaim>> {
        self.deny_derived_fork_egress(crate::instance_fork::EgressFamily::CronTick, now_ms)?;
        // The cron lane consults the persisted migration fence per claim
        // (LLP 0081 §4's lane registry).
        self.db.ensure_migration_lane_open()?;
        // Admission precedes the scheduler mutation and its durable claim
        // write. If a close races while a multi-job batch is being assembled,
        // acquisition of any remaining per-claim root fails and the in-memory
        // scheduler rolls back before persistence.
        let first_admission = self.admission.admit()?;
        let active_live_functions = self.active_live_functions();
        let before_claim = self.cron.clone();
        let claims = self
            .cron
            .claim_due_runs(&self.functions, &active_live_functions, now_ms);
        if claims.is_empty() {
            let effect = match first_admission.effect_guard("cron scheduler state publication") {
                Ok(effect) => effect,
                Err(error) => {
                    self.cron = before_claim;
                    return Err(error);
                }
            };
            if let Err(error) = self.persist_cron_state() {
                self.cron = before_claim;
                return Err(error);
            }
            drop(effect);
            return Ok(Vec::new());
        }
        let mut admissions = Vec::with_capacity(claims.len());
        admissions.push(first_admission);
        for _ in 1..claims.len() {
            match self.admission.admit() {
                Ok(admission) => admissions.push(admission),
                Err(error) => {
                    self.cron = before_claim;
                    return Err(error);
                }
            }
        }
        let effect = match admissions[0].effect_guard("cron claim publication") {
            Ok(effect) => effect,
            Err(error) => {
                self.cron = before_claim;
                return Err(error);
            }
        };
        if let Err(error) = self.persist_cron_state() {
            self.cron = before_claim;
            return Err(error);
        }
        drop(effect);
        Ok(claims
            .into_iter()
            .zip(admissions)
            .map(|(claim, admission)| {
                let observation = self.telemetry.start_classified_span(
                    crate::telemetry_contract::OperationClassIdV1::JOB_SCHEDULER,
                    &claim.metadata.job_name,
                    Some(&claim.metadata.run_id),
                    Some(claim.metadata.telemetry_details()),
                );
                AdmittedCronClaim {
                    claim,
                    admission,
                    observation,
                }
            })
            .collect())
    }

    /// Claim (and persist) a manual run of one cron job — the detached-flow
    /// counterpart of [`Self::run_cron_job_now`]'s claim step (ENG-23324).
    pub fn claim_manual_cron_run(
        &mut self,
        name: &str,
        now_ms: u64,
    ) -> SnapbackResult<AdmittedCronClaim> {
        self.deny_derived_fork_egress(crate::instance_fork::EgressFamily::CronTick, now_ms)?;
        self.db.ensure_migration_lane_open()?;
        let admission = self.admission.admit()?;
        let before_claim = self.cron.clone();
        let claim = self.cron.claim_manual_run(&self.functions, name, now_ms)?;
        let effect = match admission.effect_guard("manual cron claim publication") {
            Ok(effect) => effect,
            Err(error) => {
                self.cron = before_claim;
                return Err(error);
            }
        };
        if let Err(error) = self.persist_cron_state() {
            self.cron = before_claim;
            return Err(error);
        }
        drop(effect);
        let observation = self.telemetry.start_classified_span(
            crate::telemetry_contract::OperationClassIdV1::JOB_SCHEDULER,
            &claim.metadata.job_name,
            Some(&claim.metadata.run_id),
            Some(claim.metadata.telemetry_details()),
        );
        Ok(AdmittedCronClaim {
            claim,
            admission,
            observation,
        })
    }

    /// Route a cron tick's *machinery* error (claim/persist/finish failure)
    /// into the diagnostics ring with a counter — the same policy as
    /// [`Self::tick_cron_recording`], callable from the server's detached
    /// cron flow.
    pub fn record_cron_tick_error(
        &mut self,
        error: SnapbackError,
        diagnostic_boundary: DiagnosticBoundary,
    ) {
        self.cron_tick_errors += 1;
        self.record_diagnostics_at_boundary(vec![error.diagnostic], diagnostic_boundary);
    }

    /// Set-based claim of every due one-off job at the supplied clock — the
    /// deterministic drain seam (LLP 0115 CV-9): due-ness is a pure function
    /// of `now_ms`, sibling of cron's forced tick but over the job set, not
    /// nominal slots. Callers execute each claim off the lock and finish it
    /// through [`Self::finish_job_claim`].
    pub fn claim_due_jobs(
        &mut self,
        now_ms: u64,
        limit: usize,
        drive: &str,
        diagnostic_boundary: DiagnosticBoundary,
    ) -> SnapbackResult<Vec<AdmittedJobClaim>> {
        self.deny_derived_fork_egress(crate::instance_fork::EgressFamily::JobsDrain, now_ms)?;
        self.db.ensure_migration_lane_open()?;
        // Admission precedes the durable claim write, mirroring cron: if the
        // process is closing, no new claims are taken.
        let first_admission = self.admission.admit()?;
        let (claims, job_changes) = self.db.jobs().claim_due_jobs(now_ms, limit, drive)?;
        if !job_changes.is_empty() {
            self.notify_live_subscriptions(&job_changes);
        }
        let mut admitted = Vec::with_capacity(claims.len());
        let mut admissions = vec![first_admission];
        for _ in 1..claims.len() {
            #[cfg(test)]
            let next_admission =
                if FAIL_NEXT_ADDITIONAL_JOB_ADMISSION.with(|fail| fail.replace(false)) {
                    Err(SnapbackError::error(
                        "SNAPBACK_AUTH_MODE_PENDING",
                        "auth",
                        "closed partial-claim admission fixture",
                    ))
                } else {
                    self.admission.admit()
                };
            #[cfg(not(test))]
            let next_admission = self.admission.admit();
            match next_admission {
                Ok(admission) => admissions.push(admission),
                Err(error) => {
                    // Claims beyond the admitted prefix stay claimed; their
                    // leases expire and a successor drain re-claims them —
                    // the same recovery path as a crash after claim
                    // (LLP 0070 §Claims and fencing). Record and stop.
                    self.record_diagnostics_at_boundary(
                        vec![error.diagnostic],
                        diagnostic_boundary,
                    );
                    break;
                }
            }
        }
        for (claim, admission) in claims.into_iter().zip(admissions) {
            let observation = self.telemetry.start_classified_span(
                crate::telemetry_contract::OperationClassIdV1::JOB_SCHEDULER,
                &claim.action,
                Some(&claim.claim_id),
                Some(claim.telemetry_details()),
            );
            admitted.push(AdmittedJobClaim {
                claim,
                drain_now_ms: now_ms,
                admission,
                observation,
            });
        }
        Ok(admitted)
    }

    pub fn create_watch(
        &mut self,
        authority: &PreparedAuthority,
        request: crate::watches::CreateWatchSpec,
        now_ms: u64,
    ) -> SnapbackResult<crate::watches::CreatedWatch> {
        authority.validate_admission("watch creation")?;
        if authority.source() != InvocationSource::WatchManagement {
            return Err(SnapbackError::error(
                "SNAPBACK_INVOCATION_SOURCE_INVALID",
                "watches",
                "watch creation requires the registered management source",
            ));
        }
        let (
            owner_principal_id,
            owner_authority_instance_id,
            owner_kind,
            authority_mode,
            installation_grant_id,
            anchor_effective_user_id,
        ) = match authority.resolved() {
            ResolvedAppAuthority::Session {
                user_id,
                authority_instance_id,
                ..
            } => (
                user_id.clone(),
                authority_instance_id.clone(),
                crate::watches::WatchOwnerKind::User,
                crate::watches::WatchAuthorityMode::RevalidatePrincipal,
                None,
                None,
            ),
            ResolvedAppAuthority::ServicePrincipal {
                actor_user_id,
                grant_id,
                effective_user_id: Some(effective_user_id),
                integration_status:
                    Some(crate::storage::auth_integrations::IntegrationStatus::Active),
                ..
            } => {
                let integration = self.db.integration_record_if_present(actor_user_id)?
                    .filter(|record| record.status == crate::storage::auth_integrations::IntegrationStatus::Active)
                    .ok_or_else(|| SnapbackError::error(
                        "SNAPBACK_WATCH_OWNER_DENIED",
                        "watches",
                        "integration watch creation requires an active integration registration",
                    ))?;
                (
                    actor_user_id.clone(),
                    integration.integration_id,
                    crate::watches::WatchOwnerKind::Integration,
                    crate::watches::WatchAuthorityMode::CapturedGrant,
                    Some(grant_id.clone()),
                    Some(effective_user_id.clone()),
                )
            }
            _ => {
                return Err(SnapbackError::error(
                    "SNAPBACK_WATCH_OWNER_DENIED",
                    "watches",
                    "durable watch creation requires a human session or active delegated integration",
                ));
            }
        };
        if !(crate::watches::MIN_DEBOUNCE_MS..=crate::watches::MAX_DEBOUNCE_MS)
            .contains(&request.debounce_ms)
            || request.daily_firing_budget == 0
            || request.daily_firing_budget > crate::watches::MAX_DAILY_FIRING_BUDGET
        {
            return Err(crate::watches::input_invalid(
                "debounceMs must be between 5000 and 2592000000 and dailyFiringBudget must be between 1 and 1000",
            ));
        }
        self.validate_external_api_function(&request.query_function)?;
        let query = self.function(&request.query_function)?.clone();
        if query.kind != FunctionKind::LiveQuery {
            return Err(crate::watches::input_invalid(
                "watch query must be an exposed LiveQuery",
            ));
        }
        InvocationGate::prepare_function(
            authority.watch_function_authority(InvocationSource::WatchEvaluation)?,
            &query,
        )?;
        let query_basis = self
            .db
            .current_auth_scope_basis(&query.id, &query.kind, query.authority_creating)?
            .ok_or_else(|| watch_basis_missing("query"))?;
        let (predicate, predicate_json) = crate::watches::parse_predicate(&request.predicate)?;
        let (query_args_json, query_args_digest) =
            crate::watches::canonical_args(&request.query_args)?;
        let mut generated_webhook_secret = None;
        let (
            reaction_kind,
            reaction_function_id,
            reaction_function_name,
            reaction_function_kind,
            reaction_basis,
            reaction_args_json,
            reaction_args_digest,
            webhook_url,
            webhook_secret,
        ) = match request.reaction {
            crate::watches::WatchReactionSpec::Function { function, args } => {
                self.validate_external_api_function(&function)?;
                let reaction = self.function(&function)?.clone();
                if reaction.kind == FunctionKind::LiveQuery {
                    return Err(crate::watches::input_invalid(
                        "watch reaction must be a finite query, mutation, or action",
                    ));
                }
                InvocationGate::prepare_function(
                    authority.watch_function_authority(InvocationSource::WatchReaction)?,
                    &reaction,
                )?;
                crate::args_contract::validate_function_args(&reaction, &args)?;
                let basis = self
                    .db
                    .current_auth_scope_basis(
                        &reaction.id,
                        &reaction.kind,
                        reaction.authority_creating,
                    )?
                    .ok_or_else(|| watch_basis_missing("reaction"))?;
                let (args_json, args_digest) = crate::watches::canonical_args(&args)?;
                let kind = match reaction.kind {
                    FunctionKind::Query => crate::watches::WatchFunctionKind::Query,
                    FunctionKind::Mutation => crate::watches::WatchFunctionKind::Mutation,
                    FunctionKind::Action => crate::watches::WatchFunctionKind::Action,
                    FunctionKind::LiveQuery => unreachable!("rejected above"),
                };
                (
                    crate::watches::WatchReactionKind::Function,
                    reaction.id,
                    reaction.name,
                    kind,
                    basis,
                    args_json,
                    args_digest,
                    None,
                    None,
                )
            }
            crate::watches::WatchReactionSpec::Webhook { url, secret } => {
                crate::webhooks::prepare_target(&url)?;
                let secret = match secret {
                    Some(secret)
                        if (16..=4_096).contains(&secret.len())
                            && !secret.chars().any(char::is_control) =>
                    {
                        secret
                    }
                    Some(_) => {
                        return Err(crate::watches::input_invalid(
                            "webhook secret must be 16..4096 bytes without control characters",
                        ));
                    }
                    None => {
                        let mut bytes = [0_u8; 32];
                        getrandom::fill(&mut bytes).map_err(|_| {
                            SnapbackError::error(
                                "SNAPBACK_WEBHOOK_SECRET_UNAVAILABLE",
                                "webhooks",
                                "a webhook signing secret could not be generated",
                            )
                        })?;
                        let secret = base64::Engine::encode(
                            &base64::engine::general_purpose::URL_SAFE_NO_PAD,
                            bytes,
                        );
                        generated_webhook_secret = Some(secret.clone());
                        secret
                    }
                };
                let (binding_json, binding_digest) =
                    crate::watches::canonical_args(&json!({ "url": url }))?;
                (
                    crate::watches::WatchReactionKind::Webhook,
                    String::new(),
                    String::new(),
                    crate::watches::WatchFunctionKind::Action,
                    0,
                    binding_json,
                    binding_digest,
                    Some(url),
                    Some(secret),
                )
            }
        };
        let initial = self.invoke_query_with_dependencies_prepared(
            &query.name,
            HandlerInput {
                args: request.query_args,
                ..HandlerInput::default()
            },
            authority.watch_function_authority(InvocationSource::WatchEvaluation)?,
        )?;
        let initial_document =
            serde_json::to_value(&initial.output).map_err(|_| crate::watches::catalog_corrupt())?;
        let initial_predicate_state = crate::watches::evaluate(&predicate, &initial_document);
        let anchor_expires_at_ms = now_ms
            .checked_add(crate::watches::ANCHOR_LIFETIME_MS)
            .filter(|value| *value <= 9_007_199_254_740_991)
            .ok_or_else(|| {
                crate::watches::input_invalid("watch anchor lifetime overflows portable time")
            })?;
        // The initial query passes its own ordinary invocation/effect gate.
        // Acquire management's effect fence only for the durable catalog
        // commit; nesting it around the query would self-deadlock the same
        // admission lease and would not strengthen the serialized app cut.
        let _effect = authority.effect_guard("watch creation transaction")?;
        let watch_id = crate::ids::mint_time_ordered(crate::ids::Kind::Watch);
        let anchor_grant_id = (owner_kind == crate::watches::WatchOwnerKind::Integration)
            .then(|| crate::ids::mint_time_ordered(crate::ids::Kind::Grant));
        let webhook_secret_ref = webhook_secret
            .as_ref()
            .map(|_| format!("_snapback.webhook.{watch_id}"));
        if let (Some(secret_ref), Some(secret)) =
            (webhook_secret_ref.as_deref(), webhook_secret.as_ref())
        {
            self.config.set(
                secret_ref,
                vec![secret.clone()],
                false,
                "watchAnchor",
                now_ms,
            )?;
        }
        let mut anchor_scopes = vec![crate::storage::auth_grants::ExactGrantScope {
            function_id: query.id.clone(),
            kind: crate::storage::auth_grants::ScopedFunctionKind::LiveQuery,
            basis: query_basis,
            authority_creating: query.authority_creating,
        }];
        if reaction_kind == crate::watches::WatchReactionKind::Function {
            let reaction = self.function(&reaction_function_name)?.clone();
            anchor_scopes.push(crate::storage::auth_grants::ExactGrantScope {
                function_id: reaction.id,
                kind: crate::storage::auth_grants::ScopedFunctionKind::from_function_kind(
                    &reaction.kind,
                )
                .ok_or_else(crate::watches::catalog_corrupt)?,
                basis: reaction_basis,
                authority_creating: reaction.authority_creating,
            });
        }
        anchor_scopes.sort();
        if owner_kind == crate::watches::WatchOwnerKind::User {
            anchor_scopes.clear();
        }
        let create = self
            .db
            .create_watch(crate::storage::watches::CreateWatchRecord {
                id: watch_id.clone(),
                owner_kind,
                owner_principal_id,
                owner_authority_instance_id,
                authority_mode,
                anchor_grant_id,
                installation_grant_id,
                anchor_effective_user_id,
                anchor_scopes,
                anchor_expires_at_ms,
                query_function_id: query.id,
                query_function_name: query.name,
                query_basis,
                query_args_json,
                query_args_digest,
                read_dependencies: initial.read_dependencies,
                predicate_json,
                reaction_kind,
                reaction_function_id,
                reaction_function_name,
                reaction_function_kind,
                reaction_basis,
                reaction_args_json,
                reaction_args_digest,
                webhook_url,
                webhook_secret_ref: webhook_secret_ref.clone(),
                daily_firing_budget: request.daily_firing_budget,
                debounce_ms: request.debounce_ms,
                initial_predicate_state,
                now_ms,
            });
        let watch = match create {
            Ok(watch) => watch,
            Err(error) => {
                if let Some(secret_ref) = webhook_secret_ref.as_deref() {
                    let _ = self.config.unset(secret_ref);
                }
                return Err(error);
            }
        };
        Ok(crate::watches::CreatedWatch {
            watch,
            webhook_secret: generated_webhook_secret,
        })
    }

    pub fn list_watches(
        &self,
        authority: &PreparedAuthority,
    ) -> SnapbackResult<Vec<crate::storage::watches::WatchRecord>> {
        let (owner, _) = watch_management_owner(authority)?;
        self.db.list_watches_for_owner(&owner)
    }

    pub fn transition_watch(
        &mut self,
        authority: &PreparedAuthority,
        id: &str,
        target: crate::watches::WatchStatus,
        now_ms: u64,
    ) -> SnapbackResult<crate::storage::watches::WatchRecord> {
        let (owner, _) = watch_management_owner(authority)?;
        let _effect = authority.effect_guard("watch state transition")?;
        let record = self.db.transition_watch(id, &owner, target, now_ms)?;
        if target == crate::watches::WatchStatus::Active
            && self.db.schedule_watch_evaluation(id, now_ms)?
        {
            self.jobs_active.store(true, Ordering::Relaxed);
        }
        self.db
            .watch_for_owner(id, &owner)?
            .or(Some(record))
            .ok_or_else(crate::storage::watches::watch_not_found)
    }

    pub fn renew_watch(
        &mut self,
        authority: &PreparedAuthority,
        id: &str,
        ttl_ms: u64,
        now_ms: u64,
    ) -> SnapbackResult<crate::storage::watches::WatchRecord> {
        authority.validate_admission("watchAnchor renewal")?;
        if authority.source() != InvocationSource::WatchManagement {
            return Err(SnapbackError::error(
                "SNAPBACK_INVOCATION_SOURCE_INVALID",
                "watches",
                "watchAnchor renewal requires the registered management source",
            ));
        }
        let ResolvedAppAuthority::Session { user_id, .. } = authority.resolved() else {
            return Err(SnapbackError::error(
                "SNAPBACK_WATCH_RENEWAL_DENIED",
                "watches",
                "watchAnchor renewal requires fresh user session consent",
            ));
        };
        let _effect = authority.effect_guard("watchAnchor renewal transaction")?;
        self.db
            .renew_watch_anchor_for_user(id, user_id, ttl_ms, now_ms)
    }

    /// Evaluate one internal watch job under credential-free, freshly
    /// revalidated owner authority. Ordinary action jobs never enter here.
    ///
    /// @ref LLP 0204#d93--durable-watches-end-user-automations — every evaluation rechecks owner,
    /// query/reaction bases, status, and anchor before the query runs.
    /// @ref LLP 0055#dated-amendment-llp-0204-integration-registrations-and-watch-anchors-2026-08-08
    /// — retained watch authority is exact-function, finite, and revalidated.
    pub fn prepare_watch_job(
        &mut self,
        claim: WatchJobContext,
    ) -> SnapbackResult<WatchJobExecution> {
        let watch_id = claim
            .args
            .as_object()
            .filter(|object| object.len() == 1)
            .and_then(|object| object.get("watchId"))
            .and_then(Value::as_str)
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_WATCH_JOB_INVALID",
                    "watches",
                    "the internal watch job args are outside the closed {watchId} shape",
                )
            })?
            .to_owned();
        let now_ms = claim.drain_now_ms;
        let Some(record) = self
            .db
            .begin_watch_evaluation(&watch_id, &claim.job_id, now_ms)?
        else {
            return Ok(WatchJobExecution::Complete(json!({
                "watchId": watch_id,
                "outcome": "stale"
            })));
        };
        let owner_principal_id = record.owner_principal_id.clone();
        self.acquire_watch_evaluation(&record.owner_principal_id)?;
        let outcome = self.prepare_watch_job_inner(&claim, record, now_ms);
        if !matches!(
            outcome,
            Ok(WatchJobExecution::Action(_) | WatchJobExecution::Webhook(_))
        ) {
            self.release_watch_evaluation(&owner_principal_id);
        }
        outcome
    }

    fn prepare_watch_job_inner(
        &mut self,
        claim: &WatchJobContext,
        record: crate::storage::watches::WatchRecord,
        now_ms: u64,
    ) -> SnapbackResult<WatchJobExecution> {
        let Some(evaluation_authority) = self.watch_execution_authority(
            claim,
            &record,
            InvocationSource::WatchEvaluation,
            now_ms,
        )?
        else {
            self.db.mark_watch_dead(
                &record.id,
                "principal_or_captured_authority_dead",
                "SNAPBACK_WATCH_AUTHORITY_DEAD",
                now_ms,
            )?;
            return Ok(WatchJobExecution::Complete(watch_outcome(
                &record.id, "dead",
            )));
        };
        let (query, reaction) = match self.current_watch_functions(&record)? {
            Some(functions) => functions,
            None => {
                self.db.mark_watch_dead(
                    &record.id,
                    "function_basis_changed",
                    "SNAPBACK_WATCH_AUTHORITY_DEAD",
                    now_ms,
                )?;
                return Ok(WatchJobExecution::Complete(watch_outcome(
                    &record.id, "dead",
                )));
            }
        };
        if record.pending_firing_job_id.as_deref() == Some(&claim.job_id)
            && let Some(ordinal) = record.pending_firing_ordinal
        {
            return self.dispatch_watch_reaction(
                claim,
                &record,
                reaction.as_ref(),
                ordinal,
                now_ms,
            );
        }
        let invocation = match self.invoke_query_with_dependencies_prepared(
            &query.name,
            HandlerInput {
                args: record.query_args.clone(),
                ..HandlerInput::default()
            },
            evaluation_authority,
        ) {
            Ok(invocation) => invocation,
            Err(error) => {
                let code = error.diagnostic.code.clone();
                if claim.attempt < claim.max_attempts {
                    self.db.record_watch_evaluation_retry(
                        &record.id,
                        &claim.job_id,
                        &code,
                        now_ms,
                    )?;
                } else {
                    self.db.finish_watch_evaluation_failure(
                        &record.id,
                        &claim.job_id,
                        &code,
                        now_ms,
                    )?;
                }
                return Err(error);
            }
        };
        let predicate = crate::watches::parse_predicate(&record.predicate)?.0;
        let document = serde_json::to_value(&invocation.output)
            .map_err(|_| crate::watches::catalog_corrupt())?;
        let predicate_state = crate::watches::evaluate(&predicate, &document);
        match self.db.decide_watch_evaluation(
            &record.id,
            &claim.job_id,
            predicate_state,
            &invocation.read_dependencies,
            now_ms,
        )? {
            crate::storage::watches::EvaluationDecision::Fire { ordinal } => {
                self.dispatch_watch_reaction(claim, &record, reaction.as_ref(), ordinal, now_ms)
            }
            crate::storage::watches::EvaluationDecision::SuspendedBudget => Ok(
                WatchJobExecution::Complete(watch_outcome(&record.id, "budget_suspended")),
            ),
            crate::storage::watches::EvaluationDecision::NoFire => Ok(WatchJobExecution::Complete(
                watch_outcome(&record.id, "evaluated"),
            )),
            crate::storage::watches::EvaluationDecision::Stale => Ok(WatchJobExecution::Complete(
                watch_outcome(&record.id, "stale"),
            )),
        }
    }

    fn current_watch_functions(
        &self,
        record: &crate::storage::watches::WatchRecord,
    ) -> SnapbackResult<Option<(FunctionDefinition, Option<FunctionDefinition>)>> {
        let Some(query) = self
            .functions
            .function(&record.query_function_name)
            .cloned()
        else {
            return Ok(None);
        };
        let query_exposed = query
            .api_exposure
            .as_ref()
            .is_some_and(|exposure| exposure.expose);
        if query.id != record.query_function_id
            || query.kind != FunctionKind::LiveQuery
            || !query_exposed
        {
            return Ok(None);
        }
        let query_basis =
            self.db
                .current_auth_scope_basis(&query.id, &query.kind, query.authority_creating)?;
        if query_basis != Some(record.query_basis) {
            return Ok(None);
        }
        if record.reaction_kind == crate::watches::WatchReactionKind::Webhook {
            let Some(url) = record.webhook_url.as_deref() else {
                return Ok(None);
            };
            crate::webhooks::prepare_target(url)?;
            return Ok(Some((query, None)));
        }
        let Some(reaction) = self
            .functions
            .function(&record.reaction_function_name)
            .cloned()
        else {
            return Ok(None);
        };
        let reaction_exposed = reaction
            .api_exposure
            .as_ref()
            .is_some_and(|exposure| exposure.expose);
        let reaction_basis = self.db.current_auth_scope_basis(
            &reaction.id,
            &reaction.kind,
            reaction.authority_creating,
        )?;
        if reaction.id != record.reaction_function_id
            || reaction.kind == FunctionKind::LiveQuery
            || !reaction_exposed
            || reaction_basis != Some(record.reaction_basis)
        {
            return Ok(None);
        }
        Ok(Some((query, Some(reaction))))
    }

    fn watch_execution_authority(
        &mut self,
        claim: &WatchJobContext,
        record: &crate::storage::watches::WatchRecord,
        source: InvocationSource,
        now_ms: u64,
    ) -> SnapbackResult<Option<PreparedAuthority>> {
        let resolved = match record.owner_kind {
            crate::watches::WatchOwnerKind::User => {
                if !self.db.watch_owner_is_active(&record.owner_principal_id)? {
                    return Ok(None);
                }
                ResolvedAppAuthority::RevalidatedPrincipal {
                    user_id: record.owner_principal_id.clone(),
                    authority_instance_id: record.owner_authority_instance_id.clone(),
                }
            }
            crate::watches::WatchOwnerKind::Integration => {
                let Some(anchor) = self.db.revalidate_watch_anchor(record, now_ms)? else {
                    return Ok(None);
                };
                ResolvedAppAuthority::ServicePrincipal {
                    actor_user_id: anchor.actor_user_id,
                    credential_id: format!("watchAnchor:{}", record.id),
                    credential_generation: 0,
                    grant_id: anchor.grant_id,
                    token_id: format!("watch:{}", record.id),
                    effective_user_id: Some(anchor.effective_user_id),
                    scopes: anchor
                        .scopes
                        .into_iter()
                        .map(crate::auth::invocation::ResolvedGrantScope::from_exact)
                        .collect(),
                    token_expires_at_ms: anchor.expires_at_ms,
                    integration_status: Some(anchor.integration_status),
                }
            }
        };
        Ok(Some(
            InvocationGate::prepare_admitted_authority(
                source,
                AuthMode::Sessions,
                ServerProfile::Dev,
                claim.admission.clone(),
                &WireAuthorityFields::default(),
                resolved,
                None,
            )?
            .with_caller_attribution(crate::telemetry::CallerAttributionV1::owner(
                record.owner_principal_id.clone(),
            )),
        ))
    }

    fn dispatch_watch_reaction(
        &mut self,
        claim: &WatchJobContext,
        record: &crate::storage::watches::WatchRecord,
        reaction: Option<&FunctionDefinition>,
        ordinal: u64,
        now_ms: u64,
    ) -> SnapbackResult<WatchJobExecution> {
        let Some(authority) =
            self.watch_execution_authority(claim, record, InvocationSource::WatchReaction, now_ms)?
        else {
            self.db.mark_watch_dead(
                &record.id,
                "captured_authority_dead_before_reaction",
                "SNAPBACK_WATCH_AUTHORITY_DEAD",
                now_ms,
            )?;
            return Ok(WatchJobExecution::Complete(watch_outcome(
                &record.id, "dead",
            )));
        };
        if record.reaction_kind == crate::watches::WatchReactionKind::Webhook {
            let payload = crate::watches::canonical_json(&json!({
                "event": "watch.fired",
                "watchId": record.id,
                "firingOrdinal": ordinal,
                "firedAtMs": record.last_fired_at_ms.unwrap_or(now_ms),
            }))?;
            let delivery_id = format!("webhook:{}:{ordinal}", record.id);
            let idempotency_key = format!("watch:{}:{ordinal}", record.id);
            let delivery =
                self.db
                    .reserve_webhook_delivery(crate::storage::webhooks::ReserveDelivery {
                        id: delivery_id,
                        consumer_id: record.id.clone(),
                        event_ordinal: ordinal,
                        owner_principal_id: record.owner_principal_id.clone(),
                        target_url: record
                            .webhook_url
                            .clone()
                            .ok_or_else(crate::watches::catalog_corrupt)?,
                        payload_digest: crate::webhooks::payload_digest(&payload),
                        payload_json: payload,
                        secret_ref: record
                            .webhook_secret_ref
                            .clone()
                            .ok_or_else(crate::watches::catalog_corrupt)?,
                        idempotency_key,
                        max_attempts: claim.max_attempts,
                        now_ms,
                    })?;
            if delivery.state == "succeeded" {
                self.db.settle_watch_firing(
                    &record.id,
                    &claim.job_id,
                    ordinal,
                    "succeeded",
                    None,
                    now_ms,
                )?;
                return Ok(WatchJobExecution::Complete(watch_outcome(
                    &record.id,
                    "succeeded",
                )));
            }
            return Ok(WatchJobExecution::Webhook(PreparedWatchWebhook {
                watch_id: record.id.clone(),
                job_id: claim.job_id.clone(),
                ordinal,
                owner_principal_id: record.owner_principal_id.clone(),
                delivery,
            }));
        }
        let reaction = reaction.ok_or_else(crate::watches::catalog_corrupt)?;
        let input = HandlerInput {
            args: record.reaction_args.clone(),
            ..HandlerInput::default()
        };
        if reaction.kind == FunctionKind::Action {
            let prepared = match InvocationGate::prepare_function(authority, reaction) {
                Ok(prepared) => prepared,
                Err(error) => {
                    let code = error.diagnostic.code.clone();
                    self.db.settle_watch_firing(
                        &record.id,
                        &claim.job_id,
                        ordinal,
                        "refused",
                        Some(&code),
                        now_ms,
                    )?;
                    return Ok(WatchJobExecution::Complete(json!({
                        "watchId": record.id,
                        "outcome": "refused",
                        "diagnosticCode": code,
                    })));
                }
            };
            let metadata = CronRunMetadata {
                job_name: format!("watch:{}", record.id),
                run_id: format!("watch:{}:{ordinal}", record.id),
                scheduled_at_ms: None,
                due_at_ms: now_ms,
                idempotency_key: format!("watch:{}:{ordinal}", record.id),
                slot_key: format!("watch:{}", record.id),
                attempt: claim.attempt,
                trigger: CronRunTrigger::Manual,
            };
            return Ok(WatchJobExecution::Action(PreparedWatchAction {
                watch_id: record.id.clone(),
                job_id: claim.job_id.clone(),
                ordinal,
                owner_principal_id: record.owner_principal_id.clone(),
                action: reaction.name.clone(),
                input,
                metadata,
                staged: self.staged_mode(reaction, prepared, None),
            }));
        }
        let run = self.run_function_with_authority(&reaction.name, input, authority);
        if let Some(diagnostic) = run.diagnostic.as_ref() {
            if claim.attempt < claim.max_attempts {
                self.db.record_watch_firing_retry(
                    &record.id,
                    &claim.job_id,
                    ordinal,
                    &diagnostic.code,
                    now_ms,
                )?;
            } else {
                self.db.settle_watch_firing(
                    &record.id,
                    &claim.job_id,
                    ordinal,
                    "failed",
                    Some(&diagnostic.code),
                    now_ms,
                )?;
            }
            return Err(SnapbackError::new(diagnostic.clone()));
        }
        self.db.settle_watch_firing(
            &record.id,
            &claim.job_id,
            ordinal,
            "succeeded",
            None,
            now_ms,
        )?;
        Ok(WatchJobExecution::Complete(json!({
            "watchId": record.id,
            "outcome": "succeeded",
            "function": run,
        })))
    }

    #[allow(clippy::too_many_arguments)] // established internal signature; regrouping is out of scope for the lint sweep
    pub fn settle_watch_action(
        &mut self,
        watch_id: String,
        job_id: String,
        ordinal: u64,
        owner_principal_id: String,
        result: &Result<Value, SnapbackError>,
        attempt: u32,
        max_attempts: u32,
        now_ms: u64,
    ) -> SnapbackResult<Value> {
        let settled = match result {
            Ok(_) => {
                self.db
                    .settle_watch_firing(&watch_id, &job_id, ordinal, "succeeded", None, now_ms)
            }
            Err(error) if attempt < max_attempts => self.db.record_watch_firing_retry(
                &watch_id,
                &job_id,
                ordinal,
                &error.diagnostic.code,
                now_ms,
            ),
            Err(error) => self.db.settle_watch_firing(
                &watch_id,
                &job_id,
                ordinal,
                "failed",
                Some(&error.diagnostic.code),
                now_ms,
            ),
        };
        self.release_watch_evaluation(&owner_principal_id);
        settled?;
        if let Err(error) = result {
            return Err(error.clone());
        }
        Ok(json!({
            "watchId": watch_id,
            "outcome": "succeeded",
        }))
    }

    /// Final authority/target/secret recheck immediately before the detached
    /// transport begins. No bearer or plaintext secret is persisted in the
    /// watch or delivery ledger.
    ///
    /// @ref LLP 0036#runtime-exposure-d5-d8 — the signing secret exits the
    /// owner-only config store only into this bounded host operation.
    /// @ref LLP 0070#webhook-work — DNS is resolved and pinned at
    /// the final effect boundary; the delivery ledger supplies immutable
    /// payload and idempotency identity.
    pub fn revalidate_watch_webhook_delivery(
        &mut self,
        prepared: &PreparedWatchWebhook,
        now_ms: u64,
    ) -> SnapbackResult<crate::webhooks::DeliveryRequest> {
        let record = self
            .db
            .watch_for_execution(&prepared.watch_id)?
            .ok_or_else(crate::storage::watches::watch_not_found)?;
        if record.status != crate::watches::WatchStatus::Active
            || record.owner_principal_id != prepared.owner_principal_id
            || record.pending_firing_ordinal != Some(prepared.ordinal)
            || record.pending_firing_job_id.as_deref() != Some(&prepared.job_id)
            || record.reaction_kind != crate::watches::WatchReactionKind::Webhook
        {
            return Err(SnapbackError::error(
                "SNAPBACK_WATCH_AUTHORITY_DEAD",
                "watches",
                "watch authority ended before webhook initiation",
            ));
        }
        match record.owner_kind {
            crate::watches::WatchOwnerKind::User => {
                if !self.db.watch_owner_is_active(&record.owner_principal_id)? {
                    return Err(SnapbackError::error(
                        "SNAPBACK_WATCH_AUTHORITY_DEAD",
                        "watches",
                        "watch owner ended before webhook initiation",
                    ));
                }
            }
            crate::watches::WatchOwnerKind::Integration => {
                if self.db.revalidate_watch_anchor(&record, now_ms)?.is_none() {
                    return Err(SnapbackError::error(
                        "SNAPBACK_WATCH_AUTHORITY_DEAD",
                        "watches",
                        "watchAnchor ended before webhook initiation",
                    ));
                }
            }
        }
        if self.current_watch_functions(&record)?.is_none() {
            return Err(SnapbackError::error(
                "SNAPBACK_WATCH_AUTHORITY_DEAD",
                "watches",
                "watch query scope changed before webhook initiation",
            ));
        }
        if prepared.delivery.owner_principal_id != record.owner_principal_id
            || prepared.delivery.event_ordinal != prepared.ordinal
            || record.webhook_url.as_deref() != Some(&prepared.delivery.target_url)
            || record.webhook_secret_ref.as_deref() != Some(&prepared.delivery.secret_ref)
        {
            return Err(crate::webhooks::DeliveryOutcome::Permanent {
                code: "SNAPBACK_WEBHOOK_DELIVERY_INVALID",
                http_status: None,
            }
            .into_error());
        }
        let secret = self
            .config
            .values(&prepared.delivery.secret_ref)
            .filter(|values| values.len() == 1)
            .and_then(|values| values.first())
            .cloned()
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_WEBHOOK_SECRET_UNAVAILABLE",
                    "webhooks",
                    "webhook signing secret is unavailable",
                )
            })?;
        Ok(crate::webhooks::DeliveryRequest {
            delivery_id: prepared.delivery.id.clone(),
            idempotency_key: prepared.delivery.idempotency_key.clone(),
            target: crate::webhooks::prepare_target(&prepared.delivery.target_url)?,
            canonical_payload: prepared.delivery.payload_json.clone(),
            signing_secret: secret,
        })
    }

    pub fn settle_watch_webhook(
        &mut self,
        prepared: PreparedWatchWebhook,
        outcome: crate::webhooks::DeliveryOutcome,
        attempt: u32,
        max_attempts: u32,
        now_ms: u64,
    ) -> SnapbackResult<Value> {
        let result = match outcome {
            crate::webhooks::DeliveryOutcome::Succeeded { http_status } => {
                self.db.settle_webhook_attempt(
                    &prepared.delivery.id,
                    attempt,
                    "succeeded",
                    Some(http_status),
                    None,
                    now_ms,
                )?;
                self.db.settle_watch_firing(
                    &prepared.watch_id,
                    &prepared.job_id,
                    prepared.ordinal,
                    "succeeded",
                    None,
                    now_ms,
                )?;
                Ok(watch_outcome(&prepared.watch_id, "succeeded"))
            }
            crate::webhooks::DeliveryOutcome::Retryable { code, http_status }
                if attempt < max_attempts =>
            {
                self.db.settle_webhook_attempt(
                    &prepared.delivery.id,
                    attempt,
                    "retryable",
                    http_status,
                    Some(code),
                    now_ms,
                )?;
                self.db.record_watch_firing_retry(
                    &prepared.watch_id,
                    &prepared.job_id,
                    prepared.ordinal,
                    code,
                    now_ms,
                )?;
                Err(SnapbackError::error(
                    code,
                    "webhooks",
                    "webhook delivery will retry",
                ))
            }
            crate::webhooks::DeliveryOutcome::Retryable { http_status, .. } => {
                let code = "SNAPBACK_WEBHOOK_DEAD_LETTERED";
                self.db.settle_webhook_attempt(
                    &prepared.delivery.id,
                    attempt,
                    "dead",
                    http_status,
                    Some(code),
                    now_ms,
                )?;
                self.db.settle_watch_firing(
                    &prepared.watch_id,
                    &prepared.job_id,
                    prepared.ordinal,
                    "failed",
                    Some(code),
                    now_ms,
                )?;
                Err(SnapbackError::error(
                    code,
                    "webhooks",
                    "webhook exhausted its bounded attempts",
                ))
            }
            crate::webhooks::DeliveryOutcome::Permanent { code, http_status } => {
                self.db.settle_webhook_attempt(
                    &prepared.delivery.id,
                    attempt,
                    "dead",
                    http_status,
                    Some(code),
                    now_ms,
                )?;
                self.db.settle_watch_firing(
                    &prepared.watch_id,
                    &prepared.job_id,
                    prepared.ordinal,
                    "refused",
                    Some(code),
                    now_ms,
                )?;
                Ok(json!({
                    "watchId": prepared.watch_id,
                    "outcome": "refused",
                    "diagnosticCode": code,
                }))
            }
        };
        self.release_watch_evaluation(&prepared.owner_principal_id);
        result
    }

    fn acquire_watch_evaluation(&mut self, owner: &str) -> SnapbackResult<()> {
        let count = self.watch_evaluations.entry(owner.to_owned()).or_default();
        if *count >= crate::watches::OWNER_CONCURRENT_EVALUATIONS {
            return Err(SnapbackError::error(
                "SNAPBACK_WATCH_OWNER_EVALUATION_LIMIT",
                "watches",
                "the owner already has four watch evaluations in flight",
            ));
        }
        *count += 1;
        Ok(())
    }

    fn release_watch_evaluation(&mut self, owner: &str) {
        if let Some(count) = self.watch_evaluations.get_mut(owner) {
            *count = count.saturating_sub(1);
            if *count == 0 {
                self.watch_evaluations.remove(owner);
            }
        }
    }

    fn schedule_invalidated_watches(&mut self, changes: &[ChangedRow]) {
        // A watch evaluation is itself an LLP 0070 job. Do not feed that
        // internal job's lifecycle row back into watch matching: a watch over
        // the declared job-status surface may observe ordinary app jobs, but
        // the evaluator must not manufacture a self-sustaining wake-up storm.
        // Empty change sets are intentional auth refreshes and remain global.
        let relevant_changes = changes
            .iter()
            .filter(|change| {
                change.table != crate::jobs::JOBS_STATUS_TABLE
                    || change.row.as_ref().and_then(|row| row.get("action"))
                        != Some(&Value::String(
                            crate::watches::INTERNAL_EVALUATION_ACTION.to_owned(),
                        ))
            })
            .cloned()
            .collect::<Vec<_>>();
        let changes = if changes.is_empty() {
            changes
        } else if relevant_changes.is_empty() {
            return;
        } else {
            relevant_changes.as_slice()
        };
        let records = match self.db.active_watches() {
            Ok(records) => records,
            Err(error) => {
                self.record_attached_diagnostics(vec![error.diagnostic]);
                return;
            }
        };
        let now_ms = now_millis();
        for record in records {
            let Some(function) = self
                .functions
                .function(&record.query_function_name)
                .cloned()
            else {
                continue;
            };
            if function.id != record.query_function_id {
                continue;
            }
            let input = HandlerInput {
                args: record.query_args.clone(),
                auth: AuthInput {
                    user_id: Some(record.owner_principal_id.clone()),
                    ..AuthInput::default()
                },
                ..HandlerInput::default()
            };
            if !live_subscription_match_outcome(
                &function,
                &input,
                &record.read_dependencies,
                changes,
            )
            .may_be_affected()
            {
                continue;
            }
            match self.db.schedule_watch_evaluation(&record.id, now_ms) {
                Ok(enqueued) => {
                    if enqueued {
                        self.jobs_active.store(true, Ordering::Relaxed);
                    }
                }
                Err(error) => self.record_attached_diagnostics(vec![error.diagnostic]),
            }
        }
    }

    /// Atomic terminal publication for one executed job claim: the fenced CAS
    /// transition, the appended attempt outcome, live fan-out for the
    /// declared job-status query, and the synchronous drain receipt.
    pub fn finish_job_claim(
        &mut self,
        claim: AdmittedJobClaim,
        result: Result<Value, Diagnostic>,
    ) -> SnapbackResult<crate::jobs::JobDrainRecord> {
        let admission = claim.admission_lease().clone();
        let observation = claim.observation;
        let outcome = match result {
            Ok(_) => crate::jobs::JobAttemptOutcome::Succeeded,
            Err(diagnostic) => {
                crate::jobs::JobAttemptOutcome::Failed(self.config.redact_diagnostic(diagnostic))
            }
        };
        let now_ms = claim.drain_now_ms;
        // The effect guard linearizes only the SQLite terminal publication;
        // it owns the admission mutex, so it MUST drop before live fan-out
        // (which takes admission-controller entry points of its own).
        let terminal_publication = (|| {
            let _publication = admission.effect_guard("job result publication")?;
            self.db.jobs().finish_job(&claim.claim, &outcome, now_ms)
        })();
        let (disposition, changed_row) = match terminal_publication {
            Ok(terminal) => terminal,
            Err(error) => {
                observation.finish(Some(500), Some(&error.diagnostic.code), None);
                return Err(error);
            }
        };
        // `finish_job` is the job-state commit boundary. Admit immediately so
        // every completion frame below shares one deadline basis and jitter
        // sample even when fan-out serialization takes different amounts of
        // work per subscription.
        let committed_at = Instant::now();
        if let Some(changed_row) = changed_row
            && disposition != crate::jobs::JobFinishDisposition::StalePublication
        {
            // Mirror finish_mutation_commit: fan out under the existing
            // admission lease rather than minting a fresh root.
            match self.db.versions_read().current_version() {
                Ok(frame_version) => {
                    self.begin_live_commit_egress(committed_at);
                    self.begin_live_delivery_frame(self.subscriptions.len());
                    // @ref LLP 0200#6-open-questions — LLP 0200
                    // OQ-2 carve-out: drain receipts publish job-status
                    // fan-out synchronously.
                    let result = self.run_live_data_fanout_frame(
                        std::slice::from_ref(&changed_row),
                        &BTreeSet::new(),
                        frame_version,
                        &admission,
                    );
                    self.end_live_commit_egress();
                    if let Err(error) = result {
                        self.record_attached_diagnostics(vec![error.diagnostic]);
                    }
                }
                Err(error) => self.record_attached_diagnostics(vec![error.diagnostic]),
            }
        }
        let (disposition_name, next_available_at_ms) = match &disposition {
            crate::jobs::JobFinishDisposition::Succeeded => ("succeeded", None),
            crate::jobs::JobFinishDisposition::RetryPending { available_at_ms } => {
                ("retry_pending", Some(*available_at_ms))
            }
            crate::jobs::JobFinishDisposition::Dead => ("dead", None),
            crate::jobs::JobFinishDisposition::StalePublication => ("stale_publication", None),
        };
        let diagnostic_code = match &outcome {
            crate::jobs::JobAttemptOutcome::Succeeded => None,
            crate::jobs::JobAttemptOutcome::Failed(diagnostic) => Some(diagnostic.code.clone()),
        };
        if let crate::jobs::JobAttemptOutcome::Failed(diagnostic) = &outcome
            && disposition == crate::jobs::JobFinishDisposition::Dead
        {
            self.record_attached_diagnostics(vec![diagnostic.clone()]);
        }
        let record = crate::jobs::JobDrainRecord {
            job_id: claim.claim.job_id.clone(),
            queue: claim.claim.queue.clone(),
            action: claim.claim.action.clone(),
            attempt: claim.claim.attempt,
            claim_id: claim.claim.claim_id.clone(),
            fence: claim.claim.fence,
            disposition: disposition_name.to_owned(),
            diagnostic_code,
            next_available_at_ms,
        };
        let (status, code) = record.telemetry_terminal();
        observation.finish(Some(status), code, None);
        Ok(record)
    }

    /// The handler input a claimed job passes to its action: the immutable
    /// validated args, under system authority (LLP 0070 v1 executes the
    /// generated action with the enqueue-time-validated argument bytes).
    pub fn job_claim_input(claim: &AdmittedJobClaim) -> HandlerInput {
        HandlerInput {
            args: claim.claim.args.clone(),
            auth: Default::default(),
            read_set: Vec::new(),
            correlation: None,
            ctx_ledger: None,
        }
    }

    /// The run metadata a claimed job hands the action runtime — the jobs
    /// sibling of a cron run's metadata, carried in the same shape so both
    /// action tiers work unchanged. `due_at_ms` is the drain clock, which the
    /// action observes as `ctx.runtime.now()` — deterministic under forced
    /// drains.
    pub fn job_claim_metadata(claim: &AdmittedJobClaim) -> CronRunMetadata {
        CronRunMetadata {
            job_name: format!("jobs:{}", claim.claim.action),
            run_id: format!("job:{}:{}", claim.claim.job_id, claim.claim.attempt),
            scheduled_at_ms: None,
            due_at_ms: claim.drain_now_ms,
            idempotency_key: claim
                .claim
                .idempotency_key
                .clone()
                .unwrap_or_else(|| format!("job:{}", claim.claim.job_id)),
            slot_key: format!("job:{}", claim.claim.job_id),
            attempt: claim.claim.attempt,
            trigger: CronRunTrigger::Manual,
        }
    }

    pub fn jobs_inspect(&self, limit: usize) -> SnapbackResult<Value> {
        let jobs = self.db.jobs_read().list_job_status_rows(limit)?;
        let pending = self.db.jobs_read().pending_job_count()?;
        Ok(json!({
            "artifactKind": "snapback.jobs-inspect/v0",
            // Honest capability posture (LLP 0070 §Non-goals): the RFC is
            // Draft, so no durable-background-work capability class or target
            // tuple is claimed here — these are lifecycle facts only.
            "claimBoundary": "LLP 0070 Draft — no durable-background-work capability claimed",
            "pendingCount": pending,
            "jobs": jobs,
        }))
    }

    pub fn job_show(&self, job_id: &str) -> SnapbackResult<Option<Value>> {
        let Some(job) = self.db.jobs_read().job_status(job_id)? else {
            return Ok(None);
        };
        let attempts = self.db.jobs_read().job_attempt_records(job_id)?;
        Ok(Some(json!({
            "artifactKind": "snapback.job-show/v0",
            "job": job,
            "attempts": attempts,
        })))
    }

    /// Whether any job could need the autonomous worker: pending or claimed
    /// rows exist. The worker polls this only when its activity hint is set.
    pub(crate) fn jobs_pending_count(&self) -> SnapbackResult<u64> {
        self.db.jobs_read().pending_job_count()
    }

    /// A lock-free hint allowing the autonomous worker to skip SQLite while
    /// the durable queue is empty. The worker refreshes it under the Local
    /// lock, and every committed enqueue arms it before releasing that lock.
    pub fn jobs_activity_flag(&self) -> Arc<AtomicBool> {
        self.jobs_active.clone()
    }

    pub fn refresh_jobs_activity(&self) -> SnapbackResult<u64> {
        let pending = self.jobs_pending_count()?;
        self.jobs_active.store(pending != 0, Ordering::Relaxed);
        Ok(pending)
    }

    /// Asset-runner loop errors land in the same bounded diagnostics ring as
    /// cron tick errors; the ledger rows themselves carry per-item failure
    /// state, so this records only scheduler-machinery faults.
    pub fn record_asset_runner_error(&mut self, error: SnapbackError) {
        self.asset_runner_errors += 1;
        self.record_standalone_diagnostics(vec![error.diagnostic]);
    }

    /// Swallowed asset-runner scheduler errors, surfaced for tests/inspection.
    #[allow(dead_code)]
    pub fn asset_runner_errors(&self) -> u64 {
        self.asset_runner_errors
    }

    /// Record a retryable maintenance failure without retaining the underlying
    /// error message (which may contain room identity or application text).
    /// Counters advance for every failure; the bounded diagnostic ring receives
    /// at most one classification per operation per minute.
    pub fn record_maintenance_error(
        &mut self,
        operation: MaintenanceOperation,
        error: &SnapbackError,
        now_ms: u64,
    ) {
        let (count, last_failure, last_reported, code, message) = match operation {
            MaintenanceOperation::PermissionResolution => (
                &mut self.maintenance.permission_resolution_failures,
                &mut self.maintenance.last_permission_resolution_failure_ms,
                &mut self.maintenance_permission_reported_at_ms,
                "SNAPBACK_MAINTENANCE_PERMISSION_RESOLUTION_FAILED",
                "maintenance permission resolution failed; retry remains pending",
            ),
            MaintenanceOperation::JournalPrune => (
                &mut self.maintenance.journal_prune_failures,
                &mut self.maintenance.last_journal_prune_failure_ms,
                &mut self.maintenance_prune_reported_at_ms,
                "SNAPBACK_MAINTENANCE_JOURNAL_PRUNE_FAILED",
                "change-journal pruning failed; retry remains scheduled",
            ),
        };
        *count = count.saturating_add(1);
        *last_failure = Some(now_ms);
        let should_report = last_reported.is_none_or(|reported| {
            now_ms.saturating_sub(reported) >= MAINTENANCE_DIAGNOSTIC_MIN_INTERVAL_MS
        });
        if should_report {
            *last_reported = Some(now_ms);
            let diagnostic =
                Diagnostic::warning(code, "maintenance", message).with_details(json!({
                    "causeCode": error.diagnostic.code.clone(),
                    "failureCount": *count,
                }));
            self.record_standalone_diagnostics(vec![diagnostic]);
        }
    }

    pub fn run_cron_job_now(&mut self, name: &str, now_ms: u64) -> SnapbackResult<CronRunRecord> {
        let claim = self.claim_manual_cron_run(name, now_ms)?;
        let mut records = self.execute_cron_claims(vec![claim])?;
        records.pop().ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_CRON_RUN_RECORD_MISSING",
                "cron",
                format!("cron job {name} did not produce a run record"),
            )
        })
    }

    pub fn drain_outbox(&mut self, connection_id: &str) -> Vec<RealtimeEnvelope> {
        // An unfenced poll remains a liveness signal but cannot extract app
        // data whose final publication must cross an authorization fence.
        self.touch_connection(connection_id, now_millis());
        self.ephemeral.drain_outbox(connection_id)
    }

    /// Guarded destructive drain for an embedding-owned transport. Retain
    /// each returned wrapper through the final transport sink.
    pub fn drain_outbox_for_send(
        &mut self,
        connection_id: &str,
    ) -> Vec<crate::ephemeral::AdmittedRealtimeEnvelope> {
        self.touch_connection(connection_id, now_millis());
        self.ephemeral.drain_outbox_for_send(connection_id)
    }

    fn prepare_scheduler_live_delivery_enqueue(
        &mut self,
        subscription: &LiveSubscription,
        payload: &[u8],
    ) {
        let Ok(envelope) = serde_json::from_slice::<LiveEnvelope>(payload) else {
            return;
        };
        let (wire_kind, position) = match &envelope {
            LiveEnvelope::LiveReplace {
                subscription_id,
                version,
                ..
            } => ("live_replace", Some((subscription_id.as_str(), *version))),
            LiveEnvelope::LiveDelta {
                subscription_id,
                version,
                ..
            } => ("live_delta", Some((subscription_id.as_str(), *version))),
            LiveEnvelope::CurrentAsOf {
                subscription_id,
                version,
                ..
            } => ("current_as_of", Some((subscription_id.as_str(), *version))),
            LiveEnvelope::AuthorizationInvalidation {
                snapshot: Some(snapshot),
                ..
            } => (
                "authorization_invalidation",
                Some((snapshot.subscription_id.as_str(), snapshot.version)),
            ),
            LiveEnvelope::AuthorizationInvalidation { snapshot: None, .. } => {
                ("authorization_invalidation", None)
            }
            LiveEnvelope::ResyncRequired { .. } => ("resync_required", None),
        };
        *self
            .live_evaluation_stats
            .delivered_frames_by_wire_kind
            .entry(wire_kind.to_owned())
            .or_default() += 1;
        self.live_evaluation_stats.delivered_bytes = self
            .live_evaluation_stats
            .delivered_bytes
            .saturating_add(payload.len() as u64);
        if let Some(evaluation) = self.current_live_evaluation.as_mut() {
            evaluation.delivered_frames = evaluation.delivered_frames.saturating_add(1);
            evaluation.delivered_bytes = evaluation
                .delivered_bytes
                .saturating_add(payload.len() as u64);
            evaluation.wire_kind = Some(wire_kind);
        }
        if wire_kind == "current_as_of" {
            self.live_watermark_stats.envelopes_emitted = self
                .live_watermark_stats
                .envelopes_emitted
                .saturating_add(1);
            if let Some((subscription_id, version)) = position {
                crate::spike_trace::watermark(
                    subscription_id,
                    &subscription.connection_id,
                    version,
                    "emitted",
                    0,
                );
            }
        }
        if self.live_coalescer.is_none() {
            return;
        }
        let Some((subscription_id, version)) = position else {
            return;
        };
        debug_assert_eq!(subscription_id, subscription.id);
        let coalesced = self.ephemeral.supersede_pending_live_watermarks(
            &subscription.connection_id,
            subscription_id,
            version,
        );
        if coalesced > 0 {
            self.live_watermark_stats.envelopes_coalesced = self
                .live_watermark_stats
                .envelopes_coalesced
                .saturating_add(coalesced);
            crate::spike_trace::watermark(
                subscription_id,
                &subscription.connection_id,
                version,
                "coalesced",
                coalesced,
            );
        }
    }

    fn enqueue_subscription_durable(
        &mut self,
        subscription: &LiveSubscription,
        payload: Vec<u8>,
    ) -> crate::ephemeral::DurableEnqueueOutcome {
        self.prepare_scheduler_live_delivery_enqueue(subscription, &payload);
        let network_egress = self.current_live_network_egress.clone().unwrap_or_else(|| {
            self.network_profiles.admit_result(
                crate::network_profile::NetworkEgressLane::LiveDelta,
                Instant::now(),
            )
        });
        match subscription.effect_fence.clone() {
            Some(effect_fence) => self.ephemeral.enqueue_durable_bound_with_network_egress(
                subscription.connection_id.clone(),
                payload,
                effect_fence,
                network_egress,
            ),
            None => self.ephemeral.enqueue_durable_with_network_egress(
                subscription.connection_id.clone(),
                payload,
                network_egress,
            ),
        }
    }

    fn enqueue_subscription_authorized_durable(
        &mut self,
        subscription: &LiveSubscription,
        payload: Vec<u8>,
        authorization: crate::storage::AuthorizationVersion,
    ) -> crate::ephemeral::DurableEnqueueOutcome {
        self.prepare_scheduler_live_delivery_enqueue(subscription, &payload);
        let network_egress = self.current_live_network_egress.clone().unwrap_or_else(|| {
            self.network_profiles.admit_result(
                crate::network_profile::NetworkEgressLane::LiveDelta,
                Instant::now(),
            )
        });
        match subscription.effect_fence.clone() {
            Some(effect_fence) => self
                .ephemeral
                .enqueue_authorized_durable_bound_with_network_egress(
                    subscription.connection_id.clone(),
                    payload,
                    authorization,
                    effect_fence,
                    network_egress,
                ),
            None => self
                .ephemeral
                .enqueue_authorized_durable_with_network_egress(
                    subscription.connection_id.clone(),
                    payload,
                    authorization,
                    network_egress,
                ),
        }
    }

    fn authorize_live_delivery(
        &mut self,
        subscription: &LiveSubscription,
        resolved: &crate::storage::AuthorizationVersion,
    ) -> bool {
        let authorized = self
            .live_coalescer
            .as_ref()
            .is_none_or(|coalescer| coalescer.authorize_delivery(&subscription.id, resolved));
        if !authorized {
            self.live_authority_stats.stale_authority_frames_discarded = self
                .live_authority_stats
                .stale_authority_frames_discarded
                .saturating_add(1);
            crate::spike_trace::fence(&subscription.id, "stale_discard", resolved, None);
        }
        authorized
    }

    /// Admit one real commit once, then let every frame it produces clone the
    /// same live-lane carrier. `Some(None)` is intentional: it suppresses the
    /// result-readiness fallback for a commit observed under `normal`.
    fn begin_live_commit_egress(&mut self, committed_at: Instant) {
        debug_assert!(self.current_live_network_egress.is_none());
        self.current_live_network_egress = Some(
            self.network_profiles
                .admit_commit(committed_at)
                .map(|commit| {
                    commit.for_lane(crate::network_profile::NetworkEgressLane::LiveDelta)
                }),
        );
    }

    fn end_live_commit_egress(&mut self) {
        self.current_live_network_egress = None;
    }

    #[cfg(test)]
    pub fn purge_connection_effects(
        &mut self,
        connection_id: &str,
        effect_fence: &crate::ephemeral::ConnectionEffectFence,
    ) {
        self.purge_connection_topology(connection_id, effect_fence);
        self.ephemeral
            .purge_connection_effects(connection_id, effect_fence);
    }

    /// Retire only global-mutex-owned subscription and invalidation topology.
    /// Terminal lifecycle code performs the room/outbox purge separately
    /// before acquiring `SharedSnapback`, preserving the no-overlap lock rule.
    ///
    /// @ref LLP 0059#prohibited-overlap — terminal topology cleanup never
    /// reacquires room/outbox authority beneath the global writer mutex.
    pub fn purge_connection_topology(
        &mut self,
        connection_id: &str,
        effect_fence: &crate::ephemeral::ConnectionEffectFence,
    ) {
        self.terminalize_local_live_effects(connection_id, Some(effect_fence));
        let retired_scopes = self
            .subscriptions
            .values()
            .filter(|subscription| {
                subscription.connection_id == connection_id
                    && subscription.effect_fence.as_ref() == Some(effect_fence)
            })
            .filter_map(|subscription| {
                subscription
                    .authorization
                    .as_ref()
                    .map(|authorization| authorization.scope_id.clone())
            })
            .collect::<Vec<_>>();
        let retired_subscription_ids = self
            .subscriptions
            .values()
            .filter(|subscription| {
                subscription.connection_id == connection_id
                    && subscription.effect_fence.as_ref() == Some(effect_fence)
            })
            .map(|subscription| subscription.id.clone())
            .collect::<Vec<_>>();
        for subscription in self.subscriptions.values().filter(|subscription| {
            subscription.connection_id == connection_id
                && subscription.effect_fence.as_ref() == Some(effect_fence)
        }) {
            subscription.observation.finish(200, None, "disconnected");
        }
        self.subscriptions.retain(|_, subscription| {
            subscription.connection_id != connection_id
                || subscription.effect_fence.as_ref() != Some(effect_fence)
        });
        for subscription_id in retired_subscription_ids {
            self.pending_live_fanout
                .evaluation_memo
                .retire_subscription(&subscription_id);
        }
        if let Some(state) = self.auth_invalidation.as_mut() {
            for scope in retired_scopes {
                let _ = state.obligations.retire_scope(&scope);
            }
        }
        self.refresh_auth_scoped_live_connections();
        self.refresh_cron_active();
    }

    /// Record connection activity for the L2 reaper.
    /// @ref LLP 0032#phase-3--lifecycle-and-resource-hardening — L2 liveness.
    fn touch_connection(&mut self, connection_id: &str, now_ms: u64) {
        self.connections_last_seen.touch(connection_id, now_ms);
    }

    /// The lock-free ephemeral lane handle for the server: room authority plus
    /// liveness map, cloneable and usable from any thread without the global
    /// mutex (LLP 0026 Phase 2 / LLP 0032 L9).
    pub fn ephemeral_api(&self) -> EphemeralApi {
        EphemeralApi {
            store: self.ephemeral.clone(),
            activity: self.connections_last_seen.clone(),
        }
    }

    pub fn managed_local_handoff(&self) -> Arc<crate::exec_guard::ManagedLocalHandoff> {
        self.managed_local_handoff.clone()
    }

    #[cfg(any(test, feature = "test-support"))]
    pub fn auth_invalidation_expectation_for_test(
        &self,
    ) -> Option<crate::storage::AuthorizationVersion> {
        self.auth_invalidation
            .as_ref()
            .map(|state| state.obligations.expectation().authorization.clone())
    }

    // Compatibility projection for callers that do not consume the observed
    // authorization version returned by authorize_ephemeral_room_observed.
    #[allow(dead_code)]
    pub(crate) fn authorize_ephemeral_room(
        &self,
        collection_name: &str,
        scope: &crate::ephemeral::Scope,
        base_auth: AuthContext,
    ) -> SnapbackResult<AuthContext> {
        self.authorize_ephemeral_room_observed(collection_name, scope, base_auth)
            .map(|(auth, _)| auth)
    }

    /// Resolve one protected room permission together with the exact
    /// authorization epoch observed by the durable read. The transport uses
    /// that witness after acquiring its room permit: equality linearizes the
    /// read before a later commit, while drift forces a fresh read.
    pub fn authorize_ephemeral_room_observed(
        &self,
        collection_name: &str,
        scope: &crate::ephemeral::Scope,
        base_auth: AuthContext,
    ) -> SnapbackResult<(AuthContext, crate::storage::AuthorizationVersion)> {
        let collection = self
            .ephemeral
            .collection_definition(collection_name)
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_EPHEMERAL_UNKNOWN_COLLECTION",
                    "ephemeral",
                    "ephemeral collection is not loaded",
                )
            })?;
        if !self
            .ephemeral
            .collection_requires_room_permission(collection_name)
        {
            let authorization = self
                .auth_invalidation
                .as_ref()
                .ok_or_else(|| {
                    SnapbackError::error(
                        "SNAPBACK_AUTH_INVALIDATION_UNAVAILABLE",
                        "auth",
                        "room authorization requires installed invalidation state",
                    )
                })?
                .issuer
                .authorization_expectation()?;
            return Ok((base_auth, authorization));
        }
        let projection = collection.permission_backing.as_ref().ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_AUTH_INVALIDATION_UNAVAILABLE",
                "auth",
                "protected room lacks its durable permissionBacking projection",
            )
        })?;
        if !self.room_permission_projection_granted(
            projection,
            scope,
            &base_auth,
            self.db.versions_read().current_version()?,
        )? {
            return Err(SnapbackError::error(
                "SNAPBACK_AUTH_PERMISSION_DENIED",
                "auth",
                "durable room permission was denied",
            ));
        }
        let authorization = self
            .auth_invalidation
            .as_ref()
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_AUTH_INVALIDATION_UNAVAILABLE",
                    "auth",
                    "protected room authorization requires installed invalidation state",
                )
            })?
            .issuer
            .authorization_expectation()?;
        Ok((
            collection.grant_projected_room_permission(base_auth, scope),
            authorization,
        ))
    }

    #[cfg(test)]
    pub(crate) fn reauthorize_pending_ephemeral_rooms<Resolve>(
        &mut self,
        mut resolve_connection: Resolve,
    ) -> SnapbackResult<usize>
    where
        Resolve: FnMut(&str, &AuthContext) -> SnapbackResult<Option<AuthContext>>,
    {
        let pending = self.ephemeral.pending_room_reauthorizations();
        let mut completed = 0_usize;
        for room in pending {
            let fresh = room
                .subscribers
                .iter()
                .map(|subscriber| {
                    resolve_connection(&subscriber.connection_id, &subscriber.previous_auth)
                })
                .collect::<SnapbackResult<Vec<_>>>()?;
            let room_id = room.room.clone();
            let generation = room.obligation.room_authority_generation;
            let resolutions = self.resolve_pending_ephemeral_room_permissions(room, fresh)?;
            if self
                .ephemeral
                .complete_room_reauthorization(&room_id, generation, resolutions)?
            {
                completed = completed.saturating_add(1);
            }
        }
        Ok(completed)
    }

    pub fn resolve_pending_ephemeral_room_permissions(
        &self,
        room: crate::ephemeral::PendingRoomReauthorization,
        fresh_authorities: Vec<Option<AuthContext>>,
    ) -> SnapbackResult<Vec<RoomSubscriberResolution>> {
        if room.subscribers.len() != fresh_authorities.len() {
            return Err(SnapbackError::error(
                "SNAPBACK_EPHEMERAL_REAUTHORIZATION_INCOMPLETE",
                "ephemeral",
                "room permission phase requires one authority result per snapshotted subscriber",
            ));
        }
        let collection = self
            .ephemeral
            .collection_definition(&room.room.collection)
            .ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_EPHEMERAL_UNKNOWN_COLLECTION",
                    "ephemeral",
                    "pending room collection is no longer loaded",
                )
            })?;
        let projection = collection.permission_backing.as_ref().ok_or_else(|| {
            SnapbackError::error(
                "SNAPBACK_AUTH_INVALIDATION_UNAVAILABLE",
                "auth",
                "pending protected room lacks its durable permissionBacking projection",
            )
        })?;
        let mut resolutions = Vec::with_capacity(room.subscribers.len());
        for (subscriber, fresh) in room.subscribers.into_iter().zip(fresh_authorities) {
            let Some(fresh) = fresh else {
                resolutions.push(RoomSubscriberResolution::Denied {
                    connection_id: subscriber.connection_id,
                    expected_effect_fence: subscriber.effect_fence,
                });
                continue;
            };
            let granted = self.room_permission_projection_granted(
                projection,
                &room.room.scope,
                &fresh,
                room.obligation.min_commit_version,
            )?;
            if granted {
                resolutions.push(RoomSubscriberResolution::Authorized {
                    connection_id: subscriber.connection_id,
                    expected_effect_fence: subscriber.effect_fence,
                    auth: collection.grant_projected_room_permission(fresh, &room.room.scope),
                });
            } else {
                resolutions.push(RoomSubscriberResolution::Denied {
                    connection_id: subscriber.connection_id,
                    expected_effect_fence: subscriber.effect_fence,
                });
            }
        }
        Ok(resolutions)
    }

    fn room_permission_projection_granted(
        &self,
        projection: &RoomPermissionProjection,
        scope: &crate::ephemeral::Scope,
        auth: &AuthContext,
        min_commit_version: u64,
    ) -> SnapbackResult<bool> {
        let Some(user_id) = auth.user_id.as_deref() else {
            return Ok(false);
        };
        let scope_fields = projection
            .scope_fields
            .iter()
            .map(|(scope_field, table_field)| {
                scope
                    .get(scope_field)
                    .map(|value| (table_field.clone(), value.to_owned()))
                    .ok_or_else(|| {
                        SnapbackError::error(
                            "SNAPBACK_EPHEMERAL_INVALID_SCOPE",
                            "ephemeral",
                            "room scope does not satisfy its permissionBacking projection",
                        )
                    })
            })
            .collect::<SnapbackResult<Vec<_>>>()?;
        self.db.room_permission_projection_granted(
            &projection.table,
            &projection.subject_field,
            user_id,
            &scope_fields,
            min_commit_version,
        )
    }

    /// Direct-library compatibility reaper. Server maintenance discovers and
    /// disconnects stale ids through [`EphemeralApi`] before entering Local;
    /// this combined form is forbidden from a managed Local writer scope.
    pub fn reap_stale_connections(&mut self, now_ms: u64, ttl_ms: u64) -> usize {
        crate::exec_guard::debug_assert_local_snapback_write_scope_inactive(
            "LocalSnapback::reap_stale_connections compatibility orchestration",
        );
        let ephemeral = self.ephemeral_api();
        let stale = ephemeral.stale_connection_ids(now_ms, ttl_ms);
        for connection_id in &stale {
            ephemeral.disconnect(connection_id, now_ms);
        }
        for connection_id in &stale {
            let topology = self.disconnect_topology_for_transport(connection_id, now_ms);
            ephemeral.enqueue_disconnected_subscription_resync(connection_id, &topology);
        }
        self.record_reaped_connections(stale.len());
        stale.len()
    }

    /// Record topology retirements selected by the off-Local activity reaper.
    /// Stale-id discovery and [`EphemeralApi::disconnect`] happen before the
    /// server enters LocalSnapback; this method preserves `/inspect` counters
    /// without reacquiring any activity or ephemeral shard lock.
    pub fn record_reaped_connections(&mut self, count: usize) {
        self.reaped_connections = self.reaped_connections.saturating_add(count as u64);
    }

    pub fn active_connection_count(&self) -> usize {
        self.connections_last_seen.len()
    }

    pub fn reaped_connection_count(&self) -> u64 {
        self.reaped_connections
    }

