#[allow(clippy::too_many_arguments)]
fn execute_snapshot_batch_v2(
    function: &FunctionDefinition,
    plan: &crate::manifest::SnapshotBatchPlanV2,
    db: &DbRead<'_>,
    input: &HandlerInput,
    prepared: &PreparedInvocation,
    cursor_authority: Option<RelationalCursorAuthority<'_>>,
) -> SnapbackResult<QueryInvocation> {
    // @ref LLP 0135#22-one-snapshot-execution-and-parent-authorization-dedup —
    // all node work shares this pinned DbRead; relational nodes add no
    // structural parent and bounded nodes share declaration-equal checks.
    let authority = cursor_authority.ok_or_else(snapshot_batch_cursor_mint_unavailable)?;
    let now_ms = now_millis();
    let database_id = db.search_database_identity()?;
    let stream_epoch = prepared
        .authority()
        .authorization_stream_incarnation()
        .unwrap_or(database_id.as_str())
        .to_owned();
    let canonical_args = snapshot_batch_non_cursor_args(input)?;
    let identity = crate::manifest::snapshot_batch_identity_v2(function, plan)?;
    let authority_partition =
        snapshot_batch_authority_partition_digest(prepared, input, &stream_epoch)?;
    let groups = crate::manifest::snapshot_batch_v2_parent_authorization_groups(function, plan)?;
    let parent_ids = groups
        .iter()
        .map(|group| {
            input
                .args
                .get(&group.identity.parent_id_argument)
                .and_then(Value::as_str)
                .filter(|id| !id.is_empty())
                .map(ToOwned::to_owned)
                .ok_or_else(|| {
                    SnapbackError::error(
                        "SNAPBACK_SNAPSHOT_BATCH_PLAN_INVALID",
                        "query",
                        "snapshot batch v2 parent argument is missing or invalid",
                    )
                })
        })
        .collect::<SnapbackResult<Vec<_>>>()?;
    let (roots, key_generation, root) = {
        let keyring = authority
            .keyring
            .read()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        let roots = keyring.snapshot_batch_cursor_v2_materials(now_ms);
        let (generation, root) = keyring
            .active_current()
            .ok_or_else(snapshot_batch_cursor_mint_unavailable)?;
        let longest_generation = roots
            .iter()
            .map(|(generation, _)| generation.as_str())
            .max_by_key(|generation| generation.len())
            .unwrap_or(generation.as_str())
            .to_owned();
        (roots, (generation, longest_generation), root)
    };

    // @ref LLP 0157#sbsb2-plaintext-and-budget — establishment compares the
    // exact class-specific maximum body against 6,099 bytes before the first
    // application row read. Relational root order fields use the same pinned
    // closed scalar templates as bounded-child order fields.
    enforce_snapshot_batch_v2_cursor_budget(
        db,
        plan,
        &identity,
        &key_generation.1,
        authority.app_id,
        &database_id,
        &stream_epoch,
        &function.id,
        &canonical_args,
        &authority_partition,
        &parent_ids,
    )?;

    let mut group_rows = Vec::with_capacity(groups.len());
    for (group_index, group) in groups.iter().enumerate() {
        let parent_id = &parent_ids[group_index];
        let node_index = *group
            .node_indices
            .first()
            .expect("snapshot-batch v2 parent group has a bounded node");
        let crate::manifest::SnapshotBatchNodeV2::BoundedChildren(node) = &plan.nodes[node_index]
        else {
            unreachable!("only bounded nodes participate in parent groups")
        };
        let parent = read_composed_bounded_parent(
            db,
            input,
            &group.identity.parent_table,
            parent_id,
            &group.identity.visibility,
            &node.parent_table_visibility,
            "snapshot-batch v2 bounded-children parent",
        )?;
        let state = if let Some(parent) = parent {
            let incarnation = db
                .active_relation_incarnation(&group.identity.parent_table, parent_id)?
                .ok_or_else(snapshot_batch_restart_required)?;
            let version = parent
                .get("_version")
                .and_then(Value::as_u64)
                .ok_or_else(snapshot_batch_restart_required)?;
            Some((parent, incarnation, version))
        } else {
            None
        };
        group_rows.push(state);
    }

    // @ref LLP 0157#sbsb2-plaintext-and-budget — bounded-parent absence or
    // invisibility seals the whole mixed tuple before any cursor validation;
    // all-relational tuples have no groups and cannot enter this arm.
    if group_rows.iter().any(Option::is_none) {
        return Ok(QueryInvocation {
            output: QueryOutput {
                version: db.current_version()?,
                rows: vec![json!({
                    "kind": "absent",
                    "nodes": null,
                    "continuation": null,
                })],
                cursor: None,
            },
            read_dependencies: Vec::new(),
        });
    }

    let mut group_for_node = vec![None; plan.nodes.len()];
    for (group_index, group) in groups.iter().enumerate() {
        for &node_index in &group.node_indices {
            group_for_node[node_index] = Some(group_index);
        }
    }
    let mut resume = vec![(false, None::<crate::storage::KeysetAfter>); plan.nodes.len()];
    if let Some(cursor) = input.args.get("cursor").filter(|cursor| !cursor.is_null()) {
        let wire = cursor.as_str().ok_or_else(snapshot_batch_cursor_invalid)?;
        let body = crate::snapshot_batch_cursor_v2::decode(
            wire,
            &roots,
            authority.app_id,
            &database_id,
            TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX,
            now_ms,
        )
        .map_err(|_| snapshot_batch_cursor_invalid())?;

        // Decode validity and every static binding failure collapse before
        // the dynamic epoch/parent restart partition. Authority is included
        // here, so cross-authority always wins over a coincident rotation.
        if body.function != function.id
            || body.plan_hash != identity.plan_hash
            || body.args != canonical_args
            || body.authority_partition != authority_partition
            || body.parent_groups.len() != groups.len()
            || body.nodes.len() != plan.nodes.len()
        {
            return Err(snapshot_batch_cursor_invalid());
        }
        for (index, cursor_group) in body.parent_groups.iter().enumerate() {
            if cursor_group.group_index != index as u32
                || cursor_group.parent_authorization_key_digest
                    != identity.parent_authorization_key_digests[index]
                || cursor_group.parent_id != parent_ids[index]
            {
                return Err(snapshot_batch_cursor_invalid());
            }
        }
        for (position, (cursor_node, node)) in body.nodes.iter().zip(&plan.nodes).enumerate() {
            if cursor_node.position != position as u32
                || cursor_node.node_plan_hash != identity.node_plan_hashes[position]
            {
                return Err(snapshot_batch_cursor_invalid());
            }
            match (&cursor_node.state, node) {
                (crate::snapshot_batch_cursor_v2::NodeState::Terminal, _) => {
                    resume[position].0 = true;
                }
                (
                    crate::snapshot_batch_cursor_v2::NodeState::Boundary {
                        order_fields,
                        boundary,
                        row_id,
                    },
                    crate::manifest::SnapshotBatchNodeV2::BoundedChildren(node),
                ) => {
                    let expected = node
                        .order
                        .iter()
                        .map(|order| order.field.as_str())
                        .collect::<Vec<_>>();
                    if order_fields.iter().map(String::as_str).collect::<Vec<_>>() != expected {
                        return Err(snapshot_batch_cursor_invalid());
                    }
                    resume[position].1 = Some(
                        crate::storage::validate_query_keyset_boundary(
                            db.schema(),
                            &node.child_table,
                            &node.order,
                            boundary,
                            row_id,
                        )
                        .map_err(|_| snapshot_batch_cursor_invalid())?,
                    );
                }
                (
                    crate::snapshot_batch_cursor_v2::NodeState::RelationalBoundary {
                        order_fields,
                        boundary,
                        row_id,
                    },
                    crate::manifest::SnapshotBatchNodeV2::RelationalQuery(node),
                ) => {
                    let expected = node
                        .order
                        .iter()
                        .map(|order| order.field.as_str())
                        .collect::<Vec<_>>();
                    if order_fields.iter().map(String::as_str).collect::<Vec<_>>() != expected {
                        return Err(snapshot_batch_cursor_invalid());
                    }
                    resume[position].1 = Some(
                        crate::storage::validate_relational_boundary(
                            db.schema(),
                            node,
                            boundary,
                            row_id,
                        )
                        .map_err(|_| snapshot_batch_cursor_invalid())?,
                    );
                }
                _ => return Err(snapshot_batch_cursor_invalid()),
            }
        }

        if body.stream_epoch != stream_epoch {
            return Err(snapshot_batch_restart_required());
        }
        for (index, (cursor_group, runtime_group)) in
            body.parent_groups.iter().zip(&group_rows).enumerate()
        {
            let (_, incarnation, version) = runtime_group
                .as_ref()
                .expect("all snapshot-batch v2 groups remain visible");
            debug_assert_eq!(cursor_group.group_index, index as u32);
            if cursor_group.parent_incarnation != *incarnation
                || cursor_group.parent_version != *version
            {
                return Err(snapshot_batch_restart_required());
            }
        }
    }

    let mut pages = Vec::with_capacity(plan.nodes.len());
    let mut next_nodes = Vec::with_capacity(plan.nodes.len());
    for (position, node) in plan.nodes.iter().enumerate() {
        match node {
            crate::manifest::SnapshotBatchNodeV2::BoundedChildren(node) => {
                let group_index = group_for_node[position]
                    .expect("every bounded snapshot-batch v2 node has a parent group");
                let (parent, incarnation, _) = group_rows[group_index]
                    .as_ref()
                    .expect("all snapshot-batch v2 parents are visible");
                if resume[position].0 || node.take == 0 {
                    pages.push(json!({
                        "parent": project_bounded_row(parent, &node.parent_projection),
                        "children": [],
                    }));
                    next_nodes.push(crate::snapshot_batch_cursor_v2::Node {
                        position: position as u32,
                        node_plan_hash: identity.node_plan_hashes[position].clone(),
                        state: crate::snapshot_batch_cursor_v2::NodeState::Terminal,
                    });
                    continue;
                }
                let child_query = QueryPlan {
                    table_visibility: composed_read_surface_table_visibility(
                        db,
                        &node.child_table,
                        &node.child_table_visibility,
                        "snapshot-batch v2 bounded-children child",
                    )?,
                    table: node.child_table.clone(),
                    filters: vec![
                        crate::manifest::FilterExpr {
                            field: node.child_foreign_key.clone(),
                            op: crate::manifest::FilterOp::Eq,
                            value: ValueExpr::Literal(Value::String(
                                parent_ids[group_index].clone(),
                            )),
                        },
                        crate::manifest::FilterExpr {
                            field: node.child_relation_incarnation.clone(),
                            op: crate::manifest::FilterOp::Eq,
                            value: ValueExpr::Literal(Value::String(incarnation.clone())),
                        },
                    ],
                    membership_filters: Vec::new(),
                    order: node.order.clone(),
                    limit: Some(node.take.saturating_add(1) as usize),
                    indexed_by: Some(node.child_index.clone()),
                };
                let mut child_output =
                    db.query_keyset(&child_query, input, resume[position].1.as_ref())?;
                let examined = child_output.rows.len();
                if examined > identity.node_examined_entry_ceilings[position] {
                    return Err(snapshot_batch_work_ceiling_exceeded());
                }
                let has_more = examined > node.take as usize;
                child_output.rows.truncate(node.take as usize);
                pages.push(json!({
                    "parent": project_bounded_row(parent, &node.parent_projection),
                    "children": child_output.rows.iter().map(|row| {
                        project_bounded_row(row, &node.child_projection)
                    }).collect::<Vec<_>>(),
                }));
                let state = if has_more {
                    let boundary_row = child_output
                        .rows
                        .last()
                        .ok_or_else(snapshot_batch_cursor_mint_unavailable)?;
                    let boundary = node
                        .order
                        .iter()
                        .map(|entry| {
                            boundary_row
                                .get(&entry.field)
                                .cloned()
                                .filter(|value| !value.is_null())
                                .ok_or_else(snapshot_batch_cursor_mint_unavailable)
                        })
                        .collect::<SnapbackResult<Vec<_>>>()?;
                    let row_id = boundary_row
                        .get("_id")
                        .and_then(Value::as_str)
                        .filter(|id| !id.is_empty())
                        .ok_or_else(snapshot_batch_cursor_mint_unavailable)?;
                    crate::snapshot_batch_cursor_v2::NodeState::Boundary {
                        order_fields: node.order.iter().map(|entry| entry.field.clone()).collect(),
                        boundary,
                        row_id: row_id.to_owned(),
                    }
                } else {
                    crate::snapshot_batch_cursor_v2::NodeState::Terminal
                };
                next_nodes.push(crate::snapshot_batch_cursor_v2::Node {
                    position: position as u32,
                    node_plan_hash: identity.node_plan_hashes[position].clone(),
                    state,
                });
            }
            crate::manifest::SnapshotBatchNodeV2::RelationalQuery(node) => {
                debug_assert!(group_for_node[position].is_none());
                if resume[position].0 || node.take == 0 {
                    pages.push(Value::Array(Vec::new()));
                    next_nodes.push(crate::snapshot_batch_cursor_v2::Node {
                        position: position as u32,
                        node_plan_hash: identity.node_plan_hashes[position].clone(),
                        state: crate::snapshot_batch_cursor_v2::NodeState::Terminal,
                    });
                    continue;
                }
                // No standalone relational cursor is decoded or minted here:
                // `KeysetAfter` is reconstructed from the sbsb2 node state
                // and returned directly to the owner executor.
                let (output, continuation, observation) =
                    crate::storage::query_relational_on_observed(
                        db,
                        node,
                        input,
                        resume[position].1.as_ref(),
                    )?;
                if observation.examined_root_entries
                    > identity.node_examined_entry_ceilings[position]
                    || observation.joined_lookups != observation.examined_root_entries
                    || observation.joined_lookups > identity.node_joined_lookup_ceilings[position]
                {
                    return Err(snapshot_batch_work_ceiling_exceeded());
                }
                pages.push(Value::Array(output.rows));
                let state = if let Some(boundary) = continuation {
                    crate::snapshot_batch_cursor_v2::NodeState::RelationalBoundary {
                        order_fields: node.order.iter().map(|entry| entry.field.clone()).collect(),
                        boundary: boundary
                            .entries
                            .into_iter()
                            .map(|(_, value)| value)
                            .collect(),
                        row_id: boundary.id,
                    }
                } else {
                    crate::snapshot_batch_cursor_v2::NodeState::Terminal
                };
                next_nodes.push(crate::snapshot_batch_cursor_v2::Node {
                    position: position as u32,
                    node_plan_hash: identity.node_plan_hashes[position].clone(),
                    state,
                });
            }
        }
    }

    let continuation = if next_nodes.iter().any(|node| {
        !matches!(
            node.state,
            crate::snapshot_batch_cursor_v2::NodeState::Terminal
        )
    }) {
        let cursor_groups = group_rows
            .iter()
            .enumerate()
            .map(|(index, state)| {
                let (_, incarnation, version) = state
                    .as_ref()
                    .expect("all snapshot-batch v2 parent groups are visible");
                crate::snapshot_batch_cursor_v2::ParentGroup {
                    group_index: index as u32,
                    parent_authorization_key_digest: identity.parent_authorization_key_digests
                        [index]
                        .clone(),
                    parent_id: parent_ids[index].clone(),
                    parent_incarnation: incarnation.clone(),
                    parent_version: *version,
                }
            })
            .collect();
        let body = crate::snapshot_batch_cursor_v2::Body::new(
            key_generation.0,
            authority.app_id.to_owned(),
            database_id,
            TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX.to_owned(),
            stream_epoch,
            function.id.clone(),
            identity.plan_hash,
            canonical_args,
            cursor_groups,
            next_nodes,
            authority_partition,
            now_ms,
        );
        Some(
            crate::snapshot_batch_cursor_v2::mint(&root, &body)
                .map_err(|_| snapshot_batch_cursor_mint_unavailable())?,
        )
    } else {
        None
    };
    Ok(QueryInvocation {
        output: QueryOutput {
            version: db.current_version()?,
            rows: vec![json!({
                "kind": "visible",
                "nodes": pages,
                "continuation": continuation,
            })],
            cursor: None,
        },
        read_dependencies: Vec::new(),
    })
}

fn project_bounded_row(row: &Value, fields: &[crate::manifest::BoundedProjectionField]) -> Value {
    let mut projected = serde_json::Map::new();
    for field in fields {
        projected.insert(
            field.name.clone(),
            row.get(&field.field).cloned().unwrap_or(Value::Null),
        );
    }
    Value::Object(projected)
}

/// Re-derive one bounded surface's restricted table policy at execution and
/// return the authoritative value used by its storage query.
///
/// @ref LLP 0231#d3--composed-into-the-plan-sized-by-a-plan-class-model
fn composed_read_surface_table_visibility(
    db: &DbRead<'_>,
    table_name: &str,
    carried: &Option<crate::manifest::TableVisibilityV1>,
    surface: &str,
) -> SnapbackResult<Option<crate::manifest::TableVisibilityV1>> {
    let table = db.schema().table(table_name).ok_or_else(|| {
        SnapbackError::error(
            "SNAPBACK_FUNCTION_SCHEMA_REFERENCE_INVALID",
            "runtime",
            format!("{surface} references unknown table {table_name}"),
        )
    })?;
    let expected = table
        .visibility
        .as_ref()
        .filter(|visibility| visibility.is_restricted())
        .cloned();
    if carried != &expected {
        return Err(SnapbackError::error(
            "SNAPBACK_TABLE_VISIBILITY_PLAN_MISMATCH",
            "auth",
            format!(
                "{surface} over {table_name} must carry the exact schema-derived restricted table visibility predicate"
            ),
        )
        .with_details(json!({
            "surface": surface,
            "table": table_name,
            "expected": expected,
            "actual": carried,
        })));
    }
    Ok(expected)
}

/// Point-read a bounded parent under both its surface-local visibility and
/// the table's declared Class-R policy. Hidden and missing parents collapse to
/// the same `None` before cursor processing.
///
/// @ref LLP 0110#13-evaluation-and-existence-secrecy
/// @ref LLP 0231#d3--composed-into-the-plan-sized-by-a-plan-class-model
fn read_composed_bounded_parent(
    db: &DbRead<'_>,
    input: &HandlerInput,
    table_name: &str,
    parent_id: &str,
    surface_visibility: &crate::manifest::BoundedParentVisibility,
    carried_table_visibility: &Option<crate::manifest::TableVisibilityV1>,
    surface: &str,
) -> SnapbackResult<Option<Value>> {
    let mut filters = vec![crate::manifest::FilterExpr {
        field: "_id".to_owned(),
        op: crate::manifest::FilterOp::Eq,
        value: ValueExpr::Literal(Value::String(parent_id.to_owned())),
    }];
    if let crate::manifest::BoundedParentVisibility::Owner { field } = surface_visibility {
        filters.push(crate::manifest::FilterExpr {
            field: field.clone(),
            op: crate::manifest::FilterOp::Eq,
            value: ValueExpr::AuthUserId,
        });
    }
    let table_visibility =
        composed_read_surface_table_visibility(db, table_name, carried_table_visibility, surface)?;
    let output = db.query(
        &QueryPlan {
            table: table_name.to_owned(),
            table_visibility,
            filters,
            membership_filters: Vec::new(),
            order: Vec::new(),
            limit: Some(1),
            indexed_by: None,
        },
        input,
    )?;
    Ok(output.rows.into_iter().next())
}

/// The one uniform standard-pattern cursor refusal (LLP 0065): malformed,
/// cross-plan, and cross-owner presentations must stay
/// byte-indistinguishable, so every class produces this exact error.
fn standard_pattern_cursor_invalid() -> SnapbackError {
    SnapbackError::error(
        "SNAPBACK_STANDARD_PATTERN_CURSOR_INVALID",
        "query",
        "pagination cursor is not valid for this operation and caller; \
         request the first page again",
    )
}

fn standard_pattern_cursor_mint_unavailable() -> SnapbackError {
    SnapbackError::error(
        "SNAPBACK_STANDARD_PATTERN_CURSOR_MINT_UNAVAILABLE",
        "query",
        "a full page could not mint its continuation cursor; retry the request",
    )
}

/// The generated owned/membership keyset facts the runtime recovers from a
/// standard-pattern function's own plan: the strict continuation filter
/// names the cursor argument, the (single) order field is the cursor field,
/// and the plan limit is the page size. Recovered rather than re-declared so
/// the manifest stays closed and the two can never disagree.
struct StandardPatternKeysetFacts<'a> {
    cursor_arg: Option<&'a str>,
    cursor_field: &'a str,
    page_limit: usize,
}

fn standard_pattern_keyset_facts<'a>(
    function: &'a FunctionDefinition,
    plan: &'a QueryPlan,
) -> Option<StandardPatternKeysetFacts<'a>> {
    let pattern = function.standard_pattern.as_ref()?;
    if !matches!(
        pattern.helper.as_str(),
        "owned-keyset-pages.v1" | "membership-keyset-pages.v1"
    ) {
        return None;
    }
    let order = plan.order.first()?;
    let page_limit = plan.limit?;
    let mut cursor_arg = None;
    for filter in &plan.filters {
        let strict = matches!(
            (&filter.op, &order.direction),
            (
                crate::manifest::FilterOp::Gt,
                crate::manifest::OrderDirection::Asc
            ) | (
                crate::manifest::FilterOp::Lt,
                crate::manifest::OrderDirection::Desc
            )
        );
        if filter.field == order.field
            && strict
            && let ValueExpr::Arg(name) = &filter.value
        {
            cursor_arg = Some(name.as_str());
        }
    }
    Some(StandardPatternKeysetFacts {
        cursor_arg,
        cursor_field: &order.field,
        page_limit,
    })
}

/// The standard-pattern cursor binding digest (LLP 0065): app, the *pair*
/// plan identity, and the caller's authority partition. A keyset pair's
/// first and next functions share everything except the strict
/// continuation filter, so the binding covers the plan with that filter
/// excluded — a cursor minted by `first` continues through `next`, while a
/// different table, index, order, direction, page size, visibility, or
/// pattern profile still refuses. The deployment/database axis rides the
/// per-instance MAC keyring rather than the digest.
fn standard_pattern_cursor_binding(
    authority: &RelationalCursorAuthority<'_>,
    function: &FunctionDefinition,
    plan: &QueryPlan,
    facts: &StandardPatternKeysetFacts<'_>,
    input: &HandlerInput,
    permission_epochs: &BTreeMap<String, u64>,
    membership_snapshot: Option<&MembershipCursorCustodySnapshot>,
) -> Result<String, ()> {
    let pattern = function.standard_pattern.as_ref().ok_or(())?;
    let shared_filters: Vec<Value> = plan
        .filters
        .iter()
        .filter(|filter| {
            !(filter.field == facts.cursor_field
                && matches!(
                    filter.op,
                    crate::manifest::FilterOp::Gt | crate::manifest::FilterOp::Lt
                )
                && matches!(&filter.value, ValueExpr::Arg(_)))
        })
        .map(|filter| serde_json::to_value(filter).unwrap_or(Value::Null))
        .collect();
    let epochs: Value = match input.auth.user_id.as_deref() {
        Some(user_id) => {
            let scope = user_permission_scope(user_id);
            let epoch = permission_epochs.get(&scope).copied().unwrap_or(0);
            json!({ scope: epoch })
        }
        None => json!({}),
    };
    let binding = json!({
        "app": authority.app_id,
        "helper": pattern.helper,
        "profile": pattern.profile,
        "table": plan.table,
        "index": plan.indexed_by,
        "order": serde_json::to_value(&plan.order).map_err(|_| ())?,
        "limit": plan.limit,
        "filters": shared_filters,
        "authority": {
            "fingerprint": crate::manifest::auth_fingerprint(&input.auth),
            "epochs": epochs,
        },
    });
    if pattern.helper != "membership-keyset-pages.v1" {
        // Keep the inherited owned-keyset digest byte-identical: membership
        // additions are profile-conditional, not nullable members appended to
        // the existing object.
        return crate::rqs_contract::sha256_identity(&binding).map_err(|_| ());
    }

    let membership = pattern.membership.as_ref().ok_or(())?;
    let membership_snapshot = membership_snapshot.ok_or(())?;
    let mut args = input.args.clone();
    if let (Some(cursor_arg), Value::Object(map)) = (facts.cursor_arg, &mut args) {
        map.remove(cursor_arg);
    }
    // @ref LLP 0100#5-index-and-continuation-contract — unlike the owner
    //   partition, membership custody must bind the concrete resource value,
    //   declaration facts, durable global authorization pair, reset stream,
    //   and exact active artifact/profile identity. `validate_function_args`
    //   has already normalized and admitted `input.args` at this seam.
    let binding = json!({
        "inherited": binding,
        "args": args,
        "membership": membership,
        "globalAuthorization": membership_snapshot.authorization,
        "dataVersionStream": membership_snapshot.data_version_stream,
        "artifact": {
            "schemaHash": authority.schema_hash,
            "functionBundleHash": authority.function_bundle_hash,
            "functionPublicationGeneration": authority.function_publication_generation,
            "targetProfile": authority.target_profile,
        },
    });
    crate::rqs_contract::sha256_identity(&binding).map_err(|_| ())
}

/// The canonical cursor binding digest (LLP 0080 §2): the cursor binds the
/// app, the plan, the normalized non-cursor arguments, the order schema, and
/// the caller's authority partition (auth fingerprint plus the caller's
/// permission-scope epoch, which rolls on authorization change — the
/// stale-authority refusal).
fn relational_cursor_binding(
    app_id: &str,
    plan: &crate::manifest::RelationalQueryPlan,
    input: &HandlerInput,
    permission_epochs: &BTreeMap<String, u64>,
    schema: &SchemaManifest,
) -> Result<String, ()> {
    let root_table = schema.tables.iter().find(|table| table.name == plan.root);
    let order_schema: Vec<Value> = plan
        .order
        .iter()
        .map(|order| {
            let declared = root_table
                .and_then(|table| table.field(&order.field))
                .map(|field| serde_json::to_value(&field.field_type).unwrap_or(Value::Null))
                .unwrap_or_else(|| Value::String("system".to_owned()));
            json!({
                "field": order.field,
                "direction": match order.direction {
                    crate::manifest::OrderDirection::Asc => "asc",
                    crate::manifest::OrderDirection::Desc => "desc",
                },
                "type": declared,
            })
        })
        .collect();
    let mut args = input.args.clone();
    if let Value::Object(map) = &mut args {
        map.remove("cursor");
    }
    let epochs: Value = match input.auth.user_id.as_deref() {
        Some(user_id) => {
            let scope = user_permission_scope(user_id);
            let epoch = permission_epochs.get(&scope).copied().unwrap_or(0);
            json!({ scope: epoch })
        }
        None => json!({}),
    };
    let binding = json!({
        "app": app_id,
        "plan": serde_json::to_value(plan).map_err(|_| ())?,
        "args": args,
        "orderSchema": order_schema,
        "authority": {
            "fingerprint": crate::manifest::auth_fingerprint(&input.auth),
            "epochs": epochs,
        },
    });
    crate::rqs_contract::sha256_identity(&binding).map_err(|_| ())
}

/// Execute a query-shaped invocation against any read view: the write lane
/// passes the live connection and its own epoch map; the read lane passes a
/// pinned reader and its snapshots. One implementation, so the two lanes
/// cannot drift.
#[derive(Default)]
struct VectorQuarantineCapture {
    target: StdMutex<Option<crate::vector::sqlite::VectorSqliteQueryFailure>>,
}

impl VectorQuarantineCapture {
    fn record(&self, failure: crate::vector::sqlite::VectorSqliteQueryFailure) {
        *self
            .target
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner()) = Some(failure);
    }

    fn take(&self) -> Option<crate::vector::sqlite::VectorSqliteQueryFailure> {
        self.target
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .take()
    }
}

#[allow(clippy::too_many_arguments)]
fn execute_query_invocation(
    serving_database: Option<&crate::storage::ServingDatabase>,
    function: &FunctionDefinition,
    name: &str,
    db: DbRead<'_>,
    permission_epochs: &BTreeMap<String, u64>,
    input: HandlerInput,
    prepared: &PreparedInvocation,
    warm_vms: Option<&crate::warm_vm::WarmVmPool>,
    cursor_authority: Option<RelationalCursorAuthority<'_>>,
    examined_entry_ceiling: Option<usize>,
    vector_quarantine: Option<&VectorQuarantineCapture>,
) -> SnapbackResult<QueryInvocation> {
    if let DbRead::Live(live) = db {
        let owned_capture = VectorQuarantineCapture::default();
        let capture = vector_quarantine.unwrap_or(&owned_capture);
        let result = live.query_reads_read().with_pinned_read_view(|db| {
            execute_query_invocation(
                serving_database,
                function,
                name,
                db,
                permission_epochs,
                input,
                prepared,
                warm_vms,
                cursor_authority,
                examined_entry_ceiling,
                Some(capture),
            )
        });
        if let Some(failure) = capture.take() {
            // Detection already installed the shared pending gate before this
            // pinned view returned; settlement records the durable state now.
            return Err(match serving_database {
                Some(database) => database.settle_vector_query_failure(failure),
                None => failure.error().clone(),
            });
        }
        return result;
    }
    prepared.validate_admission("query execution")?;
    // @ref LLP 0131#runtime-ingress-validation — fresh query admission
    // (direct run, server request, live subscribe binding, search) validates
    // the declared argument contract before any plan or handler work.
    crate::args_contract::validate_function_args(function, &input.args)?;
    let invocation = match (&function.kind, &function.runtime) {
        (
            FunctionKind::Query | FunctionKind::LiveQuery,
            FunctionRuntime::HostPlan(HandlerPlan::Query(plan)),
        ) => {
            // @ref LLP 0065#3-common-pattern-contracts — defineOwnedKeysetPages
            //   continuation is an opaque versioned cursor: the runtime
            //   verifies the presented token (MAC + binding over app, plan
            //   identity, and authority partition), substitutes the bound
            //   boundary value for the cursor argument, and mints the next
            //   continuation for a full page. Malformed, cross-plan, and
            //   cross-owner presentations refuse byte-identically and are
            //   never repositioned.
            let keyset = standard_pattern_keyset_facts(function, plan);
            let membership_keyset = function.standard_pattern.as_ref().is_some_and(|pattern| {
                pattern.helper == "membership-keyset-pages.v1" && pattern.profile == "membership.v1"
            });
            let mut membership_snapshot = None;
            let mut input = input;
            if let Some(facts) = &keyset
                && let Some(arg_name) = facts.cursor_arg
            {
                match input.args.get(arg_name).cloned() {
                    None | Some(Value::Null) => {}
                    Some(Value::String(token)) => {
                        let authority =
                            cursor_authority.ok_or_else(standard_pattern_cursor_invalid)?;
                        let body = crate::rqs::decode_and_verify_standard_pattern_cursor(
                            &token,
                            &authority
                                .keyring
                                .read()
                                .unwrap_or_else(|poisoned| poisoned.into_inner()),
                            now_millis(),
                            crate::rqs::RELATIONAL_CURSOR_MAX_AGE_MS,
                        )
                        .map_err(|_| standard_pattern_cursor_invalid())?;
                        if membership_keyset && membership_snapshot.is_none() {
                            let (authorization, data_version_stream) = db
                                .membership_cursor_custody_snapshot()
                                .map_err(|_| standard_pattern_cursor_invalid())?;
                            membership_snapshot = Some(MembershipCursorCustodySnapshot {
                                authorization,
                                data_version_stream,
                            });
                        }
                        let binding = standard_pattern_cursor_binding(
                            &authority,
                            function,
                            plan,
                            facts,
                            &input,
                            permission_epochs,
                            membership_snapshot.as_ref(),
                        )
                        .map_err(|()| standard_pattern_cursor_invalid())?;
                        if body.app != authority.app_id || body.binding != binding {
                            return Err(standard_pattern_cursor_invalid());
                        }
                        crate::storage::validate_standard_pattern_boundary(
                            db.schema(),
                            &plan.table,
                            facts.cursor_field,
                            &body.boundary,
                        )
                        .map_err(|_| standard_pattern_cursor_invalid())?;
                        if let Value::Object(args) = &mut input.args {
                            args.insert(arg_name.to_owned(), body.boundary);
                        }
                    }
                    Some(_) => return Err(standard_pattern_cursor_invalid()),
                }
            }
            let mut output = if let Some(ceiling) = examined_entry_ceiling {
                db.query_with_examined_entry_ceiling(plan, &input, ceiling)?
            } else {
                db.query(plan, &input)?
            };
            if let Some(facts) = &keyset
                && facts.page_limit > 0
                && output.rows.len() == facts.page_limit
            {
                // A full page must carry its continuation (mirrors the
                // relational rule): mint failure fails the request rather
                // than misreporting the page as terminal.
                let boundary = output
                    .rows
                    .last()
                    .and_then(|row| row.get(facts.cursor_field).cloned())
                    .filter(|value| !value.is_null())
                    .ok_or_else(standard_pattern_cursor_mint_unavailable)?;
                let authority =
                    cursor_authority.ok_or_else(standard_pattern_cursor_mint_unavailable)?;
                if membership_keyset && membership_snapshot.is_none() {
                    let (authorization, data_version_stream) = db
                        .membership_cursor_custody_snapshot()
                        .map_err(|_| standard_pattern_cursor_mint_unavailable())?;
                    membership_snapshot = Some(MembershipCursorCustodySnapshot {
                        authorization,
                        data_version_stream,
                    });
                }
                let binding = standard_pattern_cursor_binding(
                    &authority,
                    function,
                    plan,
                    facts,
                    &input,
                    permission_epochs,
                    membership_snapshot.as_ref(),
                )
                .map_err(|()| standard_pattern_cursor_mint_unavailable())?;
                let (key_id, key) = authority
                    .keyring
                    .read()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .active_current()
                    .ok_or_else(standard_pattern_cursor_mint_unavailable)?;
                let body = crate::rqs::StandardPatternCursorBody {
                    app: authority.app_id.to_owned(),
                    binding,
                    boundary,
                    issued_at: now_millis(),
                };
                output.cursor = Some(
                    crate::rqs::mint_standard_pattern_cursor(key.as_ref(), &key_id, &body)
                        .ok_or_else(standard_pattern_cursor_mint_unavailable)?,
                );
            }
            let mut read_dependencies = query_dependencies_from_plan(plan, &input, &output, &db)?;
            add_permission_dependencies_with(permission_epochs, &input, &mut read_dependencies);
            Ok(QueryInvocation {
                output,
                read_dependencies,
            })
        }
        (
            FunctionKind::Query | FunctionKind::LiveQuery,
            FunctionRuntime::HostPlan(HandlerPlan::JobStatusQuery(_)),
        ) => {
            // The generated declared job-status query (LLP 0121 option 3):
            // one point read of the privacy-bounded lifecycle projection,
            // captured as a Row/MissingRow dependency on the reserved
            // job-status table so job lifecycle transitions wake live
            // subscriptions through the ordinary matcher — including the
            // absent→present direction after a later enqueue.
            let Some(job_id) = input.args.get("jobId").and_then(Value::as_str) else {
                return Err(SnapbackError::error(
                    "SNAPBACK_JOB_STATUS_ARGS_INVALID",
                    "jobs",
                    "the job-status query requires a string jobId argument",
                ));
            };
            let status = db.job_status_row(job_id)?;
            let version = db.current_version()?;
            let rows = status
                .as_ref()
                .map(|row| vec![row.to_row_value()])
                .unwrap_or_default();
            let mut read_dependencies = vec![CapturedReadDependency {
                kind: if status.is_some() {
                    CapturedReadKind::Row
                } else {
                    CapturedReadKind::MissingRow
                },
                table: Some(crate::jobs::JOBS_STATUS_TABLE.to_owned()),
                id: Some(job_id.to_owned()),
                version: status.as_ref().map(|row| row.state_version),
                predicate: None,
                rows: Vec::new(),
                field: None,
                value: None,
                order: None,
                limit: None,
                result_count: Some(rows.len()),
                boundary: None,
            }];
            add_permission_dependencies_with(permission_epochs, &input, &mut read_dependencies);
            Ok(QueryInvocation {
                output: QueryOutput {
                    version,
                    cursor: None,
                    rows,
                },
                read_dependencies,
            })
        }
        (FunctionKind::Query, FunctionRuntime::HostPlan(HandlerPlan::PushLedgerQuery(_))) => {
            let Some(intent_id) = input.args.get("intentId").and_then(Value::as_str) else {
                return Err(SnapbackError::error(
                    "SNAPBACK_PUSH_LEDGER_ARGS_INVALID",
                    "push",
                    "the push ledger query requires a string intentId argument",
                ));
            };
            let schema = db.schema();
            let declaration = schema.push_seam.as_ref().ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_PUSH_LEDGER_NOT_DECLARED",
                    "push",
                    "the application does not declare the push ledger",
                )
            })?;
            let (projection, authorization_dependency) =
                crate::push::read_ledger_projection_for_prepared(
                    serving_database.ok_or_else(read_lane_unavailable)?,
                    &db,
                    declaration,
                    schema,
                    prepared.authority(),
                    intent_id,
                )?;
            let version = db.current_version()?;
            let rows = projection
                .iter()
                .map(crate::push::PushLedgerRowV1::to_row_value)
                .collect();
            let mut read_dependencies = authorization_dependency.into_iter().collect::<Vec<_>>();
            add_permission_dependencies_with(permission_epochs, &input, &mut read_dependencies);
            Ok(QueryInvocation {
                output: QueryOutput {
                    version,
                    cursor: None,
                    rows,
                },
                read_dependencies,
            })
        }
        (
            FunctionKind::Query | FunctionKind::LiveQuery,
            FunctionRuntime::HostPlan(HandlerPlan::SearchQuery(plan)),
        ) => {
            // @ref LLP 0073#authorization-and-result-release — the search
            // executor receives only server-resolved authority and evaluates
            // inside this pinned read snapshot; application input cannot
            // supply an owner partition or cursor binding identity.
            let cursor_authority = cursor_authority.ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_SEARCH_INDEX_UNAVAILABLE",
                    "search",
                    "search cursor authority is unavailable",
                )
            })?;
            let now_ms = now_millis();
            let roots = cursor_authority
                .keyring
                .read()
                .unwrap_or_else(|poisoned| poisoned.into_inner())
                .search_cursor_materials(now_ms);
            let database_id = db.search_database_identity()?;
            let authority_instance = prepared.authority().resolved().invalidation_subject();
            let owner_subject = match prepared.authority().resolved() {
                ResolvedAppAuthority::Session { user_id, .. }
                | ResolvedAppAuthority::DevImpersonation { user_id, .. } => Some(user_id.as_str()),
                ResolvedAppAuthority::ServicePrincipal {
                    effective_user_id: Some(user_id),
                    ..
                } => Some(user_id.as_str()),
                _ => None,
            };
            let release_policy_digest = crate::rqs_contract::sha256_identity(
                &serde_json::to_value(function).map_err(|_| {
                    SnapbackError::error(
                        "SNAPBACK_SEARCH_INDEX_UNAVAILABLE",
                        "search",
                        "search release policy does not serialize",
                    )
                })?,
            )
            .map_err(|_| {
                SnapbackError::error(
                    "SNAPBACK_SEARCH_INDEX_UNAVAILABLE",
                    "search",
                    "search release policy is not canonicalizable",
                )
            })?;
            let stream_epoch = prepared
                .authority()
                .authorization_stream_incarnation()
                .unwrap_or(database_id.as_str());
            let output = db.search(
                plan,
                &input,
                &crate::search::sqlite::SearchExecutionAuthority {
                    app_id: cursor_authority.app_id,
                    database_id: &database_id,
                    target_profile_id: TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX,
                    stream_epoch,
                    authority_instance: &authority_instance,
                    owner_subject,
                    release_policy_digest: &release_policy_digest,
                    now_ms,
                    cursor_roots: &roots,
                },
            )?;
            // Search has no serializable QueryPlan predicate in the shared
            // matcher vocabulary. Omitting an incomplete Query dependency lets
            // the HostPlan::SearchQuery matcher below prove disjoint-table
            // commits irrelevant while conservatively re-running every commit
            // on the searched table.
            //
            // @ref LLP 0008#reactivity-and-read-sets — incomplete dependency
            //   facts fall back; they must not disable a coarser correct proof.
            let mut read_dependencies = Vec::new();
            add_permission_dependencies_with(permission_epochs, &input, &mut read_dependencies);
            Ok(QueryInvocation {
                output,
                read_dependencies,
            })
        }
        (FunctionKind::Query, FunctionRuntime::HostPlan(HandlerPlan::VectorQuery(plan))) => {
            // @ref LLP 0132#candidate-to-release-consistency — the SQLite
            // adapter enumerates, scores, and release-rechecks against this
            // one pinned snapshot. Only server-resolved effective authority
            // selects an owner partition; authored args carry no authority.
            let owner_subject = match prepared.authority().resolved() {
                ResolvedAppAuthority::Session { user_id, .. }
                | ResolvedAppAuthority::DevImpersonation { user_id, .. } => Some(user_id.as_str()),
                ResolvedAppAuthority::ServicePrincipal {
                    effective_user_id: Some(user_id),
                    ..
                } => Some(user_id.as_str()),
                _ => None,
            };
            let result = match db.vector(plan, &input, owner_subject) {
                Ok(result) => result,
                Err(failure) => {
                    let error = failure.error().clone();
                    if let Some(capture) = vector_quarantine {
                        capture.record(failure);
                    }
                    return Err(error);
                }
            };
            let output = result.output;
            let mut read_dependencies = vec![CapturedReadDependency {
                kind: CapturedReadKind::Query,
                table: Some(plan.table.clone()),
                id: None,
                version: Some(output.version),
                predicate: None,
                rows: output
                    .rows
                    .iter()
                    .filter_map(|row| {
                        row.get("rowId")
                            .and_then(Value::as_str)
                            .map(ToOwned::to_owned)
                    })
                    .collect(),
                field: None,
                value: None,
                order: Some(json!(crate::vector::VECTOR_ORDERING_PROFILE_ID)),
                limit: Some(
                    input
                        .args
                        .get("k")
                        .and_then(Value::as_u64)
                        .unwrap_or(u64::from(crate::vector::VECTOR_DEFAULT_K))
                        as usize,
                ),
                result_count: Some(output.rows.len()),
                boundary: None,
            }];
            add_permission_dependencies_with(permission_epochs, &input, &mut read_dependencies);
            Ok(QueryInvocation {
                output,
                read_dependencies,
            })
        }
        (
            FunctionKind::Query | FunctionKind::LiveQuery,
            FunctionRuntime::HostPlan(HandlerPlan::RelationalQuery(plan)),
        ) => {
            // @ref LLP 0080#2-portable-evaluation-semantics — opaque
            //   versioned cursor: verify the presented cursor's MAC and
            //   binding digest, validate its boundary against the order
            //   schema, execute from that boundary, and mint the
            //   continuation for a full page. All six refusal classes
            //   collapse into the one byte-identical refusal and are never
            //   repositioned.
            let presented = match input.args.get("cursor") {
                None | Some(Value::Null) => None,
                Some(Value::String(token)) => Some(token.clone()),
                Some(_) => return Err(relational_cursor_invalid()),
            };
            let keyset = match presented {
                None => None,
                Some(token) => {
                    let authority = cursor_authority.ok_or_else(relational_cursor_invalid)?;
                    let body = crate::rqs::decode_and_verify_relational_cursor(
                        &token,
                        &authority
                            .keyring
                            .read()
                            .unwrap_or_else(|poisoned| poisoned.into_inner()),
                        now_millis(),
                        crate::rqs::RELATIONAL_CURSOR_MAX_AGE_MS,
                    )
                    .map_err(|_| relational_cursor_invalid())?;
                    let binding = relational_cursor_binding(
                        authority.app_id,
                        plan,
                        &input,
                        permission_epochs,
                        db.schema(),
                    )
                    .map_err(|()| relational_cursor_invalid())?;
                    if body.app != authority.app_id || body.binding != binding {
                        return Err(relational_cursor_invalid());
                    }
                    Some(
                        crate::storage::validate_relational_boundary(
                            db.schema(),
                            plan,
                            &body.boundary,
                            &body.id,
                        )
                        .map_err(|_| relational_cursor_invalid())?,
                    )
                }
            };
            // @ref LLP 0080#4-live-and-retained-capability — relational reads
            //   deliberately capture no Query-kind dependency: the matcher
            //   then falls through to the table-granular runtime arm, so any
            //   commit touching either declared source resnapshots and no
            //   proved-disjoint skip is claimed.
            let (mut output, continuation) =
                crate::storage::query_relational_on(&db, plan, &input, keyset.as_ref())?;
            if let Some(boundary) = continuation {
                // A full page must carry its continuation: silently omitting
                // it would misreport the page as terminal, so mint failure
                // fails the request rather than the pagination contract.
                let authority = cursor_authority.ok_or_else(relational_cursor_mint_unavailable)?;
                let binding = relational_cursor_binding(
                    authority.app_id,
                    plan,
                    &input,
                    permission_epochs,
                    db.schema(),
                )
                .map_err(|()| relational_cursor_mint_unavailable())?;
                let (key_id, key) = authority
                    .keyring
                    .read()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .active_current()
                    .ok_or_else(relational_cursor_mint_unavailable)?;
                let body = crate::rqs::RelationalCursorBody {
                    app: authority.app_id.to_owned(),
                    binding,
                    boundary: boundary
                        .entries
                        .into_iter()
                        .map(|(_, value)| value)
                        .collect(),
                    id: boundary.id,
                    issued_at: now_millis(),
                };
                output.cursor = Some(
                    crate::rqs::mint_relational_cursor(key.as_ref(), &key_id, &body)
                        .ok_or_else(relational_cursor_mint_unavailable)?,
                );
            }
            let mut read_dependencies = Vec::new();
            if let Some(user_id) = input.auth.user_id.as_deref() {
                read_dependencies.push(CapturedReadDependency {
                    kind: CapturedReadKind::Auth,
                    table: None,
                    id: None,
                    version: None,
                    predicate: None,
                    rows: Vec::new(),
                    field: Some("userId".to_owned()),
                    value: Some(Value::String(user_id.to_owned())),
                    order: None,
                    limit: None,
                    result_count: None,
                    boundary: None,
                });
            }
            add_permission_dependencies_with(permission_epochs, &input, &mut read_dependencies);
            Ok(QueryInvocation {
                output,
                read_dependencies,
            })
        }
        (
            FunctionKind::Query | FunctionKind::LiveQuery,
            FunctionRuntime::HostPlan(HandlerPlan::SnapshotBatchV2(plan)),
        ) => execute_snapshot_batch_v2(function, plan, &db, &input, prepared, cursor_authority),
        (
            FunctionKind::Query | FunctionKind::LiveQuery,
            FunctionRuntime::HostPlan(HandlerPlan::SnapshotBatch(plan)),
        ) => {
            // @ref LLP 0135#22-one-snapshot-execution-and-parent-authorization-dedup —
            // all point reads and child ranges use this invocation's already-pinned
            // DbRead, while structural groups share exactly one parent check.
            let authority = cursor_authority.ok_or_else(snapshot_batch_cursor_mint_unavailable)?;
            let now_ms = now_millis();
            let database_id = db.search_database_identity()?;
            let stream_epoch = prepared
                .authority()
                .authorization_stream_incarnation()
                .unwrap_or(database_id.as_str())
                .to_owned();
            let canonical_args = snapshot_batch_non_cursor_args(&input)?;
            let identity = crate::manifest::snapshot_batch_identity_v1(function, plan)?;
            let authority_partition =
                snapshot_batch_authority_partition_digest(prepared, &input, &stream_epoch)?;
            let groups =
                crate::manifest::snapshot_batch_parent_authorization_groups(function, plan)?;
            let parent_ids = groups
                .iter()
                .map(|group| {
                    input
                        .args
                        .get(&group.identity.parent_id_argument)
                        .and_then(Value::as_str)
                        .filter(|id| !id.is_empty())
                        .map(ToOwned::to_owned)
                        .ok_or_else(|| {
                            SnapbackError::error(
                                "SNAPBACK_SNAPSHOT_BATCH_PLAN_INVALID",
                                "query",
                                "snapshot batch parent argument is missing or invalid",
                            )
                        })
                })
                .collect::<SnapbackResult<Vec<_>>>()?;
            let (roots, key_generation, root) = {
                let keyring = authority
                    .keyring
                    .read()
                    .unwrap_or_else(|poisoned| poisoned.into_inner());
                let roots = keyring.snapshot_batch_cursor_materials(now_ms);
                let (generation, root) = keyring
                    .active_current()
                    .ok_or_else(snapshot_batch_cursor_mint_unavailable)?;
                let longest_generation = roots
                    .iter()
                    .map(|(generation, _)| generation.as_str())
                    .max_by_key(|generation| generation.len())
                    .unwrap_or(generation.as_str())
                    .to_owned();
                (roots, (generation, longest_generation), root)
            };
            // LLP 0157 requires a static worst-case check before the first
            // storage read, including every parent/member and order bound.
            enforce_snapshot_batch_cursor_budget(
                &db,
                plan,
                &identity,
                &key_generation.1,
                authority.app_id,
                &database_id,
                &stream_epoch,
                &function.id,
                &canonical_args,
                &authority_partition,
                &parent_ids,
            )?;

            let mut group_rows = Vec::with_capacity(groups.len());
            for (group_index, group) in groups.iter().enumerate() {
                let parent_id = &parent_ids[group_index];
                let node_index = *group
                    .node_indices
                    .first()
                    .expect("snapshot-batch parent group has a bounded node");
                let node = &plan.nodes[node_index];
                let parent = read_composed_bounded_parent(
                    &db,
                    &input,
                    &group.identity.parent_table,
                    parent_id,
                    &group.identity.visibility,
                    &node.parent_table_visibility,
                    "snapshot-batch bounded-children parent",
                )?;
                let state = if let Some(parent) = parent {
                    let incarnation = db
                        .active_relation_incarnation(&group.identity.parent_table, parent_id)?
                        .ok_or_else(snapshot_batch_restart_required)?;
                    let version = parent
                        .get("_version")
                        .and_then(Value::as_u64)
                        .ok_or_else(snapshot_batch_restart_required)?;
                    Some((parent, incarnation, version))
                } else {
                    None
                };
                group_rows.push(state);
            }
            // Every structural parent group has now been checked. A malformed
            // cursor cannot distinguish which check sealed the response.
            if group_rows.iter().any(Option::is_none) {
                return Ok(QueryInvocation {
                    output: QueryOutput {
                        version: db.current_version()?,
                        rows: vec![json!({
                            "kind": "absent",
                            "nodes": null,
                            "continuation": null,
                        })],
                        cursor: None,
                    },
                    read_dependencies: Vec::new(),
                });
            }

            let mut group_for_node = vec![usize::MAX; plan.nodes.len()];
            for (group_index, group) in groups.iter().enumerate() {
                for &node_index in &group.node_indices {
                    group_for_node[node_index] = group_index;
                }
            }
            let mut resume = vec![(false, None::<crate::storage::KeysetAfter>); plan.nodes.len()];
            if let Some(cursor) = input.args.get("cursor").filter(|cursor| !cursor.is_null()) {
                let wire = cursor.as_str().ok_or_else(snapshot_batch_cursor_invalid)?;
                let body = crate::snapshot_batch_cursor::decode(
                    wire,
                    &roots,
                    authority.app_id,
                    &database_id,
                    TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX,
                    now_ms,
                )
                .map_err(|_| snapshot_batch_cursor_invalid())?;
                if body.function != function.id
                    || body.plan_hash != identity.plan_hash
                    || body.args != canonical_args
                    || body.authority_partition != authority_partition
                    || body.parent_groups.len() != groups.len()
                    || body.nodes.len() != plan.nodes.len()
                {
                    return Err(snapshot_batch_cursor_invalid());
                }
                if body.stream_epoch != stream_epoch {
                    return Err(snapshot_batch_restart_required());
                }
                for (index, (cursor_group, runtime_group)) in
                    body.parent_groups.iter().zip(&group_rows).enumerate()
                {
                    let (_, incarnation, version) = runtime_group
                        .as_ref()
                        .expect("all groups visible after seal check");
                    if cursor_group.group_index != index as u32
                        || cursor_group.parent_authorization_key_digest
                            != identity.parent_authorization_key_digests[index]
                        || cursor_group.parent_id != parent_ids[index]
                    {
                        return Err(snapshot_batch_cursor_invalid());
                    }
                    if cursor_group.parent_incarnation != *incarnation
                        || cursor_group.parent_version != *version
                    {
                        return Err(snapshot_batch_restart_required());
                    }
                }
                for (position, (cursor_node, node)) in
                    body.nodes.iter().zip(&plan.nodes).enumerate()
                {
                    if cursor_node.position != position as u32
                        || cursor_node.node_plan_hash != identity.node_plan_hashes[position]
                    {
                        return Err(snapshot_batch_cursor_invalid());
                    }
                    match &cursor_node.state {
                        crate::snapshot_batch_cursor::NodeState::Terminal => {
                            resume[position].0 = true;
                        }
                        crate::snapshot_batch_cursor::NodeState::Boundary {
                            order_fields,
                            boundary,
                            row_id,
                        } => {
                            let expected = node
                                .order
                                .iter()
                                .map(|order| order.field.as_str())
                                .collect::<Vec<_>>();
                            if order_fields.iter().map(String::as_str).collect::<Vec<_>>()
                                != expected
                            {
                                return Err(snapshot_batch_cursor_invalid());
                            }
                            resume[position].1 = Some(
                                crate::storage::validate_query_keyset_boundary(
                                    db.schema(),
                                    &node.child_table,
                                    &node.order,
                                    boundary,
                                    row_id,
                                )
                                .map_err(|_| snapshot_batch_cursor_invalid())?,
                            );
                        }
                    }
                }
            }

            let mut pages = Vec::with_capacity(plan.nodes.len());
            let mut next_nodes = Vec::with_capacity(plan.nodes.len());
            for (position, node) in plan.nodes.iter().enumerate() {
                let group_index = group_for_node[position];
                let (parent, incarnation, _) = group_rows[group_index]
                    .as_ref()
                    .expect("all snapshot parent groups visible");
                if resume[position].0 || node.take == 0 {
                    pages.push(json!({
                        "parent": project_bounded_row(parent, &node.parent_projection),
                        "children": [],
                    }));
                    next_nodes.push(crate::snapshot_batch_cursor::Node {
                        position: position as u32,
                        node_plan_hash: identity.node_plan_hashes[position].clone(),
                        state: crate::snapshot_batch_cursor::NodeState::Terminal,
                    });
                    continue;
                }
                let child_query = QueryPlan {
                    table_visibility: composed_read_surface_table_visibility(
                        &db,
                        &node.child_table,
                        &node.child_table_visibility,
                        "snapshot-batch bounded-children child",
                    )?,
                    table: node.child_table.clone(),
                    filters: vec![
                        crate::manifest::FilterExpr {
                            field: node.child_foreign_key.clone(),
                            op: crate::manifest::FilterOp::Eq,
                            value: ValueExpr::Literal(Value::String(
                                parent_ids[group_index].clone(),
                            )),
                        },
                        crate::manifest::FilterExpr {
                            field: node.child_relation_incarnation.clone(),
                            op: crate::manifest::FilterOp::Eq,
                            value: ValueExpr::Literal(Value::String(incarnation.clone())),
                        },
                    ],
                    membership_filters: Vec::new(),
                    order: node.order.clone(),
                    limit: Some(node.take.saturating_add(1) as usize),
                    indexed_by: Some(node.child_index.clone()),
                };
                let mut child_output =
                    db.query_keyset(&child_query, &input, resume[position].1.as_ref())?;
                let has_more = child_output.rows.len() > node.take as usize;
                child_output.rows.truncate(node.take as usize);
                pages.push(json!({
                    "parent": project_bounded_row(parent, &node.parent_projection),
                    "children": child_output.rows.iter().map(|row| {
                        project_bounded_row(row, &node.child_projection)
                    }).collect::<Vec<_>>(),
                }));
                let state = if has_more {
                    let boundary_row = child_output
                        .rows
                        .last()
                        .ok_or_else(snapshot_batch_cursor_mint_unavailable)?;
                    let boundary = node
                        .order
                        .iter()
                        .map(|entry| {
                            boundary_row
                                .get(&entry.field)
                                .cloned()
                                .filter(|value| !value.is_null())
                                .ok_or_else(snapshot_batch_cursor_mint_unavailable)
                        })
                        .collect::<SnapbackResult<Vec<_>>>()?;
                    let row_id = boundary_row
                        .get("_id")
                        .and_then(Value::as_str)
                        .filter(|id| !id.is_empty())
                        .ok_or_else(snapshot_batch_cursor_mint_unavailable)?;
                    crate::snapshot_batch_cursor::NodeState::Boundary {
                        order_fields: node.order.iter().map(|entry| entry.field.clone()).collect(),
                        boundary,
                        row_id: row_id.to_owned(),
                    }
                } else {
                    crate::snapshot_batch_cursor::NodeState::Terminal
                };
                next_nodes.push(crate::snapshot_batch_cursor::Node {
                    position: position as u32,
                    node_plan_hash: identity.node_plan_hashes[position].clone(),
                    state,
                });
            }
            let continuation = if next_nodes.iter().any(|node| {
                matches!(
                    node.state,
                    crate::snapshot_batch_cursor::NodeState::Boundary { .. }
                )
            }) {
                let cursor_groups = group_rows
                    .iter()
                    .enumerate()
                    .map(|(index, state)| {
                        let (_, incarnation, version) =
                            state.as_ref().expect("all snapshot parent groups visible");
                        crate::snapshot_batch_cursor::ParentGroup {
                            group_index: index as u32,
                            parent_authorization_key_digest: identity
                                .parent_authorization_key_digests[index]
                                .clone(),
                            parent_id: parent_ids[index].clone(),
                            parent_incarnation: incarnation.clone(),
                            parent_version: *version,
                        }
                    })
                    .collect();
                let body = crate::snapshot_batch_cursor::Body::new(
                    key_generation.0,
                    authority.app_id.to_owned(),
                    database_id,
                    TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX.to_owned(),
                    stream_epoch,
                    function.id.clone(),
                    identity.plan_hash,
                    canonical_args,
                    cursor_groups,
                    next_nodes,
                    authority_partition,
                    now_ms,
                );
                Some(
                    crate::snapshot_batch_cursor::mint(&root, &body)
                        .map_err(|_| snapshot_batch_cursor_mint_unavailable())?,
                )
            } else {
                None
            };
            Ok(QueryInvocation {
                output: QueryOutput {
                    version: db.current_version()?,
                    rows: vec![json!({
                        "kind": "visible",
                        "nodes": pages,
                        "continuation": continuation,
                    })],
                    cursor: None,
                },
                read_dependencies: Vec::new(),
            })
        }
        (
            FunctionKind::Query | FunctionKind::LiveQuery,
            FunctionRuntime::HostPlan(HandlerPlan::BoundedChildrenQuery(plan)),
        ) => {
            let parent_id = input
                .args
                .get(&plan.parent_id_arg)
                .and_then(Value::as_str)
                .ok_or_else(|| {
                    SnapbackError::error(
                        "SNAPBACK_BOUNDED_CHILDREN_PLAN_INVALID",
                        "query",
                        "bounded children parent id argument is missing or invalid",
                    )
                })?;
            let parent = read_composed_bounded_parent(
                &db,
                &input,
                &plan.parent_table,
                parent_id,
                &plan.parent_visibility,
                &plan.parent_table_visibility,
                "bounded-children parent",
            )?;
            if parent.is_none() {
                return Ok(QueryInvocation {
                    output: QueryOutput {
                        version: db.current_version()?,
                        rows: vec![json!({
                            "kind": "absent",
                            "parent": null,
                            "children": [],
                            "continuation": null,
                        })],
                        cursor: None,
                    },
                    read_dependencies: Vec::new(),
                });
            }
            let incarnation = db
                .active_relation_incarnation(&plan.parent_table, parent_id)?
                .ok_or_else(bounded_children_parent_restart_required)?;
            let parent = parent.expect("visible parent exists");
            let parent_version = parent
                .get("_version")
                .and_then(Value::as_u64)
                .ok_or_else(bounded_children_parent_restart_required)?;
            let now_ms = now_millis();
            let authority =
                cursor_authority.ok_or_else(bounded_children_cursor_mint_unavailable)?;
            let database_id = db.search_database_identity()?;
            let stream_epoch = prepared
                .authority()
                .authorization_stream_incarnation()
                .unwrap_or(database_id.as_str())
                .to_owned();
            let authority_partition = prepared.authority().resolved().invalidation_subject();
            let plan_hash = crate::rqs_contract::sha256_identity(
                &serde_json::to_value(plan).map_err(|_| bounded_children_cursor_invalid())?,
            )
            .map_err(|_| bounded_children_cursor_invalid())?;
            let order_fields = plan
                .order
                .iter()
                .map(|entry| entry.field.clone())
                .collect::<Vec<_>>();
            // Cursor bytes stay deferred until the parent has passed
            // visibility, preserving absent/invisible parity.
            let keyset = match input.args.get("cursor") {
                None | Some(Value::Null) => None,
                Some(Value::String(wire)) => {
                    let roots = authority
                        .keyring
                        .read()
                        .unwrap_or_else(|poisoned| poisoned.into_inner())
                        .bounded_children_cursor_materials(now_ms);
                    let body = crate::bounded_children_cursor::decode(
                        wire,
                        &roots,
                        authority.app_id,
                        &database_id,
                        TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX,
                        now_ms,
                    )
                    .map_err(|_| bounded_children_cursor_invalid())?;
                    if body.function != name
                        || body.plan_hash != plan_hash
                        || body.parent_id != parent_id
                        || body.authority_partition != authority_partition
                        || body.order_fields != order_fields
                    {
                        return Err(bounded_children_cursor_invalid());
                    }
                    if body.stream_epoch != stream_epoch
                        || body.parent_incarnation != incarnation
                        || body.parent_version != parent_version
                    {
                        return Err(bounded_children_parent_restart_required());
                    }
                    Some(
                        crate::storage::validate_query_keyset_boundary(
                            db.schema(),
                            &plan.child_table,
                            &plan.order,
                            &body.boundary,
                            &body.row_id,
                        )
                        .map_err(|_| bounded_children_cursor_invalid())?,
                    )
                }
                Some(_) => return Err(bounded_children_cursor_invalid()),
            };
            let child_query = QueryPlan {
                table_visibility: composed_read_surface_table_visibility(
                    &db,
                    &plan.child_table,
                    &plan.child_table_visibility,
                    "bounded-children child",
                )?,
                table: plan.child_table.clone(),
                filters: vec![
                    crate::manifest::FilterExpr {
                        field: plan.child_foreign_key.clone(),
                        op: crate::manifest::FilterOp::Eq,
                        value: ValueExpr::Literal(Value::String(parent_id.to_owned())),
                    },
                    crate::manifest::FilterExpr {
                        field: plan.child_relation_incarnation.clone(),
                        op: crate::manifest::FilterOp::Eq,
                        value: ValueExpr::Literal(Value::String(incarnation.clone())),
                    },
                ],
                membership_filters: Vec::new(),
                order: plan.order.clone(),
                limit: Some(plan.take.saturating_add(1) as usize),
                indexed_by: Some(plan.child_index.clone()),
            };
            if plan.take == 0 {
                return Ok(QueryInvocation {
                    output: QueryOutput {
                        version: db.current_version()?,
                        rows: vec![json!({
                            "kind": "visible",
                            "parent": project_bounded_row(&parent, &plan.parent_projection),
                            "children": [],
                            "continuation": null,
                        })],
                        cursor: None,
                    },
                    read_dependencies: Vec::new(),
                });
            }
            let mut child_output = db.query_keyset(&child_query, &input, keyset.as_ref())?;
            let has_more = child_output.rows.len() > plan.take as usize;
            child_output.rows.truncate(plan.take as usize);
            let children = child_output
                .rows
                .iter()
                .map(|row| project_bounded_row(row, &plan.child_projection))
                .collect::<Vec<_>>();
            let continuation = if has_more {
                let boundary_row = child_output
                    .rows
                    .last()
                    .ok_or_else(bounded_children_cursor_mint_unavailable)?;
                let boundary = plan
                    .order
                    .iter()
                    .map(|entry| {
                        boundary_row
                            .get(&entry.field)
                            .cloned()
                            .filter(|value| !value.is_null())
                            .ok_or_else(bounded_children_cursor_mint_unavailable)
                    })
                    .collect::<SnapbackResult<Vec<_>>>()?;
                let row_id = boundary_row
                    .get("_id")
                    .and_then(Value::as_str)
                    .filter(|id| !id.is_empty())
                    .ok_or_else(bounded_children_cursor_mint_unavailable)?;
                let (key_generation, root) = authority
                    .keyring
                    .read()
                    .unwrap_or_else(|poisoned| poisoned.into_inner())
                    .active_current()
                    .ok_or_else(bounded_children_cursor_mint_unavailable)?;
                let body = crate::bounded_children_cursor::Body::new(
                    key_generation,
                    authority.app_id.to_owned(),
                    database_id,
                    TARGET_PROFILE_LOCAL_DEV_SQLITE_IBEX.to_owned(),
                    stream_epoch.to_owned(),
                    name.to_owned(),
                    plan_hash,
                    parent_id.to_owned(),
                    incarnation,
                    parent_version,
                    authority_partition,
                    order_fields,
                    boundary,
                    row_id.to_owned(),
                    now_ms,
                );
                Some(
                    crate::bounded_children_cursor::mint(&root, &body)
                        .map_err(|_| bounded_children_cursor_mint_unavailable())?,
                )
            } else {
                None
            };
            Ok(QueryInvocation {
                output: QueryOutput {
                    version: child_output.version,
                    rows: vec![json!({
                        "kind": "visible",
                        "parent": project_bounded_row(&parent, &plan.parent_projection),
                        "children": children,
                        "continuation": continuation,
                    })],
                    cursor: None,
                },
                read_dependencies: Vec::new(),
            })
        }
        (FunctionKind::Query | FunctionKind::LiveQuery, FunctionRuntime::IbexModule(module)) => {
            let protected_query_profile = function.is_protected_query();
            let run = crate::runtime::run_ibex_query_with_reads_prepared(
                module,
                input.clone(),
                prepared,
                db,
                if protected_query_profile {
                    None
                } else {
                    warm_vms
                },
                protected_query_profile,
                cursor_authority,
            )?;
            let mut read_dependencies = run.read_dependencies;
            add_permission_dependencies_with(permission_epochs, &input, &mut read_dependencies);
            Ok(QueryInvocation {
                output: run.output,
                read_dependencies,
            })
        }
        _ => Err(SnapbackError::error(
            "SNAPBACK_FUNCTION_KIND_MISMATCH",
            "runtime",
            format!("{name} is not a query"),
        )),
    }?;
    #[cfg(test)]
    BEFORE_QUERY_RESULT_HANDOFF_HOOK.with(|slot| {
        if let Some(hook) = slot.borrow_mut().take() {
            hook();
        }
    });
    crate::result_contract::validate_query_handler_result(function, &invocation.output.rows)?;
    let _publication = prepared.effect_guard("query result handoff")?;
    Ok(invocation)
}

fn add_permission_dependencies_with(
    permission_epochs: &BTreeMap<String, u64>,
    input: &HandlerInput,
    dependencies: &mut Vec<CapturedReadDependency>,
) {
    let Some(user_id) = input.auth.user_id.as_deref() else {
        return;
    };
    let scope = user_permission_scope(user_id);
    if dependencies.iter().any(|dependency| {
        dependency.kind == CapturedReadKind::Permission
            && dependency.value.as_ref().and_then(Value::as_str) == Some(scope.as_str())
    }) {
        return;
    }
    dependencies.push(CapturedReadDependency {
        kind: CapturedReadKind::Permission,
        table: None,
        id: None,
        version: Some(permission_epochs.get(&scope).copied().unwrap_or(0)),
        predicate: None,
        rows: Vec::new(),
        field: Some("scope".to_owned()),
        value: Some(Value::String(scope)),
        order: None,
        limit: None,
        result_count: None,
        boundary: None,
    });
}

fn permission_epochs_from_dependencies(
    dependencies: &[CapturedReadDependency],
) -> BTreeMap<String, u64> {
    let mut epochs = BTreeMap::new();
    for dependency in dependencies
        .iter()
        .filter(|dependency| dependency.kind == CapturedReadKind::Permission)
    {
        let Some(scope) = dependency.value.as_ref().and_then(Value::as_str) else {
            continue;
        };
        let Some(epoch) = dependency.version else {
            continue;
        };
        epochs.insert(scope.to_owned(), epoch);
    }
    epochs
}

fn current_permission_epochs_for_dependencies(
    dependencies: &[CapturedReadDependency],
    current_epoch: impl Fn(&str) -> u64,
) -> BTreeMap<String, u64> {
    let mut epochs = BTreeMap::new();
    for dependency in dependencies
        .iter()
        .filter(|dependency| dependency.kind == CapturedReadKind::Permission)
    {
        let Some(scope) = dependency.value.as_ref().and_then(Value::as_str) else {
            continue;
        };
        let epoch = dependency.version.unwrap_or_else(|| current_epoch(scope));
        epochs.insert(scope.to_owned(), epoch);
    }
    epochs
}

/// Resolve every declared `permission_epoch_bumps` scope for a mutation
/// invocation. Called pre-execution so a scope that cannot be evaluated
/// (missing auth user, missing arg, empty scope) rejects the mutation before
/// any write, never after commit (ENG-23329).
fn evaluate_permission_epoch_scopes(
    function: &FunctionDefinition,
    input: &HandlerInput,
) -> SnapbackResult<BTreeSet<String>> {
    let mut scopes = BTreeSet::new();
    for expr in &function.permission_epoch_bumps {
        scopes.insert(evaluate_permission_scope(expr, input)?);
    }
    Ok(scopes)
}

fn evaluate_permission_scope(
    expr: &PermissionScopeExpr,
    input: &HandlerInput,
) -> SnapbackResult<String> {
    let scope = match expr {
        PermissionScopeExpr::AuthUser => {
            let Some(user_id) = input.auth.user_id.as_deref() else {
                return Err(SnapbackError::error(
                    "SNAPBACK_AUTH_USER_MISSING",
                    "runtime",
                    "permission scope requires an authenticated user",
                ));
            };
            user_permission_scope(user_id)
        }
        PermissionScopeExpr::Arg(path) => {
            lookup_arg_string(&input.args, path).ok_or_else(|| {
                SnapbackError::error(
                    "SNAPBACK_PERMISSION_SCOPE_MISSING",
                    "runtime",
                    "permission scope argument is missing or is not a string",
                )
                .with_details(json!({ "path": path }))
            })?
        }
        PermissionScopeExpr::Literal(scope) => scope.clone(),
    };

    if scope.is_empty() {
        return Err(SnapbackError::error(
            "SNAPBACK_PERMISSION_SCOPE_MISSING",
            "runtime",
            "permission scope is empty",
        ));
    }

    Ok(scope)
}

fn lookup_arg_string(args: &Value, path: &str) -> Option<String> {
    if path.is_empty() {
        return None;
    }

    let mut current = args;
    for segment in path.split('.') {
        current = current.get(segment)?;
    }
    current.as_str().map(ToOwned::to_owned)
}

fn subscription_stale_permission_change<'a>(
    subscription: &LiveSubscription,
    changes: &'a [(String, u64)],
) -> Option<(&'a String, &'a u64)> {
    for dependency in subscription
        .read_dependencies
        .iter()
        .filter(|dependency| dependency.kind == CapturedReadKind::Permission)
    {
        let Some(scope) = dependency.value.as_ref().and_then(Value::as_str) else {
            continue;
        };
        let captured_epoch = dependency.version.unwrap_or_default();
        for (changed_scope, epoch) in changes {
            if changed_scope == scope && *epoch > captured_epoch {
                return Some((changed_scope, epoch));
            }
        }
    }
    None
}

fn eval_action_args(
    args: &BTreeMap<String, ValueExpr>,
    input: &HandlerInput,
    bindings: &BTreeMap<String, Value>,
    metadata: &CronRunMetadata,
    snapback: &LocalSnapback,
) -> SnapbackResult<Map<String, Value>> {
    let mut output = Map::new();
    for (name, expr) in args {
        output.insert(
            name.clone(),
            eval_action_expr(expr, input, bindings, metadata, snapback)?,
        );
    }
    Ok(output)
}

// Delegates to the shared profile evaluator; only the intrinsic sources
// differ here (cron actions stamp `RuntimeNow` from the run's due time and
// draw ids from the store's generator).
fn eval_action_expr(
    expr: &ValueExpr,
    input: &HandlerInput,
    bindings: &BTreeMap<String, Value>,
    metadata: &CronRunMetadata,
    snapback: &LocalSnapback,
) -> SnapbackResult<Value> {
    let generate_id = |_site: &str| Ok(snapback.db.generate_id());
    let env = crate::value_expr::ExprEnv {
        args: &input.args,
        auth_user_id: input.auth.user_id.as_deref(),
        auth_kind: input.auth.authorization_kind.as_deref(),
        auth_actor_kind: input.auth.authorization_actor_kind.as_deref(),
        auth_activity_actor_kind: input.auth.authorization_activity_actor_kind.as_deref(),
        auth_actor_user_id: input.auth.authorization_actor_user_id.as_deref(),
        auth_grant_id: input.auth.authorization_grant_id.as_deref(),
        client_mutation_digest: input.auth.client_mutation_digest.as_deref(),
        auth_is_delegated: input.auth.authorization_is_delegated,
        bindings: Some(bindings),
        now_ms: Some(metadata.due_at_ms),
        runtime_id: Some(&generate_id),
    };
    crate::value_expr::eval_value_expr(expr, &env)
        .map_err(|error| crate::diagnostic::SnapbackError::from(error.into_snapback()))
}

fn plan_io(definition: &FunctionDefinition) -> (Vec<String>, Vec<String>) {
    match &definition.runtime {
        FunctionRuntime::HostPlan(HandlerPlan::Query(plan)) => {
            (vec![plan.table.clone()], Vec::new())
        }
        FunctionRuntime::HostPlan(HandlerPlan::SearchQuery(plan)) => {
            (vec![plan.table.clone()], Vec::new())
        }
        FunctionRuntime::HostPlan(HandlerPlan::VectorQuery(plan)) => {
            (vec![plan.table.clone()], Vec::new())
        }
        FunctionRuntime::HostPlan(HandlerPlan::JobStatusQuery(_)) => {
            (vec![crate::jobs::JOBS_STATUS_TABLE.to_owned()], Vec::new())
        }
        FunctionRuntime::HostPlan(HandlerPlan::PushLedgerQuery(_)) => {
            (vec!["_snapback_push_ledger_v1".to_owned()], Vec::new())
        }
        FunctionRuntime::HostPlan(HandlerPlan::RelationalQuery(plan)) => {
            (vec![plan.root.clone(), plan.joined.clone()], Vec::new())
        }
        FunctionRuntime::HostPlan(HandlerPlan::BoundedChildrenQuery(plan)) => (
            vec![plan.parent_table.clone(), plan.child_table.clone()],
            Vec::new(),
        ),
        FunctionRuntime::HostPlan(HandlerPlan::SnapshotBatch(plan)) => {
            let reads = plan
                .nodes
                .iter()
                .flat_map(|node| [node.parent_table.clone(), node.child_table.clone()])
                .collect::<BTreeSet<_>>();
            (reads.into_iter().collect(), Vec::new())
        }
        FunctionRuntime::HostPlan(HandlerPlan::SnapshotBatchV2(plan)) => {
            let reads = plan
                .nodes
                .iter()
                .flat_map(|node| match node {
                    crate::manifest::SnapshotBatchNodeV2::BoundedChildren(node) => {
                        [node.parent_table.clone(), node.child_table.clone()]
                    }
                    crate::manifest::SnapshotBatchNodeV2::RelationalQuery(node) => {
                        [node.root.clone(), node.joined.clone()]
                    }
                })
                .collect::<BTreeSet<_>>();
            (reads.into_iter().collect(), Vec::new())
        }
        FunctionRuntime::HostPlan(HandlerPlan::Mutation(plan))
        | FunctionRuntime::HostPlan(HandlerPlan::WriteWithActivity(
            crate::manifest::WriteWithActivityPlan { mutation: plan, .. },
        )) => {
            let mut reads = BTreeSet::new();
            let mut writes = BTreeSet::new();
            for step in &plan.steps {
                match step {
                    MutationStep::AssetCollection(plan) => {
                        reads.insert(plan.owner_table.clone());
                        reads.insert(plan.child_table.clone());
                        reads.extend(plan.sharing_derivation_tables.iter().cloned());
                        writes.insert(plan.child_table.clone());
                    }
                    MutationStep::Insert { table, .. } | MutationStep::InsertEach { table, .. } => {
                        writes.insert(table.clone());
                    }
                    MutationStep::Patch { table, .. }
                    | MutationStep::Delete { table, .. }
                    | MutationStep::DeleteWhere { table, .. } => {
                        reads.insert(table.clone());
                        writes.insert(table.clone());
                    }
                    MutationStep::Get { table, .. } => {
                        reads.insert(table.clone());
                    }
                    MutationStep::AssertCurrentRelation {
                        table, scope_table, ..
                    } => {
                        reads.insert(table.clone());
                        reads.insert(scope_table.clone());
                    }
                    MutationStep::AssertSourceChanged { table, .. } => {
                        reads.insert(table.clone());
                    }
                    MutationStep::AllocateSequence { .. }
                    | MutationStep::Guard { .. }
                    | MutationStep::Let { .. } => {}
                }
            }
            (reads.into_iter().collect(), writes.into_iter().collect())
        }
        FunctionRuntime::HostPlan(HandlerPlan::Action(_)) => (
            definition.read_set_summary.tables.clone(),
            definition.write_set_summary.tables.clone(),
        ),
        FunctionRuntime::IbexModule(_) => (
            definition.read_set_summary.tables.clone(),
            definition.write_set_summary.tables.clone(),
        ),
    }
}

/// Compose every HostPlan authority-write refusal at the last runtime seam
/// before plan execution. The identity-binding seal is policy-independent and
/// therefore precedes the narrower service-principal provenance refusal for
/// both HostPlan mutation wrappers.
///
/// @ref LLP 0214#59-relationship-to-the-guide-binding-gap — ordinary HostPlan
///   writers cannot reach a declared identity-binding table under any caller
///   authority.
/// @ref LLP 0264#d10-diagnostics-and-refusal-vocabulary — the binding seal is
///   outside, and precedes, the generic policy-refusal precedence list.
pub(crate) fn preflight_host_plan_authority_writes(
    prepared: &PreparedInvocation,
    function: &FunctionDefinition,
    schema: &SchemaManifest,
) -> SnapbackResult<()> {
    if matches!(
        function.runtime,
        FunctionRuntime::HostPlan(HandlerPlan::Mutation(_) | HandlerPlan::WriteWithActivity(_))
    ) {
        let (_, writes) = plan_io(function);
        for table in writes {
            crate::storage::enforce_identity_binding_write_seal(schema, &table)?;
        }
    }
    refuse_unprovenanced_host_plan_authority_creation(prepared, function, schema)
}

/// HostPlan writes do not traverse the Ibex host-call dispatcher and cannot
/// attach LLP 0056's full provenance. Refuse their permission-backing effects
/// under service-principal authority after the policy-independent binding seal;
/// ordinary app-data HostPlans and every human invocation remain unchanged.
///
/// @ref LLP 0055#grants — non-provenanced permission-backing writes have no
///   consentable service-principal lane in v1.
fn refuse_unprovenanced_host_plan_authority_creation(
    prepared: &PreparedInvocation,
    function: &FunctionDefinition,
    schema: &SchemaManifest,
) -> SnapbackResult<()> {
    if !matches!(
        prepared.authority().resolved(),
        ResolvedAppAuthority::ServicePrincipal { .. }
    ) || !matches!(
        function.runtime,
        FunctionRuntime::HostPlan(HandlerPlan::Mutation(_))
    ) {
        return Ok(());
    }
    let (_, writes) = plan_io(function);
    if let Some(table) = writes.iter().find_map(|name| {
        schema
            .tables
            .iter()
            .find(|table| table.name == *name && table.is_permission_backing())
    }) {
        return Err(SnapbackError::error(
            "SNAPBACK_AUTH_AUTHORITY_CREATING_UNCONSENTED",
            "auth",
            "service-principal HostPlan writes to permission-backing tables are unavailable without full provenance",
        )
        .with_details(json!({
            "reason": "permission_backing_provenance_unavailable",
            "table": table.name,
        })));
    }
    Ok(())
}

pub fn live_stream_text(envelope: RealtimeEnvelope) -> Option<String> {
    live_stream_text_with_server_observed(envelope, None)
}

pub fn live_stream_text_with_server_observed(
    envelope: RealtimeEnvelope,
    server_observed_at_ms: Option<u64>,
) -> Option<String> {
    match envelope {
        RealtimeEnvelope::Durable(message) => String::from_utf8(message.into_live_socket_payload())
            .or_else(|error| {
                serde_json::to_string(&LiveSocketServerFrame::DurableBytes {
                    payload: error.into_bytes(),
                })
            })
            .ok(),
        RealtimeEnvelope::Ephemeral(message) => {
            let mut value =
                serde_json::to_value(&LiveSocketServerFrame::Ephemeral { message }).ok()?;
            if let (Some(now_ms), Some(object)) = (server_observed_at_ms, value.as_object_mut()) {
                object.insert("serverObservedAtMs".to_owned(), serde_json::json!(now_ms));
            }
            serde_json::to_string(&value).ok()
        }
    }
}

fn elapsed_ms(started: Instant) -> u64 {
    started.elapsed().as_millis() as u64
}

